        [HttpGet]
        [Route("HR/SearchJournalEntryLink")]
        public async Task<IActionResult> SearchJournalEntryLink(string doctype, string txt = "", string partyType = "")
        {
            try
            {
                if (string.IsNullOrWhiteSpace(doctype))
                    return Content("[]", "application/json");

                txt = txt ?? "";

                if (doctype == "Party Type")
                {
                    return Content(
                        JsonConvert.SerializeObject(new[]
                        {
                    new { name = "Customer", label = "Customer" },
                    new { name = "Supplier", label = "Supplier" },
                    new { name = "Employee", label = "Employee" },
                    new { name = "Shareholder", label = "Shareholder" }
                        }),
                        "application/json");
                }

                if (doctype == "Party")
                {
                    if (string.IsNullOrWhiteSpace(partyType))
                        return Content("[]", "application/json");

                    doctype = partyType;
                }

                if (doctype == "Company GSTIN")
                {
                    string safeGstinTxt = txt.Replace("\"", "\\\"");

                    string gstinUrl =
                        "/api/resource/Address?fields=" +
                        Uri.EscapeDataString("[\"name\",\"gstin\"]") +
                        "&filters=" +
                        Uri.EscapeDataString("[[\"gstin\",\"like\",\"%" + safeGstinTxt + "%\"]]") +
                        "&limit_page_length=50";

                    string gstinResponse = await _erpNextService.GetAsync(gstinUrl);

                    if (string.IsNullOrWhiteSpace(gstinResponse))
                        return Content("[]", "application/json");

                    JObject gstinParsed = JObject.Parse(gstinResponse);
                    var gstinResult = new List<object>();

                    foreach (var row in gstinParsed["data"] ?? new JArray())
                    {
                        string gstin = row["gstin"]?.ToString() ?? "";
                        string name = row["name"]?.ToString() ?? "";

                        if (!string.IsNullOrWhiteSpace(gstin))
                        {
                            gstinResult.Add(new
                            {
                                name = gstin,
                                label = name
                            });
                        }
                    }

                    return Content(JsonConvert.SerializeObject(gstinResult), "application/json");
                }

                var allowed = new HashSet<string>
        {
            "Journal Entry Template",
            "Company",
            "Account",
            "Mode of Payment",
            "Customer",
            "Supplier",
            "Employee",
            "Shareholder",
            "Print Heading",
        };

                if (!allowed.Contains(doctype))
                    return Content("[]", "application/json");

                string safeTxt = txt.Replace("\"", "\\\"");
                string fields = Uri.EscapeDataString("[\"name\"]");

                string filters = string.IsNullOrWhiteSpace(safeTxt)
                    ? ""
                    : "&filters=" + Uri.EscapeDataString("[[\"name\",\"like\",\"%" + safeTxt + "%\"]]");

                string url =
                    "/api/resource/" + Uri.EscapeDataString(doctype) +
                    "?fields=" + fields +
                    filters +
                    "&limit_page_length=20";

                string response = await _erpNextService.GetAsync(url);

                if (string.IsNullOrWhiteSpace(response))
                    return Content("[]", "application/json");

                JObject parsed = JObject.Parse(response);
                var result = new List<object>();

                foreach (var row in parsed["data"] ?? new JArray())
                {
                    string name = row["name"]?.ToString() ?? "";

                    if (!string.IsNullOrWhiteSpace(name))
                    {
                        result.Add(new
                        {
                            name = name,
                            label = name
                        });
                    }
                }

                return Content(JsonConvert.SerializeObject(result), "application/json");
            }
            catch
            {
                return Content("[]", "application/json");
            }
        }


