        private string CleanTravelRequestErpError(string rawError)
        {
            if (string.IsNullOrWhiteSpace(rawError))
                return "ERPNext operation failed.";

            try
            {
                int start = rawError.IndexOf('{');

                if (start >= 0)
                {
                    var json = Newtonsoft.Json.Linq.JObject.Parse(
                        rawError.Substring(start)
                    );

                    string messages = json["_server_messages"]?.ToString();

                    if (!string.IsNullOrWhiteSpace(messages))
                    {
                        var list = Newtonsoft.Json.Linq.JArray.Parse(messages);

                        if (list.Count > 0)
                        {
                            var first = Newtonsoft.Json.Linq.JObject.Parse(
                                list[0].ToString()
                            );

                            string message = first["message"]?.ToString();

                            if (!string.IsNullOrWhiteSpace(message))
                            {
                                message = System.Text.RegularExpressions.Regex.Replace(
                                    message, "<[^>]*>", " "
                                );

                                return System.Net.WebUtility.HtmlDecode(message).Trim();
                            }
                        }
                    }
                }
            }
            catch
            {
            }

            return rawError.Length > 200
                ? rawError.Substring(0, 200) + "..."
                : rawError;
        }




        [HttpGet]
        [Route("HR/SearchTravelRequestMaster")]
        public async Task<JsonResult> SearchTravelRequestMaster(
    string master,
    string search = "")
        {
            var masters = new Dictionary<string, string>(
                StringComparer.OrdinalIgnoreCase)
    {
        { "Employee", "Employee" },
        { "IdentificationDocumentType", "Identification Document Type" },
        { "Company", "Company" },
        { "ExpenseType", "Expense Claim Type" },
        { "CostCenter", "Cost Center" },

        // Keep existing Purpose of Travel search working.
        { "PurposeOfTravel", "Purpose of Travel" }
    };

            if (string.IsNullOrWhiteSpace(master) ||
                !masters.TryGetValue(master, out string doctype))
            {
                return Json(new
                {
                    success = false,
                    message = "Invalid master."
                });
            }

            try
            {
                string url =
                    "/api/method/frappe.desk.search.search_link" +
                    "?doctype=" + Uri.EscapeDataString(doctype) +
                    "&txt=" + Uri.EscapeDataString(search ?? "") +
                    "&reference_doctype=" +
                        Uri.EscapeDataString("Travel Request") +
                    "&page_length=100";

                string json = await _erpNextService.GetAsync(url);

                var parsed = Newtonsoft.Json.Linq.JObject.Parse(json);

                var rows = parsed["message"] as Newtonsoft.Json.Linq.JArray
                           ?? new Newtonsoft.Json.Linq.JArray();

                return Json(new
                {
                    success = true,
                    items = rows.Select(x => new
                    {
                        value = x["value"]?.ToString(),
                        description = x["description"]?.ToString()
                    }).ToList()
                });
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    success = false,
                    message = CleanTravelRequestErpError(ex.Message)
                });
            }
        }






