        [HttpPost]
        [Route("HR/UpdateTravelRequest")]
        public async Task<ActionResult> UpdateTravelRequest(TravelRequest model)
        {
            if (model == null || string.IsNullOrWhiteSpace(model.TravelRequestCode))
                return RedirectToAction("TravelRequest");

            try
            {
                await PrepareTravelRequestForErpAsync(model);

                await _erpNextService.PutAsync(
                    "/api/resource/Travel%20Request/" +
                    Uri.EscapeDataString(model.TravelRequestCode),
                    BuildTravelRequestPayload(model)
                );

                await RefreshTravelRequestFromErpNextAsync(model.TravelRequestCode);

                TempData["Success"] = "Travel Request saved successfully.";

                return RedirectToAction(
                    "TravelRequestDetails",
                    new { code = model.TravelRequestCode }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanTravelRequestErpError(ex.Message);

                return RedirectToAction(
                    "TravelRequestDetails",
                    new { code = model.TravelRequestCode }
                );
            }
        }

        [HttpPost]
        [Route("HR/DeleteTravelRequest")]
        public async Task<ActionResult> DeleteTravelRequest(string code)
        {
            if (string.IsNullOrWhiteSpace(code))
                return RedirectToAction("TravelRequest");

            try
            {
                await _erpNextService.DeleteAsync(
                    "/api/resource/Travel%20Request/" +
                    Uri.EscapeDataString(code)
                );

                _travelRequestService.SoftDeleteByCode(code);

                TempData["Success"] = "Travel Request deleted successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Delete failed: "
                    + CleanTravelRequestErpError(ex.Message);
            }

            return RedirectToAction("TravelRequest");
        }






























        [HttpGet]
        [Route("HR/SearchPayrollSettingsLink")]
        public async Task<IActionResult> SearchPayrollSettingsLink(string doctype, string txt = "")
        {
            try
            {
                if (string.IsNullOrWhiteSpace(doctype))
                    return Content("[]", "application/json");

                var allowed = new HashSet<string>
        {
            "Email Account",
            "Email Template"
        };

                if (!allowed.Contains(doctype))
                    return Content("[]", "application/json");

                string safeTxt = (txt ?? "").Replace("\"", "\\\"");
                string fields = Uri.EscapeDataString("[\"name\"]");

                string filters = string.IsNullOrWhiteSpace(safeTxt)
                    ? ""
                    : "&filters=" + Uri.EscapeDataString("[[\"name\",\"like\",\"%" + safeTxt + "%\"]]");

                string url =
                    "/api/resource/" + Uri.EscapeDataString(doctype) +
                    "?fields=" + fields +
                    filters +
                    "&limit_page_length=20";

                string response = await _erpNextService.GetAsync(url);

                if (string.IsNullOrWhiteSpace(response))
                    return Content("[]", "application/json");

                JObject parsed = JObject.Parse(response);
                var result = new List<object>();

                foreach (var row in parsed["data"] ?? new JArray())
                {
                    string name = row["name"]?.ToString() ?? "";

                    if (!string.IsNullOrWhiteSpace(name))
                    {
                        result.Add(new
                        {
                            name = name,
                            label = name
                        });
                    }
                }

                return Content(JsonConvert.SerializeObject(result), "application/json");
            }
            catch
            {
                return Content("[]", "application/json");
            }
        }

























        [HttpGet]
        [Route("HR/GetJournalEntryCompanyDetails")]
        public async Task<IActionResult> GetJournalEntryCompanyDetails(string company)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(company))
                    return Content("{\"companyGstin\":\"\"}", "application/json");

                string response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Company/" + Uri.EscapeDataString(company)
                    );

                if (string.IsNullOrWhiteSpace(response))
                    return Content("{\"companyGstin\":\"\"}", "application/json");

                JObject parsed = JObject.Parse(response);
                JObject data = parsed["data"] as JObject;

                string gstin =
                    data?["gstin"]?.ToString()
                    ?? data?["tax_id"]?.ToString()
                    ?? data?["company_gstin"]?.ToString()
                    ?? "";

                return Content(
                    JsonConvert.SerializeObject(new { companyGstin = gstin }),
                    "application/json");
            }
            catch
            {
                return Content("{\"companyGstin\":\"\"}", "application/json");
            }
        }












        private string CleanGoalErpError(string rawError)
        {
            if (string.IsNullOrWhiteSpace(rawError))
            {
                return "ERPNext operation failed.";
            }

            try
            {
                int jsonStart = rawError.IndexOf('{');

                if (jsonStart >= 0)
                {
                    string jsonPart =
                        rawError.Substring(jsonStart);

                    JObject json =
                        JObject.Parse(jsonPart);

                    JToken serverMessages =
                        json["_server_messages"];

                    if (serverMessages != null)
                    {
                        JArray messages =
                            JArray.Parse(
                                serverMessages.ToString()
                            );

                        if (messages.Count > 0)
                        {
                            JObject messageObject =
                                JObject.Parse(
                                    messages[0].ToString()
                                );

                            string message =
                                messageObject["message"]
                                    ?.ToString();

                            if (!string.IsNullOrWhiteSpace(message))
                            {
                                message =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        message,
                                        "<[^>]*>",
                                        " "
                                    );

                                message =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        message,
                                        @"\s+",
                                        " "
                                    ).Trim();

                                return System.Net.WebUtility.HtmlDecode(
                                    message
                                );
                            }
                        }
                    }
                }
            }
            catch
            {
                // Ignore parsing error
            }

            return rawError;
        }


















