        [HttpPost]
        public async Task<ActionResult> SyncGrievanceTypesFromErpNext()
        {
            try
            {
                string listJson = await _erpNextService.GetAsync(
                    "/api/resource/Grievance%20Type?fields=[\"name\",\"description\"]&limit_page_length=1000"
                );

                dynamic parsed = JsonConvert.DeserializeObject(listJson);
                int synced = 0;

                foreach (var row in parsed.data)
                {
                    string name = row.name?.ToString();

                    if (string.IsNullOrWhiteSpace(name))
                        continue;

                    var model = new GrievanceType
                    {
                        ErpNextId = name,
                        Name = name,
                        Description = row.description?.ToString()
                    };

                    _grievanceTypeService.UpsertFromErpNext(model);
                    synced++;
                }

                TempData["Success"] = synced + " Grievance Type records synced from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "ERPNext to HRMS sync failed: " + ex.Message;
            }

            return RedirectToAction("GrievanceType");
        }

