        [HttpPost]
        [Route("HR/CreateGrievanceType")]
        public async Task<ActionResult> CreateGrievanceType(GrievanceType model)
        {
            int newId = _grievanceTypeService.Insert(model);

            try
            {
                string erpNextId = await PushGrievanceTypeToErpNext(_grievanceTypeService.GetById(newId));

                if (!string.IsNullOrWhiteSpace(erpNextId))
                    _grievanceTypeService.UpdateErpNextId(newId, erpNextId);

                TempData["Success"] = "Grievance Type saved and synced to ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Saved in HRMS but ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("GrievanceTypeDetails", new { id = newId });
        }

