        private async Task<string> PushGrievanceTypeToErpNext(GrievanceType model)
        {
            if (model == null || string.IsNullOrWhiteSpace(model.Name))
                return string.Empty;

            var payload = new
            {
                name = model.Name,
                description = model.Description
            };

            try
            {
                await _erpNextService.GetAsync(
                    "/api/resource/Grievance%20Type/" + Uri.EscapeDataString(model.Name)
                );

                await _erpNextService.PutAsync(
                    "/api/resource/Grievance%20Type/" + Uri.EscapeDataString(model.Name),
                    payload
                );

                return model.Name;
            }
            catch
            {
                string createJson = await _erpNextService.PostAsync(
                    "/api/resource/Grievance%20Type",
                    payload
                );

                dynamic created = JsonConvert.DeserializeObject(createJson);
                return created?.data?.name?.ToString() ?? model.Name;
            }
        }






















