        [HttpGet]
        [Route("HR/CreateEmployeePerformanceFeedback")]
        public async Task<ActionResult> CreateEmployeePerformanceFeedback()
        {
            try
            {
                // ============================================================
                // EMPLOYEES / REVIEWERS
                // ============================================================

                string employeeResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee" +
                        "?fields=[\"name\",\"employee_name\",\"company\",\"status\"]" +
                        "&filters=[[\"status\",\"=\",\"Active\"]]" +
                        "&limit_page_length=5000"
                    );


                dynamic employeeParsed =
                    JsonConvert.DeserializeObject(
                        employeeResponse
                    );


                ViewBag.Employees =
                    employeeParsed?.data;


                ViewBag.Reviewers =
                    employeeParsed?.data;


                // ============================================================
                // APPRAISAL DROPDOWN
                //
                // Get all Appraisals except cancelled.
                // Browser filters them by selected employee.
                // ============================================================

                string appraisalResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal" +
                        "?fields=[\"name\",\"employee\",\"employee_name\",\"appraisal_template\",\"appraisal_cycle\",\"docstatus\"]" +
                        "&filters=[[\"docstatus\",\"!=\",2]]" +
                        "&limit_page_length=5000"
                    );


                dynamic appraisalParsed =
                    JsonConvert.DeserializeObject(
                        appraisalResponse
                    );


                ViewBag.Appraisals =
                    appraisalParsed?.data;


                // ============================================================
                // CRITERIA MASTER
                //
                // We collect criteria from existing Appraisal Templates.
                // ============================================================

                var criteriaList =
                    new List<object>();


                string templateListResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal%20Template" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=5000"
                    );


                JObject templateListJson =
                    JObject.Parse(
                        templateListResponse
                    );


                JArray templates =
                    templateListJson["data"]
                        as JArray;


                var usedCriteria =
                    new HashSet<string>(
                        StringComparer.OrdinalIgnoreCase
                    );


                if (templates != null)
                {
                    foreach (JToken template in templates)
                    {
                        string templateName =
                            template["name"]
                                ?.ToString();


                        if (string.IsNullOrWhiteSpace(
                            templateName))
                        {
                            continue;
                        }


                        try
                        {
                            string templateResponse =
                                await _erpNextService.GetAsync(
                                    "/api/resource/Appraisal%20Template/" +
                                    Uri.EscapeDataString(
                                        templateName
                                    )
                                );


                            JObject templateJson =
                                JObject.Parse(
                                    templateResponse
                                );


                            JArray ratings =
                                templateJson["data"]?["rating_criteria"]
                                    as JArray;


                            if (ratings == null)
                                continue;


                            foreach (JToken rating in ratings)
                            {
                                string criteria =
                                    rating["criteria"]
                                        ?.ToString()
                                    ?? "";


                                decimal weightage =
                                    rating["per_weightage"]
                                        ?.ToObject<decimal>()
                                    ?? 0;


                                if (
                                    string.IsNullOrWhiteSpace(
                                        criteria) ||
                                    usedCriteria.Contains(
                                        criteria)
                                )
                                {
                                    continue;
                                }


                                usedCriteria.Add(
                                    criteria
                                );


                                criteriaList.Add(
                                    new
                                    {
                                        criteria =
                                            criteria,

                                        per_weightage =
                                            weightage
                                    }
                                );
                            }
                        }
                        catch
                        {
                            // Skip one inaccessible/bad template.
                        }
                    }
                }


                ViewBag.FeedbackCriteria =
                    criteriaList;
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Unable to load Employee Performance Feedback data: "
                    + ex.Message;


                ViewBag.Employees = null;
                ViewBag.Reviewers = null;
                ViewBag.Appraisals = null;
                ViewBag.FeedbackCriteria =
                    new List<object>();
            }


            return View(
                "~/Views/HR/CreateEmployeePerformanceFeedback.cshtml",
                new EmployeePerformanceFeedback
                {
                    AddedOn =
                        DateTime.Now
                }
            );
        }






















