        [HttpPost]
        [Route("HR/SyncEmployeePerformanceFeedbackFromErpNext")]
        public async Task<ActionResult>
      SyncEmployeePerformanceFeedbackFromErpNext()
        {
            try
            {
                var result = await SyncEmployeePerformanceFeedbackFromErpNextInternal();

                TempData["Success"] =
                    "Employee Performance Feedback sync completed. " +
                    "New: " + result.inserted +
                    ", Updated: " + result.updated +
                    ", Failed: " + result.failed + ".";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext sync failed: "
                    + CleanEmployeePerformanceFeedbackErpError(ex.Message);
            }


            return RedirectToAction(
                "EmployeePerformanceFeedback"
            );
        }

        private async Task<(int inserted, int updated, int failed)> SyncEmployeePerformanceFeedbackFromErpNextInternal()
        {
            string listResponse =
                await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Performance%20Feedback" +
                    "?fields=[\"name\"]" +
                    "&limit_page_length=5000"
                );

            JObject listJson = JObject.Parse(listResponse);
            JArray records = listJson["data"] as JArray;

            int inserted = 0;
            int updated = 0;
            int failed = 0;

            if (records != null)
            {
                foreach (JToken row in records)
                {
                    try
                    {
                        string erpId = row["name"]?.ToString();

                        if (string.IsNullOrWhiteSpace(erpId))
                            continue;

                        bool exists =
                            _employeePerformanceFeedbackService
                                .GetByErpNextId(erpId) != null;

                        await SyncOneEmployeePerformanceFeedbackFromErpNext(erpId);

                        if (exists)
                            updated++;
                        else
                            inserted++;
                    }
                    catch
                    {
                        failed++;
                    }
                }
            }

            return (inserted, updated, failed);
        }

        private async Task<int> SyncOneEmployeePerformanceFeedbackFromErpNext(string erpId)
        {
            string detailResponse =
                await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Performance%20Feedback/" +
                    Uri.EscapeDataString(erpId)
                );

            JObject detailJson = JObject.Parse(detailResponse);

            EmployeePerformanceFeedback model =
                MapErpEmployeePerformanceFeedback(detailJson["data"]);

            return _employeePerformanceFeedbackService.InsertOrUpdate(model);
        }

        private EmployeePerformanceFeedback
            MapErpEmployeePerformanceFeedback(
                JToken doc)
        {
            var model =
                new EmployeePerformanceFeedback
                {
                    ErpNextId =
                        doc?["name"]
                            ?.ToString()
                        ?? "",

                    ForEmployee =
                        doc?["employee"]
                            ?.ToString()
                        ?? "",

                    EmployeeName =
                        doc?["employee_name"]
                            ?.ToString()
                        ?? "",

                    Reviewer =
                        doc?["reviewer"]
                            ?.ToString()
                        ?? "",

                    ReviewerName =
                        doc?["reviewer_name"]
                            ?.ToString()
                        ?? "",

                    Company =
                        doc?["company"]
                            ?.ToString()
                        ?? "",

                    AppraisalCycle =
                        doc?["appraisal_cycle"]
                            ?.ToString()
                        ?? "",

                    Appraisal =
                        doc?["appraisal"]
                            ?.ToString()
                        ?? "",

                    Feedback =
                        doc?["feedback"]
                            ?.ToString()
                        ?? "",

                    TotalScore =
                        doc?["total_score"]
                            ?.ToObject<decimal>()
                        ?? 0,

                    DocStatus =
                        doc?["docstatus"]
                            ?.ToObject<int>()
                        ?? 0,

                    AmendedFrom =
                        doc?["amended_from"]
                            ?.ToString()
                        ?? "",

                    FeedbackRatings =
                        new List<EmployeePerformanceFeedbackRating>()
                };


            DateTime addedOn;

            if (
                DateTime.TryParse(
                    doc?["added_on"]
                        ?.ToString(),
                    out addedOn
                )
            )
            {
                model.AddedOn =
                    addedOn;
            }
            else
            {
                model.AddedOn =
                    DateTime.Now;
            }


            JArray ratings =
                doc?["feedback_ratings"]
                    as JArray;


            if (ratings != null)
            {
                foreach (
                    JToken row
                    in ratings)
                {
                    model.FeedbackRatings.Add(
                        new EmployeePerformanceFeedbackRating
                        {
                            Criteria =
                                row["criteria"]
                                    ?.ToString()
                                ?? "",

                            Weightage =
                                row["per_weightage"]
                                    ?.ToObject<decimal>()
                                ?? 0,

                            Rating =
                                row["rating"]
                                    ?.ToObject<decimal>()
                                ?? 0
                        }
                    );
                }
            }


            return model;
        }

        // GET: HR/GetPartiesByDocType
        [HttpGet]
        [Route("HR/GetPartiesByDocType")]
        public async Task<JsonResult> GetPartiesByDocType(
     string doctype)
        {
            var result = new List<object>();


            try
            {
                if (string.IsNullOrWhiteSpace(doctype))
                    return Json(result);


                string nameField;

                switch (doctype)
                {
                    case "Customer":
                        nameField = "customer_name";
                        break;

                    case "Supplier":
                        nameField = "supplier_name";
                        break;

                    case "Employee":
                        nameField = "employee_name";
                        break;

                    case "Shareholder":
                        nameField = "title";
                        break;

                    default:
                        return Json(result);
                }


                string url =
                    "/api/resource/"
                    + Uri.EscapeDataString(doctype)
                    + "?fields=[\"name\",\""
                    + nameField
                    + "\"]"
                    + "&limit_page_length=5000";


                string json =
                    await _erpNextService.GetAsync(url);


                JObject parsed =
                    JObject.Parse(json);


                JArray rows =
                    parsed["data"] as JArray;


                if (rows != null)
                {
                    foreach (JToken row in rows)
                    {
                        result.Add(
                            new
                            {
                                name =
                                    row["name"]
                                        ?.ToString(),

                                title =
                                    row[nameField]
                                        ?.ToString()
                                    ?? row["name"]
                                        ?.ToString()
                            }
                        );
                    }
                }
            }
            catch
            {
                // Keep endpoint clean.
            }


            return Json(result);
        }


