      string postingDate = null)
        {
            if (
                string.IsNullOrWhiteSpace(partyType) ||
                string.IsNullOrWhiteSpace(party) ||
                string.IsNullOrWhiteSpace(company) ||
                string.IsNullOrWhiteSpace(paymentType)
            )
            {
                return Json(new { success = false });
            }

            try
            {
                if (string.IsNullOrWhiteSpace(postingDate))
                    postingDate = DateTime.Today.ToString("yyyy-MM-dd");

                var formData =
                    new Dictionary<string, string>
                    {
                { "company", company },
                { "party_type", partyType },
                { "party", party },
                { "payment_type", paymentType },
                { "posting_date", postingDate }
                    };

                string json =
                    //await _erpNextService.PostFormAsync(
                    await _erpNextService.PostFormDataAsync(
                        "/api/method/erpnext.accounts.doctype.payment_entry.payment_entry.get_party_details",
                        formData
                    );

                JObject root =
                    JObject.Parse(json);

                JObject message =
