        // POST: HR/SyncEmployeePerformanceFeedbackToServerToErpNext
        // POST: HR/SyncEmployeePerformanceFeedbackToServerToErpNext
        [HttpPost]
        [Route("HR/SyncEmployeePerformanceFeedbackToServerToErpNext")]
        public async Task<ActionResult> SyncEmployeePerformanceFeedbackToServerToErpNext()
        {
            int successCount = 0;
            int failCount = 0;

            try
            {
                var unsynced = _employeePerformanceFeedbackService.GetUnsynced();

                foreach (var model in unsynced)
                {
                    try
                    {
                        // Ensure Employee exists in ERPNext before pushing link
                        if (!string.IsNullOrWhiteSpace(model.ForEmployee))
                        {
                            await EnsureDocExistsAsync("Employee", model.ForEmployee);
                        }

                        // Map child table: feedback_ratings
                        var ratingsList = new List<object>();
                        if (model.FeedbackRatings != null)
                        {
                            foreach (var r in model.FeedbackRatings)
                            {
                                if (string.IsNullOrWhiteSpace(r.Criteria)) continue;
                                ratingsList.Add(new
                                {
                                    criteria = r.Criteria,
                                    per_weightage = r.Weightage,
                                    rating = r.Rating
                                });
                            }
                        }

                        var payload = new
                        {
                            employee = model.ForEmployee,
                            employee_name = model.EmployeeName,
                            reviewer = model.Reviewer,
                            company = model.Company,
                            added_on = model.AddedOn.ToString("yyyy-MM-dd HH:mm:ss"),
                            appraisal = model.Appraisal,
                            feedback = model.Feedback,
                            total_score = model.TotalScore,
                            feedback_ratings = ratingsList
                        };

                        var responseJson = await _erpNextService.PostAsync("/api/resource/Employee%20Performance%20Feedback", payload);
                        dynamic responseParsed = JsonConvert.DeserializeObject(responseJson);
                        string erpNextId = responseParsed?.data?.name;

                        if (!string.IsNullOrEmpty(erpNextId))
                        {
                            _employeePerformanceFeedbackService.UpdateErpNextId(model.Id, erpNextId);
                            successCount++;
                        }
                    }
                    catch
                    {
                        failCount++;
                    }
                }

                if (successCount > 0)
                {
                    TempData["Success"] = $"Synced {successCount} local feedback record(s) to ERPNext successfully!" + (failCount > 0 ? $" ({failCount} failed)" : "");
                }
                else if (failCount > 0)
                {
                    TempData["ErpNextError"] = $"Failed to sync {failCount} record(s) to ERPNext.";
                }
                else
                {
                    TempData["Success"] = "All local records are already synced with ERPNext!";
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Push error: " + ex.Message;
            }

            return RedirectToAction("EmployeePerformanceFeedback");
        }


