        [HttpPost]
        [Route("HR/CreateLeaveBlockList")]
        public async Task<ActionResult> CreateLeaveBlockList(LeaveBlockList model)
        {
            try
            {
                NormalizeLeaveBlockList(model);
                ValidateLeaveBlockList(model);

                string erpId = model.LeaveBlockListName;
                var payload = BuildLeaveBlockListPayload(model);

                try
                {
                    await _erpNextService.GetAsync($"/api/resource/Leave%20Block%20List/{Uri.EscapeDataString(erpId)}");
                    await _erpNextService.PutAsync($"/api/resource/Leave%20Block%20List/{Uri.EscapeDataString(erpId)}", payload);
                }
                catch
                {
                    var response = await _erpNextService.PostAsync("/api/resource/Leave%20Block%20List", payload);
                    erpId = ExtractErpDocName(response) ?? erpId;
                }

                var detailJson = await _erpNextService.GetAsync($"/api/resource/Leave%20Block%20List/{Uri.EscapeDataString(erpId)}");
                var localModel = MapErpLeaveBlockList(JObject.Parse(detailJson)["data"]);
                int localId = _leaveBlockListService.InsertOrUpdate(localModel);

                TempData["SuccessMessage"] = "Leave Block List saved in ERPNext and HRMS.";
                return RedirectToAction("LeaveBlockListDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErrorMessage"] = "Failed to save: " + ExtractErpNextErrorMessage(ex.Message);
                await PopulateDropdownsAsync();
                return View("~/Views/HR/CreateLeaveBlockList.cshtml", model);
            }
        }

        private static void SetInt(Dictionary<string, object?> payload, string key, int? value)
        {
            payload[key] = value.HasValue ? value.Value : null;
        }

        private static void SetDecimal(Dictionary<string, object?> payload, string key, decimal? value)
        {
            payload[key] = value.HasValue ? value.Value : null;
        }

        private static void SetCheck(Dictionary<string, object?> payload, string key, bool value)
        {
            payload[key] = value ? 1 : 0;
        }






        private static string BuildEmployeeFullName(Employee model)
        {
            string combinedName = $"{model.FirstName} {model.MiddleName} {model.LastName}".Replace("  ", " ").Trim();
            return FirstNonEmpty(combinedName, model.FullName, model.EmployeeCode, model.ErpNextId);
        }
        private static Employee MergePostedEmployeeFields(Employee existing, Employee posted)
        {
            bool fullNameChanged = !string.IsNullOrWhiteSpace(posted.FullName)
                && !string.Equals(posted.FullName, existing.FullName, StringComparison.OrdinalIgnoreCase);
            existing.EmployeeCode = FirstNonEmpty(posted.EmployeeCode, existing.EmployeeCode);
            existing.ErpNextId = FirstNonEmpty(posted.ErpNextId, existing.ErpNextId);
            existing.FullName = FirstNonEmpty(posted.FullName, existing.FullName);
            existing.Gender = posted.Gender;
            existing.DateOfBirth = posted.DateOfBirth;
            existing.DateOfJoining = posted.DateOfJoining;
            existing.Company = posted.Company;
            existing.Department = posted.Department;
            existing.Designation = posted.Designation;
            existing.Mobile = posted.Mobile;
            existing.PersonalEmail = posted.PersonalEmail;
            existing.CompanyEmail = posted.CompanyEmail;
            existing.SalaryMode = posted.SalaryMode;
            existing.BankName = posted.BankName;
            existing.BankAccountNo = posted.BankAccountNo;
            existing.IFSCCode = posted.IFSCCode;
            existing.MICRCode = posted.MICRCode;
            existing.IBAN = posted.IBAN;
            if (fullNameChanged)
            {
                var nameParts = posted.FullName.Split(' ', StringSplitOptions.RemoveEmptyEntries);
                existing.FirstName = nameParts.Length > 0 ? nameParts[0] : posted.FullName;
                existing.MiddleName = nameParts.Length > 2 ? string.Join(" ", nameParts.Skip(1).Take(nameParts.Length - 2)) : null;
                existing.LastName = nameParts.Length > 1 ? nameParts[^1] : null;
            }
            return existing;
        }
        private static string FirstNonEmpty(params string?[] values)
        {
            foreach (var value in values)
            {
                if (!string.IsNullOrWhiteSpace(value))
                {
                    return value.Trim();
                }
            }
            return string.Empty;
        }
        private static string? ReadText(JObject doc, string field)
        {
            var token = doc[field];
            if (token == null || token.Type == JTokenType.Null)
            {
                return null;
            }
            var value = token.ToString();
            return string.IsNullOrWhiteSpace(value) ? null : value.Trim();
        }
        private static DateTime? ReadDate(JObject doc, string field)
        {
            string value = ReadText(doc, field);
            return DateTime.TryParse(value, out var date) ? date : (DateTime?)null;
        }
        private static DateTime? FirstDate(params DateTime?[] values)
        {
            foreach (var value in values)
            {
                if (value.HasValue)
                {
                    return value;
                }
            }
            return null;
        }
        private static int? ReadInt(JObject doc, string field)
        {
            string value = ReadText(doc, field);
            return int.TryParse(value, out var number) ? number : (int?)null;
        }
        private static decimal? ReadDecimal(JObject doc, string field)
        {
            string value = ReadText(doc, field);
            return decimal.TryParse(value, out var number) ? number : (decimal?)null;
        }
        private static bool ReadBool(JObject doc, string field)
        {
            string value = ReadText(doc, field);
            return value == "1"
                || string.Equals(value, "true", StringComparison.OrdinalIgnoreCase)
                || string.Equals(value, "yes", StringComparison.OrdinalIgnoreCase);
        }
        //private static bool IsErpNextMissing(Exception ex)
        //{
        //    return ex.Message.Contains("404")
        //        || ex.Message.Contains("DoesNotExistError", StringComparison.OrdinalIgnoreCase)
        //        || ex.Message.Contains("not found", StringComparison.OrdinalIgnoreCase);
        //}
        private static bool IsErpNextMissing(Exception ex)
        {
            string message = ex.Message ?? "";

            return message.Contains("404") ||
                   message.Contains("DoesNotExistError", StringComparison.OrdinalIgnoreCase) ||
                   message.Contains("not found", StringComparison.OrdinalIgnoreCase);
        }

        private async Task<List<string>> VerifyErpNextEmployeePayloadAsync(string remoteId, Dictionary<string, object?> payload)
        {
            var mismatches = new List<string>();

            var skipFields = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        "education",
        "external_work_history",
        "internal_work_history"
    };

            var verifyJson = await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(remoteId)}");
            var verifyDoc = JObject.Parse(verifyJson)["data"] as JObject ?? new JObject();

            foreach (var item in payload)
            {
                if (skipFields.Contains(item.Key))
                    continue;

                string sentValue = NormalizeErpValue(item.Value);
                string erpValue = NormalizeErpValue(verifyDoc[item.Key]);

                if (!string.Equals(sentValue, erpValue, StringComparison.OrdinalIgnoreCase))
                {
                    mismatches.Add($"{item.Key}: sent '{sentValue}', ERPNext has '{erpValue}'");
                }
            }

            return mismatches;
        }

        private async Task<int> RefreshEmployeeSeparationsFromErpNextAsync()
        {
            const int pageSize = 100;

            int start = 0;
            int syncedCount = 0;

            // Keep track of every ERPNext document name returned
            // so we can detect deletions after a full successful fetch.
            var erpCodes = new HashSet<string>(
                StringComparer.OrdinalIgnoreCase
            );

            var erpSeparations =
                new List<EmployeeSeparation>();


            // ============================================================
            // STEP 1: FETCH COMPLETE ERPNext EMPLOYEE SEPARATION LIST
            // ============================================================

            while (true)
            {
                string listUrl =
                    "/api/resource/Employee%20Separation" +
                    "?fields=" +
                    Uri.EscapeDataString("[\"name\"]") +
                    "&limit_start=" + start +
                    "&limit_page_length=" + pageSize +
                    "&order_by=" +
                    Uri.EscapeDataString("name asc");


                string listResponse =
                    await _erpNextService.GetAsync(
                        listUrl
                    );


                JObject listJson =
                    JObject.Parse(
                        listResponse
                    );


                JArray records =
                    listJson["data"] as JArray;


                if (records == null)
                {
                    throw new Exception(
                        "Invalid ERPNext Employee Separation response."
                    );
                }


                // ========================================================
                // STEP 2: FETCH EACH COMPLETE ERP DOCUMENT
                // ========================================================

                foreach (JToken item in records)
                {
                    string erpId =
                        item["name"]?.ToString();


                    if (string.IsNullOrWhiteSpace(
                        erpId))
                    {
                        throw new Exception(
                            "ERPNext returned Employee Separation without document name."
                        );
                    }


                    erpId =
                        erpId.Trim();


                    // Duplicate document IDs in ERP response should not
                    // be processed twice.
                    if (!erpCodes.Add(erpId))
                    {
                        continue;
                    }


                    string detailUrl =
                        "/api/resource/Employee%20Separation/" +
                        Uri.EscapeDataString(
                            erpId
                        );


                    string detailResponse =
                        await _erpNextService.GetAsync(
                            detailUrl
                        );


                    JObject detailJson =
                        JObject.Parse(
                            detailResponse
                        );


                    JToken doc =
                        detailJson["data"];


                    if (doc == null)
                    {
                        throw new Exception(
                            "Unable to load Employee Separation: " +
                            erpId
                        );
                    }


                    // ====================================================
                    // STEP 3: MAP ERPNext -> HRMS MODEL
                    // ====================================================

                    var separation =
                        new EmployeeSeparation
                        {
                            EmployeeSeparationCode =
                                doc["name"]
                                    ?.ToString()
                                    ?.Trim()
                                ?? "",

                            Employee =
                                doc["employee"]
                                    ?.ToString()
                                ?? "",

                            EmployeeName =
                                doc["employee_name"]
                                    ?.ToString()
                                ?? "",

                            Company =
                                doc["company"]
                                    ?.ToString()
                                ?? "",

                            Status =
                                doc["boarding_status"]
                                    ?.ToString()
                                ?? "Pending",

                            SeparationBeginsOn =
                                ParseEmployeeSeparationDate(
                                    doc["boarding_begins_on"]
                                ),

                            EmployeeSeparationTemplate =
                                doc["employee_separation_template"]
                                    ?.ToString()
                                ?? "",

                            Department =
                                doc["department"]
                                    ?.ToString()
                                ?? "",

                            Designation =
                                doc["designation"]
                                    ?.ToString()
                                ?? "",

                            EmployeeGrade =
                                doc["employee_grade"]
                                    ?.ToString()
                                ?? "",

                            Project =
                                doc["project"]
                                    ?.ToString()
                                ?? "",

                            NotifyUsersByEmail =
                                GetEmployeeSeparationErpBoolean(
                                    doc["notify_users_by_email"]
                                ),

                            ExitInterviewSummary =
                                CleanEmployeeSeparationRichText(
                                    doc["exit_interview"]
                                        ?.ToString()
                                    ?? ""
                                ),

                            DocStatus =
                                doc["docstatus"]
                                    ?.ToObject<int>()
                                ?? 0,

                            AmendedFrom =
                                doc["amended_from"]
                                    ?.ToString()
                                ?? "",

                            Activities =
                                new List<EmployeeSeparationActivity>()
                        };


                    if (string.IsNullOrWhiteSpace(
                        separation.EmployeeSeparationCode))
                    {
                        throw new Exception(
                            "ERPNext Employee Separation document name is missing."
                        );
                    }


                    // ====================================================
                    // STEP 4: MAP CHILD TABLE - activities
                    // ====================================================

                    JArray activities =
                        doc["activities"] as JArray;


                    if (activities != null)
                    {
                        foreach (JToken activity
                                 in activities)
                        {
                            separation.Activities.Add(
                                new EmployeeSeparationActivity
                                {
                                    ActivityName =
                                        activity["activity_name"]
                                            ?.ToString()
                                        ?? "",

                                    UserName =
                                        activity["user"]
                                            ?.ToString()
                                        ?? "",

                                    BeginOnDays =
                                        activity["begin_on"]
                                            ?.ToObject<int?>(),

                                    DurationDays =
                                        activity["duration"]
                                            ?.ToObject<int?>()
                                }
                            );
                        }
                    }


                    erpSeparations.Add(
                        separation
                    );
                }


                // ========================================================
                // STEP 5: PAGINATION
                // ========================================================

                if (records.Count < pageSize)
                {
                    break;
                }


                start += records.Count;
            }


            // ============================================================
            // STEP 6: SAFETY CHECK BEFORE MODIFYING LOCAL DATA
            // ============================================================

            var currentLocalRecords =
                _employeeSeparationService
                    .GetAll(
                        null,
                        null
                    );


            bool hasLinkedLocalRecords =
                currentLocalRecords.Any(
                    x =>
                        !string.IsNullOrWhiteSpace(
                            x.EmployeeSeparationCode
                        )
                );


            // If ERPNext unexpectedly returns an empty list,
            // do not mark every local record deleted.
            if (erpCodes.Count == 0 &&
                hasLinkedLocalRecords)
            {
                throw new Exception(
                    "ERPNext returned zero Employee Separation records. " +
                    "Local deletion reconciliation was stopped for safety."
                );
            }


            // ============================================================
            // STEP 7: UPSERT EVERY ERP DOCUMENT
            //
            // IMPORTANT:
            // DO NOT use Insert() here.
            // DO NOT use GetExistingCodes() + Insert() here.
            //
            // EmployeeSeparationCode is the ERP identity.
            // ============================================================

            foreach (EmployeeSeparation separation
                     in erpSeparations)
            {
                _employeeSeparationService
                    .InsertOrUpdateByCode(
                        separation
                    );

                syncedCount++;
            }


            // ============================================================
            // STEP 8: ERP DELETE -> HRMS SOFT DELETE
            // ============================================================

            var refreshedLocalRecords =
                _employeeSeparationService
                    .GetAll(
                        null,
                        null
                    );


            foreach (EmployeeSeparation local
                     in refreshedLocalRecords)
            {
                if (string.IsNullOrWhiteSpace(
                    local.EmployeeSeparationCode))
                {
                    continue;
                }


                string localCode =
                    local.EmployeeSeparationCode
                        .Trim();


                if (!erpCodes.Contains(
                    localCode))
                {
                    _employeeSeparationService
                        .MarkDeletedByCode(
                            localCode
                        );
                }
            }


            return syncedCount;
        }




        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateEmployeeOnboarding/{id:int}")]
        public async Task<ActionResult> UpdateEmployeeOnboarding(
    int id,
    EmployeeOnboarding model,
    List<string> ActivityNames,
    List<string> Users,
    List<int?> BeginOnDaysArr,
    List<int?> DurationDaysArr)
        {
            try
            {
                var existing = _employeeOnboardingService.GetById(id);

                if (existing == null)
                    return NotFound();

                if (existing.DocStatus != 0)
                {
                    TempData["ErpNextError"] = "Submitted, completed, or cancelled Employee Onboarding cannot be edited.";
                    return RedirectToAction("EmployeeOnboardingDetails", new { id });
                }

                if (string.IsNullOrWhiteSpace(existing.ErpNextId))
                    throw new Exception("This Employee Onboarding is not linked with ERPNext.");

                // ERPNext is authoritative for lifecycle state. A record may have been
                // submitted there since this HRMS page was opened.
                var currentResponse = await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Onboarding/" + Uri.EscapeDataString(existing.ErpNextId));
                var currentDocument = JObject.Parse(currentResponse)["data"];
                if (currentDocument == null)
                    throw new Exception("Employee Onboarding could not be loaded from ERPNext.");

                var currentFromErp = MapErpEmployeeOnboarding(currentDocument);
                if (currentFromErp.DocStatus != 0)
                {
                    _employeeOnboardingService.InsertOrUpdate(currentFromErp);
                    TempData["ErpNextError"] = "This Employee Onboarding is already submitted in ERPNext. HRMS has been refreshed and the form is now read-only.";
                    return RedirectToAction("EmployeeOnboardingDetails", new { id });
                }

                model.Id = existing.Id;
                model.ErpNextId = existing.ErpNextId;

                model.Activities = new List<EmployeeOnboardingActivity>();

                if (ActivityNames != null)
                {
                    for (int i = 0; i < ActivityNames.Count; i++)
                    {
                        if (string.IsNullOrWhiteSpace(ActivityNames[i]))
                            continue;

                        model.Activities.Add(new EmployeeOnboardingActivity
                        {
                            ActivityName = ActivityNames[i],
                            User = Users != null && i < Users.Count ? Users[i] : null,
                            BeginOnDays = BeginOnDaysArr != null && i < BeginOnDaysArr.Count ? BeginOnDaysArr[i] : 0,
                            DurationDays = DurationDaysArr != null && i < DurationDaysArr.Count ? DurationDaysArr[i] : 1
                        });
                    }
                }

                var payload = new
                {
                    job_applicant = model.JobApplicant,
                    job_offer = model.JobOffer,
                    employee_onboarding_template = model.EmployeeOnboardingTemplate,
                    company = model.Company,
                    employee_name = model.EmployeeName,
                    date_of_joining = model.DateOfJoining.ToString("yyyy-MM-dd"),
                    department = model.Department,
                    boarding_begins_on = model.OnboardingBeginsOn.ToString("yyyy-MM-dd"),
                    designation = model.Designation,
                    employee_grade = model.EmployeeGrade,
                    holiday_list = model.HolidayList,
                    notify_users_by_email = model.NotifyUsersByEmail ? 1 : 0,
                    activities = model.Activities.Select(a => new
                    {
                        activity_name = a.ActivityName,
                        user = a.User,
                        begin_on = a.BeginOnDays ?? 0,
                        duration = a.DurationDays ?? 1
                    }).ToList()
                };

                await _erpNextService.PutAsync(
                    "/api/resource/Employee%20Onboarding/" + Uri.EscapeDataString(existing.ErpNextId),
                    payload);

                var fullResponse = await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Onboarding/" + Uri.EscapeDataString(existing.ErpNextId));

                var doc = JObject.Parse(fullResponse)["data"];

                if (doc == null)
                    throw new Exception("Updated ERPNext Employee Onboarding could not be reloaded.");

                var saved = MapErpEmployeeOnboarding(doc);
                _employeeOnboardingService.InsertOrUpdate(saved);

                TempData["Success"] = "Employee Onboarding updated in ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Employee Onboarding update failed: " + ShortErpNextError(ex.Message);
            }

            return RedirectToAction("EmployeeOnboardingDetails", new { id });
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/SubmitEmployeeOnboarding/{id:int}")]
        public async Task<ActionResult> SubmitEmployeeOnboarding(int id)
        {
            try
            {
                var existing = _employeeOnboardingService.GetById(id);
                if (existing == null) return NotFound();
                if (existing.DocStatus != 0) throw new Exception("Only a draft Employee Onboarding can be submitted.");
                if (string.IsNullOrWhiteSpace(existing.ErpNextId)) throw new Exception("This Employee Onboarding is not linked with ERPNext.");

                var response = await _erpNextService.GetAsync("/api/resource/Employee%20Onboarding/" + Uri.EscapeDataString(existing.ErpNextId));
                var document = JObject.Parse(response)["data"];
                if (document == null) throw new Exception("Employee Onboarding could not be loaded from ERPNext.");

                await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new { doc = document });
                await RefreshEmployeeOnboardingFromErpAsync(existing.ErpNextId);
                TempData["Success"] = "Employee Onboarding submitted in ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Employee Onboarding submit failed: " + ShortErpNextError(ex.Message);
            }
            return RedirectToAction("EmployeeOnboardingDetails", new { id });
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/CompleteEmployeeOnboarding/{id:int}")]
        public async Task<ActionResult> CompleteEmployeeOnboarding(int id)
        {
            try
            {
                var existing = _employeeOnboardingService.GetById(id);
                if (existing == null) return NotFound();
                if (existing.DocStatus != 1) throw new Exception("Submit the Employee Onboarding before marking it as completed.");
                if (string.IsNullOrWhiteSpace(existing.ErpNextId)) throw new Exception("This Employee Onboarding is not linked with ERPNext.");

                await _erpNextService.PutAsync("/api/resource/Employee%20Onboarding/" + Uri.EscapeDataString(existing.ErpNextId), new { boarding_status = "Completed" });
                await RefreshEmployeeOnboardingFromErpAsync(existing.ErpNextId);
                TempData["Success"] = "Employee Onboarding marked as completed in ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Employee Onboarding completion failed: " + ShortErpNextError(ex.Message);
            }
            return RedirectToAction("EmployeeOnboardingDetails", new { id });
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/CancelEmployeeOnboarding/{id:int}")]
        public async Task<ActionResult> CancelEmployeeOnboarding(int id)
        {
            try
            {
                var existing = _employeeOnboardingService.GetById(id);
                if (existing == null) return NotFound();
                if (existing.DocStatus != 1) throw new Exception("Only a submitted Employee Onboarding can be cancelled.");
                if (string.IsNullOrWhiteSpace(existing.ErpNextId)) throw new Exception("This Employee Onboarding is not linked with ERPNext.");

                await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new { doctype = "Employee Onboarding", name = existing.ErpNextId });
                await RefreshEmployeeOnboardingFromErpAsync(existing.ErpNextId);
                TempData["Success"] = "Employee Onboarding cancelled in ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Employee Onboarding cancel failed: " + ShortErpNextError(ex.Message);
            }
            return RedirectToAction("EmployeeOnboardingDetails", new { id });
        }

        private async Task RefreshEmployeeOnboardingFromErpAsync(string erpNextId)
        {
            var response = await _erpNextService.GetAsync("/api/resource/Employee%20Onboarding/" + Uri.EscapeDataString(erpNextId));
            var document = JObject.Parse(response)["data"];
            if (document == null) throw new Exception("Employee Onboarding could not be reloaded from ERPNext.");
            _employeeOnboardingService.InsertOrUpdate(MapErpEmployeeOnboarding(document));
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteEmployeeOnboarding/{id:int}")]
        public async Task<ActionResult> DeleteEmployeeOnboarding(int id)
        {
            try
            {
                var existing = _employeeOnboardingService.GetById(id);

                if (existing == null)
                {
                    TempData["ErpNextError"] = "Employee Onboarding not found.";
                    return RedirectToAction("EmployeeOnboarding");
                }

                if (!string.IsNullOrWhiteSpace(existing.ErpNextId))
                {
                    await _erpNextService.DeleteAsync(
                        "/api/resource/Employee%20Onboarding/" + Uri.EscapeDataString(existing.ErpNextId));
                }

                _employeeOnboardingService.MarkDeletedById(id);

                TempData["Success"] = "Employee Onboarding deleted from ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Employee Onboarding delete failed: " + ShortErpNextError(ex.Message);
                return RedirectToAction("EmployeeOnboardingDetails", new { id });
            }

            return RedirectToAction("EmployeeOnboarding");
        }




        private EmployeeSeparation MapErpEmployeeSeparation(
    JToken doc)
        {
            if (doc == null)
                throw new Exception(
                    "ERPNext Employee Separation document is empty."
                );

            var model = new EmployeeSeparation
            {
                EmployeeSeparationCode =
                    doc["name"]?.ToString() ?? "",

                Employee =
                    doc["employee"]?.ToString() ?? "",

                EmployeeName =
                    doc["employee_name"]?.ToString() ?? "",

                Company =
                    doc["company"]?.ToString() ?? "",

                Status =
                    doc["boarding_status"]?.ToString()
                    ?? "Pending",

                SeparationBeginsOn =
                    ParseEmployeeSeparationDate(
                        doc["boarding_begins_on"]
                    ),

                EmployeeSeparationTemplate =
                    doc["employee_separation_template"]
                        ?.ToString()
                    ?? "",

                Department =
                    doc["department"]?.ToString() ?? "",

                Designation =
                    doc["designation"]?.ToString() ?? "",

                EmployeeGrade =
                    doc["employee_grade"]?.ToString() ?? "",

                Project =
                    doc["project"]?.ToString() ?? "",

                NotifyUsersByEmail =
                    GetEmployeeSeparationErpBoolean(
                        doc["notify_users_by_email"]
                    ),

                ExitInterviewSummary =
                    CleanEmployeeSeparationRichText(
                        doc["exit_interview"]?.ToString()
                        ?? ""
                    ),

                DocStatus =
                    doc["docstatus"]?.ToObject<int>() ?? 0,

                AmendedFrom =
                    doc["amended_from"]?.ToString() ?? "",

                Activities =
                    new List<EmployeeSeparationActivity>()
            };

            JArray activities =
                doc["activities"] as JArray;

            if (activities != null)
            {
                foreach (JToken activity in activities)
                {
                    model.Activities.Add(
                        new EmployeeSeparationActivity
                        {
                            ActivityName =
                                activity["activity_name"]
                                    ?.ToString()
                                ?? "",

                            UserName =
                                activity["user"]
                                    ?.ToString()
                                ?? "",

                            BeginOnDays =
                                activity["begin_on"]
                                    ?.ToObject<int?>(),

                            DurationDays =
                                activity["duration"]
                                    ?.ToObject<int?>()
                        }
                    );
                }
            }

            return model;
        }















        private static string NormalizeErpValue(object? value)
        {
            if (value == null)
                return "";

            if (value is JValue jValue)
                value = jValue.Value;

            if (value is JToken token)
                return NormalizeErpValue(token.Type == JTokenType.Null ? null : token.ToString());

            string text = Convert.ToString(value, System.Globalization.CultureInfo.InvariantCulture)?.Trim() ?? "";

            if (string.Equals(text, "null", StringComparison.OrdinalIgnoreCase))
                return "";

            if (DateTime.TryParse(text, out var date))
                return date.ToString("yyyy-MM-dd");

            if (decimal.TryParse(text, System.Globalization.NumberStyles.Any, System.Globalization.CultureInfo.InvariantCulture, out var number))
                return number.ToString("0.##########", System.Globalization.CultureInfo.InvariantCulture);

            return text;
        }



        private static string ShortErpNextError(string message)
        {
            if (string.IsNullOrWhiteSpace(message))
                return "Unknown ERPNext error.";

            try
            {
                int jsonStart = message.IndexOf('{');
                if (jsonStart >= 0)
                {
                    var jsonText = message.Substring(jsonStart);
                    var json = JObject.Parse(jsonText);

                    var exception = json["exception"]?.ToString();
                    if (!string.IsNullOrWhiteSpace(exception))
                    {
                        var main = exception.Contains(":")
                            ? exception.Substring(exception.IndexOf(":") + 1).Trim()
                            : exception.Trim();

                        return main;
                    }

                    var excType = json["exc_type"]?.ToString();
                    if (!string.IsNullOrWhiteSpace(excType))
                        return excType;
                }
            }
            catch
            {
            }

            var cleaned = message
                .Replace("\\n", " ")
                .Replace("\n", " ")
                .Replace("\\\"", "\"")
                .Trim();

            return cleaned.Length <= 180 ? cleaned : cleaned.Substring(0, 180) + "...";
        }


        private void ApplyEmployeeChildTablesFromRequest(Employee model)
        {
            if (model == null || !Request.HasFormContentType) return;

            var form = Request.Form;
            bool hasChildTablePost =
                form.ContainsKey("EduSchools")
                || form.ContainsKey("ExpCompanies")
                || form.ContainsKey("HistBranches");

            if (!hasChildTablePost) return;

            model.ChildTablesPosted = true;
            model.EducationRows = new List<EmployeeEducationRow>();
            model.ExternalWorkHistoryRows = new List<EmployeeExternalWorkHistoryRow>();
            model.InternalWorkHistoryRows = new List<EmployeeInternalWorkHistoryRow>();

            int educationCount = new[]
            {
        form["EduSchools"].Count,
        form["EduQualifications"].Count,
        form["EduLevels"].Count,
        form["EduYears"].Count,
        form["EduClassPercentages"].Count,
        form["EduMajorSubjects"].Count
    }.Max();

            for (int i = 0; i < educationCount; i++)
            {
                var row = new EmployeeEducationRow
                {
                    SchoolUniversity = ReadFormString(form, "EduSchools", i),
                    Qualification = ReadFormString(form, "EduQualifications", i),
                    Level = ReadFormString(form, "EduLevels", i),
                    YearOfPassing = ReadFormInt(form, "EduYears", i),
                    ClassPercentage = ReadFormString(form, "EduClassPercentages", i),
                    MajorOptionalSubjects = ReadFormString(form, "EduMajorSubjects", i)
                };

                if (HasEmployeeEducationData(row)) model.EducationRows.Add(row);
            }

            int externalCount = new[]
            {
        form["ExpCompanies"].Count,
        form["ExpDesignations"].Count,
        form["ExpSalaries"].Count,
        form["ExpAddresses"].Count,
        form["ExpContacts"].Count,
        form["ExpTotalExperiences"].Count
    }.Max();

            for (int i = 0; i < externalCount; i++)
            {
                var row = new EmployeeExternalWorkHistoryRow
                {
                    CompanyName = ReadFormString(form, "ExpCompanies", i),
                    Designation = ReadFormString(form, "ExpDesignations", i),
                    Salary = ReadFormDecimal(form, "ExpSalaries", i),
                    Address = ReadFormString(form, "ExpAddresses", i),
                    Contact = ReadFormString(form, "ExpContacts", i),
                    TotalExperience = ReadFormString(form, "ExpTotalExperiences", i)
                };

                if (HasEmployeeExternalWorkHistoryData(row)) model.ExternalWorkHistoryRows.Add(row);
            }

            int internalCount = new[]
            {
        form["HistBranches"].Count,
        form["HistDepartments"].Count,
        form["HistDesignations"].Count,
        form["HistFromDates"].Count,
        form["HistToDates"].Count
    }.Max();

            for (int i = 0; i < internalCount; i++)
            {
                var row = new EmployeeInternalWorkHistoryRow
                {
                    Branch = ReadFormString(form, "HistBranches", i),
                    Department = ReadFormString(form, "HistDepartments", i),
                    Designation = ReadFormString(form, "HistDesignations", i),
                    FromDate = ReadFormDate(form, "HistFromDates", i),
                    ToDate = ReadFormDate(form, "HistToDates", i)
                };

                if (HasEmployeeInternalWorkHistoryData(row)) model.InternalWorkHistoryRows.Add(row);
            }
        }

        private static string ReadFormString(Microsoft.AspNetCore.Http.IFormCollection form, string key)
        {
            return form.ContainsKey(key) ? form[key].ToString()?.Trim() ?? string.Empty : string.Empty;
        }

        private static int? ReadFormInt(Microsoft.AspNetCore.Http.IFormCollection form, string key)
        {
            var value = ReadFormString(form, key);
            return int.TryParse(value, out var number) ? number : (int?)null;
        }

        private static decimal? ReadFormDecimal(Microsoft.AspNetCore.Http.IFormCollection form, string key)
        {
            var value = ReadFormString(form, key);
            return decimal.TryParse(value, out var number) ? number : (decimal?)null;
        }

        private static DateTime? ReadFormDate(Microsoft.AspNetCore.Http.IFormCollection form, string key)
        {
            var value = ReadFormString(form, key);
            return DateTime.TryParse(value, out var date) ? date : (DateTime?)null;
        }

        private static string ReadFormString(Microsoft.AspNetCore.Http.IFormCollection form, string key, int index)
        {
            var values = form[key];

            if (index < 0 || index >= values.Count)
            {
                return string.Empty;
            }

            var value = values[index];
            return string.IsNullOrWhiteSpace(value) ? string.Empty : value.Trim();
        }

        private static int? ReadFormInt(Microsoft.AspNetCore.Http.IFormCollection form, string key, int index)
        {
            var value = ReadFormString(form, key, index);
            return int.TryParse(value, out var number) ? number : (int?)null;
        }

        private static decimal? ReadFormDecimal(Microsoft.AspNetCore.Http.IFormCollection form, string key, int index)
        {
            var value = ReadFormString(form, key, index);
            return decimal.TryParse(value, out var number) ? number : (decimal?)null;
        }

        private static DateTime? ReadFormDate(Microsoft.AspNetCore.Http.IFormCollection form, string key, int index)
        {
            var value = ReadFormString(form, key, index);
            return DateTime.TryParse(value, out var date) ? date : (DateTime?)null;
        }

        private static bool HasEmployeeEducationData(EmployeeEducationRow row)
        {
            return !string.IsNullOrWhiteSpace(row.SchoolUniversity)
                || !string.IsNullOrWhiteSpace(row.Qualification)
                || !string.IsNullOrWhiteSpace(row.Level)
                || row.YearOfPassing.HasValue
                || !string.IsNullOrWhiteSpace(row.ClassPercentage)
                || !string.IsNullOrWhiteSpace(row.MajorOptionalSubjects);
        }

        private static bool HasEmployeeExternalWorkHistoryData(EmployeeExternalWorkHistoryRow row)
        {
            return !string.IsNullOrWhiteSpace(row.CompanyName)
                || !string.IsNullOrWhiteSpace(row.Designation)
                || row.Salary.HasValue
                || !string.IsNullOrWhiteSpace(row.Address)
                || !string.IsNullOrWhiteSpace(row.Contact)
                || !string.IsNullOrWhiteSpace(row.TotalExperience);
        }

        private static bool HasEmployeeInternalWorkHistoryData(EmployeeInternalWorkHistoryRow row)
        {
            return !string.IsNullOrWhiteSpace(row.Branch)
                || !string.IsNullOrWhiteSpace(row.Department)
                || !string.IsNullOrWhiteSpace(row.Designation)
                || row.FromDate.HasValue
                || row.ToDate.HasValue;
        }
















        [HttpPost]
        [Route("HR/SyncFromErpNext")]
        public async Task<ActionResult> SyncFromErpNext(LeaveBlockList model)
        {
            try
            {
                var response = await _erpNextService.GetAsync("/api/resource/Leave Block List?fields=[\"name\",\"leave_block_list_name\",\"leave_type\",\"company\",\"applies_to_company\"]&limit_page_length=50");
                dynamic parsed = JsonConvert.DeserializeObject(response);

                if (parsed?.data != null && parsed.data.Count > 0)
                {
                    var item = parsed.data[0];
                    string docName = item.name?.ToString();

                    model.LeaveBlockListName = item.leave_block_list_name?.ToString() ?? docName;
                    model.LeaveType = item.leave_type?.ToString();
                    model.Company = item.company?.ToString() ?? "AITS";
                    model.AppliesToCompany = item.applies_to_company?.ToString() == "1" || item.applies_to_company?.ToString().ToLower() == "true";

                    if (!string.IsNullOrEmpty(docName))
                    {
                        var detailResponse = await _erpNextService.GetAsync($"/api/resource/Leave Block List/{Uri.EscapeDataString(docName)}");
                        dynamic detailParsed = JsonConvert.DeserializeObject(detailResponse);

                        if (detailParsed?.data != null)
                        {
                            model.BlockDates = new List<LeaveBlockListDate>();
                            if (detailParsed.data.block_days != null)
                            {
                                foreach (var d in detailParsed.data.block_days)
                                {
                                    model.BlockDates.Add(new LeaveBlockListDate
                                    {
                                        BlockDate = Convert.ToDateTime(d.block_date),
                                        Reason = d.reason?.ToString() ?? ""
                                    });
                                }
                            }

                            model.AllowedUsers = new List<LeaveBlockListAllowedUser>();
                            if (detailParsed.data.leave_block_list_allowed != null)
                            {
                                foreach (var u in detailParsed.data.leave_block_list_allowed)
                                {
                                    model.AllowedUsers.Add(new LeaveBlockListAllowedUser
                                    {
                                        AllowUser = u.allow_user?.ToString() ?? ""
                                    });
                                }
                            }
                        }
                    }

                    TempData["SuccessMessage"] = "Successfully synced data from ERPNext!";
                }
                else
                {
                    TempData["ErrorMessage"] = "No Leave Block List records found in ERPNext to sync.";
                }
            }
            catch (Exception ex)
            {
                TempData["ErrorMessage"] = "Failed to sync from ERPNext: " + ex.Message;
            }

            await PopulateDropdownsAsync();
            return View("~/Views/HR/CreateLeaveBlockList.cshtml", model);
        }



