        private async Task PopulateDropdownsAsync()
        {
            try
            {
                // Fetch Leave Types
                var leaveTypeResponse = await _erpNextService.GetAsync("/api/resource/Leave Type?fields=[\"name\"]&limit_page_length=100");
                dynamic ltParsed = JsonConvert.DeserializeObject(leaveTypeResponse);
                var leaveTypes = new List<string>();
                if (ltParsed?.data != null)
                {
                    foreach (var lt in ltParsed.data) leaveTypes.Add(lt.name.ToString());
                }
                ViewBag.LeaveTypes = leaveTypes;

                // Fetch Users for allow_user dropdown from ERPNext User resource
                var userResponse = await _erpNextService.GetAsync("/api/resource/User?fields=[\"name\",\"email\"]&limit_page_length=100");
                dynamic userParsed = JsonConvert.DeserializeObject(userResponse);
                var allowedUsers = new List<string>();
                if (userParsed?.data != null)
                {
                    foreach (var u in userParsed.data)
                    {
                        string emailOrName = u.name?.ToString() ?? u.email?.ToString();
                        allowedUsers.Add(emailOrName);
                    }
                }
                ViewBag.AllowedUsersList = allowedUsers;
            }
            catch
            {
                ViewBag.LeaveTypes = new List<string> { "Casual Leave", "Sick Leave", "Earned Leave" };
                ViewBag.AllowedUsersList = new List<string> { "Administrator", "abhivcw@gmail.com" };
            }
        }



        [HttpPost]
        [Route("HR/CreateEmployeePerformanceFeedback")]
        public async Task<ActionResult> CreateEmployeePerformanceFeedback(
    EmployeePerformanceFeedback model)
        {
            try
            {
                // ============================================================
                // 1. BASIC REQUIRED VALIDATION
                // ============================================================

                if (string.IsNullOrWhiteSpace(model.ForEmployee))
                {
                    TempData["ErpNextError"] =
                        "For Employee is required.";

                    return RedirectToAction(
                        "CreateEmployeePerformanceFeedback"
                    );
                }


                if (string.IsNullOrWhiteSpace(model.Reviewer))
                {
                    TempData["ErpNextError"] =
                        "Reviewer is required.";

                    return RedirectToAction(
                        "CreateEmployeePerformanceFeedback"
                    );
                }


                if (model.ForEmployee == model.Reviewer)
                {
                    TempData["ErpNextError"] =
                        "Employees cannot give feedback to themselves.";

                    return RedirectToAction(
                        "CreateEmployeePerformanceFeedback"
                    );
                }


                if (model.AddedOn == default(DateTime))
                {
                    model.AddedOn =
                        DateTime.Now;
                }


                if (string.IsNullOrWhiteSpace(model.Appraisal))
                {
                    TempData["ErpNextError"] =
                        "Appraisal is required.";

                    return RedirectToAction(
                        "CreateEmployeePerformanceFeedback"
                    );
                }


                // ============================================================
                // 2. VALIDATE APPRAISAL BELONGS TO SELECTED EMPLOYEE
                // ============================================================

                string appraisalResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal/" +
                        Uri.EscapeDataString(
                            model.Appraisal
                        )
                    );


                JObject appraisalJson =
                    JObject.Parse(
                        appraisalResponse
                    );


                JToken appraisalDoc =
                    appraisalJson["data"];


                if (appraisalDoc == null)
                {
                    TempData["ErpNextError"] =
                        "Selected Appraisal was not found in ERPNext.";

                    return RedirectToAction(
                        "CreateEmployeePerformanceFeedback"
                    );
                }


                string appraisalEmployee =
                    appraisalDoc["employee"]
                        ?.ToString()
                    ?? "";


                if (!string.Equals(
                    appraisalEmployee,
                    model.ForEmployee,
                    StringComparison.OrdinalIgnoreCase))
                {
                    TempData["ErpNextError"] =
                        "Selected Appraisal does not belong to the selected Employee.";

                    return RedirectToAction(
                        "CreateEmployeePerformanceFeedback"
                    );
                }


                // ============================================================
                // 3. GET ERP AUTHORITATIVE EMPLOYEE DETAILS
                // ============================================================

                string employeeResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee/" +
                        Uri.EscapeDataString(
                            model.ForEmployee
                        )
                    );


                JObject employeeJson =
                    JObject.Parse(
                        employeeResponse
                    );


                JToken employeeDoc =
                    employeeJson["data"];


                if (employeeDoc == null)
                {
                    TempData["ErpNextError"] =
                        "Selected Employee was not found in ERPNext.";

                    return RedirectToAction(
                        "CreateEmployeePerformanceFeedback"
                    );
                }


                model.EmployeeName =
                    employeeDoc["employee_name"]
                        ?.ToString()
                    ?? "";


                model.Company =
                    employeeDoc["company"]
                        ?.ToString()
                    ?? "";


                // ============================================================
                // 4. GET ERP AUTHORITATIVE REVIEWER DETAILS
                // ============================================================

                string reviewerResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee/" +
                        Uri.EscapeDataString(
                            model.Reviewer
                        )
                    );


                JObject reviewerJson =
                    JObject.Parse(
                        reviewerResponse
                    );


                JToken reviewerDoc =
                    reviewerJson["data"];


                if (reviewerDoc == null)
                {
                    TempData["ErpNextError"] =
                        "Selected Reviewer was not found in ERPNext.";

                    return RedirectToAction(
                        "CreateEmployeePerformanceFeedback"
                    );
                }


                model.ReviewerName =
                    reviewerDoc["employee_name"]
                        ?.ToString()
                    ?? "";


                // ============================================================
                // 5. APPRAISAL CYCLE
                // ============================================================

                model.AppraisalCycle =
                    appraisalDoc["appraisal_cycle"]
                        ?.ToString()
                    ?? "";


                // ============================================================
                // 6. BUILD FEEDBACK RATINGS CHILD TABLE
                //
                // IMPORTANT ERP field mappings:
                //
                // Criteria      -> criteria
                // Weightage     -> per_weightage
                // Rating        -> rating
                //
                // Do NOT send TotalScore as authority.
                // ERPNext calculates total_score.
                // ============================================================

                var ratingsPayload =
                    new List<object>();


                decimal totalWeightage = 0;


                if (model.FeedbackRatings != null)
                {
                    foreach (
                        var row
                        in model.FeedbackRatings)
                    {
                        if (row == null)
                            continue;


                        if (string.IsNullOrWhiteSpace(
                            row.Criteria))
                        {
                            continue;
                        }


                        if (row.Weightage < 0)
                        {
                            TempData["ErpNextError"] =
                                "Feedback Rating weightage cannot be negative.";

                            return RedirectToAction(
                                "CreateEmployeePerformanceFeedback"
                            );
                        }


                        if (row.Rating < 0 ||
                            row.Rating > 1)
                        {
                            TempData["ErpNextError"] =
                                "Feedback rating must be between 0 and 1.";

                            return RedirectToAction(
                                "CreateEmployeePerformanceFeedback"
                            );
                        }


                        totalWeightage +=
                            row.Weightage;


                        ratingsPayload.Add(
                            new
                            {
                                criteria =
                                    row.Criteria,

                                per_weightage =
                                    row.Weightage,

                                rating =
                                    row.Rating
                            }
                        );
                    }
                }


                // ============================================================
                // 7. VALIDATE TOTAL WEIGHTAGE
                //
                // ERP also validates this.
                // Local check is only for quicker UI feedback.
                // ============================================================

                if (
                    ratingsPayload.Count > 0 &&
                    totalWeightage != 100
                )
                {
                    TempData["ErpNextError"] =
                        "Total Feedback Rating weightage must be 100%.";

                    return RedirectToAction(
                        "CreateEmployeePerformanceFeedback"
                    );
                }


                // ============================================================
                // 8. BUILD ERP PAYLOAD
                //
                // Company, employee name, reviewer name,
                // appraisal cycle, total score are NOT trusted from browser.
                // ERP derives/recalculates them.
                // ============================================================

                var payload =
                    new
                    {
                        employee =
                            model.ForEmployee,

                        reviewer =
                            model.Reviewer,

                        added_on =
                            model.AddedOn.ToString(
                                "yyyy-MM-dd HH:mm:ss"
                            ),

                        appraisal =
                            model.Appraisal,

                        feedback =
                            string.IsNullOrWhiteSpace(
                                model.Feedback)
                                ? null
                                : model.Feedback,

                        feedback_ratings =
                            ratingsPayload
                    };


                // ============================================================
                // 9. CREATE IN ERP FIRST
                // ============================================================

                string createResponse =
                    await _erpNextService.PostAsync(
                        "/api/resource/Employee%20Performance%20Feedback",
                        payload
                    );


                JObject createJson =
                    JObject.Parse(
                        createResponse
                    );


                string erpId =
                    createJson["data"]?["name"]
                        ?.ToString();


                if (string.IsNullOrWhiteSpace(
                    erpId))
                {
                    throw new Exception(
                        "ERPNext created the feedback but did not return the document ID."
                    );
                }


                // ============================================================
                // 10. READ FULL ERP DOCUMENT BACK
                //
                // This is important because ERP calculates:
                // employee_name
                // reviewer_name
                // company
                // appraisal_cycle
                // total_score
                // docstatus
                // rating rows
                // ============================================================

                string fullResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Performance%20Feedback/" +
                        Uri.EscapeDataString(
                            erpId
                        )
                    );


                JObject fullJson =
                    JObject.Parse(
                        fullResponse
                    );


                JToken fullDoc =
                    fullJson["data"];


                if (fullDoc == null)
                {
                    throw new Exception(
                        "Feedback was created in ERPNext but could not be reloaded."
                    );
                }


                // ============================================================
                // 11. MAP ERP -> LOCAL MODEL
                // ============================================================

                EmployeePerformanceFeedback localModel =
                    MapErpEmployeePerformanceFeedback(
                        fullDoc
                    );


                // ============================================================
                // 12. SAVE LOCALLY ONLY AFTER ERP SUCCESS
                // ============================================================

                int localId =
                    _employeePerformanceFeedbackService
                        .InsertOrUpdate(
                            localModel
                        );


                // ============================================================
                // 13. SUCCESS
                // ============================================================

                TempData["Success"] =
                    "Employee Performance Feedback created successfully. " +
                    "ERPNext Ref: " +
                    erpId;


                return RedirectToAction(
                    "EmployeePerformanceFeedbackDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                // ============================================================
                // ERP REJECTED -> DO NOT SAVE LOCAL DATA
                // ============================================================

                TempData["ErpNextError"] =
                    CleanEmployeePerformanceFeedbackErpError(
                        ex.Message
                    );


                return RedirectToAction(
                    "CreateEmployeePerformanceFeedback"
                );
            }
        }


        private string CleanEmployeePerformanceFeedbackErpError(
    string rawError)
        {
            if (string.IsNullOrWhiteSpace(rawError))
            {
                return "ERPNext operation failed.";
            }

            try
            {
                int jsonStart =
                    rawError.IndexOf('{');

                if (jsonStart >= 0)
                {
                    string jsonPart =
                        rawError.Substring(jsonStart);

                    JObject json =
                        JObject.Parse(jsonPart);

                    JToken serverMessages =
                        json["_server_messages"];

                    if (serverMessages != null)
                    {
                        JArray messages =
                            JArray.Parse(
                                serverMessages.ToString()
                            );

                        if (messages.Count > 0)
                        {
                            JObject messageObject =
                                JObject.Parse(
                                    messages[0].ToString()
                                );

                            string message =
                                messageObject["message"]
                                    ?.ToString();

                            if (!string.IsNullOrWhiteSpace(
                                message))
                            {
                                message =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        message,
                                        "<[^>]*>",
                                        " "
                                    );

                                message =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        message,
                                        @"\s+",
                                        " "
                                    ).Trim();

                                return System.Net.WebUtility.HtmlDecode(
                                    message
                                );
                            }
                        }
                    }
                }
            }
            catch
            {
                // fall through
            }

            return rawError;
        }



