        // GET: HR/CreateEmployeeOnboardingTemplate
        [HttpGet]
        [Route("HR/CreateEmployeeOnboardingTemplate")]
        public async Task<ActionResult>
            CreateEmployeeOnboardingTemplate()
        {
            try
            {
                // ============================================================
                // COMPANY
                // ERP Link -> Company
                // ============================================================

                var companyJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Company" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=1000"
                    );

                dynamic companyParsed =
                    JsonConvert.DeserializeObject(
                        companyJson
                    );

                ViewBag.Companies =
                    companyParsed?.data;


                // ============================================================
                // DEPARTMENT
                // ERP Link -> Department
                // ============================================================

                var departmentJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Department" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=1000"
                    );

                dynamic departmentParsed =
                    JsonConvert.DeserializeObject(
                        departmentJson
                    );

                ViewBag.Departments =
                    departmentParsed?.data;


                // ============================================================
                // DESIGNATION
                // ERP Link -> Designation
                // ============================================================

                var designationJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Designation" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=1000"
                    );

                dynamic designationParsed =
                    JsonConvert.DeserializeObject(
                        designationJson
                    );

                ViewBag.Designations =
                    designationParsed?.data;


                // ============================================================
                // EMPLOYEE GRADE
                // ERP Link -> Employee Grade
                // ============================================================

                var gradeJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Grade" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=1000"
                    );

                dynamic gradeParsed =
                    JsonConvert.DeserializeObject(
                        gradeJson
                    );

                ViewBag.EmployeeGrades =
                    gradeParsed?.data;


                // ============================================================
                // USER
                // ERP Link -> User
                // ============================================================

                var userJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/User" +
                        "?fields=[\"name\",\"full_name\",\"enabled\"]" +
                        "&filters=[[\"enabled\",\"=\",1]]" +
                        "&limit_page_length=1000"
                    );

                dynamic userParsed =
                    JsonConvert.DeserializeObject(
                        userJson
                    );

                ViewBag.Users =
                    userParsed?.data;
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Unable to load ERPNext dropdown data: "
                    + ex.Message;

                ViewBag.Companies = null;
                ViewBag.Departments = null;
                ViewBag.Designations = null;
                ViewBag.EmployeeGrades = null;
                ViewBag.Users = null;
            }


            return View(
                "~/Views/HR/CreateEmployeeOnboardingTemplate.cshtml",
                new EmployeeOnboardingTemplate()
            );
        }



        private async Task PullEmployeeOnboardingTemplatesFromErpNext()
        {
            string listResponse =
                await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Onboarding%20Template" +
                    "?fields=[\"name\"]" +
                    "&limit_page_length=5000"
                );

            JObject listJson = JObject.Parse(listResponse);
            JArray records = listJson["data"] as JArray;

            var remoteIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (records != null)
            {
                foreach (JToken item in records)
                {
                    string erpId = item["name"]?.ToString();

                    if (string.IsNullOrWhiteSpace(erpId))
                        continue;

                    remoteIds.Add(erpId);

                    string detailResponse =
                        await _erpNextService.GetAsync(
                            "/api/resource/Employee%20Onboarding%20Template/" +
                            Uri.EscapeDataString(erpId)
                        );

                    JObject detailJson = JObject.Parse(detailResponse);
                    JToken doc = detailJson["data"];

                    if (doc == null)
                        continue;

                    EmployeeOnboardingTemplate model =
                        MapErpEmployeeOnboardingTemplate(doc);

                    _employeeOnboardingTemplateService.InsertOrUpdate(model);
                }
            }

            _employeeOnboardingTemplateService
                .MarkMissingErpNextTemplatesAsDeleted(remoteIds);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/SyncEmployeeOnboardingTemplatesFromErpNext")]
        public async Task<ActionResult> SyncEmployeeOnboardingTemplatesFromErpNext()
        {
            try
            {
                await PullEmployeeOnboardingTemplatesFromErpNext();

                TempData["Success"] =
                    "Employee Onboarding Template synced from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext sync failed: " + ShortErpNextError(ex.Message);
            }

            return RedirectToAction("EmployeeOnboardingTemplate");
        }


        private EmployeeOnboardingTemplate
    MapErpEmployeeOnboardingTemplate(
        JToken doc)
        {
            var model =
                new EmployeeOnboardingTemplate
                {
                    ErpNextId =
                        doc["name"]
                            ?.ToString()
                        ?? "",

                    Title =
                        doc["title"]
                            ?.ToString()
                        ?? "",

                    Company =
                        doc["company"]
                            ?.ToString()
                        ?? "",

                    Department =
                        doc["department"]
                            ?.ToString()
                        ?? "",

                    Designation =
                        doc["designation"]
                            ?.ToString()
                        ?? "",

                    EmployeeGrade =
                        doc["employee_grade"]
                            ?.ToString()
                        ?? "",

                    Activities =
                        new List<EmployeeOnboardingTemplateActivity>()
                };


            JArray activities =
                doc["activities"] as JArray;


            if (activities != null)
            {
                foreach (
                    JToken activity
                    in activities)
                {
                    model.Activities.Add(
                        new EmployeeOnboardingTemplateActivity
                        {
                            ActivityName =
                                activity["activity_name"]
                                    ?.ToString()
                                ?? "",

                            UserName =
                                activity["user"]
                                    ?.ToString()
                                ?? "",

                            BeginOnDays =
                                activity["begin_on"]
                                    ?.ToObject<int?>(),

                            DurationDays =
                                activity["duration"]
                                    ?.ToObject<int?>()
                        }
                    );
                }
            }


            return model;
        }










        // POST: HR/SyncEmployeeOnboardingTemplatesToServerToErpNext
        [HttpPost]
        [Route("HR/SyncEmployeeOnboardingTemplatesToServerToErpNext")]
        public async Task<ActionResult> SyncEmployeeOnboardingTemplatesToServerToErpNext()
        {
            int successCount = 0;
            int failCount = 0;

            try
            {
                var unsyncedTemplates = _employeeOnboardingTemplateService.GetUnsynced();

                foreach (var model in unsyncedTemplates)
                {
                    try
                    {
                        // Ensure dependent masters exist in ERPNext
                        if (!string.IsNullOrWhiteSpace(model.Designation)) await EnsureDocExistsAsync("Designation", model.Designation);
                        if (!string.IsNullOrWhiteSpace(model.Department)) await EnsureDocExistsAsync("Department", model.Department);
                        if (!string.IsNullOrWhiteSpace(model.EmployeeGrade)) await EnsureDocExistsAsync("Employee Grade", model.EmployeeGrade);

                        // Build activities child table payload
                        var activitiesList = new List<object>();
                        if (model.Activities != null)
                        {
                            foreach (var act in model.Activities)
                            {
                                if (string.IsNullOrWhiteSpace(act.ActivityName)) continue;
                                activitiesList.Add(new
                                {
                                    activity_name = act.ActivityName,
                                    user = act.UserName,
                                    begin_on_days = act.BeginOnDays,
                                    duration_days = act.DurationDays
                                });
                            }
                        }

                        var payload = new
                        {
                            title = model.Title,
                            designation = model.Designation,
                            company = model.Company,
                            employee_grade = model.EmployeeGrade,
                            department = model.Department,
                            activities = activitiesList
                        };

                        var responseJson = await _erpNextService.PostAsync("/api/resource/Employee%20Onboarding%20Template", payload);
                        dynamic responseParsed = JsonConvert.DeserializeObject(responseJson);
                        string erpNextId = responseParsed?.data?.name;

                        if (!string.IsNullOrEmpty(erpNextId))
                        {
                            _employeeOnboardingTemplateService.UpdateErpNextId(model.Id, erpNextId);
                            successCount++;
                        }
                    }
                    catch
                    {
                        failCount++;
                    }
                }

                if (successCount > 0)
                {
                    TempData["Success"] = $"Synced {successCount} local template(s) to ERPNext successfully!" + (failCount > 0 ? $" ({failCount} failed)" : "");
                }
                else if (failCount > 0)
                {
                    TempData["ErpNextError"] = $"Failed to sync {failCount} template(s) to ERPNext.";
                }
                else
                {
                    TempData["Success"] = "All local templates are already synced with ERPNext!";
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Push error: " + ex.Message;
            }

            return RedirectToAction("EmployeeOnboardingTemplate");
        }

       

        // POST: HR/CreateEmployeeOnboardingTemplate
        [HttpPost]
        [Route("HR/CreateEmployeeOnboardingTemplate")]
        public async Task<ActionResult>
            CreateEmployeeOnboardingTemplate(
                EmployeeOnboardingTemplate model)
        {
            try
            {
                // ============================================================
                // REQUIRED ERP FIELD
                // ============================================================

                if (string.IsNullOrWhiteSpace(
                    model.Title))
                {
                    TempData["ErpNextError"] =
                        "Title is required.";

                    return RedirectToAction(
                        "CreateEmployeeOnboardingTemplate"
                    );
                }


                // ============================================================
                // BUILD ACTIVITIES
                //
                // Correct ERP child field names:
                // activity_name
                // user
                // begin_on
                // duration
                // ============================================================

                var activities =
                    new List<object>();


                if (model.Activities != null)
                {
                    foreach (
                        var activity
                        in model.Activities)
                    {
                        if (string.IsNullOrWhiteSpace(
                            activity.ActivityName))
                        {
                            continue;
                        }


                        activities.Add(
                            new
                            {
                                activity_name =
                                    activity.ActivityName,

                                user =
                                    string.IsNullOrWhiteSpace(
                                        activity.UserName)
                                        ? null
                                        : activity.UserName,

                                begin_on =
                                    activity.BeginOnDays
                                    ?? 0,

                                duration =
                                    activity.DurationDays
                                    ?? 0
                            }
                        );
                    }
                }


                // ============================================================
                // ERP PAYLOAD
                // ============================================================

                var payload =
                    new
                    {
                        title =
                            model.Title,

                        company =
                            string.IsNullOrWhiteSpace(
                                model.Company)
                                ? null
                                : model.Company,

                        department =
                            string.IsNullOrWhiteSpace(
                                model.Department)
                                ? null
                                : model.Department,

                        designation =
                            string.IsNullOrWhiteSpace(
                                model.Designation)
                                ? null
                                : model.Designation,

                        employee_grade =
                            string.IsNullOrWhiteSpace(
                                model.EmployeeGrade)
                                ? null
                                : model.EmployeeGrade,

                        activities =
                            activities
                    };


                // ============================================================
                // ERP FIRST
                // ============================================================

                string response =
                    await _erpNextService.PostAsync(
                        "/api/resource/Employee%20Onboarding%20Template",
                        payload
                    );


                JObject responseJson =
                    JObject.Parse(
                        response
                    );


                string erpId =
                    responseJson["data"]?["name"]
                        ?.ToString();


                if (string.IsNullOrWhiteSpace(
                    erpId))
                {
                    throw new Exception(
                        "ERPNext did not return Employee Onboarding Template ID."
                    );
                }


                // ============================================================
                // READ FULL ERP DOCUMENT BACK
                // ============================================================

                string fullResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Onboarding%20Template/" +
                        Uri.EscapeDataString(
                            erpId
                        )
                    );


                JObject fullJson =
                    JObject.Parse(
                        fullResponse
                    );


                JToken doc =
                    fullJson["data"];


                if (doc == null)
                {
                    throw new Exception(
                        "Template was created in ERPNext but could not be reloaded."
                    );
                }


                EmployeeOnboardingTemplate localModel =
                    MapErpEmployeeOnboardingTemplate(
                        doc
                    );


                int localId =
                    _employeeOnboardingTemplateService
                        .InsertOrUpdate(
                            localModel
                        );


                TempData["Success"] =
                    "Employee Onboarding Template created successfully. ERPNext Ref: "
                    + erpId;


                return RedirectToAction(
                    "EmployeeOnboardingTemplateDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                // ERP rejects -> no local save

                TempData["ErpNextError"] =
                    "ERPNext rejected Employee Onboarding Template: "
                    + ex.Message;


                return RedirectToAction(
                    "CreateEmployeeOnboardingTemplate"
                );
            }
        }

