        // POST: HR/CreateDesignation (Local Server -> ERPNext Sync)
        [HttpPost]
        [Route("HR/CreateDesignation")]
        public async Task<ActionResult> CreateDesignation(Designation model, string[] Skills)
        {
            model.Skills = new List<DesignationSkill>();
            if (Skills != null)
            {
                foreach (var s in Skills)
                {
                    if (!string.IsNullOrWhiteSpace(s))
                    {
                        model.Skills.Add(new DesignationSkill { Skill = s.Trim() });
                    }
                }
            }

            try
            {
                // 1. Ensure Appraisal Template exists in ERPNext (Auto-create missing KRA + Template)
                if (!string.IsNullOrWhiteSpace(model.AppraisalTemplate))
                {
                    try
                    {
                        await _erpNextService.GetAsync($"/api/resource/Appraisal%20Template/{Uri.EscapeDataString(model.AppraisalTemplate)}");
                    }
                    catch
                    {
                        string kraName = "General Performance";

                        // Ensure KRA exists in ERPNext
                        try
                        {
                            await _erpNextService.GetAsync($"/api/resource/KRA/{Uri.EscapeDataString(kraName)}");
                        }
                        catch
                        {
                            var kraPayload = new { title = kraName };
                            await _erpNextService.PostAsync("/api/resource/KRA", kraPayload);
                        }

                        // Create Appraisal Template
                        var templatePayload = new
                        {
                            template_title = model.AppraisalTemplate,
                            goals = new[]
                            {
                        new
                        {
                            key_result_area = kraName,
                            per_weightage = 100
                        }
                    }
                        };

                        await _erpNextService.PostAsync("/api/resource/Appraisal%20Template", templatePayload);
                    }
                }

                // 2. Ensure Skills exist in ERPNext
                var skillsPayloadList = new List<object>();
                foreach (var sk in model.Skills)
                {
                    try
                    {
                        await _erpNextService.GetAsync($"/api/resource/Skill/{Uri.EscapeDataString(sk.Skill)}");
                    }
                    catch
                    {
                        var skillPayload = new { skill_name = sk.Skill };
                        await _erpNextService.PostAsync("/api/resource/Skill", skillPayload);
                    }

                    skillsPayloadList.Add(new { skill = sk.Skill });
                }

                // 3. Build ERPNext Designation Payload
                var payload = new
                {
                    designation_name = model.DesignationName,
                    description = model.Description,
                    appraisal_template = string.IsNullOrWhiteSpace(model.AppraisalTemplate) ? null : model.AppraisalTemplate,
                    skills = skillsPayloadList
                };

                // 4. Sync to ERPNext REST API
                var resultJson = await _erpNextService.PostAsync("/api/resource/Designation", payload);
                dynamic parsed = JsonConvert.DeserializeObject(resultJson);
                string erpNextId = parsed?.data?.name;

                // 5. Upsert locally to prevent duplicate key crashes
                var existing = _designationService.GetByName(model.DesignationName);
                if (existing != null)
                {
                    model.DesignationCode = erpNextId ?? existing.DesignationCode;
                    _designationService.UpdateDesignationByName(model);
                    TempData["Success"] = $"Designation updated locally and synced to ERPNext (ID: {erpNextId})!";
                }
                else
                {
                    model.DesignationCode = erpNextId;
                    _designationService.InsertDesignation(model);
                    TempData["Success"] = $"Designation created locally and synced to ERPNext (ID: {erpNextId})!";
                }
            }
            catch (Exception ex)
            {
                try
                {
                    var existing = _designationService.GetByName(model.DesignationName);
                    if (existing != null)
                    {
                        _designationService.UpdateDesignationByName(model);
                    }
                    else
                    {
                        _designationService.InsertDesignation(model);
                    }
                    TempData["ErpNextError"] = "Saved locally, but ERPNext sync failed: " + ex.Message;
                }
                catch (Exception dbEx)
                {
                    TempData["ErpNextError"] = "Failed locally and ERPNext sync failed: " + dbEx.Message;
                }
            }

            return RedirectToAction("Designation");
        }
        //// GET: HR/Department
        //[HttpGet]
        //public ActionResult Department()
        //{
        //    var list = _departmentService.GetAllDepartments();
        //    return View("Department", list);
        //}


        private async Task PullDepartmentsFromErpNext()
        {
            var localDepartments = _departmentService.GetAllDepartments();
            //var localByCode = localDepartments
            //    .Where(x => !string.IsNullOrWhiteSpace(x.DepartmentCode))
            //    .ToDictionary(x => x.DepartmentCode, x => x, StringComparer.OrdinalIgnoreCase);
            var localByCode = localDepartments
    .Where(x => !string.IsNullOrWhiteSpace(x.DepartmentCode))
    .GroupBy(x => x.DepartmentCode, StringComparer.OrdinalIgnoreCase)
    .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

            string jsonResponse = await _erpNextService.GetAsync(
                "/api/resource/Department?fields=[\"name\",\"department_name\",\"company\",\"parent_department\",\"is_group\",\"disabled\",\"payroll_cost_center\",\"leave_block_list\"]&limit_page_length=5000");

            dynamic parsed = JsonConvert.DeserializeObject(jsonResponse);

            var erpCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (parsed?.data != null)
            {
                foreach (var item in parsed.data)
                {
                    string erpName = item.name?.ToString() ?? "";
                    string deptName = item.department_name?.ToString() ?? erpName;

                    if (string.IsNullOrWhiteSpace(erpName))
                        continue;

                    erpCodes.Add(erpName);

                    bool disabled = item.disabled != null && Convert.ToBoolean(item.disabled);

                    var dep = new Department
                    {
                        DepartmentCode = erpName,
                        DepartmentName = deptName,
                        Company = item.company?.ToString() ?? "Vinod Cookware India Private Limited",
                        ParentDepartment = item.parent_department?.ToString() ?? "",
                        IsGroup = item.is_group != null && Convert.ToBoolean(item.is_group),
                        Disabled = disabled,
                        PayrollCostCenter = item.payroll_cost_center?.ToString() ?? "",
                        LeaveBlockList = item.leave_block_list?.ToString() ?? "",
                        Status = disabled ? "Disabled" : "Active"
                    };

                    if (localByCode.TryGetValue(erpName, out var existing))
                    {
                        dep.Id = existing.Id;
                        _departmentService.UpdateDepartmentById(dep);
                    }
                    else
                    {
                        _departmentService.InsertDepartment(dep);
                    }
                }
            }

            foreach (var local in localDepartments)
            {
                if (!string.IsNullOrWhiteSpace(local.DepartmentCode) &&
                    !erpCodes.Contains(local.DepartmentCode))
                {
                    _departmentService.MarkDeletedById(local.Id);
                }
            }
        }

        [HttpGet]
        [Route("HR/DepartmentDetails/{id:int}")]
        public async Task<ActionResult> DepartmentDetails(int id, bool edit = false)
        {
            var model = _departmentService.GetById(id);

            if (model == null)
                return NotFound();

            await LoadDepartmentDropdowns();

            try
            {
                string erpId = !string.IsNullOrWhiteSpace(model.DepartmentCode)
                    ? model.DepartmentCode
                    : model.DepartmentName;

                if (!string.IsNullOrWhiteSpace(erpId))
                {
                    string json = await _erpNextService.GetAsync(
                        "/api/resource/Department/" + Uri.EscapeDataString(erpId));

                    dynamic parsed = JsonConvert.DeserializeObject(json);
                    dynamic data = parsed?.data;

                    if (data != null)
                    {
                        model.DepartmentCode = data.name?.ToString() ?? model.DepartmentCode;
                        model.DepartmentName = data.department_name?.ToString() ?? model.DepartmentName;
                        model.Company = data.company?.ToString() ?? model.Company;
                        model.ParentDepartment = data.parent_department?.ToString() ?? model.ParentDepartment;
                        model.IsGroup = data.is_group != null && Convert.ToBoolean(data.is_group);
                        model.Disabled = data.disabled != null && Convert.ToBoolean(data.disabled);
                        model.PayrollCostCenter = data.payroll_cost_center?.ToString() ?? model.PayrollCostCenter;
                        model.LeaveBlockList = data.leave_block_list?.ToString() ?? model.LeaveBlockList;
                        model.Status = model.Disabled ? "Disabled" : "Active";

                        model.ShiftRequestApprovers = new List<DepartmentApprover>();
                        model.LeaveApprovers = new List<DepartmentApprover>();
                        model.ExpenseApprovers = new List<DepartmentApprover>();

                        if (data.shift_request_approver != null)
                        {
                            foreach (var row in data.shift_request_approver)
                            {
                                string approver = row.approver?.ToString();
                                if (!string.IsNullOrWhiteSpace(approver))
                                    model.ShiftRequestApprovers.Add(new DepartmentApprover { Approver = approver });
                            }
                        }

                        if (data.leave_approvers != null)
                        {
                            foreach (var row in data.leave_approvers)
                            {
                                string approver = row.approver?.ToString();
                                if (!string.IsNullOrWhiteSpace(approver))
                                    model.LeaveApprovers.Add(new DepartmentApprover { Approver = approver });
                            }
                        }

                        if (data.expense_approvers != null)
                        {
                            foreach (var row in data.expense_approvers)
                            {
                                string approver = row.approver?.ToString();
                                if (!string.IsNullOrWhiteSpace(approver))
                                    model.ExpenseApprovers.Add(new DepartmentApprover { Approver = approver });
                            }
                        }
                    }
                }
            }
            catch
            {
                // If ERPNext is unavailable, still show local HRMS data.
            }

            ViewBag.IsEdit = edit;
            return View("DepartmentDetails", model);
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateDepartment/{id:int}")]
        public async Task<ActionResult> UpdateDepartment(int id, Department model)
        {
            try
            {
                var existing = _departmentService.GetById(id);

                if (existing == null)
                    return NotFound();

                if (model == null || string.IsNullOrWhiteSpace(model.DepartmentName))
                    throw new Exception("Department Name is required.");

                string erpId = !string.IsNullOrWhiteSpace(existing.DepartmentCode)
                    ? existing.DepartmentCode
                    : existing.DepartmentName;

                string company = string.IsNullOrWhiteSpace(model.Company)
                    ? "Vinod Cookware India Private Limited"
                    : model.Company;

                var payload = new
                {
                    department_name = model.DepartmentName.Trim(),
                    company = company,
                    parent_department = string.IsNullOrWhiteSpace(model.ParentDepartment) ? null : model.ParentDepartment,
                    is_group = model.IsGroup ? 1 : 0,
                    disabled = model.Disabled ? 1 : 0,
                    payroll_cost_center = string.IsNullOrWhiteSpace(model.PayrollCostCenter) ? null : model.PayrollCostCenter,
                    leave_block_list = string.IsNullOrWhiteSpace(model.LeaveBlockList) ? null : model.LeaveBlockList
                };

                await _erpNextService.PutAsync(
                    "/api/resource/Department/" + Uri.EscapeDataString(erpId),
                    payload);

                string updatedJson = await _erpNextService.GetAsync(
                    "/api/resource/Department/" + Uri.EscapeDataString(erpId));

                dynamic parsed = JsonConvert.DeserializeObject(updatedJson);
                dynamic data = parsed?.data;

                bool disabled = data?.disabled != null && Convert.ToBoolean(data.disabled);

                var saved = new Department
                {
                    Id = existing.Id,
                    DepartmentCode = data?.name?.ToString() ?? erpId,
                    DepartmentName = data?.department_name?.ToString() ?? model.DepartmentName.Trim(),
                    Company = data?.company?.ToString() ?? company,
                    ParentDepartment = data?.parent_department?.ToString() ?? "",
                    IsGroup = data?.is_group != null && Convert.ToBoolean(data.is_group),
                    Disabled = disabled,
                    PayrollCostCenter = data?.payroll_cost_center?.ToString() ?? "",
                    LeaveBlockList = data?.leave_block_list?.ToString() ?? "",
                    Status = disabled ? "Disabled" : "Active"
                };

                _departmentService.UpdateDepartmentById(saved);

                TempData["Success"] = "Department updated in ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Department update failed: " + ShortErpNextError(ex.Message);
                return RedirectToAction("DepartmentDetails", new { id, edit = true });
            }

            return RedirectToAction("DepartmentDetails", new { id });
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteDepartment/{id:int}")]
        public async Task<ActionResult> DeleteDepartment(int id)
        {
            var model = _departmentService.GetById(id);

            if (model == null)
                return RedirectToAction("Department");

            try
            {
                string erpId = !string.IsNullOrWhiteSpace(model.DepartmentCode)
                    ? model.DepartmentCode
                    : model.DepartmentName;

                if (!string.IsNullOrWhiteSpace(erpId))
                {
                    try
                    {
                        await _erpNextService.DeleteAsync(
                            "/api/resource/Department/" + Uri.EscapeDataString(erpId));
                    }
                    catch (Exception ex) when (IsErpNextMissing(ex))
                    {
                    }
                }

                _departmentService.MarkDeletedById(id);

                TempData["Success"] = "Department deleted from ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Department delete failed: " + ShortErpNextError(ex.Message);
                return RedirectToAction("DepartmentDetails", new { id });
            }

            return RedirectToAction("Department");
        }

