        private async Task<int> RefreshBranchesFromErpNextAsync()
        {
            const int pageSize = 100;

            int start = 0;
            int syncedCount = 0;

            var erpNames = new HashSet<string>(
                StringComparer.OrdinalIgnoreCase
            );

            var erpBranches = new List<(string ErpName, string BranchName)>();


            // ============================================================
            // STEP 1: FETCH ERPNext BRANCH LIST
            // Only "name" is safe in list query.
            // ============================================================

            while (true)
            {
                string listUrl =
                    "/api/resource/Branch" +
                    "?fields=" +
                    Uri.EscapeDataString("[\"name\"]") +
                    "&limit_start=" + start +
                    "&limit_page_length=" + pageSize +
                    "&order_by=" +
                    Uri.EscapeDataString("name asc");


                string listResponse =
                    await _erpNextService.GetAsync(
                        listUrl
                    );


                JObject listJson =
                    JObject.Parse(
                        listResponse
                    );


                JArray rows =
                    listJson["data"] as JArray;


                if (rows == null)
                {
                    throw new Exception(
                        "Invalid ERPNext Branch list response."
                    );
                }


                // ========================================================
                // STEP 2: FETCH COMPLETE BRANCH DOCUMENT
                // ========================================================

                foreach (JToken row in rows)
                {
                    string erpName =
                        row["name"]
                            ?.ToString()
                            ?.Trim();


                    if (string.IsNullOrWhiteSpace(erpName))
                    {
                        throw new Exception(
                            "ERPNext returned a Branch without document name."
                        );
                    }


                    if (!erpNames.Add(erpName))
                    {
                        continue;
                    }


                    string detailUrl =
                        "/api/resource/Branch/" +
                        Uri.EscapeDataString(
                            erpName
                        );


                    string detailResponse =
                        await _erpNextService.GetAsync(
                            detailUrl
                        );


                    JObject detailJson =
                        JObject.Parse(
                            detailResponse
                        );


                    JToken doc =
                        detailJson["data"];


                    if (doc == null)
                    {
                        throw new Exception(
                            "Unable to load Branch details: " +
                            erpName
                        );
                    }


                    // ====================================================
                    // STEP 3: GET DISPLAY BRANCH NAME
                    //
                    // ERP installations may expose slightly different
                    // fields. Prefer "branch", then "branch_name",
                    // otherwise use document name.
                    // ====================================================

                    string branchName =
                        doc["branch"]
                            ?.ToString()
                            ?.Trim();


                    if (string.IsNullOrWhiteSpace(branchName))
                    {
                        branchName =
                            doc["branch_name"]
                                ?.ToString()
                                ?.Trim();
                    }


                    if (string.IsNullOrWhiteSpace(branchName))
                    {
                        branchName =
                            doc["name"]
                                ?.ToString()
                                ?.Trim();
                    }


                    if (string.IsNullOrWhiteSpace(branchName))
                    {
                        branchName = erpName;
                    }


                    erpBranches.Add(
                        (
                            erpName,
                            branchName
                        )
                    );
                }


                // ========================================================
                // STEP 4: PAGINATION
                // ========================================================

                if (rows.Count < pageSize)
                {
                    break;
                }


                start += rows.Count;
            }


            // ============================================================
            // STEP 5: SAFETY CHECK
            // ============================================================

            var localBefore =
                _branchService.GetAllBranches();


            bool hasLinkedLocalBranches =
                localBefore.Any(
                    x =>
                        !string.IsNullOrWhiteSpace(
                            x.ErpName
                        )
                );


            if (erpNames.Count == 0 &&
                hasLinkedLocalBranches)
            {
                throw new Exception(
                    "ERPNext returned zero Branch records. " +
                    "Local deletion reconciliation was stopped for safety."
                );
            }


            // ============================================================
            // STEP 6: ERPNext -> HRMS INSERT / UPDATE
            // ============================================================

            foreach (var item in erpBranches)
            {
                _branchService
                    .InsertOrUpdateFromErpNext(
                        item.ErpName,
                        item.BranchName
                    );

                syncedCount++;
            }


            // ============================================================
            // STEP 7: ERP DELETE -> HRMS SOFT DELETE
            // ============================================================

            var localAfter =
                _branchService.GetAllBranches();


            foreach (Branch local in localAfter)
            {
                if (string.IsNullOrWhiteSpace(
                    local.ErpName))
                {
                    continue;
                }


                string localErpName =
                    local.ErpName.Trim();


                if (!erpNames.Contains(
                    localErpName))
                {
                    _branchService
                        .MarkDeletedByErpName(
                            localErpName
                        );
                }
            }


            return syncedCount;
        }










