        // POST: HR/SyncDepartmentsFromErpNext
        [HttpPost]
        public async Task<ActionResult> SyncDepartmentsFromErpNext()
        {
            try
            {
                var existingNames = _departmentService.GetExistingDepartmentNames();

                // Fetch ALL past and present departments
                string listUrl = "/api/resource/Department?fields=[\"*\"]&limit_page_length=5000";
                var jsonResponse = await _erpNextService.GetAsync(listUrl);
                dynamic parsed = JsonConvert.DeserializeObject(jsonResponse);

                if (parsed == null || parsed.data == null)
                {
                    TempData["ErpNextError"] = "No departments returned from ERPNext.";
                    return RedirectToAction("Department");
                }

                int totalFromErp = parsed.data.Count;
                int newInserted = 0;
                int existingUpdated = 0;

                foreach (var item in parsed.data)
                {
                    string deptName = item.department_name?.ToString() ?? item.name?.ToString();
                    if (string.IsNullOrEmpty(deptName)) continue;

                    bool isDisabled = item.disabled != null && Convert.ToBoolean(item.disabled);

                    var dept = new Department
                    {
                        DepartmentName = deptName,
                        Company = item.company?.ToString() ?? "Vinod Cookware India Private Limited",
                        ParentDepartment = item.parent_department?.ToString() ?? "",
                        IsGroup = item.is_group != null && Convert.ToBoolean(item.is_group),
                        Disabled = isDisabled,
                        PayrollCostCenter = item.payroll_cost_center?.ToString() ?? "",
                        LeaveBlockList = item.leave_block_list?.ToString() ?? "",
                        Status = isDisabled ? "Disabled" : "Active"
                    };

                    try
                    {
                        if (existingNames.Contains(deptName))
                        {
                            _departmentService.UpdateDepartmentByName(dept);
                            existingUpdated++;
                        }
                        else
                        {
                            _departmentService.InsertDepartment(dept);
                            newInserted++;
                            existingNames.Add(deptName);
                        }
                    }
                    catch { }
                }

                TempData["Success"] = $"Synced successfully! Total ERPNext Departments: {totalFromErp} (New added: {newInserted}, Updated: {existingUpdated}).";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("Department");
        }

