        [HttpPost("HR/CreateDepartment")]
        public async Task<ActionResult> CreateDepartmentPost(
            Department model,
            string[] ShiftApprovers,
            string[] LeaveApprovers,
            string[] ExpenseApprovers)
        {
            model.ShiftRequestApprovers = new List<DepartmentApprover>();
            model.LeaveApprovers = new List<DepartmentApprover>();
            model.ExpenseApprovers = new List<DepartmentApprover>();

            if (ShiftApprovers != null)
            {
                foreach (var app in ShiftApprovers)
                    if (!string.IsNullOrWhiteSpace(app))
                        model.ShiftRequestApprovers.Add(new DepartmentApprover { Approver = app });
            }

            if (LeaveApprovers != null)
            {
                foreach (var app in LeaveApprovers)
                    if (!string.IsNullOrWhiteSpace(app))
                        model.LeaveApprovers.Add(new DepartmentApprover { Approver = app });
            }

            if (ExpenseApprovers != null)
            {
                foreach (var app in ExpenseApprovers)
                    if (!string.IsNullOrWhiteSpace(app))
                        model.ExpenseApprovers.Add(new DepartmentApprover { Approver = app });
            }

            try
            {
                string companyName = string.IsNullOrWhiteSpace(model.Company) ? "Vinod Cookware India Private Limited" : model.Company;
                await _erpNextService.EnsureLinkExistsAsync("Company", companyName, "company_name");

                // Auto-create Parent Department in ERPNext if missing
                if (!string.IsNullOrWhiteSpace(model.ParentDepartment))
                {
                    await _erpNextService.EnsureLinkExistsAsync("Department", model.ParentDepartment, "department_name");
                }

                // Auto-create Cost Center in ERPNext if missing
                if (!string.IsNullOrWhiteSpace(model.PayrollCostCenter))
                {
                    await _erpNextService.EnsureLinkExistsAsync("Cost Center", model.PayrollCostCenter, "cost_center_name");
                }

                // Auto-create Leave Block List with mandatory child dates table if missing
                if (!string.IsNullOrWhiteSpace(model.LeaveBlockList))
                {
                    try
                    {
                        await _erpNextService.GetAsync($"/api/resource/Leave%20Block%20List/{Uri.EscapeDataString(model.LeaveBlockList)}");
                    }
                    catch
                    {
                        var lblPayload = new
                        {
                            leave_block_list_name = model.LeaveBlockList,
                            company = companyName,
                            leave_block_list_dates = new[]
                            {
                        new { block_date = DateTime.Now.ToString("yyyy-MM-dd"), reason = "System Default Block Date" }
                    }
                        };
                        await _erpNextService.PostAsync("/api/resource/Leave%20Block%20List", lblPayload);
                    }
                }

                // Helper: Resolves Employee Code (HR-EMP-...) to User ID OR creates the User in ERPNext if missing
                async Task<string> EnsureUserExistsAsync(string approverInput)
                {
                    if (string.IsNullOrWhiteSpace(approverInput)) return null;

                    // If an Employee ID was passed, find its linked user_id
                    if (approverInput.StartsWith("HR-EMP-", StringComparison.OrdinalIgnoreCase))
                    {
                        try
                        {
                            var empJson = await _erpNextService.GetAsync($"/api/resource/Employee/{approverInput}");
                            dynamic empParsed = JsonConvert.DeserializeObject(empJson);
                            string linkedUserId = empParsed?.data?.user_id?.ToString();
                            if (!string.IsNullOrEmpty(linkedUserId)) return linkedUserId;
                        }
                        catch { }
                    }

                    // Otherwise, ensure User exists in ERPNext
                    try
                    {
                        await _erpNextService.EnsureLinkExistsAsync("User", approverInput, "email");
                        return approverInput;
                    }
                    catch
                    {
                        // Fallback to Administrator if user creation is restricted
                        return "Administrator";
                    }
                }

                // Resolve all approver rows to valid ERPNext Users
                var shiftPayloadList = new List<object>();
                foreach (var a in model.ShiftRequestApprovers)
                {
                    string validUser = await EnsureUserExistsAsync(a.Approver);
                    if (!string.IsNullOrEmpty(validUser))
                        shiftPayloadList.Add(new { approver = validUser });
                }

                var leavePayloadList = new List<object>();
                foreach (var a in model.LeaveApprovers)
                {
                    string validUser = await EnsureUserExistsAsync(a.Approver);
                    if (!string.IsNullOrEmpty(validUser))
                        leavePayloadList.Add(new { approver = validUser });
                }

                var expensePayloadList = new List<object>();
                foreach (var a in model.ExpenseApprovers)
                {
                    string validUser = await EnsureUserExistsAsync(a.Approver);
                    if (!string.IsNullOrEmpty(validUser))
                        expensePayloadList.Add(new { approver = validUser });
                }

                // Payload formatted strictly for ERPNext Department doctype
                var payload = new
                {
                    department_name = model.DepartmentName,
                    company = companyName,
                    parent_department = string.IsNullOrWhiteSpace(model.ParentDepartment) ? null : model.ParentDepartment,
                    is_group = model.IsGroup ? 1 : 0,
                    disabled = model.Disabled ? 1 : 0,
                    payroll_cost_center = string.IsNullOrWhiteSpace(model.PayrollCostCenter) ? null : model.PayrollCostCenter,
                    leave_block_list = string.IsNullOrWhiteSpace(model.LeaveBlockList) ? null : model.LeaveBlockList,
                    shift_request_approver = shiftPayloadList,
                    leave_approvers = leavePayloadList,
                    expense_approvers = expensePayloadList
                };

                var resultJson = await _erpNextService.PostAsync("/api/resource/Department", payload);
                dynamic parsed = JsonConvert.DeserializeObject(resultJson);
                string erpNextId = parsed?.data?.name;

                model.DepartmentCode = erpNextId;
                int localId = _departmentService.Insert(model);

                TempData["Success"] = $"Department created successfully in local DB and synced to ERPNext (ID: {erpNextId})!";
            }
            catch (Exception ex)
            {
                try
                {
                    _departmentService.Insert(model);
                    TempData["ErpNextError"] = "Saved locally, but ERPNext sync failed: " + ex.Message;
                }
                catch (Exception dbEx)
                {
                    TempData["ErpNextError"] = "Failed to save locally and ERPNext sync failed: " + dbEx.Message;
                }
            }

            return RedirectToAction("Department");
        }
