                        "/api/resource/Employee%20Separation%20Template/" +
                        Uri.EscapeDataString(
                            templateName
                        )
                    );


                var json =
                    JObject.Parse(response);


                var doc =
                    json["data"];


                if (doc == null)
                {
                    return Json(
                        new
                        {
                            success = false
                        }
                    );
                }


                var activities =
                    new List<object>();


                var rows =
                    doc["activities"] as JArray;


