        [HttpPost]
        [Route("HR/SyncEmployeeSeparationsFromErpNext")]
        public async Task<ActionResult> SyncEmployeeSeparationsFromErpNext()
        {
            try
            {
                // ============================================================
                // 1. GET EXISTING LOCAL ERP IDS
                // ============================================================

                var existingCodes =
                    _employeeSeparationService
                        .GetExistingCodes();


                // ============================================================
                // 2. GET ALL ERP EMPLOYEE SEPARATION IDS
                // ============================================================

                string listUrl =
                    "/api/resource/Employee%20Separation" +
                    "?fields=[\"name\"]" +
                    "&limit_page_length=5000";


                string listResponse =
                    await _erpNextService.GetAsync(
                        listUrl
                    );


                JObject listJson =
                    JObject.Parse(
                        listResponse
                    );


                JArray records =
                    listJson["data"] as JArray;


                if (records == null)
                {
                    TempData["ErpNextError"] =
                        "No Employee Separation records returned from ERPNext.";

                    return RedirectToAction(
                        "EmployeeSeparation"
                    );
                }


                int totalFromErp =
                    records.Count;

                int insertedCount = 0;
                int updatedCount = 0;
                int failedCount = 0;


                // ============================================================
                // 3. PROCESS EACH ERP DOCUMENT
                // ============================================================

                foreach (JToken item in records)
                {
                    try
                    {
                        string erpId =
                            item["name"]
                                ?.ToString();


                        if (string.IsNullOrWhiteSpace(
                            erpId))
                        {
                            continue;
                        }


                        // ====================================================
                        // 4. FETCH FULL ERP DOCUMENT
                        // ====================================================

                        string detailUrl =
                            "/api/resource/Employee%20Separation/" +
                            Uri.EscapeDataString(
                                erpId
                            );


                        string detailResponse =
                            await _erpNextService.GetAsync(
                                detailUrl
                            );


                        JObject detailJson =
                            JObject.Parse(
                                detailResponse
                            );


                        JToken doc =
                            detailJson["data"];


                        if (doc == null)
                        {
                            failedCount++;
                            continue;
                        }


                        // ====================================================
                        // 5. MAP ERP -> HRMS
                        // ====================================================

                        var separation =
                            new EmployeeSeparation
                            {
                                EmployeeSeparationCode =
                                    erpId,

                                Employee =
                                    doc["employee"]
                                        ?.ToString()
                                    ?? "",

                                EmployeeName =
                                    doc["employee_name"]
                                        ?.ToString()
                                    ?? "",

                                Company =
                                    doc["company"]
                                        ?.ToString()
                                    ?? "",

                                Status =
                                    doc["boarding_status"]
                                        ?.ToString()
                                    ?? "Pending",

                                SeparationBeginsOn =
                                    ParseEmployeeSeparationDate(
                                        doc["boarding_begins_on"]
                                    ),

                                EmployeeSeparationTemplate =
                                    doc["employee_separation_template"]
                                        ?.ToString()
                                    ?? "",

                                Department =
                                    doc["department"]
                                        ?.ToString()
                                    ?? "",

                                Designation =
                                    doc["designation"]
                                        ?.ToString()
                                    ?? "",

                                EmployeeGrade =
                                    doc["employee_grade"]
                                        ?.ToString()
                                    ?? "",

                                Project =
                                    doc["project"]
                                        ?.ToString()
                                    ?? "",

                                NotifyUsersByEmail =
                                    GetEmployeeSeparationErpBoolean(
                                        doc["notify_users_by_email"]
                                    ),

                                ExitInterviewSummary =
                                    CleanEmployeeSeparationRichText(
                                        doc["exit_interview"]
                                            ?.ToString()
                                        ?? ""
                                    ),

                                DocStatus =
                                    doc["docstatus"]
                                        ?.ToObject<int>()
                                    ?? 0,

                                AmendedFrom =
                                    doc["amended_from"]
                                        ?.ToString()
                                    ?? "",

                                Activities =
                                    new List<EmployeeSeparationActivity>()
                            };


                        // ====================================================
                        // 6. ACTIVITIES
                        // ====================================================

                        JArray activities =
                            doc["activities"] as JArray;


                        if (activities != null)
                        {
                            foreach (
                                JToken activity
                                in activities
                            )
                            {
                                separation.Activities.Add(
                                    new EmployeeSeparationActivity
                                    {
                                        ActivityName =
                                            activity["activity_name"]
                                                ?.ToString()
                                            ?? "",

                                        UserName =
                                            activity["user"]
                                                ?.ToString()
                                            ?? "",

                                        BeginOnDays =
                                            activity["begin_on"]
                                                ?.ToObject<int?>(),

                                        DurationDays =
                                            activity["duration"]
                                                ?.ToObject<int?>()
                                    }
                                );
                            }
                        }


                        // ====================================================
                        // 7. INSERT / UPDATE
                        // ====================================================

                        if (
                            existingCodes.Contains(
                                erpId
                            )
                        )
                        {
                            _employeeSeparationService
                                .UpdateByCode(
                                    separation
                                );

                            updatedCount++;
                        }
                        else
                        {
                            _employeeSeparationService
                                .Insert(
                                    separation
                                );

                            existingCodes.Add(
                                erpId
                            );

                            insertedCount++;
                        }
                    }
                    catch (Exception recordEx)
                    {
                        failedCount++;

                        System.Diagnostics.Debug.WriteLine(
                            "Employee Separation sync record error: "
                            + recordEx.Message
                        );
                    }
                }


                // ============================================================
                // 8. RESULT
                // ============================================================

                TempData["Success"] =
                    "Employee Separation sync completed. " +
                    "ERP Records: " +
                    totalFromErp +
                    ", New: " +
                    insertedCount +
                    ", Updated: " +
                    updatedCount +
                    ", Failed: " +
                    failedCount +
                    ".";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext Employee Separation sync failed: "
                    + ex.Message;
            }


            return RedirectToAction(
                "EmployeeSeparation"
            );
        }



        private bool GetEmployeeSeparationErpBoolean(
    JToken token)
        {
            if (token == null)
                return false;


            if (token.Type == JTokenType.Boolean)
            {
                return token.ToObject<bool>();
            }


            int number;


            if (
                int.TryParse(
                    token.ToString(),
                    out number
                )
            )
            {
                return number == 1;
            }


            bool result;


            if (
                bool.TryParse(
                    token.ToString(),
                    out result
                )
            )
            {
                return result;
            }


            return false;
        }


        private string CleanEmployeeSeparationRichText(
    string html)
        {
            if (string.IsNullOrWhiteSpace(html))
                return "";


            // Decode &lt;p&gt; etc.
            string decoded =
                System.Net.WebUtility
                    .HtmlDecode(
                        html
                    );


            // Remove HTML tags
            string plainText =
                System.Text.RegularExpressions
                    .Regex.Replace(
                        decoded,
                        "<[^>]*>",
                        " "
                    );


            // Normalize spaces
            plainText =
                System.Text.RegularExpressions
                    .Regex.Replace(
                        plainText,
                        @"\s+",
                        " "
                    )
                    .Trim();


            return plainText;
        }


        private DateTime ParseEmployeeSeparationDate(
    JToken token)
        {
            if (
                token == null ||
                string.IsNullOrWhiteSpace(
                    token.ToString()
                )
            )
            {
                return DateTime.Today;
            }


            DateTime value;


            if (
                DateTime.TryParse(
                    token.ToString(),
                    out value
                )
            )
            {
                return value;
            }


            return DateTime.Today;
        }

        private bool GetErpBoolean(
            JToken token)
        {
            if (token == null)
                return false;


            if (
                token.Type ==
                JTokenType.Boolean
            )
            {
                return token.ToObject<bool>();
            }


            int number;

            if (
                int.TryParse(
                    token.ToString(),
                    out number
                )
            )
            {
                return number == 1;
            }


            bool value;

            if (
                bool.TryParse(
                    token.ToString(),
                    out value
                )
            )
            {
                return value;
            }


            return false;
        }


