        private async Task PullEmployeeCheckinsFromErpNext()
        {
            var erpCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            int limitStart = 0;
            int pageLength = 500;

            while (true)
            {
                string listUrl =
                    "/api/resource/Employee%20Checkin" +
                    "?fields=[\"name\",\"employee\",\"employee_name\",\"time\",\"log_type\",\"device_id\",\"skip_auto_attendance\",\"shift\"]" +
                    "&limit_page_length=" + pageLength +
                    "&limit_start=" + limitStart;

                var jsonResponse = await _erpNextService.GetAsync(listUrl);
                dynamic parsed = JsonConvert.DeserializeObject(jsonResponse);

                if (parsed == null || parsed.data == null || parsed.data.Count == 0)
                    break;

                foreach (var item in parsed.data)
                {
                    string erpId = item.name?.ToString();

                    if (string.IsNullOrWhiteSpace(erpId))
                        continue;

                    erpId = erpId.Trim();
                    erpCodes.Add(erpId);

                    DateTime? logTime = null;

                    if (item.time != null && !string.IsNullOrWhiteSpace(item.time.ToString()))
                        logTime = Convert.ToDateTime(item.time.ToString());

                    var checkin = new EmployeeCheckin
                    {
                        EmployeeCheckinCode = erpId,
                        Employee = item.employee?.ToString() ?? "",
                        EmployeeName = item.employee_name?.ToString() ?? "",
                        Time = logTime,
                        LogType = item.log_type?.ToString() ?? "",
                        LocationDeviceId = item.device_id?.ToString() ?? "",
                        SkipAutoAttendance = item.skip_auto_attendance != null &&
                                             Convert.ToBoolean(item.skip_auto_attendance),
                        Shift = item.shift?.ToString() ?? ""
                    };

                    _employeeCheckinService.InsertOrUpdateByCode(checkin);
                }

                if (parsed.data.Count < pageLength)
                    break;

                limitStart += pageLength;
            }

            _employeeCheckinService.MarkDeletedIfMissingFromErpNext(erpCodes);
        }














