        // POST: HR/SyncEmployeeCheckinsFromErpNext
        [HttpPost]
        public async Task<ActionResult> SyncEmployeeCheckinsFromErpNext()
        {
            try
            {
                var existingCodes = _employeeCheckinService.GetExistingCodes();

                // Fetch ALL past & present Employee Checkin records
                string listUrl = "/api/resource/Employee%20Checkin?fields=[\"*\"]&limit_page_length=5000";
                var jsonResponse = await _erpNextService.GetAsync(listUrl);
                dynamic parsed = JsonConvert.DeserializeObject(jsonResponse);

                if (parsed == null || parsed.data == null)
                {
                    TempData["ErpNextError"] = "No checkin records returned from ERPNext.";
                    return RedirectToAction("EmployeeCheckin");
                }

                int totalFromErp = parsed.data.Count;
                int newInserted = 0;
                int existingUpdated = 0;
                var erpCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                foreach (var item in parsed.data)
                {
                    string erpId = item.name?.ToString();
                    if (string.IsNullOrEmpty(erpId)) continue;
                    erpCodes.Add(erpId);

                    DateTime? logTime = null;
                    if (item.time != null)
                    {
                        logTime = Convert.ToDateTime(item.time);
                    }

                    var checkin = new EmployeeCheckin
                    {
                        EmployeeCheckinCode = erpId,
                        Employee = item.employee?.ToString() ?? "",
                        EmployeeName = item.employee_name?.ToString() ?? "",
                        Time = logTime ?? DateTime.Now,
                        LogType = item.log_type?.ToString() ?? "",
                        LocationDeviceId = item.device_id?.ToString() ?? (item.location?.ToString() ?? ""),
                        SkipAutoAttendance = item.skip_auto_attendance != null && Convert.ToBoolean(item.skip_auto_attendance),
                        Shift = item.shift?.ToString() ?? ""
                    };

                    try
                    {
                        if (existingCodes.Contains(erpId))
                        {
                            _employeeCheckinService.UpdateCheckinByCode(checkin);
                            existingUpdated++;
                        }
                        else
                        {
                            _employeeCheckinService.InsertCheckin(checkin);
                            newInserted++;
                            existingCodes.Add(erpId);
                        }
                    }
                    catch { }
                }

                TempData["Success"] = $"Synced successfully! Total ERPNext records: {totalFromErp} (New added: {newInserted}, Past/Existing updated: {existingUpdated}).";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("EmployeeCheckin");
        }

        // POST: HR/CreateEmployeeCheckin
        // POST: HR/CreateEmployeeCheckin
        [HttpPost]
        public async Task<ActionResult> CreateEmployeeCheckin(EmployeeCheckin model)
        {
            // 1. Save locally in SQL Server first
            model.EmployeeCheckinCode = _employeeCheckinService.GetNextCheckinCode();
            _employeeCheckinService.InsertCheckin(model);

            try
            {
                // 2. Ensure Employee exists in ERPNext
                if (!string.IsNullOrWhiteSpace(model.Employee))
                {
                    await _erpNextService.EnsureLinkExistsAsync("Employee", model.Employee, "name");
                }

                // 3. Build ERPNext API Payload using an Anonymous Object (preserves standard C# types)
                var payload = new
                {
                    employee = model.Employee,
                    time = model.Time?.ToString("yyyy-MM-dd HH:mm:ss") ?? DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"),
                    log_type = string.IsNullOrWhiteSpace(model.LogType) ? "IN" : model.LogType,
                    device_id = string.IsNullOrWhiteSpace(model.LocationDeviceId) ? null : model.LocationDeviceId,
                    skip_auto_attendance = model.SkipAutoAttendance ? 1 : 0,
                    shift = string.IsNullOrWhiteSpace(model.Shift) ? null : model.Shift
                };

                // 4. Post directly to ERPNext REST API
                var resultJson = await _erpNextService.PostAsync("/api/resource/Employee%20Checkin", payload);
                dynamic parsed = JsonConvert.DeserializeObject(resultJson);
                string erpNextId = parsed?.data?.name;

                TempData["Success"] = $"Employee Checkin created locally and synced to ERPNext (ID: {erpNextId})!";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Saved locally, but ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("EmployeeCheckin");
        }

