        private async Task<(int total, int inserted, int updated)> PullEmployeeAdvancesFromErpNext()
        {
            try
            {
                var existingCodes = _employeeAdvanceService.GetExistingErpNextCodes();

                // 1. Request ALL past & present records without ERPNext status or page filters
                string listUrl = "/api/resource/Employee%20Advance?fields=[\"*\"]&limit_page_length=5000";
                var jsonResponse = await _erpNextService.GetAsync(listUrl);
                dynamic parsed = JsonConvert.DeserializeObject(jsonResponse);

                if (parsed == null || parsed.data == null)
                {
                    throw new Exception("No records returned from ERPNext.");
                }

                int totalFromErp = parsed.data.Count;
                int newInserted = 0;
                int existingUpdated = 0;
                var erpCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                foreach (var item in parsed.data)
                {
                    string erpId = item.name?.ToString();
                    if (string.IsNullOrEmpty(erpId)) continue;
                    erpCodes.Add(erpId);

                    var advance = MapErpEmployeeAdvance(item);

                    try
                    {
                        if (existingCodes.Contains(erpId))
                        {
                            // UPDATE existing local record with latest past/present ERPNext data
                            _employeeAdvanceService.UpdateEmployeeAdvanceByCode(advance);
                            existingUpdated++;
                        }
                        else
                        {
                            // INSERT new record
                            _employeeAdvanceService.InsertEmployeeAdvanceWithCode(advance);
                            newInserted++;
                            existingCodes.Add(erpId);
                        }
                    }
                    catch { }
                }

                SoftDeleteMissingErpDocuments("EmployeeAdvances", "EmployeeAdvanceCode", erpCodes);

                return (totalFromErp, newInserted, existingUpdated);
            }
            catch (Exception ex)
            {
                throw new Exception("Sync error: " + ex.Message, ex);
            }
        }

        private EmployeeAdvance MapErpEmployeeAdvance(dynamic item)
        {
            string erpId = item.name?.ToString();

            decimal amount = 0;
            if (item.advance_amount != null) amount = Convert.ToDecimal(item.advance_amount);
            else if (item.paid_amount != null) amount = Convert.ToDecimal(item.paid_amount);

            bool repay = false;
            if (item.repay_unclaimed_amount_from_salary != null)
            {
                string raw = item.repay_unclaimed_amount_from_salary.ToString();
                repay = raw == "1" || raw.Equals("true", StringComparison.OrdinalIgnoreCase);
            }

            return new EmployeeAdvance
            {
                EmployeeAdvanceCode = erpId,
                PostingDate = item.posting_date != null ? Convert.ToDateTime(item.posting_date) : DateTime.Now,
                Employee = item.employee?.ToString() ?? "",
                EmployeeName = item.employee_name?.ToString() ?? "",
                Company = item.company?.ToString() ?? "VCIPL",
                Purpose = item.purpose?.ToString() ?? "",
                AdvanceAmount = amount,
                AdvanceAccount = item.advance_account?.ToString() ?? "",
                RepayUnclaimedFromSalary = repay,
                ModeOfPayment = item.mode_of_payment?.ToString() ?? "",
                Status = item.status?.ToString() ?? "Draft"
            };
        }

        private async Task<EmployeeAdvance> RefreshEmployeeAdvanceFromErpNextAsync(string employeeAdvanceCode)
        {
            string json =
                await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Advance/" +
                    Uri.EscapeDataString(employeeAdvanceCode)
                );

            dynamic parsed = JsonConvert.DeserializeObject(json);
            if (parsed?.data == null)
                throw new Exception("Employee Advance not found in ERPNext.");

            return MapErpEmployeeAdvance(parsed.data);
        }

        private Dictionary<string, object> BuildEmployeeAdvancePayload(EmployeeAdvance model)
        {
            return new Dictionary<string, object>
            {
                ["posting_date"] = model.PostingDate?.ToString("yyyy-MM-dd") ?? DateTime.Today.ToString("yyyy-MM-dd"),
                ["employee"] = model.Employee,
                ["company"] = string.IsNullOrWhiteSpace(model.Company) ? "Vinod Cookware India Private Limited" : model.Company,
                ["purpose"] = model.Purpose,
                ["advance_amount"] = model.AdvanceAmount,
                ["repay_unclaimed_amount_from_salary"] = model.RepayUnclaimedFromSalary ? 1 : 0,
                ["currency"] = "INR",
                ["exchange_rate"] = 1.0,
                ["advance_account"] = string.IsNullOrWhiteSpace(model.AdvanceAccount) ? null : model.AdvanceAccount,
                ["mode_of_payment"] = string.IsNullOrWhiteSpace(model.ModeOfPayment) ? null : model.ModeOfPayment
            };
        }

