        [HttpPost]
        [Route("HR/SyncExpenseClaimsFromErpNext")]
        public async Task<ActionResult> SyncExpenseClaimsFromErpNext()
        {
            try
            {
                var result = await PullExpenseClaimsFromErpNext();
                TempData["Success"] =
                    $"ERP to HRMS Expense Claim sync done. Fetched: {result.fetched}, Imported/Updated: {result.imported}, Failed: {result.failed}. {result.firstError}";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERP to HRMS Expense Claim sync failed: " + ex.Message;
            }

            return RedirectToAction("ExpenseClaimList");
        }

        private async Task<(int fetched, int imported, int failed, string firstError)> PullExpenseClaimsFromErpNext()
        {
            int fetchedCount = 0;
            int importedCount = 0;
            int failedCount = 0;
            string firstError = "";

            DateTime? GetDate(JToken token)
            {
                string value = token?.ToString();
                return DateTime.TryParse(value, out DateTime result) ? result : null;
            }

            decimal GetDecimal(JToken token)
            {
                string value = token?.ToString();
                return decimal.TryParse(value, out decimal result) ? result : 0;
            }

            bool GetBool(JToken token)
            {
                string value = token?.ToString();
                return value == "1" || value?.Equals("true", StringComparison.OrdinalIgnoreCase) == true;
            }

            try
            {
                var existingErpIds = _expenseClaimService.GetExistingErpNextIds();
                var existingCodes = _expenseClaimService.GetExistingClaimCodes();

                string listUrl =
                    "/api/resource/Expense%20Claim" +
                    "?fields=[\"name\"]" +
                    "&limit_page_length=50" +
                    "&order_by=modified%20desc";

                string listJson = await _erpNextService.GetAsync(listUrl);
                JObject listRoot = JObject.Parse(listJson);
                JArray rows = listRoot["data"] as JArray ?? new JArray();

                fetchedCount = rows.Count;

                foreach (JObject row in rows)
                {
                    string erpId = row["name"]?.ToString();

                    if (string.IsNullOrWhiteSpace(erpId))
                    {
                        failedCount++;
                        continue;
                    }

                    //if (existingErpIds.Contains(erpId) || existingCodes.Contains(erpId))
                    //{
                    //    skippedCount++;
                    //    continue;
                    //}
                    // Existing ERP Expense Claims are allowed to import again for testing.
                    // Do not skip here, because we want to verify ERP -> HRMS data is coming.

                    try
                    {
                        string docUrl =
                            "/api/resource/Expense%20Claim/" +
                            Uri.EscapeDataString(erpId);

                        string docJson = await _erpNextService.GetAsync(docUrl);
                        JObject docRoot = JObject.Parse(docJson);
                        JObject doc = docRoot["data"] as JObject;

                        if (doc == null)
                        {
                            failedCount++;
                            continue;
                        }

                        var claim = MapErpExpenseClaim(doc);

                        _expenseClaimService.InsertOrUpdateExpenseClaim(claim);

                        importedCount++;
                        existingErpIds.Add(erpId);
                        existingCodes.Add(erpId);
                    }
                    catch (Exception rowEx)
                    {
                        failedCount++;

                        if (string.IsNullOrWhiteSpace(firstError))
                        {
                            firstError = $"Failed ERP ID: {erpId} | Error: {rowEx.Message}";
                        }
                    }
                }

                return (fetchedCount, importedCount, failedCount, firstError);
            }
            catch (Exception ex)
            {
                throw new Exception("ERP to HRMS Expense Claim sync failed: " + ex.Message, ex);
            }
        }

        private ExpenseClaim MapErpExpenseClaim(JObject doc)
        {
            DateTime? GetDate(JToken token)
            {
                string value = token?.ToString();
                return DateTime.TryParse(value, out DateTime result) ? result : null;
            }

            decimal GetDecimal(JToken token)
            {
                string value = token?.ToString();
                return decimal.TryParse(value, out decimal result) ? result : 0;
            }

            bool GetBool(JToken token)
            {
                string value = token?.ToString();
                return value == "1" || value?.Equals("true", StringComparison.OrdinalIgnoreCase) == true;
            }

            string erpId = doc["name"]?.ToString();

            var claim = new ExpenseClaim
            {
                ExpenseClaimCode = erpId,
                ErpNextId = erpId,
                ExpenseApprover = doc["expense_approver"]?.ToString(),
                Employee = doc["employee"]?.ToString(),
                EmployeeName = doc["employee_name"]?.ToString(),
                ApprovalStatus = doc["approval_status"]?.ToString() ?? "Draft",
                Department = doc["department"]?.ToString(),
                Company = doc["company"]?.ToString(),
                CompanyGstin = doc["company_gstin"]?.ToString(),
                PostingDate = GetDate(doc["posting_date"]),
                ClearanceDate = GetDate(doc["clearance_date"]),
                IsPaid = GetBool(doc["is_paid"]),
                Remark = doc["remark"]?.ToString(),
                PayableAccount = doc["payable_account"]?.ToString(),
                Project = doc["project"]?.ToString(),
                CostCenter = doc["cost_center"]?.ToString(),
                Status = doc["status"]?.ToString() ?? "Draft",
                Task = doc["task"]?.ToString()
            };

            foreach (JObject exp in (doc["expenses"] as JArray ?? new JArray()))
            {
                string expenseType =
                    exp["expense_type"]?.ToString()
                    ?? exp["claim_type"]?.ToString();

                if (string.IsNullOrWhiteSpace(expenseType)) continue;

                claim.Expenses.Add(new ExpenseClaimDetail
                {
                    ExpenseDate = GetDate(exp["expense_date"]),
                    ExpenseClaimType = expenseType,
                    Description = exp["description"]?.ToString(),
                    Amount = GetDecimal(exp["amount"]),
                    SanctionedAmount = GetDecimal(exp["sanctioned_amount"])
                });
            }

            foreach (JObject tax in (doc["taxes"] as JArray ?? new JArray()))
            {
                string accountHead = tax["account_head"]?.ToString();
                if (string.IsNullOrWhiteSpace(accountHead)) continue;

                claim.Taxes.Add(new ExpenseTaxAndCharge
                {
                    AccountHead = accountHead,
                    Rate = GetDecimal(tax["rate"]),
                    Amount = GetDecimal(tax["tax_amount"] ?? tax["amount"]),
                    Total = GetDecimal(tax["total"])
                });
            }

            foreach (JObject adv in (doc["advances"] as JArray ?? new JArray()))
            {
                string employeeAdvance = adv["employee_advance"]?.ToString();
                if (string.IsNullOrWhiteSpace(employeeAdvance)) continue;

                claim.Advances.Add(new ExpenseClaimAdvance
                {
                    EmployeeAdvance = employeeAdvance,
                    PostingDate = GetDate(adv["posting_date"]),
                    AdvancePaid = GetDecimal(adv["advance_paid"]),
                    UnclaimedAmount = GetDecimal(adv["unclaimed_amount"]),
                    AllocatedAmount = GetDecimal(adv["allocated_amount"])
                });
            }

            return claim;
        }



        [HttpGet]
        [Route("HR/ExpenseClaimDetails/{id:int}")]
        public async Task<ActionResult> ExpenseClaimDetails(int id)
        {
            var model = _expenseClaimService.GetExpenseClaimById(id);

            if (model == null)
            {
                TempData["ErpNextError"] = "Expense Claim not found.";
                return RedirectToAction("ExpenseClaimList");
            }

            if (!string.IsNullOrWhiteSpace(model.ErpNextId))
            {
                try
                {
                    var refreshed = await RefreshExpenseClaimFromErpNextAsync(model.ErpNextId);
                    int localId = _expenseClaimService.InsertOrUpdateExpenseClaim(refreshed);
                    model = _expenseClaimService.GetExpenseClaimById(localId) ?? model;
                }
                catch (Exception ex)
                {
                    TempData["ErpNextError"] = "ERPNext refresh failed: " + ex.Message;
                }
            }

            await LoadExpenseClaimDropdownDataAsync();
            return View("~/Views/HR/ExpenseClaimDetails.cshtml", model);
        }









