        [HttpPost]
        [Route("HR/SyncExpenseClaimsToServerToErpNext")]
        public async Task<ActionResult> SyncExpenseClaimsToServerToErpNext()
        {
            int successCount = 0;
            int failCount = 0;

            try
            {
                var claims =
                    _expenseClaimService.GetAllExpenseClaims(null);

                foreach (var row in claims)
                {
                    if (!string.IsNullOrWhiteSpace(row.ErpNextId))
                        continue;

                    try
                    {
                        var model = row;

                        string targetCompany =
                            string.IsNullOrWhiteSpace(model.Company)
                                ? "Vinod Cookware India Private Limited"
                                : model.Company.Trim();

                        var expensesList = new List<object>();

                        if (model.Expenses != null)
                        {
                            foreach (var e in model.Expenses)
                            {
                                if (string.IsNullOrWhiteSpace(e.ExpenseClaimType))
                                    continue;

                                expensesList.Add(
                                    new
                                    {
                                        expense_date =
                                            e.ExpenseDate?.ToString("yyyy-MM-dd")
                                            ?? DateTime.Today.ToString("yyyy-MM-dd"),

                                        expense_type =
                                            e.ExpenseClaimType,

                                        description =
                                            string.IsNullOrWhiteSpace(e.Description)
                                                ? e.ExpenseClaimType
                                                : e.Description,

                                        amount =
                                            e.Amount,

                                        sanctioned_amount =
                                            e.SanctionedAmount > 0
                                                ? e.SanctionedAmount
                                                : e.Amount
                                    }
                                );
                            }
                        }

                        var taxesList = new List<object>();

                        if (model.Taxes != null)
                        {
                            foreach (var t in model.Taxes)
                            {
                                if (string.IsNullOrWhiteSpace(t.AccountHead))
                                    continue;

                                taxesList.Add(
                                    new
                                    {
                                        account_head = t.AccountHead,
                                        description = t.AccountHead,
                                        rate = t.Rate,
                                        tax_amount = t.Amount,
                                        total = t.Total
                                    }
                                );
                            }
                        }

                        var advancesList = new List<object>();

                        if (model.Advances != null)
                        {
                            foreach (var a in model.Advances)
                            {
                                if (string.IsNullOrWhiteSpace(a.EmployeeAdvance))
                                    continue;

                                advancesList.Add(
                                    new
                                    {
                                        employee_advance = a.EmployeeAdvance,
                                        posting_date =
                                            a.PostingDate?.ToString("yyyy-MM-dd"),
                                        advance_paid = a.AdvancePaid,
                                        unclaimed_amount = a.UnclaimedAmount,
                                        allocated_amount = a.AllocatedAmount
                                    }
                                );
                            }
                        }

                        var payload =
                            new Dictionary<string, object>
                            {
                        { "employee", model.Employee },
                        { "employee_name", model.EmployeeName },
                        { "expense_approver", model.ExpenseApprover },
                        { "approval_status", string.IsNullOrWhiteSpace(model.ApprovalStatus) ? "Draft" : model.ApprovalStatus },
                        { "department", model.Department },
                        { "company", targetCompany },
                        { "company_gstin", model.CompanyGstin },
                        { "posting_date", model.PostingDate?.ToString("yyyy-MM-dd") ?? DateTime.Today.ToString("yyyy-MM-dd") },
                        { "clearance_date", model.ClearanceDate?.ToString("yyyy-MM-dd") },
                        { "is_paid", model.IsPaid ? 1 : 0 },
                        { "remark", model.Remark },
                        { "payable_account", model.PayableAccount },
                        { "project", model.Project },
                        { "cost_center", model.CostCenter },
                        { "task", model.Task },
                        { "expenses", expensesList },
                        { "taxes", taxesList },
                        { "advances", advancesList }
                            };

                        string responseJson =
                            await _erpNextService.PostAsync(
                                "/api/resource/Expense%20Claim",
                                payload
                            );

                        dynamic parsed =
                            JsonConvert.DeserializeObject(responseJson);

                        string erpNextId =
                            parsed?.data?.name;

                        if (!string.IsNullOrWhiteSpace(erpNextId))
                        {
                            _expenseClaimService.UpdateErpNextId(
                                model.Id,
                                erpNextId
                            );

                            successCount++;
                        }
                        else
                        {
                            failCount++;
                        }
                    }
                    catch
                    {
                        failCount++;
                    }
                }

                if (successCount > 0)
                {
                    TempData["Success"] =
                        $"Pushed {successCount} Expense Claim(s) to ERPNext.";
                }
                else if (failCount > 0)
                {
                    TempData["ErpNextError"] =
                        $"Failed to push {failCount} Expense Claim(s) to ERPNext.";
                }
                else
                {
                    TempData["Success"] =
                        "All Expense Claims are already synced with ERPNext.";
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Expense Claim push failed: " + ex.Message;
            }

            return RedirectToAction("ExpenseClaimList");
        }


        private bool IsExpenseClaimDraft(ExpenseClaim model)
        {
            string status = model?.Status ?? "";
            return !status.Equals("Submitted", StringComparison.OrdinalIgnoreCase)
                && !status.Equals("Cancelled", StringComparison.OrdinalIgnoreCase)
                && !status.Equals("Paid", StringComparison.OrdinalIgnoreCase)
                && !status.Equals("Unpaid", StringComparison.OrdinalIgnoreCase);
        }

        private Dictionary<string, object> BuildExpenseClaimPayload(ExpenseClaim model)
        {
            var expensesList = new List<object>();
            foreach (var e in model.Expenses ?? new List<ExpenseClaimDetail>())
            {
                if (string.IsNullOrWhiteSpace(e.ExpenseClaimType))
                    continue;

                expensesList.Add(new
                {
                    expense_date = e.ExpenseDate?.ToString("yyyy-MM-dd") ?? DateTime.Today.ToString("yyyy-MM-dd"),
                    expense_type = e.ExpenseClaimType,
                    description = string.IsNullOrWhiteSpace(e.Description) ? e.ExpenseClaimType : e.Description,
                    amount = e.Amount,
                    sanctioned_amount = e.SanctionedAmount > 0 ? e.SanctionedAmount : e.Amount
                });
            }

            var taxesList = new List<object>();
            foreach (var t in model.Taxes ?? new List<ExpenseTaxAndCharge>())
            {
                if (string.IsNullOrWhiteSpace(t.AccountHead))
                    continue;

                taxesList.Add(new
                {
                    account_head = t.AccountHead,
                    description = t.AccountHead,
                    rate = t.Rate,
                    tax_amount = t.Amount,
                    total = t.Total
                });
            }

            var advancesList = new List<object>();
            foreach (var a in model.Advances ?? new List<ExpenseClaimAdvance>())
            {
                if (string.IsNullOrWhiteSpace(a.EmployeeAdvance))
                    continue;

                advancesList.Add(new
                {
                    employee_advance = a.EmployeeAdvance,
                    posting_date = a.PostingDate?.ToString("yyyy-MM-dd"),
                    advance_paid = a.AdvancePaid,
                    unclaimed_amount = a.UnclaimedAmount,
                    allocated_amount = a.AllocatedAmount
                });
            }

            return new Dictionary<string, object>
            {
                ["employee"] = model.Employee,
                ["employee_name"] = model.EmployeeName,
                ["expense_approver"] = model.ExpenseApprover,
                ["approval_status"] = string.IsNullOrWhiteSpace(model.ApprovalStatus) ? "Draft" : model.ApprovalStatus,
                ["department"] = string.IsNullOrWhiteSpace(model.Department) ? null : model.Department,
                ["company"] = string.IsNullOrWhiteSpace(model.Company) ? "Vinod Cookware India Private Limited" : model.Company,
                ["company_gstin"] = string.IsNullOrWhiteSpace(model.CompanyGstin) ? null : model.CompanyGstin,
                ["posting_date"] = model.PostingDate?.ToString("yyyy-MM-dd") ?? DateTime.Today.ToString("yyyy-MM-dd"),
                ["clearance_date"] = model.ClearanceDate?.ToString("yyyy-MM-dd"),
                ["is_paid"] = model.IsPaid ? 1 : 0,
                ["remark"] = model.Remark,
                ["payable_account"] = string.IsNullOrWhiteSpace(model.PayableAccount) ? null : model.PayableAccount,
                ["project"] = string.IsNullOrWhiteSpace(model.Project) ? null : model.Project,
                ["cost_center"] = string.IsNullOrWhiteSpace(model.CostCenter) ? null : model.CostCenter,
                ["task"] = string.IsNullOrWhiteSpace(model.Task) ? null : model.Task,
                ["expenses"] = expensesList,
                ["taxes"] = taxesList,
                ["advances"] = advancesList
            };
        }

        private async Task<ExpenseClaim> RefreshExpenseClaimFromErpNextAsync(string erpNextId)
        {
            string json =
                await _erpNextService.GetAsync(
                    "/api/resource/Expense%20Claim/" +
                    Uri.EscapeDataString(erpNextId)
                );

            JObject root = JObject.Parse(json);
            JObject doc = root["data"] as JObject;

            if (doc == null)
                throw new Exception("Expense Claim not found in ERPNext.");

            return MapErpExpenseClaim(doc);
        }

        [HttpPost]
        [Route("HR/UpdateExpenseClaim")]
        public async Task<ActionResult> UpdateExpenseClaim(int id, ExpenseClaim model)
        {
            try
            {
                ExpenseClaim local = _expenseClaimService.GetExpenseClaimById(id);

                if (local == null)
                    throw new Exception("Expense Claim not found.");

                if (!IsExpenseClaimDraft(local))
                    throw new Exception("Cannot edit submitted or cancelled Expense Claim.");

                if (string.IsNullOrWhiteSpace(local.ErpNextId))
                    throw new Exception("ERPNext reference is missing.");

                await _erpNextService.PutAsync(
                    "/api/resource/Expense%20Claim/" +
                    Uri.EscapeDataString(local.ErpNextId),
                    BuildExpenseClaimPayload(model)
                );

                ExpenseClaim refreshed = await RefreshExpenseClaimFromErpNextAsync(local.ErpNextId);
                int localId = _expenseClaimService.InsertOrUpdateExpenseClaim(refreshed);

                TempData["Success"] = "Expense Claim saved successfully.";

                return RedirectToAction("ExpenseClaimDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Expense Claim update failed: " + ex.Message;
                await LoadExpenseClaimDropdownDataAsync();
                model.Id = id;
                return View("~/Views/HR/ExpenseClaimDetails.cshtml", model);
            }
        }

        [HttpPost]
        [Route("HR/SubmitExpenseClaim")]
        public async Task<ActionResult> SubmitExpenseClaim(int id)
        {
            try
            {
                ExpenseClaim local = _expenseClaimService.GetExpenseClaimById(id);

                if (local == null)
                    throw new Exception("Expense Claim not found.");

                if (string.IsNullOrWhiteSpace(local.ErpNextId))
                    throw new Exception("ERPNext reference is missing.");

                string json =
                    await _erpNextService.GetAsync(
                        "/api/resource/Expense%20Claim/" +
                        Uri.EscapeDataString(local.ErpNextId)
                    );

                JObject root = JObject.Parse(json);

                await _erpNextService.PostMethodAsync(
                    "/api/method/frappe.client.submit",
                    new { doc = root["data"] }
                );

                ExpenseClaim refreshed = await RefreshExpenseClaimFromErpNextAsync(local.ErpNextId);
                int localId = _expenseClaimService.InsertOrUpdateExpenseClaim(refreshed);

                TempData["Success"] = "Expense Claim submitted successfully.";
                return RedirectToAction("ExpenseClaimDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Expense Claim submit failed: " + ex.Message;
                return RedirectToAction("ExpenseClaimDetails", new { id });
            }
        }

        [HttpPost]
        [Route("HR/CancelExpenseClaim")]
        public async Task<ActionResult> CancelExpenseClaim(int id)
        {
            try
            {
                ExpenseClaim local = _expenseClaimService.GetExpenseClaimById(id);

                if (local == null)
                    throw new Exception("Expense Claim not found.");

                if (string.IsNullOrWhiteSpace(local.ErpNextId))
                    throw new Exception("ERPNext reference is missing.");

                await _erpNextService.PostMethodAsync(
                    "/api/method/frappe.client.cancel",
                    new
                    {
                        doctype = "Expense Claim",
                        name = local.ErpNextId
                    }
                );

                ExpenseClaim refreshed = await RefreshExpenseClaimFromErpNextAsync(local.ErpNextId);
                int localId = _expenseClaimService.InsertOrUpdateExpenseClaim(refreshed);

                TempData["Success"] = "Expense Claim cancelled successfully.";
                return RedirectToAction("ExpenseClaimDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Expense Claim cancel failed: " + ex.Message;
                return RedirectToAction("ExpenseClaimDetails", new { id });
            }
        }

        [HttpGet]
        [Route("HR/SearchExpenseClaimLink")]
        public async Task<JsonResult> SearchExpenseClaimLink(string doctype, string txt = "", string employee = "")
        {
            try
            {
                if (doctype != "Department" && doctype != "Employee Advance")
                {
                    return Json(new List<object>());
                }

                var formData = new Dictionary<string, string>
                {
                    ["doctype"] = doctype,
                    ["txt"] = txt ?? "",
                    ["searchfield"] = "name",
                    ["start"] = "0",
                    ["page_length"] = "20",
                    ["reference_doctype"] = "Expense Claim",
                    ["ignore_user_permissions"] = "0"
                };

                if (doctype == "Employee Advance" && !string.IsNullOrWhiteSpace(employee))
                {
                    formData["filters"] = JsonConvert.SerializeObject(new
                    {
                        employee = employee,
                        docstatus = 1
                    });
                }

                string json = await _erpNextService.PostFormUrlEncodedAsync(
                    "/api/method/frappe.desk.search.search_link",
                    formData
                );

                JObject root = JObject.Parse(json);
                JArray message = root["message"] as JArray ?? new JArray();

                var result = message.Select(x =>
                {
                    if (x is JArray arr)
                    {
                        return new
                        {
                            name = arr.Count > 0 ? arr[0]?.ToString() ?? "" : "",
                            label = arr.Count > 1 ? arr[1]?.ToString() ?? "" : ""
                        };
                    }

                    return new
                    {
                        name = x["value"]?.ToString() ?? x["name"]?.ToString() ?? "",
                        label = x["description"]?.ToString() ?? x["label"]?.ToString() ?? ""
                    };
                })
                .Where(x => !string.IsNullOrWhiteSpace(x.name))
                .ToList();

                return Json(result);
            }
            catch
            {
                return Json(new List<object>());
            }
        }










        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> SyncEmployeeGradesFromErpNext()
        {
            try
            {
                string url = "/api/resource/Employee%20Grade?fields=[\"name\",\"default_salary_structure\",\"default_base_pay\"]&limit_page_length=500";

                var jsonResponse = await _erpNextService.GetAsync(url);
                dynamic parsed = JsonConvert.DeserializeObject(jsonResponse);

                int syncedCount = 0;
                var remoteIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                if (parsed != null && parsed.data != null)
                {
                    foreach (var item in parsed.data)
                    {
                        string erpId = item.name?.ToString();

                        if (string.IsNullOrWhiteSpace(erpId))
                            continue;

                        remoteIds.Add(erpId);

                        decimal? basePay = null;
                        if (decimal.TryParse(item.default_base_pay?.ToString(), out decimal parsedBasePay))
                        {
                            basePay = parsedBasePay;
                        }

                        var grade = new EmployeeGrade
                        {
                            ErpNextId = erpId,
                            GradeName = erpId,
                            DefaultSalaryStructure = item.default_salary_structure?.ToString(),
                            DefaultBasePay = basePay
                        };

                        _employeeGradeService.InsertOrUpdateFromErpNext(grade);
                        syncedCount++;
                    }
                }

                int deletedCount = _employeeGradeService.MarkMissingErpNextGradesAsDeleted(remoteIds);

                TempData["Success"] =
                    $"Successfully synced {syncedCount} Employee Grade(s) from ERPNext. Deleted locally: {deletedCount}.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext sync failed: " + ShortErpNextError(ex.Message);
            }

            return RedirectToAction("EmployeeGrades");
        }









      















