        [Route("HR/EmployeeGroup")]
        public async Task<ActionResult> EmployeeGroups()
        {
            try
            {
                // Automatically synchronize on every page request.
                await RefreshEmployeeGroupsFromErpNextAsync();
            }
            catch (Exception ex)
            {
                // Do not delete local records if ERPNext cannot be reached.
                ViewBag.SyncWarning =
                    "Unable to refresh Employee Groups from ERPNext: " +
                    ex.Message;
