        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteEmployeeGroup/{id:int}")]
        public async Task<ActionResult> DeleteEmployeeGroup(int id)
        {
            try
            {
                EmployeeGroup existing =
                    _employeeGroupService.GetById(id);

                if (existing == null)
                    return NotFound();

                // 1. Delete ERPNext record first.
                if (!string.IsNullOrWhiteSpace(existing.ErpNextId))
                {
                    string erpUrl =
                        "/api/resource/Employee%20Group/" +
                        Uri.EscapeDataString(existing.ErpNextId);

                    await _erpNextService.DeleteAsync(erpUrl);
                }

                // 2. Mark HRMS record deleted only after ERPNext success.
                _employeeGroupService.MarkDeletedByLocalId(id);

                TempData["Success"] =
                    "Employee Group deleted successfully.";
            }
            catch (Exception ex)
            {
                // Do not delete locally if ERPNext rejects the request.
                TempData["ErpNextError"] =
                    "Employee Group deletion failed: " +
                    CleanErpNextError(ex.Message);

                return RedirectToAction(
                    "EmployeeGroupDetails",
                    new { id = id }
                );
            }

            return RedirectToAction("EmployeeGroups");
        }





        private async Task<int> RefreshEmployeeGroupsFromErpNextAsync()
        {
            const int pageSize = 100;

            int start = 0;
            int syncedCount = 0;

            // Track all ERPNext Employee Group IDs.
            var erpIds = new HashSet<string>(
                StringComparer.OrdinalIgnoreCase
            );

            // =========================================================
            // STEP 1: FETCH ALL EMPLOYEE GROUPS FROM ERPNext
            // =========================================================

            while (true)
            {
                string listUrl =
                    "/api/resource/Employee%20Group" +
                    "?fields=" +
                    Uri.EscapeDataString("[\"name\"]") +
                    "&limit_start=" + start +
                    "&limit_page_length=" + pageSize +
                    "&order_by=" + Uri.EscapeDataString("name asc");

                string response =
                    await _erpNextService.GetAsync(listUrl);

                JObject listJson = JObject.Parse(response);

                JArray records = listJson["data"] as JArray;

                if (records == null)
                {
                    throw new Exception(
                        "Invalid Employee Group response from ERPNext."
                    );
                }

                // =====================================================
                // STEP 2: FETCH COMPLETE DOCUMENT INCLUDING MEMBERS
                // =====================================================

                foreach (JToken item in records)
                {
                    string erpId = item["name"]?.ToString();

                    if (string.IsNullOrWhiteSpace(erpId))
                    {
                        throw new Exception(
                            "ERPNext returned an Employee Group without an ID."
                        );
                    }

                    erpIds.Add(erpId);

                    string detailUrl =
                        "/api/resource/Employee%20Group/" +
                        Uri.EscapeDataString(erpId);

                    string detailResponse =
                        await _erpNextService.GetAsync(detailUrl);

                    JObject detailJson =
                        JObject.Parse(detailResponse);

                    JToken doc = detailJson["data"];

                    if (doc == null)
                    {
                        throw new Exception(
                            "Employee Group details not found: " + erpId
                        );
                    }

                    // =================================================
                    // STEP 3: MAP ERPNext DATA TO HRMS MODEL
                    // =================================================

                    var group = new EmployeeGroup
                    {
                        ErpNextId =
                            doc["name"]?.ToString() ?? "",

                        GroupCode =
                            doc["name"]?.ToString() ?? "",

                        GroupName =
                            doc["employee_group_name"]?.ToString()
                            ?? doc["name"]?.ToString()
                            ?? "",

                        Members = new List<EmployeeGroupMember>()
                    };

                    // =================================================
                    // STEP 4: MAP CHILD TABLE employee_list
                    // =================================================

                    JArray employees =
                        doc["employee_list"] as JArray;

                    if (employees != null)
                    {
                        foreach (JToken member in employees)
                        {
                            string employeeId =
                                member["employee"]?.ToString() ?? "";

                            if (string.IsNullOrWhiteSpace(employeeId))
                                continue;

                            group.Members.Add(
                                new EmployeeGroupMember
                                {
                                    Employee = employeeId,

                                    EmployeeName =
                                        member["employee_name"]?.ToString()
                                        ?? "",

                                    ERPNextUserId =
                                        member["user_id"]?.ToString()
                                        ?? ""
                                }
                            );
                        }
                    }

                    // =================================================
                    // STEP 5: INSERT NEW / UPDATE EXISTING HRMS RECORD
                    // =================================================

                    if (string.IsNullOrWhiteSpace(group.ErpNextId))
                    {
                        throw new Exception(
                            "ERPNext Employee Group identity is missing."
                        );
                    }

                    _employeeGroupService.InsertOrUpdate(group);

                    syncedCount++;
                }

                // =====================================================
                // STEP 6: PAGINATION
                // =====================================================

                if (records.Count < pageSize)
                    break;

                start += records.Count;
            }

            // =========================================================
            // STEP 7: SYNCHRONIZE DELETED ERPNext RECORDS
            // =========================================================

            var localGroups =
                _employeeGroupService.GetAllGroups();

            // Safety: Do not remove local records if ERPNext unexpectedly
            // returns an empty list.
            if (erpIds.Count == 0 &&
                localGroups.Any(x =>
                    !string.IsNullOrWhiteSpace(x.ErpNextId)))
            {
                throw new Exception(
                    "ERPNext returned an empty Employee Group list. " +
                    "Local deletion reconciliation was stopped for safety."
                );
            }

            foreach (var localGroup in localGroups)
            {
                if (string.IsNullOrWhiteSpace(localGroup.ErpNextId))
                    continue;

                if (!erpIds.Contains(localGroup.ErpNextId))
                {
                    _employeeGroupService.MarkDeletedByErpNextId(
                        localGroup.ErpNextId
                    );
                }
            }

            return syncedCount;
        }





        private async Task<int> RefreshEmployeeGradesFromErpNextAsync()
        {
            const int pageSize = 100;

            int start = 0;

            var erpIds = new HashSet<string>(
                StringComparer.OrdinalIgnoreCase);

            var erpGrades = new List<EmployeeGrade>();

            while (true)
            {
                string url =
                    "/api/resource/Employee%20Grade" +
                    "?fields=" + Uri.EscapeDataString("[\"name\"]") +
                    "&limit_start=" + start +
                    "&limit_page_length=" + pageSize +
                    "&order_by=" + Uri.EscapeDataString("name asc");

                string response = await _erpNextService.GetAsync(url);

                JObject parsed = JObject.Parse(response);

                JArray records = parsed["data"] as JArray;

                if (records == null)
                    throw new Exception("Invalid ERPNext Employee Grade response.");

                foreach (JToken row in records)
                {
                    string erpId = row["name"]?.ToString();

                    if (string.IsNullOrWhiteSpace(erpId))
                        throw new Exception("ERPNext returned an empty Grade ID.");

                    if (!erpIds.Add(erpId))
                        throw new Exception(
                            "Duplicate ERPNext Grade ID in synchronization: " +
                            erpId);

                    // Fetch complete ERPNext document.
                    string detailResponse = await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Grade/" +
                        Uri.EscapeDataString(erpId));

                    JObject detail = JObject.Parse(detailResponse);

                    JToken doc = detail["data"];

                    if (doc == null)
                        throw new Exception(
                            "Employee Grade details not found: " + erpId);

                    erpGrades.Add(new EmployeeGrade
                    {
                        ErpNextId = doc["name"]?.ToString() ?? "",
                        GradeName = doc["name"]?.ToString() ?? "",
                        DefaultSalaryStructure =
                            doc["default_salary_structure"]?.ToString() ?? ""
                    });
                }

                if (records.Count < pageSize)
                    break;

                start += records.Count;
            }

            // Protect existing records from an unexpectedly empty ERP list.
            var localGrades = _employeeGradeService.GetAllGrades();

            if (erpIds.Count == 0 &&
                localGrades.Any(g =>
                    !string.IsNullOrWhiteSpace(g.ErpNextId)))
            {
                throw new Exception(
                    "ERPNext returned zero Employee Grades. " +
                    "Deletion reconciliation was stopped for safety.");
            }

            // Only begin local changes once the complete ERP retrieval succeeds.
            foreach (var grade in erpGrades)
            {
                _employeeGradeService.InsertOrUpdateFromErpNext(grade);
            }

            // Remove locally linked records missing from the complete ERP list.
            foreach (var local in _employeeGradeService.GetAllGrades())
            {
                if (string.IsNullOrWhiteSpace(local.ErpNextId))
                    continue;

                if (!erpIds.Contains(local.ErpNextId))
                {
                    _employeeGradeService.MarkDeletedByErpNextId(
                        local.ErpNextId);
                }
            }

            return erpGrades.Count;
        }












