        // Bi-directional Sync Action

        // Details / Edit Form Action
        [HttpGet]
        [Route("HR/EmployeeGroupDetails/{id}")]
        public async Task<ActionResult> EmployeeGroupDetails(int id)
        {



            try
            {
                // Fetch the latest ERPNext groups, member changes
                // and deletions before loading the Details page.
                await RefreshEmployeeGroupsFromErpNextAsync();
            }
            catch (Exception ex)
            {
                ViewBag.SyncWarning =
                    "ERPNext refresh was not completed: " + ex.Message;
            }

            var groupService = new EmployeeGroupService(_connectionString);
            var group = groupService.GetById(id);

            if (group == null) return NotFound();

            // Fetch employee options from ERPNext Employee Master API
            var employeeSelectList = new List<SelectListItem>();
            try
            {
                var response = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\",\"user_id\"]&limit_page_length=500");
                dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);

                if (parsed?.data != null)
                {
                    foreach (var emp in parsed.data)
                    {
                        string empId = emp.name?.ToString();
                        string empName = emp.employee_name?.ToString();
                        employeeSelectList.Add(new SelectListItem
                        {
                            Value = empId,
                            Text = $"{empId} - {empName}"
                        });
                    }
                }
            }
            catch
            {
                // Fallback if API fails
            }

            ViewBag.EmployeeList = employeeSelectList;
            return View(group);
        }










        [HttpPost]
        [Route("HR/UpdateEmployeeGroup/{id}")]
        public async Task<ActionResult>
            UpdateEmployeeGroup(
                int id,
                EmployeeGroup model)
        {
            if (id <= 0)
            {
                TempData["ErpNextError"] =
                    "Employee Group ID is missing.";

                return RedirectToAction(
                    "EmployeeGroup",
                    "HR"
                );
            }


            try
            {
                var existingGroup =
                    _employeeGroupService
                        .GetById(id);


                if (existingGroup == null)
                    return NotFound();


                string erpId =
                    existingGroup.ErpNextId;


                var memberRows =
                    new List<object>();


                if (model.Members != null)
                {
                    foreach (var member in model.Members)
                    {
                        if (string.IsNullOrWhiteSpace(
                            member.Employee))
                        {
                            continue;
                        }


                        memberRows.Add(new
                        {
                            employee =
                                member.Employee,

                            employee_name =
                                member.EmployeeName,

                            user_id =
                                member.ERPNextUserId
                        });
                    }
                }


                var payload = new
                {
                    employee_group_name =
                        model.GroupName,

                    employee_list =
                        memberRows
                };


                // ============================================================
                // UPDATE EXISTING ERP GROUP
                // ============================================================

                if (!string.IsNullOrWhiteSpace(
                    erpId))
                {
                    await _erpNextService.PutAsync(
                        "/api/resource/Employee%20Group/" +
                        Uri.EscapeDataString(erpId),
                        payload
                    );
                }

                // ============================================================
                // ERP ID MISSING -> CREATE IN ERP
                // ============================================================

                else
                {
                    var createResponse =
                        await _erpNextService.PostAsync(
                            "/api/resource/Employee%20Group",
                            payload
                        );


                    dynamic createParsed =
                        JsonConvert.DeserializeObject(
                            createResponse
                        );


                    erpId =
                        createParsed?.data?.name
                            ?.ToString();


                    if (string.IsNullOrWhiteSpace(
                        erpId))
                    {
                        throw new Exception(
                            "ERPNext Employee Group ID was not returned."
                        );
                    }
                }


                // ============================================================
                // RELOAD ERP AUTHORITATIVE COPY
                // ============================================================

                var fullResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Group/" +
                        Uri.EscapeDataString(
                            erpId
                        )
                    );


                dynamic fullParsed =
                    JsonConvert.DeserializeObject(
                        fullResponse
                    );


                var doc =
                    fullParsed?.data;


                if (doc == null)
                {
                    throw new Exception(
                        "Unable to reload Employee Group from ERPNext."
                    );
                }


                EmployeeGroup syncedGroup =
                    MapErpEmployeeGroup(
                        doc
                    );


                syncedGroup.Id =
                    id;


                _employeeGroupService
                    .InsertOrUpdate(
                        syncedGroup
                    );


                TempData["Success"] =
                    "Employee Group updated successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanErpNextError(
                        ex.Message
                    );
            }


            return RedirectToAction(
                "EmployeeGroupDetails",
                new
                {
                    id = id
                }
            );
        }

        [HttpPost]
        [Route("HR/EmployeeGroupWebhook")]
        public ActionResult EmployeeGroupWebhook(
    [FromBody] JObject payload)
        {
            try
            {
                if (payload == null)
                    return BadRequest();


                string eventType =
                    payload["event"]?.ToString()
                    ?? "";


                var doc =
                    payload["doc"];


                if (doc == null)
                    return BadRequest();


                string erpId =
                    doc["name"]?.ToString()
                    ?? "";


                if (string.IsNullOrWhiteSpace(
                    erpId))
                {
                    return BadRequest();
                }


                // ============================================================
                // DELETE EVENT
                // ============================================================

                if (string.Equals(
                    eventType,
                    "on_trash",
                    StringComparison.OrdinalIgnoreCase))
                {
                    _employeeGroupService
                        .MarkDeletedByErpNextId(
                            erpId
                        );

                    return Ok();
                }


                // ============================================================
                // CREATE / UPDATE EVENT
                // ============================================================

                EmployeeGroup group =
                    MapErpEmployeeGroup(
                        doc
                    );


                _employeeGroupService
                    .InsertOrUpdate(group);


                return Ok();
            }
            catch (Exception ex)
            {
                return BadRequest(
                    new
                    {
                        success = false,
                        message = ex.Message
                    }
                );
            }
        }





















        [HttpGet]
        public async Task<ActionResult> CreateEmployeeGroup()
        {
            try
            {
                // Fetch Employee master for child row dropdown options
                var empJson = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\",\"user_id\"]&limit_page_length=500");
                dynamic empParsed = JsonConvert.DeserializeObject(empJson);
                ViewBag.Employees = empParsed?.data;
            }
            catch { /* Fallback gracefully */ }

            return View(new EmployeeGroup());
        }
