        [HttpGet]
        [Route("HR/Employee")]
        public async Task<ActionResult> Employee(string status = "Active")
        {
            try
            {
                await SyncEmployeesFromErpNextSilent();
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Auto refresh from ERPNext failed: " + ShortErpNextError(ex.Message);
            }

            var employees = _employeeService.GetAllEmployees();

            if (!string.IsNullOrWhiteSpace(status))
            {
                employees = employees
                    .Where(emp => string.Equals(emp.Status, status, StringComparison.OrdinalIgnoreCase))
                    .ToList();
            }

            ViewBag.StatusFilter = status;
            return View(employees);
        }

        private async Task SyncEmployeesFromErpNextSilent()
        {
            int pageLength = 500;
            int start = 0;
            string fields = Uri.EscapeDataString("[\"name\",\"branch\"]");
            var remoteEmployeeIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            while (true)
            {
                string listUrl = $"/api/resource/Employee?fields={fields}&limit_start={start}&limit_page_length={pageLength}";
                var response = await _erpNextService.GetAsync(listUrl);
                var rows = JObject.Parse(response)["data"] as JArray;

                if (rows == null || rows.Count == 0)
                    break;

                foreach (var item in rows)
                {
                    string erpName = item["name"]?.ToString();
                    if (string.IsNullOrWhiteSpace(erpName))
                        continue;

                    remoteEmployeeIds.Add(erpName);

                    string detailResponse = await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(erpName)}");
                    var doc = JObject.Parse(detailResponse)["data"] as JObject;

                    if (doc == null)
                        continue;

                    var branchFromList = item["branch"]?.ToString();
                    if (string.IsNullOrWhiteSpace(ReadText(doc, "branch")) && !string.IsNullOrWhiteSpace(branchFromList))
                    {
                        doc["branch"] = branchFromList;
                    }

                    var emp = MapEmployeeFromErpNext(doc);
                    emp.ErpNextId = erpName;
                    emp.EmployeeCode = erpName;

                    _employeeService.UpsertFromErpNext(emp);
                }

                if (rows.Count < pageLength)
                    break;

                start += pageLength;
            }

            _employeeService.MarkMissingErpNextEmployeesAsDeleted(remoteEmployeeIds);
        }


