        [HttpPost]
        [Route("HR/SyncEmployeesFromErpNext")]
        public async Task<ActionResult> SyncEmployeesFromErpNext()
        {
            int insertedCount = 0, updatedCount = 0, deletedCount = 0, failedCount = 0;
            var failures = new List<string>();
            var remoteEmployeeIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            try
            {
                int pageLength = 500;
                int start = 0;
                //string fields = Uri.EscapeDataString("[\"name\"]");
                string fields = Uri.EscapeDataString("[\"name\",\"branch\"]");

                while (true)
                {
                    string listUrl = $"/api/resource/Employee?fields={fields}&limit_start={start}&limit_page_length={pageLength}";
                    var response = await _erpNextService.GetAsync(listUrl);
                    var rows = JObject.Parse(response)["data"] as JArray;

                    if (rows == null || rows.Count == 0) break;

                    foreach (var item in rows)
                    {
                        string erpName = item["name"]?.ToString();
                        if (string.IsNullOrWhiteSpace(erpName)) continue;

                        remoteEmployeeIds.Add(erpName);

                        try
                        {
                            bool existedLocally = _employeeService.ExistsByErpNextIdOrCode(erpName);
                            var detailResponse = await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(erpName)}");
                            var doc = JObject.Parse(detailResponse)["data"] as JObject;

                            if (doc == null) continue;

                            var branchFromList = item["branch"]?.ToString();
                            if (string.IsNullOrWhiteSpace(ReadText(doc, "branch")) && !string.IsNullOrWhiteSpace(branchFromList))
                            {
                                doc["branch"] = branchFromList;
                            }

                            string firstName = ReadText(doc, "first_name");
                            string middleName = ReadText(doc, "middle_name");
                            string lastName = ReadText(doc, "last_name");

                            var emp = new Employee
                            {
                                ErpNextId = erpName,
                                EmployeeCode = erpName,
                                FullName = FirstNonEmpty(ReadText(doc, "employee_name"), $"{firstName} {middleName} {lastName}".Replace("  ", " ").Trim(), erpName),
                                Salutation = ReadText(doc, "salutation"),
                                FirstName = firstName,
                                MiddleName = middleName,
                                LastName = lastName,
                                Gender = ReadText(doc, "gender"),
                                DateOfBirth = ReadDate(doc, "date_of_birth"),
                                DateOfJoining = ReadDate(doc, "date_of_joining"),
                                Status = FirstNonEmpty(ReadText(doc, "status"), "Active"),
                                Company = ReadText(doc, "company"),
                                Department = ReadText(doc, "department"),
                                Designation = ReadText(doc, "designation"),
                                Grade = ReadText(doc, "grade"),
                                EmploymentType = ReadText(doc, "employment_type"),
                                ReportsTo = ReadText(doc, "reports_to"),
                                EmployeeNumber = ReadText(doc, "employee_number"),
                                Branch = ReadText(doc, "branch"),
                                UserId = ReadText(doc, "user_id"),
                                JobApplicant = ReadText(doc, "job_applicant"),
                                ConfirmationDate = ReadDate(doc, "final_confirmation_date"),
                                NoticeDays = ReadInt(doc, "notice_number_of_days"),
                                OfferDate = ReadDate(doc, "scheduled_confirmation_date"),
                                ContractEndDate = ReadDate(doc, "contract_end_date"),
                                DateOfRetirement = ReadDate(doc, "date_of_retirement"),
                                Mobile = ReadText(doc, "cell_number"),
                                PersonalEmail = ReadText(doc, "personal_email"),
                                CompanyEmail = ReadText(doc, "company_email"),
                                PreferredContactEmail = FirstNonEmpty(ReadText(doc, "prefered_contact_email"), ReadText(doc, "prefered_email")),
                                Unsubscribed = ReadBool(doc, "unsubscribed"),
                                CurrentAddress = ReadText(doc, "current_address"),
                                PermanentAddress = ReadText(doc, "permanent_address"),
                                CurrentAddressIs = FirstNonEmpty(ReadText(doc, "current_accommodation_type"), ReadText(doc, "current_address_is")),
                                PermanentAddressIs = FirstNonEmpty(ReadText(doc, "permanent_accommodation_type"), ReadText(doc, "permanent_address_is")),
                                EmergencyContactName = ReadText(doc, "person_to_be_contacted"),
                                EmergencyPhone = ReadText(doc, "emergency_phone_number"),
                                Relation = ReadText(doc, "relation"),
                                AttendanceDeviceId = ReadText(doc, "attendance_device_id"),
                                HolidayList = ReadText(doc, "holiday_list"),
                                CTC = ReadDecimal(doc, "ctc"),
                                SalaryCurrency = ReadText(doc, "salary_currency"),
                                BankName = ReadText(doc, "bank_name"),
                                BankAccountNo = ReadText(doc, "bank_ac_no"),
                                MaritalStatus = ReadText(doc, "marital_status"),
                                BloodGroup = ReadText(doc, "blood_group"),
                                Bio = ReadText(doc, "bio"),
                                Email = FirstNonEmpty(ReadText(doc, "company_email"), ReadText(doc, "personal_email")),
                                Phone = ReadText(doc, "cell_number")
                            };

                            _employeeService.UpsertFromErpNext(emp);

                            if (existedLocally) updatedCount++;
                            else insertedCount++;
                        }
                        catch (Exception rowEx)
                        {
                            failedCount++;
                            if (failures.Count < 5)
                            {
                                failures.Add($"{erpName}: {ShortErpNextError(rowEx.Message)}");
                            }
                        }
                    }

                    if (rows.Count < pageLength) break;
                    start += pageLength;
                }

                deletedCount = _employeeService.MarkMissingErpNextEmployeesAsDeleted(remoteEmployeeIds);
                TempData["Success"] = $"ERPNext to HRMS sync complete. Inserted: {insertedCount}, Updated: {updatedCount}, Deleted locally: {deletedCount}, Failed: {failedCount}.";

                if (failures.Any())
                {
                    TempData["ErpNextError"] = "Some employees could not sync: " + string.Join(" | ", failures);
                }
            }
            catch (Exception ex)
            {
                //TempData["ErpNextError"] = "Employee sync from ERPNext failed: " + ShortErpNextError(ex.Message);
                TempData["ErpNextError"] = "Employee sync from ERPNext failed: " + ShortErpNextError(ex.GetBaseException().Message);
            }

            return RedirectToAction("Employee", "HR");
        }





