        [HttpPost]
        [Route("HR/SyncEmployeesToErpNext")]
        public async Task<ActionResult> SyncEmployeesToErpNext()
        {
            int createdCount = 0;
            int updatedCount = 0;
            int failedCount = 0;
            var failures = new List<string>();
            var employeeService = new EmployeeService(_connectionString);
            var erpEmployeeFields = await GetErpNextEmployeeFieldnamesAsync();

            foreach (var employee in employeeService.GetAllEmployees())
            {
                try
                {
                    employeeService.LoadEmployeeChildRows(employee);

                    string remoteId = employee.ErpNextId;
                    var payload = FilterEmployeePayload(BuildEmployeeErpNextPayload(employee), erpEmployeeFields);

                    if (!string.IsNullOrWhiteSpace(remoteId) && await ErpNextEmployeeExistsAsync(remoteId))
                    {
                        await _erpNextService.PutResourceAsync("Employee", remoteId, payload);
                        updatedCount++;
                    }
                    else
                    {
                        var resultJson = await _erpNextService.PostResourceAsync("Employee", payload);
                        string newErpNextId = JObject.Parse(resultJson)["data"]?["name"]?.ToString();

                        if (!string.IsNullOrWhiteSpace(newErpNextId))
                        {
                            employeeService.UpdateErpNextId(employee.Id, newErpNextId);
                        }

                        createdCount++;
                    }
                }
                catch (Exception ex)
                {
                    failedCount++;
                    if (failures.Count < 5)
                    {
                        failures.Add($"{FirstNonEmpty(employee.FullName, employee.EmployeeCode, employee.ErpNextId, employee.Id.ToString())}: {ShortErpNextError(ex.Message)}");
                    }
                }
            }

            TempData["Success"] = $"HRMS to ERPNext sync complete. Created: {createdCount}, Updated: {updatedCount}, Failed: {failedCount}.";
            if (failures.Any())
            {
                TempData["ErpNextError"] = "ERPNext rejected some employee records: " + string.Join(" | ", failures);
            }

            return RedirectToAction("Employee", "HR");
        }




























        // POST: HR/CreateEmployeeAdvance
        // POST: HR/CreateEmployeeAdvance
        [HttpPost]
        public async Task<ActionResult> CreateEmployeeAdvance(EmployeeAdvance model)
        {
            try
            {
                var resultJson = await _erpNextService.PostAsync(
                    "/api/resource/Employee%20Advance",
                    BuildEmployeeAdvancePayload(model)
                );
                dynamic parsed = JsonConvert.DeserializeObject(resultJson);
                string erpNextId = parsed?.data?.name;

                if (string.IsNullOrWhiteSpace(erpNextId))
                    throw new Exception("ERPNext did not return Employee Advance ID.");

                EmployeeAdvance refreshed =
                    await RefreshEmployeeAdvanceFromErpNextAsync(erpNextId);

                int localId = _employeeAdvanceService.InsertOrUpdate(refreshed);

                TempData["Success"] = $"Employee Advance saved as Draft. ERPNext Ref: {erpNextId}.";
                return RedirectToAction("EmployeeAdvanceDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Employee Advance save failed: " + ex.Message;
                await PopulateEmployeeAdvanceDropdownsAsync();
                ViewBag.NextCode = _employeeAdvanceService.GetNextEmployeeAdvanceCode();
                return View("~/Views/HR/CreateEmployeeAdvance.cshtml", model);
            }
        }

        [HttpPost]
        [Route("HR/UpdateEmployeeAdvance")]
        public async Task<ActionResult> UpdateEmployeeAdvance(int id, EmployeeAdvance model)
        {
            try
            {
                var local = _employeeAdvanceService.GetById(id);
                if (local == null)
                    throw new Exception("Employee Advance not found.");

                if (!string.Equals(local.Status, "Draft", StringComparison.OrdinalIgnoreCase))
                    throw new Exception("Cannot edit submitted or cancelled Employee Advance.");

                await _erpNextService.PutAsync(
                    "/api/resource/Employee%20Advance/" +
                    Uri.EscapeDataString(local.EmployeeAdvanceCode),
                    BuildEmployeeAdvancePayload(model)
                );

                EmployeeAdvance refreshed =
                    await RefreshEmployeeAdvanceFromErpNextAsync(local.EmployeeAdvanceCode);

                int localId = _employeeAdvanceService.InsertOrUpdate(refreshed);

                TempData["Success"] = "Employee Advance saved successfully.";
                return RedirectToAction("EmployeeAdvanceDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Employee Advance update failed: " + ex.Message;
                await PopulateEmployeeAdvanceDropdownsAsync();
                model.Id = id;
                return View("~/Views/HR/EmployeeAdvanceDetails.cshtml", model);
            }
        }

        [HttpPost]
        [Route("HR/SubmitEmployeeAdvance")]
        public async Task<ActionResult> SubmitEmployeeAdvance(int id)
        {
            try
            {
                var local = _employeeAdvanceService.GetById(id);
                if (local == null)
                    throw new Exception("Employee Advance not found.");

                string json =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Advance/" +
                        Uri.EscapeDataString(local.EmployeeAdvanceCode)
                    );

                dynamic parsed = JsonConvert.DeserializeObject(json);

                await _erpNextService.PostMethodAsync(
                    "/api/method/frappe.client.submit",
                    new { doc = parsed?.data }
                );

                EmployeeAdvance refreshed =
                    await RefreshEmployeeAdvanceFromErpNextAsync(local.EmployeeAdvanceCode);

                int localId = _employeeAdvanceService.InsertOrUpdate(refreshed);
                TempData["Success"] = "Employee Advance submitted successfully.";
                return RedirectToAction("EmployeeAdvanceDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Employee Advance submit failed: " + ex.Message;
                return RedirectToAction("EmployeeAdvanceDetails", new { id });
            }
        }

        [HttpPost]
        [Route("HR/CancelEmployeeAdvance")]
        public async Task<ActionResult> CancelEmployeeAdvance(int id)
        {
            try
            {
                var local = _employeeAdvanceService.GetById(id);
                if (local == null)
                    throw new Exception("Employee Advance not found.");

                await _erpNextService.PostMethodAsync(
                    "/api/method/frappe.client.cancel",
                    new
                    {
                        doctype = "Employee Advance",
                        name = local.EmployeeAdvanceCode
                    }
                );

                EmployeeAdvance refreshed =
                    await RefreshEmployeeAdvanceFromErpNextAsync(local.EmployeeAdvanceCode);

                int localId = _employeeAdvanceService.InsertOrUpdate(refreshed);
                TempData["Success"] = "Employee Advance cancelled successfully.";
                return RedirectToAction("EmployeeAdvanceDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Employee Advance cancel failed: " + ex.Message;
                return RedirectToAction("EmployeeAdvanceDetails", new { id });
            }
        }
