        [HttpPost]
        [Route("HR/SyncEmployeeOnboardingFromErpNext")]
        public async Task<ActionResult>
            SyncEmployeeOnboardingFromErpNext()
        {
            try
            {
                var response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Onboarding" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=1000"
                    );


                var json =
                    JObject.Parse(response);


                var records =
                    json["data"] as JArray;


                int syncCount = 0;


                if (records != null)
                {
                    foreach (var record in records)
                    {
                        string erpId =
                            record["name"]?.ToString();


                        if (string.IsNullOrWhiteSpace(
                            erpId))
                        {
                            continue;
                        }


                        var detailResponse =
                            await _erpNextService.GetAsync(
                                "/api/resource/Employee%20Onboarding/" +
                                Uri.EscapeDataString(erpId)
                            );


                        var detailJson =
                            JObject.Parse(detailResponse);


                        var doc =
                            detailJson["data"];


                        if (doc == null)
                            continue;


                        EmployeeOnboarding onboarding =
                            MapErpEmployeeOnboarding(
                                doc
                            );


                        _employeeOnboardingService
                            .InsertOrUpdate(
                                onboarding
                            );


                        syncCount++;
                    }
                }


                TempData["Success"] =
                    syncCount +
                    " Employee Onboarding record(s) synced from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Employee Onboarding sync failed: "
                    + ex.Message;
            }


            return RedirectToAction(
                "EmployeeOnboarding"
            );
        }

        private EmployeeOnboarding
    MapErpEmployeeOnboarding(
        JToken doc)
        {
            var onboarding =
                new EmployeeOnboarding
                {
                    ErpNextId =
                        doc["name"]?.ToString()
                        ?? "",

                    JobApplicant =
                        doc["job_applicant"]?.ToString()
                        ?? "",

                    JobOffer =
                        doc["job_offer"]?.ToString()
                        ?? "",

                    EmployeeOnboardingTemplate =
                        doc["employee_onboarding_template"]
                            ?.ToString(),

                    Company =
                        doc["company"]?.ToString()
                        ?? "",

                    BoardingStatus =
                        doc["boarding_status"]?.ToString()
                        ?? "Pending",

                    Employee =
                        doc["employee"]?.ToString(),

                    EmployeeName =
                        doc["employee_name"]?.ToString()
                        ?? "",

                    DateOfJoining =
                        ParseErpDate(
                            doc["date_of_joining"]
                        ),

                    Department =
                        doc["department"]?.ToString(),

                    OnboardingBeginsOn =
                        ParseErpDate(
                            doc["boarding_begins_on"]
                        ),

                    Designation =
                        doc["designation"]?.ToString(),

                    EmployeeGrade =
                        doc["employee_grade"]?.ToString(),

                    HolidayList =
                        doc["holiday_list"]?.ToString(),

                    Project =
                        doc["project"]?.ToString(),

                    NotifyUsersByEmail =
                        doc["notify_users_by_email"]
                            ?.ToObject<int>() == 1,

                    DocStatus =
                        doc["docstatus"]
                            ?.ToObject<int>()
                        ?? 0,

                    AmendedFrom =
                        doc["amended_from"]?.ToString(),

                    Activities =
                        new List<EmployeeOnboardingActivity>()
                };


            var activities =
                doc["activities"] as JArray;


            if (activities != null)
            {
                foreach (var row in activities)
                {
                    onboarding.Activities.Add(
                        new EmployeeOnboardingActivity
                        {
                            ActivityName =
                                row["activity_name"]
                                    ?.ToString()
                                ?? "",

                            User =
                                row["user"]?.ToString(),

                            BeginOnDays =
                                row["begin_on"]
                                    ?.ToObject<int?>(),

                            DurationDays =
                                row["duration"]
                                    ?.ToObject<int?>()
                        }
                    );
                }
            }


            return onboarding;
        }



        private DateTime ParseErpDate(
    JToken token)
        {
            if (token == null ||
                string.IsNullOrWhiteSpace(
                    token.ToString()))
            {
                return DateTime.Today;
            }

            DateTime value;

            return DateTime.TryParse(
                token.ToString(),
                out value
            )
                ? value
                : DateTime.Today;
        }
