        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteEmployeeOnboardingTemplate/{id:int}")]
        public async Task<ActionResult> DeleteEmployeeOnboardingTemplate(int id)
        {
            try
            {
                var existing =
                    _employeeOnboardingTemplateService.GetById(id);

                if (existing == null)
                {
                    TempData["ErpNextError"] =
                        "Employee Onboarding Template not found.";

                    return RedirectToAction("EmployeeOnboardingTemplate");
                }

                if (!string.IsNullOrWhiteSpace(existing.ErpNextId))
                {
                    try
                    {
                        await _erpNextService.DeleteAsync(
                            "/api/resource/Employee%20Onboarding%20Template/" +
                            Uri.EscapeDataString(existing.ErpNextId));
                    }
                    catch (Exception ex)
                    {
                        if (!IsErpNextMissing(ex))
                            throw;
                    }
                }

                _employeeOnboardingTemplateService.MarkDeletedById(id);

                TempData["Success"] =
                    "Employee Onboarding Template deleted from ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Employee Onboarding Template delete failed: " +
                    ShortErpNextError(ex.Message);

                return RedirectToAction(
                    "EmployeeOnboardingTemplateDetails",
                    new { id });
            }

            return RedirectToAction("EmployeeOnboardingTemplate");
        }




        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateEmployeeOnboardingTemplate/{id:int}")]
        public async Task<ActionResult> UpdateEmployeeOnboardingTemplate(
    int id,
    EmployeeOnboardingTemplate model)
        {
            try
            {
                var existing =
                    _employeeOnboardingTemplateService.GetById(id);

                if (existing == null)
                    return NotFound();

                if (string.IsNullOrWhiteSpace(existing.ErpNextId))
                    throw new Exception("This template is not linked with ERPNext.");

                if (string.IsNullOrWhiteSpace(model.Title))
                    throw new Exception("Title is required.");

                var activities = new List<object>();

                if (model.Activities != null)
                {
                    foreach (var activity in model.Activities)
                    {
                        if (activity == null ||
                            string.IsNullOrWhiteSpace(activity.ActivityName))
                            continue;

                        activities.Add(new
                        {
                            activity_name = activity.ActivityName,
                            user = string.IsNullOrWhiteSpace(activity.UserName)
                                ? null
                                : activity.UserName,
                            begin_on = activity.BeginOnDays ?? 0,
                            duration = activity.DurationDays ?? 0
                        });
                    }
                }

                var payload = new
                {
                    title = model.Title,
                    company = string.IsNullOrWhiteSpace(model.Company) ? null : model.Company,
                    department = string.IsNullOrWhiteSpace(model.Department) ? null : model.Department,
                    designation = string.IsNullOrWhiteSpace(model.Designation) ? null : model.Designation,
                    employee_grade = string.IsNullOrWhiteSpace(model.EmployeeGrade) ? null : model.EmployeeGrade,
                    activities = activities
                };

                await _erpNextService.PutAsync(
                    "/api/resource/Employee%20Onboarding%20Template/" +
                    Uri.EscapeDataString(existing.ErpNextId),
                    payload);

                string fullResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Onboarding%20Template/" +
                        Uri.EscapeDataString(existing.ErpNextId));

                JToken doc = JObject.Parse(fullResponse)["data"];

                if (doc == null)
                    throw new Exception("Updated ERPNext template could not be reloaded.");

                EmployeeOnboardingTemplate saved =
                    MapErpEmployeeOnboardingTemplate(doc);

                _employeeOnboardingTemplateService.InsertOrUpdate(saved);

                TempData["Success"] =
                    "Employee Onboarding Template updated in ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Employee Onboarding Template update failed: " +
                    ShortErpNextError(ex.Message);
            }

            return RedirectToAction(
                "EmployeeOnboardingTemplateDetails",
                new { id });
        }





















