                {
                    TempData["ErpNextError"] =
                        "Employee Name is required.";

                    return RedirectToAction(
                        "CreateEmployeeOnboarding"
                    );
                }


                // ============================================================
                // 2. BUILD ACTIVITY ROWS FROM FORM
                // ============================================================

                model.Activities =
                    new List<EmployeeOnboardingActivity>();


                if (ActivityNames != null)
                {
                    for (int i = 0;
                         i < ActivityNames.Count;
                         i++)
                    {
                        if (string.IsNullOrWhiteSpace(
                            ActivityNames[i]))
                        {
                            continue;
                        }


                        model.Activities.Add(
                            new EmployeeOnboardingActivity
                            {
                                ActivityName =
                                    ActivityNames[i],

                                User =
                                    Users != null &&
                                    i < Users.Count &&
                                    !string.IsNullOrWhiteSpace(
                                        Users[i])
                                        ? Users[i]
                                        : null,

                                BeginOnDays =
                                    BeginOnDaysArr != null &&
                                    i < BeginOnDaysArr.Count
                                        ? BeginOnDaysArr[i]
                                        : 0,

                                DurationDays =
                                    DurationDaysArr != null &&
                                    i < DurationDaysArr.Count
                                        ? DurationDaysArr[i]
                                        : 1
                            }
                        );
                    }
                }


                // ============================================================
                // 3. DO NOT AUTO-CREATE MASTER DOCUMENTS
                //
                // Job Applicant
                // Job Offer
                // Department
                // Designation
                // Employee Grade
                // Holiday List
                // Employee Onboarding Template
                //
                // must already exist in ERPNext.
                // ERPNext will validate them.
                // ============================================================


                // ============================================================
                // 4. BUILD ERP ACTIVITY CHILD TABLE
                // ============================================================

                var activitiesPayload =
                    model.Activities
                        .Select(
                            activity => new
                            {
                                activity_name =
                                    activity.ActivityName,

                                user =
                                    activity.User,

                                begin_on =
                                    activity.BeginOnDays
                                    ?? 0,

                                duration =
                                    activity.DurationDays
                                    ?? 1
                            }
                        )
                        .ToList();


                // ============================================================
                // 5. SAFE DATE VALUES
                // ============================================================

                DateTime joiningDate =
                    model.DateOfJoining != default(DateTime)
                        ? model.DateOfJoining
                        : DateTime.Today;


                DateTime onboardingDate =
                    model.OnboardingBeginsOn != default(DateTime)
                        ? model.OnboardingBeginsOn
                        : DateTime.Today;


                // ============================================================
                // 6. ERP PAYLOAD
                //
                // IMPORTANT:
                // boarding_status is NOT manually sent.
                // ERPNext controls this field.
                // ============================================================

                var payload = new
                {
                    job_applicant =
                        model.JobApplicant,

                    job_offer =
                        model.JobOffer,

                    employee_onboarding_template =
                        string.IsNullOrWhiteSpace(
                            model.EmployeeOnboardingTemplate)
                            ? null
                            : model.EmployeeOnboardingTemplate,

                    company =
                        model.Company,

                    employee_name =
                        model.EmployeeName,

                    date_of_joining =
                        joiningDate.ToString(
                            "yyyy-MM-dd"
                        ),

                    department =
                        string.IsNullOrWhiteSpace(
                            model.Department)
                            ? null
                            : model.Department,

                    boarding_begins_on =
                        onboardingDate.ToString(
                            "yyyy-MM-dd"
                        ),

                    designation =
                        string.IsNullOrWhiteSpace(
                            model.Designation)
                            ? null
                            : model.Designation,

                    employee_grade =
                        string.IsNullOrWhiteSpace(
                            model.EmployeeGrade)
                            ? null
                            : model.EmployeeGrade,

                    holiday_list =
                        string.IsNullOrWhiteSpace(
                            model.HolidayList)
                            ? null
                            : model.HolidayList,

                    notify_users_by_email =
                        model.NotifyUsersByEmail
                            ? 1
                            : 0,

                    activities =
                        activitiesPayload
                };


                // ============================================================
                // 7. ERP FIRST
                //
                // If ERPNext rejects:
                // DO NOT insert local HRMS record.
                // ============================================================

                var responseJson =
                    await _erpNextService.PostAsync(
                        "/api/resource/Employee%20Onboarding",
                        payload
                    );


                dynamic responseParsed =
                    JsonConvert.DeserializeObject(
                        responseJson
                    );


                string erpNextId =
                    responseParsed?.data?.name
                        ?.ToString();


                if (string.IsNullOrWhiteSpace(
                    erpNextId))
                {
                    throw new Exception(
                        "ERPNext did not return Employee Onboarding ID."
                    );
                }


                // ============================================================
                // 8. READ FULL ERP DOCUMENT BACK
                //
                // We save ERP's authoritative values locally.
                // ============================================================

                var fullResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Onboarding/" +
                        Uri.EscapeDataString(
                            erpNextId
                        )
                    );


                var fullJson =
                    JObject.Parse(
                        fullResponse
                    );


                var erpDocument =
                    fullJson["data"];


                if (erpDocument == null)
                {
                    throw new Exception(
                        "Employee Onboarding was created in ERPNext, " +
                        "but the ERP document could not be reloaded."
                    );
                }


                // ============================================================
                // 9. MAP ERP DOCUMENT TO HRMS MODEL
                //
                // Uses the mapper method I gave you:
                // MapErpEmployeeOnboarding(...)
                // ============================================================

                EmployeeOnboarding localModel =
                    MapErpEmployeeOnboarding(
                        erpDocument
                    );


                // ============================================================
                // 10. SAVE / UPSERT LOCAL HRMS
                // ============================================================

                int localId =
                    _employeeOnboardingService
                        .InsertOrUpdate(
                            localModel
                        );


                // ============================================================
                // 11. SUCCESS
                // ============================================================

                TempData["Success"] =
                    "Employee Onboarding created successfully. " +
                    "ERPNext Ref: " +
                    erpNextId;


                return RedirectToAction(
                    "EmployeeOnboardingDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                // ============================================================
                // ERPNext rejected the record:
                //
                // DO NOT save locally.
                // ============================================================

                TempData["ErpNextError"] =
                    CleanEmployeeOnboardingErpError(
                        ex.Message
                    );


                return RedirectToAction(
                    "CreateEmployeeOnboarding"
                );
            }
        }

        private string CleanEmployeeOnboardingErpError(
    string rawError)
        {
            if (string.IsNullOrWhiteSpace(
                rawError))
            {
                return "ERPNext operation failed.";
            }


            try
            {
                int jsonStart =
                    rawError.IndexOf('{');


                if (jsonStart >= 0)
                {
                    string jsonPart =
                        rawError.Substring(
                            jsonStart
                        );


                    var errorJson =
                        JObject.Parse(
                            jsonPart
                        );


                    var serverMessages =
                        errorJson[
                            "_server_messages"
                        ];


                    if (serverMessages != null)
                    {
                        var messages =
                            JArray.Parse(
                                serverMessages
                                    .ToString()
                            );


                        if (messages.Count > 0)
                        {
                            var messageObject =
                                JObject.Parse(
                                    messages[0]
                                        .ToString()
                                );


                            string message =
                                messageObject[
                                    "message"
                                ]?.ToString();


                            if (!string.IsNullOrWhiteSpace(
                                message))
                            {
                                message =
                                    System.Text.RegularExpressions
                                        .Regex.Replace(
                                            message,
                                            "<.*?>",
                                            ""
                                        );


                                return
                                    System.Net.WebUtility
                                        .HtmlDecode(
                                            message
                                        );
                            }
                        }
                    }


                    string exception =
                        errorJson["exception"]
                            ?.ToString();


                    if (!string.IsNullOrWhiteSpace(
                        exception))
                    {
                        return
                            System.Net.WebUtility
                                .HtmlDecode(
                                    System.Text.RegularExpressions
                                        .Regex.Replace(
                                            exception,
                                            "<.*?>",
                                            ""
                                        )
                                );
                    }
                }
            }
            catch
            {
                // Fall back below
            }


            return rawError;
        }

