        public async Task<ActionResult> SyncAttendanceFromErpNext()
        {
            try
            {
                var fields = Uri.EscapeDataString("[\"name\",\"employee\",\"employee_name\",\"company\",\"attendance_date\",\"status\",\"shift\",\"late_entry\",\"early_exit\",\"docstatus\"]");

                var response = await _erpNextService.GetAsync(
                    $"/api/resource/Attendance?fields={fields}&limit_page_length=0"
                );

                var parsed = Newtonsoft.Json.Linq.JObject.Parse(response);
                var dataList = parsed["data"];

                if (dataList != null)
                {
                    using (var conn = new SqlConnection(_connectionString))
                    {
                        conn.Open();

                        foreach (var item in dataList)
                        {
                            string erpId = item["name"]?.ToString();
                            string emp = item["employee"]?.ToString();

                            if (string.IsNullOrWhiteSpace(erpId) || string.IsNullOrWhiteSpace(emp))
                                continue;

                            string empName = item["employee_name"]?.ToString();
                            string comp = item["company"]?.ToString();
                            string status = item["status"]?.ToString();
                            string shift = item["shift"]?.ToString();

                            DateTime attDate = DateTime.TryParse(item["attendance_date"]?.ToString(), out DateTime parsedDate)
                                ? parsedDate
                                : DateTime.Today;

                            int docstatus = int.TryParse(item["docstatus"]?.ToString(), out int ds) ? ds : 0;

                            bool lateEntry = item["late_entry"]?.ToString() == "1";
                            bool earlyExit = item["early_exit"]?.ToString() == "1";

                            using (var checkCmd = new SqlCommand(
                                "SELECT COUNT(*) FROM Attendances WHERE ErpNextId = @ErpId OR AttendanceCode = @ErpId", conn))
                            {
                                checkCmd.Parameters.AddWithValue("@ErpId", erpId);
                                int exists = (int)checkCmd.ExecuteScalar();

                                if (exists > 0)
                                {
                                    using (var updCmd = new SqlCommand(@"
UPDATE Attendances
SET ErpNextId=@ErpId,
    AttendanceCode=@ErpId,
    Employee=@Emp,
    EmployeeName=@EmpName,
    Company=@Comp,
    AttendanceDate=@Date,
    Status=@Status,
    Shift=@Shift,
    LateEntry=@LateEntry,
    EarlyExit=@EarlyExit,
    DocStatus=@DocStatus,
    IsDeleted=0
WHERE ErpNextId=@ErpId OR AttendanceCode=@ErpId", conn))
                                    {
                                        updCmd.Parameters.AddWithValue("@ErpId", erpId);
                                        updCmd.Parameters.AddWithValue("@Emp", emp);
                                        updCmd.Parameters.AddWithValue("@EmpName", empName ?? (object)DBNull.Value);
                                        updCmd.Parameters.AddWithValue("@Comp", comp ?? (object)DBNull.Value);
                                        updCmd.Parameters.AddWithValue("@Date", attDate);
                                        updCmd.Parameters.AddWithValue("@Status", status ?? "Present");
                                        updCmd.Parameters.AddWithValue("@Shift", shift ?? (object)DBNull.Value);
                                        updCmd.Parameters.AddWithValue("@LateEntry", lateEntry);
                                        updCmd.Parameters.AddWithValue("@EarlyExit", earlyExit);
                                        updCmd.Parameters.AddWithValue("@DocStatus", docstatus);

                                        updCmd.ExecuteNonQuery();
                                    }
                                }
                                else
                                {
                                    using (var insCmd = new SqlCommand(@"
INSERT INTO Attendances
(ErpNextId, AttendanceCode, Employee, EmployeeName, Company, AttendanceDate, Status, Shift, LateEntry, EarlyExit, DocStatus, IsDeleted)
VALUES
(@ErpId, @ErpId, @Emp, @EmpName, @Comp, @Date, @Status, @Shift, @LateEntry, @EarlyExit, @DocStatus, 0)", conn))
                                    {
                                        insCmd.Parameters.AddWithValue("@ErpId", erpId);
                                        insCmd.Parameters.AddWithValue("@Emp", emp);
                                        insCmd.Parameters.AddWithValue("@EmpName", empName ?? (object)DBNull.Value);
                                        insCmd.Parameters.AddWithValue("@Comp", comp ?? (object)DBNull.Value);
                                        insCmd.Parameters.AddWithValue("@Date", attDate);
                                        insCmd.Parameters.AddWithValue("@Status", status ?? "Present");
                                        insCmd.Parameters.AddWithValue("@Shift", shift ?? (object)DBNull.Value);
                                        insCmd.Parameters.AddWithValue("@LateEntry", lateEntry);
                                        insCmd.Parameters.AddWithValue("@EarlyExit", earlyExit);
                                        insCmd.Parameters.AddWithValue("@DocStatus", docstatus);
                                        checkCmd.Parameters.AddWithValue("@Date", attDate);
                                        checkCmd.Parameters.AddWithValue("@Emp", emp);

                                        insCmd.ExecuteNonQuery();
                                    }
                                }
                            }
                        }
                    }
                }

                TempData["Success"] = "Attendance synced successfully from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Sync failed: " + ex.Message;
            }

            return RedirectToAction("Attendance");
        }



        private async Task LoadDropdownsToViewBag()
        {
            try
            {
                var empRes = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=99999");
                ViewBag.Employees = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(empRes)?.data;

                var shiftRes = await _erpNextService.GetAsync("/api/resource/Shift Type?fields=[\"name\"]&limit_page_length=500");
                ViewBag.Shifts = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(shiftRes)?.data;

                var compRes = await _erpNextService.GetAsync("/api/resource/Company?fields=[\"name\"]&limit_page_length=500");
                ViewBag.Companies = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(compRes)?.data;

                var leaveTypeRes = await _erpNextService.GetAsync("/api/resource/Leave Type?fields=[\"name\"]&limit_page_length=500");
                ViewBag.LeaveTypes = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(leaveTypeRes)?.data;
            }
            catch
            {
                ViewBag.Employees = new List<object>();
                ViewBag.Shifts = new List<object>();
                ViewBag.Companies = new List<object>();
                ViewBag.LeaveTypes = new List<object>();
            }
        }










