        public ActionResult TrainingResult(string id)
        {
            var list = _trainingResultService.GetAll(id);
            ViewBag.IdFilter = id;
            return View(list);
        }

        public ActionResult CreateTrainingResult()
        {
            return View(new TrainingResult());
        }

        [HttpPost]
        public ActionResult CreateTrainingResult(TrainingResult model,
            string[] Employees, decimal?[] Hours, string[] Grades, string[] Comments)
        {
            var emps = Employees != null ? new List<string>(Employees) : new List<string>();
            var hrs = Hours != null ? new List<decimal?>(Hours) : new List<decimal?>();
            var grds = Grades != null ? new List<string>(Grades) : new List<string>();
            var cmts = Comments != null ? new List<string>(Comments) : new List<string>();

            int newId = _trainingResultService.Insert(model, emps, hrs, grds, cmts);
            return RedirectToAction("TrainingResultDetails", new { id = newId });
        }

        public ActionResult TrainingResultDetails(int id)
        {
            var model = _trainingResultService.GetById(id);
            if (model == null) return NotFound();
            return View(model);
        }

