        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> CreateEmployeeGrade(EmployeeGrade model)
        {
            try
            {
                // =====================================================
                // VALIDATION
                // =====================================================

                if (model == null)
                {
                    throw new Exception("Employee Grade data is required.");
                }

                if (string.IsNullOrWhiteSpace(model.GradeName))
                {
                    throw new Exception("Grade Name is required.");
                }

                model.GradeName = model.GradeName.Trim();


                // =====================================================
                // VALIDATE / ENSURE SALARY STRUCTURE LINK
                // =====================================================

                if (!string.IsNullOrWhiteSpace(
                    model.DefaultSalaryStructure))
                {
                    await _erpNextService.EnsureLinkExistsAsync(
                        "Salary Structure",
                        model.DefaultSalaryStructure.Trim(),
                        "name"
                    );
                }


                // =====================================================
                // ERPNext PAYLOAD
                // =====================================================

                var payload = new
                {
                    name = model.GradeName,

                    default_salary_structure =
                        string.IsNullOrWhiteSpace(
                            model.DefaultSalaryStructure)
                            ? null
                            : model.DefaultSalaryStructure.Trim(),

                    default_base_pay =
                        model.DefaultBasePay
                };


                // =====================================================
                // ERPNext FIRST
                // =====================================================

                string response =
                    await _erpNextService.PostAsync(
                        "/api/resource/Employee%20Grade",
                        payload
                    );


                JObject json =
                    JObject.Parse(response);


                JToken doc =
                    json["data"];


                if (doc == null)
                {
                    throw new Exception(
                        "ERPNext did not return Employee Grade details."
                    );
                }


                string erpNextId =
                    doc["name"]?.ToString();


                if (string.IsNullOrWhiteSpace(
                    erpNextId))
                {
                    throw new Exception(
                        "ERPNext did not return Employee Grade ID."
                    );
                }


                // =====================================================
                // READ ACTUAL VALUES SAVED BY ERPNext
                // =====================================================

                string detailResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Grade/" +
                        Uri.EscapeDataString(
                            erpNextId
                        )
                    );


                JObject detailJson =
                    JObject.Parse(
                        detailResponse
                    );


                JToken savedDoc =
                    detailJson["data"];


                if (savedDoc == null)
                {
                    throw new Exception(
                        "Created Employee Grade could not be reloaded from ERPNext."
                    );
                }


                var savedGrade =
                    new EmployeeGrade
                    {
                        ErpNextId =
                            savedDoc["name"]?.ToString()
                            ?? erpNextId,

                        GradeName =
                            savedDoc["employee_grade_name"]
                                ?.ToString()
                            ?? savedDoc["name"]
                                ?.ToString()
                            ?? model.GradeName,

                        DefaultSalaryStructure =
                            savedDoc["default_salary_structure"]
                                ?.ToString()
                            ?? "",

                        DefaultBasePay =
                            savedDoc["default_base_pay"] == null ||
                            savedDoc["default_base_pay"].Type ==
                                Newtonsoft.Json.Linq.JTokenType.Null
                                ? (decimal?)null
                                : savedDoc["default_base_pay"]
                                    .ToObject<decimal?>()
                    };


                // =====================================================
                // SAVE / UPSERT HRMS AFTER ERP SUCCESS
                // =====================================================

                int localId =
                    _employeeGradeService
                        .InsertOrUpdateFromErpNext(
                            savedGrade
                        );


                TempData["Success"] =
                    "Employee Grade created successfully in ERPNext and HRMS.";


                return RedirectToAction(
                    "EmployeeGradeDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Microsoft.Data.SqlClient.SqlException ex)
                when (ex.Number == 2627 ||
                      ex.Number == 2601)
            {
                TempData["ErpNextError"] =
                    "Employee Grade already exists in HRMS.";

                return RedirectToAction(
                    "EmployeeGrades"
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Employee Grade creation failed: " +
                    ex.Message;

                return RedirectToAction(
                    "EmployeeGrades"
                );
            }
        }


