        [HttpGet]
        [Route("HR/EmployeeSkillMap")]
        public async Task<ActionResult> EmployeeSkillMap(string id, string employeeName)
        {
            try
            {
                await PullEmployeeSkillMapsFromErpNext();
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext refresh failed: " + CleanEmployeeSkillMapErpError(ex.Message);
            }

            var list = _employeeSkillMapService.GetAll(id, employeeName);

            ViewBag.IdFilter = id;
            ViewBag.EmployeeNameFilter = employeeName;

            return View("~/Views/HR/EmployeeSkillMap.cshtml", list);
        }





        private async Task PullEmployeeSkillMapsFromErpNext()
        {
            string listResponse = await _erpNextService.GetAsync(
                "/api/resource/Employee%20Skill%20Map?fields=[\"name\"]&limit_page_length=5000"
            );

            JObject listJson = JObject.Parse(listResponse);
            JArray records = listJson["data"] as JArray;

            var erpIds = new List<string>();

            if (records == null) return;

            foreach (JToken item in records)
            {
                string erpId = item["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpId))
                    continue;

                erpIds.Add(erpId);

                string detailResponse = await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Skill%20Map/" + Uri.EscapeDataString(erpId)
                );

                JObject detailJson = JObject.Parse(detailResponse);
                JToken doc = detailJson["data"];

                if (doc == null)
                    continue;

                EmployeeSkillMap model = MapErpEmployeeSkillMap(doc);

                _employeeSkillMapService.InsertOrUpdate(model);
            }

            _employeeSkillMapService.MarkDeletedIfMissingFromErpNext(erpIds);
        }




















        [HttpGet]
        [Route("HR/CreateEmployeeSkillMap")]
        public async Task<ActionResult>
            CreateEmployeeSkillMap()
        {
            try
            {
                // ============================================================
                // EMPLOYEE DROPDOWN
                // ERP Link field -> Employee
                // ============================================================

                string employeeResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee" +
                        "?fields=[\"name\",\"employee_name\",\"designation\"]" +
                        "&limit_page_length=5000"
                    );


                dynamic employeeParsed =
                    JsonConvert.DeserializeObject(
                        employeeResponse
                    );


                ViewBag.Employees =
                    employeeParsed?.data;


                // ============================================================
                // SKILL DROPDOWN
                // ERP Link field -> Skill
                // ============================================================

                string skillResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Skill" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=5000"
                    );


                dynamic skillParsed =
                    JsonConvert.DeserializeObject(
                        skillResponse
                    );


                ViewBag.Skills =
                    skillParsed?.data;


                // ============================================================
                // TRAINING DROPDOWN
                // ERP Link field -> Training Event
                // ============================================================

                string trainingResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Training%20Event" +
                        "?fields=[\"name\",\"event_name\",\"end_time\"]" +
                        "&limit_page_length=5000"
                    );


                dynamic trainingParsed =
                    JsonConvert.DeserializeObject(
                        trainingResponse
                    );


                ViewBag.Trainings =
                    trainingParsed?.data;
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Unable to load Employee Skill Map ERPNext masters: "
                    + ex.Message;


                ViewBag.Employees = null;
                ViewBag.Skills = null;
                ViewBag.Trainings = null;
            }


            return View(
                "~/Views/HR/CreateEmployeeSkillMap.cshtml",
                new EmployeeSkillMap()
            );
        }



        [HttpGet]
        [Route("HR/GetEmployeeSkillMapEmployeeDetails")]
        public async Task<JsonResult>
    GetEmployeeSkillMapEmployeeDetails(
        string employee)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(
                    employee))
                {
                    return Json(
                        new
                        {
                            success = false
                        }
                    );
                }


                string response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee/" +
                        Uri.EscapeDataString(
                            employee
                        )
                    );


                JObject json =
                    JObject.Parse(
                        response
                    );


                JToken doc =
                    json["data"];


                if (doc == null)
                {
                    return Json(
                        new
                        {
                            success = false
                        }
                    );
                }


                return Json(
                    new
                    {
                        success = true,

                        employeeName =
                            doc["employee_name"]
                                ?.ToString()
                            ?? "",

                        designation =
                            doc["designation"]
                                ?.ToString()
                            ?? ""
                    }
                );
            }
            catch (Exception ex)
            {
                return Json(
                    new
                    {
                        success = false,
                        message = ex.Message
                    }
                );
            }
        }

        [HttpPost]
        [Route("HR/CreateEmployeeSkillMap")]
        public async Task<ActionResult> CreateEmployeeSkillMap(EmployeeSkillMap model)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(model.Employee))
                {
                    TempData["ErpNextError"] = "Employee is required.";
                    return RedirectToAction("CreateEmployeeSkillMap");
                }

                var skillRows = new List<object>();

                if (model.Skills != null)
                {
                    foreach (var row in model.Skills)
                    {
                        if (string.IsNullOrWhiteSpace(row.Skill))
                            continue;

                        if (row.Proficiency <= 0)
                        {
                            TempData["ErpNextError"] =
                                "Proficiency is required for skill " + row.Skill + ".";

                            return RedirectToAction("CreateEmployeeSkillMap");
                        }

                        skillRows.Add(new
                        {
                            skill = row.Skill,

                            // HRMS stores/shows 1 to 5 stars.
                            // ERPNext Rating field stores 0 to 1.
                            proficiency = row.Proficiency > 1
                                ? row.Proficiency / 5
                                : row.Proficiency,

                            evaluation_date = row.EvaluationDate.HasValue
                                ? row.EvaluationDate.Value.ToString("yyyy-MM-dd")
                                : null
                        });
                    }
                }

                var trainingRows = new List<object>();

                if (model.Trainings != null)
                {
                    foreach (var row in model.Trainings)
                    {
                        if (string.IsNullOrWhiteSpace(row.Training))
                            continue;

                        trainingRows.Add(new
                        {
                            training = row.Training
                        });
                    }
                }

                var payload = new
                {
                    employee = model.Employee,
                    employee_skills = skillRows,
                    trainings = trainingRows
                };

                string createResponse = await _erpNextService.PostAsync(
                    "/api/resource/Employee%20Skill%20Map",
                    payload
                );

                JObject createJson = JObject.Parse(createResponse);

                string erpId = createJson["data"]?["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpId))
                {
                    throw new Exception("ERPNext did not return Employee Skill Map ID.");
                }

                string fullResponse = await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Skill%20Map/" + Uri.EscapeDataString(erpId)
                );

                JObject fullJson = JObject.Parse(fullResponse);

                JToken doc = fullJson["data"];

                if (doc == null)
                {
                    throw new Exception("Employee Skill Map was created in ERPNext but could not be reloaded.");
                }

                EmployeeSkillMap localModel = MapErpEmployeeSkillMap(doc);

                int localId = _employeeSkillMapService.InsertOrUpdate(localModel);

                TempData["Success"] =
                    "Employee Skill Map created successfully. ERPNext Ref: " + erpId;

                return RedirectToAction(
                    "EmployeeSkillMapDetails",
                    new { id = localId }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanEmployeeSkillMapErpError(ex.Message);

                return RedirectToAction("CreateEmployeeSkillMap");
            }
        }

        [HttpPost]
        [Route("HR/SyncEmployeeSkillMapsFromErpNext")]
        public async Task<ActionResult>
    SyncEmployeeSkillMapsFromErpNext()
        {
            try
            {
                string listResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Skill%20Map" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=5000"
                    );


                JObject listJson =
                    JObject.Parse(
                        listResponse
                    );


                JArray records =
                    listJson["data"]
                        as JArray;


                int insertedCount = 0;
                int updatedCount = 0;
                int failedCount = 0;


                if (records != null)
                {
                    foreach (JToken item in records)
                    {
                        try
                        {
                            string erpId =
                                item["name"]
                                    ?.ToString();


                            if (string.IsNullOrWhiteSpace(
                                erpId))
                            {
                                continue;
                            }
                            bool exists =
                                _employeeSkillMapService
                                    .GetByErpNextId(
                                        erpId
                                    ) != null;


                            // ================================================
                            // GET FULL DOCUMENT
                            // ================================================

                            string detailResponse =
                                await _erpNextService.GetAsync(
                                    "/api/resource/Employee%20Skill%20Map/" +
                                    Uri.EscapeDataString(
                                        erpId
                                    )
                                );


                            JObject detailJson =
                                JObject.Parse(
                                    detailResponse
                                );


                            JToken doc =
                                detailJson["data"];


                            if (doc == null)
                            {
                                failedCount++;
                                continue;
                            }


                            EmployeeSkillMap model =
                                MapErpEmployeeSkillMap(
                                    doc
                                );


                            _employeeSkillMapService
                                .InsertOrUpdate(
                                    model
                                );


                            if (exists)
                            {
                                updatedCount++;
                            }
                            else
                            {
                                insertedCount++;
                            }
                        }
                        catch (Exception recordEx)
                        {
                            failedCount++;


                            System.Diagnostics.Debug
                                .WriteLine(
                                    "Employee Skill Map sync error: "
                                    + recordEx.Message
                                );
                        }
                    }
                }


                TempData["Success"] =
                    "Employee Skill Map sync completed. " +
                    "New: "
                    + insertedCount
                    + ", Updated: "
                    + updatedCount
                    + ", Failed: "
                    + failedCount
                    + ".";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Employee Skill Map sync failed: "
                    + ex.Message;
            }


            return RedirectToAction(
                "EmployeeSkillMap"
            );
        }



        private EmployeeSkillMap
    MapErpEmployeeSkillMap(
        JToken doc)
        {
            var model =
                new EmployeeSkillMap
                {
                    ErpNextId =
                        doc["name"]
                            ?.ToString()
                        ?? "",

                    Employee =
                        doc["employee"]
                            ?.ToString()
                        ?? "",

                    EmployeeName =
                        doc["employee_name"]
                            ?.ToString()
                        ?? "",

                    Designation =
                        doc["designation"]
                            ?.ToString()
                        ?? "",

                    Skills =
                        new List<EmployeeSkillMapSkill>(),

                    Trainings =
                        new List<EmployeeSkillMapTraining>()
                };


            // ============================================================
            // EMPLOYEE SKILLS
            // ============================================================

            JArray skills =
                doc["employee_skills"]
                    as JArray;


            if (skills != null)
            {
                foreach (JToken row in skills)
                {
                    model.Skills.Add(
                        new EmployeeSkillMapSkill
                        {
                            Skill =
                                row["skill"]
                                    ?.ToString()
                                ?? "",

                            Proficiency = NormalizeEmployeeSkillMapProficiency(
    row["proficiency"]?.ToObject<decimal>() ?? 0
),

                            EvaluationDate =
                                ParseEmployeeSkillMapNullableDate(
                                    row["evaluation_date"]
                                )
                        }
                    );
                }
            }


            // ============================================================
            // TRAININGS
            // ============================================================

            JArray trainings =
                doc["trainings"]
                    as JArray;


            if (trainings != null)
            {
                foreach (JToken row in trainings)
                {
                    model.Trainings.Add(
                        new EmployeeSkillMapTraining
                        {
                            Training =
                                row["training"]
                                    ?.ToString()
                                ?? "",

                            TrainingDate =
                                ParseEmployeeSkillMapNullableDate(
                                    row["training_date"]
                                )
                        }
                    );
                }
            }


            return model;
        }



        private DateTime?
    ParseEmployeeSkillMapNullableDate(
        JToken token)
        {
            if (
                token == null ||
                string.IsNullOrWhiteSpace(
                    token.ToString()
                )
            )
            {
                return null;
            }


            DateTime value;


            if (
                DateTime.TryParse(
                    token.ToString(),
                    out value
                )
            )
            {
                return value;
            }


            return null;
        }


        private string CleanEmployeeSkillMapErpError(
    string rawError)
        {
            if (string.IsNullOrWhiteSpace(
                rawError))
            {
                return "ERPNext operation failed.";
            }


            try
            {
                int jsonStart =
                    rawError.IndexOf('{');


                if (jsonStart >= 0)
                {
                    JObject json =
                        JObject.Parse(
                            rawError.Substring(
                                jsonStart
                            )
                        );


                    JToken serverMessages =
                        json["_server_messages"];


                    if (serverMessages != null)
                    {
                        JArray messages =
                            JArray.Parse(
                                serverMessages.ToString()
                            );


                        if (messages.Count > 0)
                        {
                            JObject message =
                                JObject.Parse(
                                    messages[0].ToString()
                                );


                            string text =
                                message["message"]
                                    ?.ToString();


                            if (!string.IsNullOrWhiteSpace(
                                text))
                            {
                                text =
                                    System.Text.RegularExpressions
                                        .Regex.Replace(
                                            text,
                                            "<[^>]*>",
                                            " "
                                        );


                                text =
                                    System.Text.RegularExpressions
                                        .Regex.Replace(
                                            text,
                                            @"\s+",
                                            " "
                                        )
                                        .Trim();


                                return
                                    System.Net.WebUtility
                                        .HtmlDecode(
                                            text
                                        );
                            }
                        }
                    }
                }
            }
            catch
            {
            }


            return rawError;
        }




