        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateEmployeeSkillMap/{id:int}")]
        public async Task<ActionResult> UpdateEmployeeSkillMap(int id, EmployeeSkillMap model)
        {
            var existing = _employeeSkillMapService.GetById(id);

            if (existing == null)
                return NotFound();

            model.Id = id;
            model.ErpNextId = existing.ErpNextId;
            model.Employee = existing.Employee;
            model.EmployeeName = existing.EmployeeName;
            model.Designation = existing.Designation;

            try
            {
                var skillRows = new List<object>();

                if (model.Skills != null)
                {
                    foreach (var row in model.Skills)
                    {
                        if (string.IsNullOrWhiteSpace(row.Skill))
                            continue;

                        decimal erpProficiency = row.Proficiency;

                        if (erpProficiency > 1)
                            erpProficiency = erpProficiency / 5;

                        skillRows.Add(new
                        {
                            skill = row.Skill,
                            proficiency = erpProficiency,
                            evaluation_date = row.EvaluationDate.HasValue
                                ? row.EvaluationDate.Value.ToString("yyyy-MM-dd")
                                : null
                        });
                    }
                }

                var trainingRows = new List<object>();

                if (model.Trainings != null)
                {
                    foreach (var row in model.Trainings)
                    {
                        if (string.IsNullOrWhiteSpace(row.Training))
                            continue;

                        trainingRows.Add(new
                        {
                            training = row.Training
                        });
                    }
                }

                var payload = new
                {
                    employee_skills = skillRows,
                    trainings = trainingRows
                };

                string erpName = !string.IsNullOrWhiteSpace(existing.ErpNextId)
                    ? existing.ErpNextId
                    : existing.Employee;

                await _erpNextService.PutAsync(
                    "/api/resource/Employee%20Skill%20Map/" + Uri.EscapeDataString(erpName),
                    payload
                );

                string fullResponse = await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Skill%20Map/" + Uri.EscapeDataString(erpName)
                );

                JObject fullJson = JObject.Parse(fullResponse);
                JToken doc = fullJson["data"];

                if (doc != null)
                {
                    var freshModel = MapErpEmployeeSkillMap(doc);
                    _employeeSkillMapService.InsertOrUpdate(freshModel);
                }

                TempData["Success"] = "Employee Skill Map updated successfully.";
                return RedirectToAction("EmployeeSkillMapDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext update failed: " + CleanEmployeeSkillMapErpError(ex.Message);

                return RedirectToAction("EmployeeSkillMapDetails", new { id, edit = true });
            }
        }





        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteEmployeeSkillMap/{id:int}")]
        public async Task<ActionResult> DeleteEmployeeSkillMap(int id)
        {
            var model = _employeeSkillMapService.GetById(id);

            if (model == null)
                return NotFound();

            string erpName = !string.IsNullOrWhiteSpace(model.ErpNextId)
                ? model.ErpNextId
                : model.Employee;

            try
            {
                await _erpNextService.DeleteAsync(
                    "/api/resource/Employee%20Skill%20Map/" + Uri.EscapeDataString(erpName)
                );
            }
            catch
            {
            }

            _employeeSkillMapService.MarkDeletedById(id);

            TempData["Success"] = "Employee Skill Map deleted successfully.";
            return RedirectToAction("EmployeeSkillMap");
        }



