        private decimal NormalizeEmployeeSkillMapProficiency(decimal value)
        {
            if (value > 0 && value <= 1)
                return Math.Round(value * 5, 0);

            return value;
        }













        [HttpGet]
        [Route("HR/EmployeeOnboardingTemplateDetails/{id:int}")]
        public async Task<ActionResult> EmployeeOnboardingTemplateDetails(int id)
        {
            EmployeeOnboardingTemplate model =
                _employeeOnboardingTemplateService.GetById(id);

            if (model == null)
            {
                TempData["ErpNextError"] =
                    "Employee Onboarding Template not found in HRMS.";

                return RedirectToAction("EmployeeOnboardingTemplate");
            }

            try
            {
                if (!string.IsNullOrWhiteSpace(model.ErpNextId))
                {
                    string response =
                        await _erpNextService.GetAsync(
                            "/api/resource/Employee%20Onboarding%20Template/" +
                            Uri.EscapeDataString(model.ErpNextId)
                        );

                    JToken doc =
                        JObject.Parse(response)["data"];

                    if (doc != null)
                    {
                        EmployeeOnboardingTemplate erpModel =
                            MapErpEmployeeOnboardingTemplate(doc);

                        _employeeOnboardingTemplateService
                            .InsertOrUpdate(erpModel);

                        model =
                            _employeeOnboardingTemplateService.GetById(id);
                    }
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext refresh failed: " + ShortErpNextError(ex.Message);
            }

            await LoadEmployeeOnboardingTemplateDropdowns();

            return View(
                "~/Views/HR/EmployeeOnboardingTemplateDetails.cshtml",
                model
            );
        }



