        private async Task<dynamic> GetErpList(string url)
        {
            try
            {
                string json = await _erpNextService.GetAsync(url);
                dynamic parsed = JsonConvert.DeserializeObject(json);
                return parsed?.data;
            }
            catch
            {
                return new List<object>();
            }
        }


        [HttpGet]
        public async Task<JsonResult> GetEmployeeGrievanceLinkOptions(string doctype)
        {
            if (string.IsNullOrWhiteSpace(doctype))
                return Json(new List<object>());

            try
            {
                string fields = doctype == "Employee"
                    ? "[\"name\",\"employee_name\"]"
                    : doctype == "User"
                        ? "[\"name\",\"full_name\"]"
                        : "[\"name\"]";

                string json = await _erpNextService.GetAsync(
                    "/api/resource/" + Uri.EscapeDataString(doctype) +
                    "?fields=" + Uri.EscapeDataString(fields) +
                    "&limit_page_length=1000&order_by=name%20asc"
                );

                dynamic parsed = JsonConvert.DeserializeObject(json);
                var result = new List<object>();

                foreach (var row in parsed.data)
                {
                    string name = row.name?.ToString();
                    string label = name;

                    if (doctype == "Employee" && row.employee_name != null)
                        label = row.employee_name.ToString() + " (" + name + ")";

                    if (doctype == "User" && row.full_name != null)
                        label = row.full_name.ToString() + " (" + name + ")";

                    result.Add(new { value = name, text = label });
                }

                return Json(result);
            }
            catch
            {
                return Json(new List<object>());
            }
        }











        private async Task<string> PushEmployeeGrievanceToErpNext(EmployeeGrievance model)
        {
            var payload = new Dictionary<string, object>
            {
                ["subject"] = model.Subject,
                ["raised_by"] = model.RaisedBy,
                ["date"] = model.GrievanceDate.ToString("yyyy-MM-dd"),
                ["status"] = string.IsNullOrWhiteSpace(model.Status) ? "Open" : model.Status,
                ["grievance_against_party"] = model.GrievanceAgainstParty,
                ["grievance_against"] = model.GrievanceAgainst,
                ["associated_document_type"] = model.AssociatedDocumentType,
                ["associated_document"] = model.AssociatedDocument,
                ["grievance_type"] = model.GrievanceType,
                ["description"] = model.Description,
                ["cause_of_grievance"] = model.CauseOfGrievance,
                ["resolved_by"] = model.ResolvedBy,
                ["resolution_date"] = model.ResolutionDate?.ToString("yyyy-MM-dd"),
                ["resolution_detail"] = model.ResolutionDetails,
                ["employee_responsible"] = model.EmployeeResponsible
            };

            string responseJson = await _erpNextService.PostAsync("/api/resource/Employee%20Grievance", payload);
            dynamic responseParsed = JsonConvert.DeserializeObject(responseJson);

            return responseParsed?.data?.name?.ToString();
        }


