        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateEmployeeSeparation/{id:int}")]
        public async Task<ActionResult>
    UpdateEmployeeSeparation(
        int id,
        EmployeeSeparation model,
        string[] ActivityNames,
        string[] Users,
        int?[] BeginOnDaysArr,
        int?[] DurationDaysArr)
        {
            try
            {
                var existing =
                    _employeeSeparationService.GetById(id);

                if (existing == null)
                    return NotFound();

                if (string.IsNullOrWhiteSpace(
                    existing.EmployeeSeparationCode))
                {
                    throw new Exception(
                        "Employee Separation is not linked to ERPNext."
                    );
                }

                if (string.IsNullOrWhiteSpace(model.Employee))
                    throw new Exception("Employee is required.");

                model.Activities =
                    new List<EmployeeSeparationActivity>();

                if (ActivityNames != null)
                {
                    for (int i = 0;
                         i < ActivityNames.Length;
                         i++)
                    {
                        if (string.IsNullOrWhiteSpace(
                            ActivityNames[i]))
                        {
                            continue;
                        }

                        model.Activities.Add(
                            new EmployeeSeparationActivity
                            {
                                ActivityName =
                                    ActivityNames[i],

                                UserName =
                                    Users != null &&
                                    i < Users.Length
                                        ? Users[i]
                                        : "",

                                BeginOnDays =
                                    BeginOnDaysArr != null &&
                                    i < BeginOnDaysArr.Length
                                        ? BeginOnDaysArr[i]
                                        : 0,

                                DurationDays =
                                    DurationDaysArr != null &&
                                    i < DurationDaysArr.Length
                                        ? DurationDaysArr[i]
                                        : 1
                            }
                        );
                    }
                }

                var activitiesPayload =
                    model.Activities.Select(x => new
                    {
                        activity_name = x.ActivityName,

                        user =
                            string.IsNullOrWhiteSpace(
                                x.UserName)
                                ? null
                                : x.UserName,

                        begin_on =
                            x.BeginOnDays ?? 0,

                        duration =
                            x.DurationDays ?? 1
                    }).ToList();

                var payload = new
                {
                    employee = model.Employee,

                    boarding_begins_on =
                        model.SeparationBeginsOn
                            .ToString("yyyy-MM-dd"),

                    employee_separation_template =
                        string.IsNullOrWhiteSpace(
                            model.EmployeeSeparationTemplate)
                            ? null
                            : model.EmployeeSeparationTemplate,

                    notify_users_by_email =
                        model.NotifyUsersByEmail ? 1 : 0,

                    exit_interview =
                        string.IsNullOrWhiteSpace(
                            model.ExitInterviewSummary)
                            ? null
                            : model.ExitInterviewSummary,

                    activities = activitiesPayload
                };

                string erpId =
                    existing.EmployeeSeparationCode;

                // =====================================================
                // ERP FIRST
                // =====================================================

                await _erpNextService.PutAsync(
                    "/api/resource/Employee%20Separation/" +
                    Uri.EscapeDataString(erpId),
                    payload
                );

                // =====================================================
                // READ ERP AUTHORITATIVE COPY
                // =====================================================

                string response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Separation/" +
                        Uri.EscapeDataString(erpId)
                    );

                JToken doc =
                    JObject.Parse(response)["data"];

                if (doc == null)
                {
                    throw new Exception(
                        "Updated Employee Separation could not be reloaded."
                    );
                }

                EmployeeSeparation saved =
                    MapErpEmployeeSeparation(doc);

                // =====================================================
                // THEN UPDATE HRMS
                // =====================================================

                _employeeSeparationService
                    .UpdateByCode(saved);

                TempData["Success"] =
                    "Employee Separation updated in ERPNext and HRMS.";

                return RedirectToAction(
                    "EmployeeSeparationDetails",
