        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteEmployeeSeparation/{id:int}")]
        public async Task<ActionResult>
    DeleteEmployeeSeparation(int id)
        {
            try
            {
                EmployeeSeparation existing =
                    _employeeSeparationService.GetById(id);

                if (existing == null)
                    return NotFound();

                // ERP FIRST
                if (!string.IsNullOrWhiteSpace(
                    existing.EmployeeSeparationCode))
                {
                    await _erpNextService.DeleteAsync(
                        "/api/resource/Employee%20Separation/" +
                        Uri.EscapeDataString(
                            existing.EmployeeSeparationCode
                        )
                    );
                }

                // HRMS AFTER ERP SUCCESS
                _employeeSeparationService
                    .MarkDeletedById(id);

                TempData["Success"] =
                    "Employee Separation deleted from ERPNext and HRMS.";

                return RedirectToAction(
                    "EmployeeSeparation"
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Employee Separation deletion failed: " +
                    ex.Message;

                return RedirectToAction(
                    "EmployeeSeparationDetails",
                    new { id }
                );
            }
        }







