        // POST: HR/SyncEmployeeGrievancesFromErpNext
        [HttpPost]
        [Route("HR/SyncEmployeeGrievancesFromErpNext")]
        public async Task<ActionResult> SyncEmployeeGrievancesFromErpNext()
        {
            try
            {
                var existingIds = _employeeGrievanceService.GetExistingErpNextIds();

                // Using "*" fetches all document fields safely without field-permission restriction errors
                var json = await _erpNextService.GetAsync("/api/resource/Employee%20Grievance?fields=[\"*\"]&limit_page_length=1000");
                dynamic parsed = JsonConvert.DeserializeObject(json);
                var items = parsed?.data;

                int syncedCount = 0;
                if (items != null)
                {
                    foreach (var item in items)
                    {
                        string erpId = item.name;
                        if (!existingIds.Contains(erpId))
                        {
                            var g = new EmployeeGrievance
                            {
                                ErpNextId = erpId,
                                Subject = item.subject,
                                GrievanceDate = item.date != null ? Convert.ToDateTime(item.date) : DateTime.Now,
                                RaisedBy = item.raised_by,
                                Status = item.status ?? "Invalid",
                                GrievanceAgainstParty = item.grievance_against_party,
                                GrievanceAgainst = item.grievance_against,
                                AssociatedDocumentType = item.associated_document_type,
                                AssociatedDocument = item.associated_document,
                                GrievanceType = item.grievance_type,
                                Description = item.description,
                                CauseOfGrievance = item.cause_of_grievance,
                                ResolvedBy = item.resolved_by,
                                ResolutionDate = item.resolution_date != null ? Convert.ToDateTime(item.resolution_date) : (DateTime?)null,
                                ResolutionDetails = item.resolution_details,
                                EmployeeResponsible = item.employee_responsible
                            };
                            _employeeGrievanceService.Insert(g);
                            syncedCount++;
                        }
                    }
                }

                TempData["Success"] = $"Successfully synced {syncedCount} Employee Grievances from ERPNext!";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Error syncing from ERPNext: " + ex.Message;
            }

            return RedirectToAction("EmployeeGrievance");
        }       // POST: HR/CreateEmployeeGrievance

