        [HttpPost]
        public ActionResult CreateEmployeeOnboarding(EmployeeOnboarding model,
            string[] ActivityNames, string[] Users, int?[] BeginOnDaysArr, int?[] DurationDaysArr)
        {
            if (string.IsNullOrWhiteSpace(model.JobApplicant))
            {
                ModelState.AddModelError("JobApplicant", "Job Applicant is required.");
                return View(model);
            }
            if (string.IsNullOrWhiteSpace(model.EmployeeName))
            {
                ModelState.AddModelError("EmployeeName", "Employee Name is required.");
                return View(model);
            }

            if (ActivityNames != null)
            {
                for (int i = 0; i < ActivityNames.Length; i++)
                {
                    if (string.IsNullOrWhiteSpace(ActivityNames[i])) continue;

                    model.Activities.Add(new EmployeeOnboardingActivity
                    {
                        ActivityName = ActivityNames[i],
                        User = (Users != null && i < Users.Length) ? Users[i] : null,
                        BeginOnDays = (BeginOnDaysArr != null && i < BeginOnDaysArr.Length) ? BeginOnDaysArr[i] : null,
                        DurationDays = (DurationDaysArr != null && i < DurationDaysArr.Length) ? DurationDaysArr[i] : null
                    });
                }
            }

            int newId = _employeeOnboardingService.Insert(model);
            return RedirectToAction("EmployeeOnboardingDetails", new { id = newId });
        }

        public async Task<ActionResult> EmployeeOnboardingDetails(int id)
        {
            var model = _employeeOnboardingService.GetById(id);
            if (model == null) return NotFound();

            // Pull the individual ERP record on refresh so external submit,
            // completion, and cancellation are immediately reflected in HRMS.
            if (!string.IsNullOrWhiteSpace(model.ErpNextId))
            {
                try
                {
                    await RefreshEmployeeOnboardingFromErpAsync(model.ErpNextId);
                    model = _employeeOnboardingService.GetById(id) ?? model;
                }
                catch (Exception ex)
                {
                    TempData["ErpNextError"] = "Employee Onboarding could not be refreshed from ERPNext: " + ShortErpNextError(ex.Message);
                }
            }

            return View(model);
        }

