        [HttpPost]
        public ActionResult BulkLeavePolicyAssignment(
            string leavePolicyId, string assignmentBasedOn, DateTime effectiveFrom, DateTime effectiveTo,
            bool addUnusedLeaves, string company,
            string[] SelectedEmployees, string[] SelectedEmployeeNames)
        {
            var results = new List<string>();

            if (SelectedEmployees == null || SelectedEmployees.Length == 0)
            {
                TempData["Error"] = "No employees selected.";
                return RedirectToAction("BulkLeavePolicyAssignment");
            }

            string policyName = null;
            if (!string.IsNullOrEmpty(leavePolicyId) && int.TryParse(leavePolicyId, out int policyIdInt))
            {
                var policy = _leavePolicyService.GetById(policyIdInt);
                policyName = policy?.Title;
            }

            for (int i = 0; i < SelectedEmployees.Length; i++)
            {
                var emp = SelectedEmployees[i];
                var empName = (SelectedEmployeeNames != null && i < SelectedEmployeeNames.Length) ? SelectedEmployeeNames[i] : null;

                var model = new LeavePolicyAssignment
                {
                    Employee = emp,
                    EmployeeName = empName,
                    Company = company ?? "AITS",
                    LeavePolicy = policyName ?? string.Empty,
                    AssignmentBasedOn = assignmentBasedOn,
                    EffectiveFrom = effectiveFrom,
                    EffectiveTo = effectiveTo,
                    AddUnusedLeaves = addUnusedLeaves
                };

                _leavePolicyAssignmentService.Insert(model);
                results.Add($"{emp} - {empName} → {policyName}");
            }

            TempData["BulkResults"] = string.Join("|", results);
            TempData["BulkCount"] = results.Count.ToString();
            return RedirectToAction("BulkLeavePolicyAssignmentResult");
        }

        public ActionResult BulkLeavePolicyAssignmentResult()
        {
            var resultsRaw = TempData["BulkResults"] as string;
            ViewBag.Results = string.IsNullOrEmpty(resultsRaw) ? new List<string>() : resultsRaw.Split('|').ToList();
            ViewBag.Count = TempData["BulkCount"];
            return View();
        }

