        [HttpPost]
        public ActionResult AllocateLeave(
            string datesBasedOn, string leavePeriod, DateTime? fromDate, bool carryForward,
            bool allocateBasedOnLeavePolicy, string leavePolicyId,
            string company, string employmentType, string branch, string designation, string department, string employeeGrade,
            string[] SelectedEmployees, string[] SelectedEmployeeNames)
        {
            var results = new List<string>();

            if (SelectedEmployees == null || SelectedEmployees.Length == 0)
            {
                TempData["Error"] = "No employees selected.";
                return RedirectToAction("LeaveControlPanel");
            }

            Erp_Aits.Models.LeavePolicy policy = null;
            if (allocateBasedOnLeavePolicy && !string.IsNullOrEmpty(leavePolicyId) && int.TryParse(leavePolicyId, out int policyIdInt))
            {
                policy = _leavePolicyService.GetById(policyIdInt);
            }

            Erp_Aits.Models.LeavePeriod period = null;
            if (!string.IsNullOrEmpty(leavePeriod) && int.TryParse(leavePeriod, out int periodIdInt))
            {
                period = _leavePeriodService.GetById(periodIdInt);
            }

            DateTime allocFrom = period?.FromDate ?? fromDate ?? DateTime.Now;
            DateTime allocTo = period?.ToDate ?? DateTime.Now.AddYears(1);

            if (policy != null && policy.Details.Any())
            {
                for (int i = 0; i < SelectedEmployees.Length; i++)
                {
                    var emp = SelectedEmployees[i];
                    var empName = (SelectedEmployeeNames != null && i < SelectedEmployeeNames.Length) ? SelectedEmployeeNames[i] : null;

                    foreach (var detail in policy.Details)
                    {
                        var allocation = new LeaveAllocation
                        {
                            Company = company ?? "AITS",
                            Employee = emp,
                            LeaveType = detail.LeaveType,
                            LeavePeriod = period?.Id.ToString(),
                            LeavePolicy = policy.Title,
                            FromDate = allocFrom,
                            ToDate = allocTo,
                            NewLeavesAllocated = detail.AnnualAllocation,
                            AddUnusedLeaves = carryForward
                        };

                        _leaveAllocationService.Insert(allocation);
                        results.Add($"{emp} - {detail.LeaveType} ({detail.AnnualAllocation} days)");
                    }
                }
            }

            TempData["AllocationResults"] = string.Join("|", results);
            TempData["AllocatedCount"] = results.Count.ToString();
            return RedirectToAction("LeaveControlPanelResult");
        }

        public ActionResult LeaveControlPanelResult()
        {
            var resultsRaw = TempData["AllocationResults"] as string;
            ViewBag.Results = string.IsNullOrEmpty(resultsRaw) ? new List<string>() : resultsRaw.Split('|').ToList();
            ViewBag.Count = TempData["AllocatedCount"];
            return View();
        }

