        [HttpPost]
        [Route("HR/UpdateLeaveBlockList/{id:int}")]
        public async Task<ActionResult> UpdateLeaveBlockList(int id, LeaveBlockList model)
        {
            var existing = _leaveBlockListService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                NormalizeLeaveBlockList(model);
                ValidateLeaveBlockList(model);

                model.Id = id;
                model.ErpNextId = string.IsNullOrWhiteSpace(existing.ErpNextId)
                    ? existing.LeaveBlockListName
                    : existing.ErpNextId;

                string erpId = model.ErpNextId;

                if (!string.Equals(existing.LeaveBlockListName, model.LeaveBlockListName, StringComparison.OrdinalIgnoreCase))
                {
                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.rename_doc", new
                    {
                        doctype = "Leave Block List",
                        old_name = erpId,
                        new_name = model.LeaveBlockListName,
                        merge = 0
                    });

                    erpId = model.LeaveBlockListName;
                    model.ErpNextId = erpId;
                }

                await _erpNextService.PutAsync(
                    $"/api/resource/Leave%20Block%20List/{Uri.EscapeDataString(erpId)}",
                    BuildLeaveBlockListPayload(model));

                var detailJson = await _erpNextService.GetAsync($"/api/resource/Leave%20Block%20List/{Uri.EscapeDataString(erpId)}");
                var updated = MapErpLeaveBlockList(JObject.Parse(detailJson)["data"]);
                updated.Id = id;
                _leaveBlockListService.Update(updated);

                TempData["SuccessMessage"] = "Leave Block List saved in ERPNext and HRMS.";
                return RedirectToAction("LeaveBlockListDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErrorMessage"] = "Leave Block List save failed: " + ExtractErpNextErrorMessage(ex.Message);
                model.Id = id;
                model.ErpNextId = existing.ErpNextId;
                await PopulateDropdownsAsync();
                return View("LeaveBlockListDetails", model);
            }
        }

        [HttpPost]
        [Route("HR/DeleteLeaveBlockList/{id:int}")]
        public async Task<ActionResult> DeleteLeaveBlockList(int id)
        {
            var existing = _leaveBlockListService.GetById(id);
            if (existing == null) return RedirectToAction("LeaveBlockList");

            try
            {
                string erpId = string.IsNullOrWhiteSpace(existing.ErpNextId)
                    ? existing.LeaveBlockListName
                    : existing.ErpNextId;

                if (!string.IsNullOrWhiteSpace(erpId))
                {
                    await _erpNextService.DeleteAsync($"/api/resource/Leave%20Block%20List/{Uri.EscapeDataString(erpId)}");
                }

                _leaveBlockListService.MarkDeletedById(id);
                TempData["SuccessMessage"] = "Leave Block List deleted from ERPNext and HRMS.";
                return RedirectToAction("LeaveBlockList");
            }
            catch (Exception ex)
            {
                TempData["ErrorMessage"] = "Leave Block List delete failed: " + ExtractErpNextErrorMessage(ex.Message);
                return RedirectToAction("LeaveBlockListDetails", new { id });
            }
        }

        private async Task<(int imported, int updated)> PullLeaveBlockListsFromErpNext()
        {
            var response = await _erpNextService.GetAsync("/api/resource/Leave%20Block%20List?fields=[\"name\"]&limit_page_length=0");
            var parsed = JObject.Parse(response);
            var rows = parsed["data"] as JArray;
            var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            int imported = 0;
            int updated = 0;

            if (rows != null)
            {
                foreach (var row in rows)
                {
                    string erpId = row["name"]?.ToString();
                    if (string.IsNullOrWhiteSpace(erpId)) continue;

                    erpIds.Add(erpId);
                    bool exists = _leaveBlockListService.ExistsByErpNextId(erpId);

                    var detailResponse = await _erpNextService.GetAsync($"/api/resource/Leave%20Block%20List/{Uri.EscapeDataString(erpId)}");
                    var model = MapErpLeaveBlockList(JObject.Parse(detailResponse)["data"]);
                    if (model == null) continue;

                    _leaveBlockListService.InsertOrUpdate(model);

                    if (exists) updated++;
                    else imported++;
                }
            }

            SoftDeleteMissingErpDocuments("LeaveBlockLists", "ErpNextId", erpIds);
            return (imported, updated);
        }

        private LeaveBlockList MapErpLeaveBlockList(JToken doc)
        {
            if (doc == null) return null;

            var model = new LeaveBlockList
            {
                ErpNextId = doc["name"]?.ToString() ?? "",
                LeaveBlockListName = doc["leave_block_list_name"]?.ToString() ?? doc["name"]?.ToString() ?? "",
                LeaveType = doc["leave_type"]?.ToString(),
                Company = doc["company"]?.ToString() ?? "AITS",
                AppliesToCompany = ToErpBool(doc["applies_to_all_departments"])
            };

            var dates = doc["leave_block_list_dates"] as JArray;
            if (dates != null)
            {
                foreach (var d in dates)
                {
                    if (DateTime.TryParse(d["block_date"]?.ToString(), out var blockDate))
                    {
                        model.BlockDates.Add(new LeaveBlockListDate
                        {
                            BlockDate = blockDate,
                            Reason = d["reason"]?.ToString() ?? ""
                        });
                    }
                }
            }

            var users = doc["leave_block_list_allowed"] as JArray;
            if (users != null)
            {
                foreach (var u in users)
                {
                    var allowUser = u["allow_user"]?.ToString();
                    if (!string.IsNullOrWhiteSpace(allowUser))
                    {
                        model.AllowedUsers.Add(new LeaveBlockListAllowedUser
                        {
                            AllowUser = allowUser
                        });
                    }
                }
            }

            return model;
        }

        private Dictionary<string, object> BuildLeaveBlockListPayload(LeaveBlockList model)
        {
            return new Dictionary<string, object>
            {
                ["leave_block_list_name"] = model.LeaveBlockListName,
                ["leave_type"] = string.IsNullOrWhiteSpace(model.LeaveType) ? null : model.LeaveType,
                ["company"] = model.Company,
                ["applies_to_all_departments"] = model.AppliesToCompany ? 1 : 0,
                ["leave_block_list_dates"] = (model.BlockDates ?? new List<LeaveBlockListDate>())
                    .Where(d => d.BlockDate != default)
                    .Select(d => new Dictionary<string, object>
                    {
                        ["block_date"] = d.BlockDate.ToString("yyyy-MM-dd"),
                        ["reason"] = d.Reason ?? ""
                    })
                    .ToList(),
                ["leave_block_list_allowed"] = (model.AllowedUsers ?? new List<LeaveBlockListAllowedUser>())
                    .Where(u => !string.IsNullOrWhiteSpace(u.AllowUser))
                    .Select(u => new Dictionary<string, object>
                    {
                        ["allow_user"] = u.AllowUser
                    })
                    .ToList()
            };
        }

        private void NormalizeLeaveBlockList(LeaveBlockList model)
        {
            model.BlockDates = (model.BlockDates ?? new List<LeaveBlockListDate>())
                .Where(d => d.BlockDate != default || !string.IsNullOrWhiteSpace(d.Reason))
                .ToList();

            model.AllowedUsers = (model.AllowedUsers ?? new List<LeaveBlockListAllowedUser>())
                .Where(u => !string.IsNullOrWhiteSpace(u.AllowUser))
                .ToList();

            model.Company = string.IsNullOrWhiteSpace(model.Company) ? "AITS" : model.Company.Trim();
        }

        private void ValidateLeaveBlockList(LeaveBlockList model)
        {
            if (string.IsNullOrWhiteSpace(model.LeaveBlockListName))
                throw new Exception("Leave Block List Name is required.");

            if (string.IsNullOrWhiteSpace(model.Company))
                throw new Exception("Company is required.");

            if (model.BlockDates == null || !model.BlockDates.Any(d => d.BlockDate != default))
                throw new Exception("At least one Leave Block List Date is required.");
        }

