        // POST: HR/CreateLeavePolicy (Auto-provisions Leave Types + Syncs Leave Policy and Details)
        [HttpPost]
        public async Task<ActionResult> CreateLeavePolicy(LeavePolicy model)
        {
            if (string.IsNullOrWhiteSpace(model.Title))
            {
                ModelState.AddModelError("Title", "Title is required.");
                return View(model);
            }

            try
            {
                // 1. Save locally first in SQL DB
                int newId = _leavePolicyService.Insert(model);
                model.Id = newId;

                // 2. Auto-create any missing Leave Types in ERPNext from details table
                var detailList = new List<object>();
                if (model.Details != null)
                {
                    foreach (var detail in model.Details)
                    {
                        string typeName = detail.LeaveType?.Trim();
                        if (!string.IsNullOrWhiteSpace(typeName))
                        {
                            try
                            {
                                var typePayload = new { leave_type_name = typeName };
                                await _erpNextService.PostAsync($"/api/resource/{Uri.EscapeDataString("Leave Type")}", typePayload);
                            }
                            catch
                            {
                                // Ignore 409 if Leave Type already exists
                            }

                            detailList.Add(new
                            {
                                leave_type = typeName,
                                annual_allocation = detail.AnnualAllocation
                            });
                        }
                    }
                }

                // 3. Prepare ERPNext Leave Policy payload
                var payload = new Dictionary<string, object>
                {
                    ["title"] = model.Title,
                    ["leave_policy_details"] = detailList
                };

                string erpNextId = model.Title;

                // 4. Update existing or Post new Leave Policy
                try
                {
                    string checkUrl = $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(model.Title)}";
                    await _erpNextService.GetAsync(checkUrl);

                    await _erpNextService.PutAsync(checkUrl, payload);
                    TempData["Success"] = $"Leave Policy '{model.Title}' updated and synced to ERPNext.";
                }
                catch
                {
                    var resultJson = await _erpNextService.PostAsync(
                        $"/api/resource/{Uri.EscapeDataString("Leave Policy")}", payload);

                    dynamic parsed = JsonConvert.DeserializeObject(resultJson);
                    erpNextId = parsed.data.name;
                    TempData["Success"] = $"Leave Policy '{model.Title}' created and synced to ERPNext ({erpNextId}).";
                }

                // 5. Save synced ERPNext ID locally
                _leavePolicyService.UpdateErpNextId(model.Id, erpNextId);
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Saved locally, but ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("LeavePolicyDetails", new { id = model.Id });
        }

