        [HttpPost]
        [Route("HR/UpdateLeavePolicy/{id:int}")]
        public async Task<ActionResult> UpdateLeavePolicy(int id, LeavePolicy model)
        {
            var existing = _leavePolicyService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                if (existing.DocStatus != 0)
                {
                    throw new Exception("You can not edit submitted or cancelled document.");
                }

                ValidateLeavePolicy(model);

                model.Id = id;
                model.ErpNextId = string.IsNullOrWhiteSpace(existing.ErpNextId)
                    ? existing.Title
                    : existing.ErpNextId;

                string erpId = model.ErpNextId;
                var payload = BuildLeavePolicyPayload(model);

                if (!string.Equals(existing.Title, model.Title, StringComparison.OrdinalIgnoreCase))
                {
                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.rename_doc", new
                    {
                        doctype = "Leave Policy",
                        old_name = erpId,
                        new_name = model.Title,
                        merge = 0
                    });

                    erpId = model.Title;
                    model.ErpNextId = erpId;
                }

                await _erpNextService.PutAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(erpId)}",
                    payload);

                string detailJson = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(erpId)}");

                var detailObject = JObject.Parse(detailJson);
                var updated = MapErpLeavePolicy(detailObject["data"]);
                updated.Id = id;

                _leavePolicyService.Update(updated);

                TempData["Success"] = "Leave Policy updated in ERPNext and HRMS.";
                return RedirectToAction("LeavePolicyDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Leave Policy update failed: "
                    + ExtractErpNextErrorMessage(ex.Message);

                model.Id = id;
                model.ErpNextId = existing.ErpNextId;
                ViewBag.LeaveTypes = _leaveTypeService.GetAll() ?? new List<LeaveType>();
                return View("LeavePolicyDetails", model);
            }
        }

