                {
                    await _erpNextService.DeleteAsync(
                        $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(erpId)}");
                }

                _leavePolicyService.MarkDeletedById(id);
                TempData["Success"] = "Leave Policy deleted from ERPNext and HRMS.";
