                TempData["ErpNextError"] =
                    "Leave Policy delete failed: "
                    + ExtractErpNextErrorMessage(ex.Message);

                return RedirectToAction("LeavePolicyDetails", new { id });
            }
        }

        private async Task<(int imported, int updated)> PullLeavePoliciesFromErpNext()
        {
            string listJson = await _erpNextService.GetAsync(
                $"/api/resource/{Uri.EscapeDataString("Leave Policy")}?fields=[\"name\"]&limit_page_length=0");

            dynamic listParsed = JsonConvert.DeserializeObject(listJson);
            int importedCount = 0;
            int updatedCount = 0;
            var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (listParsed?.data != null)
            {
                foreach (var d in listParsed.data)
                {
                    string erpNextId = d.name?.ToString();
                    if (string.IsNullOrWhiteSpace(erpNextId)) continue;

                    erpIds.Add(erpNextId);

                    string singleDocJson = await _erpNextService.GetAsync(
                        $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(erpNextId)}");

                    var singleDocObject = JObject.Parse(singleDocJson);
                    var model = MapErpLeavePolicy(singleDocObject["data"]);
                    if (model == null) continue;

                    if (_leavePolicyService.ExistsByErpNextId(erpNextId))
                    {
                        _leavePolicyService.UpdateFromErpNext(model);
                        updatedCount++;
                    }
                    else
                    {
                        _leavePolicyService.Insert(model);
                        importedCount++;
                    }
                }
            }

            SoftDeleteMissingErpDocuments("LeavePolicies", "ErpNextId", erpIds);

            return (importedCount, updatedCount);
        }

        private LeavePolicy MapErpLeavePolicy(JToken doc)
        {
            if (doc == null) return null;

            var model = new LeavePolicy
            {
                Title = doc["title"]?.ToString() ?? doc["name"]?.ToString() ?? "",
                ErpNextId = doc["name"]?.ToString() ?? "",
                DocStatus = doc["docstatus"] != null ? doc["docstatus"].ToObject<int>() : 0
            };

            model.Status = model.DocStatus == 1
                ? "Submitted"
                : model.DocStatus == 2
                    ? "Cancelled"
                    : "Draft";

            var details = doc["leave_policy_details"] as JArray;
            if (details != null)
            {
                foreach (var detail in details)
                {
                    model.Details.Add(new LeavePolicyDetail
                    {
                        LeaveType = detail["leave_type"]?.ToString() ?? "",
                        AnnualAllocation = detail["annual_allocation"] != null
                            ? detail["annual_allocation"].ToObject<decimal>()
                            : 0
                    });
                }
            }

            return model;
        }

        private Dictionary<string, object> BuildLeavePolicyPayload(LeavePolicy model)
        {
            var rows = new List<Dictionary<string, object>>();

            foreach (var detail in model.Details ?? new List<LeavePolicyDetail>())
            {
                if (string.IsNullOrWhiteSpace(detail.LeaveType)) continue;

                rows.Add(new Dictionary<string, object>
                {
                    ["leave_type"] = detail.LeaveType.Trim(),
                    ["annual_allocation"] = detail.AnnualAllocation
                });
            }

            return new Dictionary<string, object>
            {
                ["title"] = model.Title?.Trim(),
                ["leave_policy_details"] = rows
            };
        }

        private void ValidateLeavePolicy(LeavePolicy model)
        {
            if (string.IsNullOrWhiteSpace(model.Title))
            {
                throw new Exception("Title is required.");
            }

            var rows = model.Details?
                .Where(d => !string.IsNullOrWhiteSpace(d.LeaveType))
                .ToList() ?? new List<LeavePolicyDetail>();

            if (!rows.Any())
            {
                throw new Exception("At least one Leave Policy Detail row is required.");
            }
        }

        [HttpPost]
        [Route("HR/SubmitLeavePolicy/{id:int}")]
        public async Task<ActionResult> SubmitLeavePolicy(int id, LeavePolicy model)
        {
            var existing = _leavePolicyService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                if (existing.DocStatus != 0)
                {
                    throw new Exception("Only Draft Leave Policy can be submitted.");
                }

                ValidateLeavePolicy(model);

                model.Id = id;
                model.ErpNextId = string.IsNullOrWhiteSpace(existing.ErpNextId)
                    ? existing.Title
                    : existing.ErpNextId;

                string erpId = model.ErpNextId;

                if (!string.Equals(existing.Title, model.Title, StringComparison.OrdinalIgnoreCase))
                {
                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.rename_doc", new
                    {
                        doctype = "Leave Policy",
                        old_name = erpId,
                        new_name = model.Title,
                        merge = 0
                    });

                    erpId = model.Title;
                    model.ErpNextId = erpId;
                }

                await _erpNextService.PutAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(erpId)}",
                    BuildLeavePolicyPayload(model));

                string draftJson = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(erpId)}");

                var draftDoc = JObject.Parse(draftJson)["data"];
                if (draftDoc == null)
                {
                    throw new Exception("Submit failed: ERPNext Leave Policy document not found.");
                }

                await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new
                {
                    doc = draftDoc
                });

                string detailJson = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(erpId)}");

                var updated = MapErpLeavePolicy(JObject.Parse(detailJson)["data"]);
                updated.Id = id;
                _leavePolicyService.Update(updated);

                TempData["Success"] = "Leave Policy submitted in ERPNext and HRMS.";
                return RedirectToAction("LeavePolicyDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Leave Policy submit failed: "
                    + ExtractErpNextErrorMessage(ex.Message);

                model.Id = id;
                model.ErpNextId = existing.ErpNextId;
                model.DocStatus = existing.DocStatus;
                model.Status = existing.Status;
                ViewBag.LeaveTypes = _leaveTypeService.GetAll() ?? new List<LeaveType>();
                return View("LeavePolicyDetails", model);
            }
        }

        [HttpPost]
        [Route("HR/CancelLeavePolicy/{id:int}")]
        public async Task<ActionResult> CancelLeavePolicy(int id)
        {
            var existing = _leavePolicyService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                if (existing.DocStatus != 1)
                {
                    throw new Exception("Only Submitted Leave Policy can be cancelled.");
                }

                string erpId = string.IsNullOrWhiteSpace(existing.ErpNextId)
                    ? existing.Title
                    : existing.ErpNextId;

                string submittedJson = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(erpId)}");

                var submittedDoc = JObject.Parse(submittedJson)["data"];
                if (submittedDoc == null)
                {
                    throw new Exception("Cancel failed: ERPNext Leave Policy document not found.");
                }

                await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                {
                    doc = submittedDoc
                });

                string detailJson = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Policy")}/{Uri.EscapeDataString(erpId)}");

                var updated = MapErpLeavePolicy(JObject.Parse(detailJson)["data"]);
                updated.Id = id;
                _leavePolicyService.Update(updated);

                TempData["Success"] = "Leave Policy cancelled in ERPNext and HRMS.";
                return RedirectToAction("LeavePolicyDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Leave Policy cancel failed: "
                    + ExtractErpNextErrorMessage(ex.Message);

                return RedirectToAction("LeavePolicyDetails", new { id });
            }
        }
