        // GET: HR/CreateLeavePeriod
        [HttpGet]
        [Route("HR/CreateLeavePeriod")]
        public async Task<ActionResult> CreateLeavePeriod()
        {
            try
            {
                // ============================================================
                // COMPANY DROPDOWN
                // ============================================================

                string companyJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Company" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=5000"
                    );

                dynamic companyParsed =
                    JsonConvert.DeserializeObject(
                        companyJson
                    );

                ViewBag.Companies =
                    companyParsed?.data;


                // ============================================================
                // HOLIDAY LIST DROPDOWN
                //
                // IMPORTANT:
                // Your ERPNext rejects "company" in Holiday List list query.
                // Therefore fetch only the document name.
                // ============================================================

                string holidayJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Holiday%20List" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=5000"
                    );

                dynamic holidayParsed =
                    JsonConvert.DeserializeObject(
                        holidayJson
                    );

                ViewBag.HolidayLists =
                    holidayParsed?.data;
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Unable to load Leave Period dropdowns: "
                    + CleanLeavePeriodErpError(
                        ex.Message
                    );

                ViewBag.Companies =
                    new List<object>();

                ViewBag.HolidayLists =
                    new List<object>();
            }


            return View(
                "~/Views/HR/CreateLeavePeriod.cshtml",
                new LeavePeriod
                {
                    FromDate = DateTime.Today,
                    ToDate = DateTime.Today.AddYears(1),
                    IsActive = false
                }
            );
        }
        [HttpPost]
        [Route("HR/CreateLeavePeriod")]
        public async Task<ActionResult>
    CreateLeavePeriod(
        LeavePeriod model)
        {
            try
            {
                // ============================================================
                // REQUIRED VALIDATION
                // ============================================================

                if (model.FromDate == default(DateTime))
                {
                    throw new Exception(
                        "From Date is required."
                    );
                }


                if (model.ToDate == default(DateTime))
                {
                    throw new Exception(
                        "To Date is required."
                    );
                }


                if (string.IsNullOrWhiteSpace(
                    model.Company))
                {
                    throw new Exception(
                        "Company is required."
                    );
                }


                // ============================================================
                // EXACT ERP DATE RULE
                //
                // ERP:
                // if from_date >= to_date -> reject
                // ============================================================

                if (
                    model.FromDate.Date >=
                    model.ToDate.Date
                )
                {
                    throw new Exception(
                        "To date can not be equal or less than from date"
                    );
                }


                // ============================================================
                // VERIFY COMPANY EXISTS
                // ============================================================

                await _erpNextService.GetAsync(
                    "/api/resource/Company/" +
                    Uri.EscapeDataString(
                        model.Company
                    )
                );


                // ============================================================
                // VERIFY HOLIDAY LIST EXISTS
                // ============================================================

                if (!string.IsNullOrWhiteSpace(
                    model.HolidayListForOptionalLeave))
                {
                    await _erpNextService.GetAsync(
                        "/api/resource/Holiday%20List/" +
                        Uri.EscapeDataString(
                            model.HolidayListForOptionalLeave
                        )
                    );
                }


                // ============================================================
                // BUILD ERP PAYLOAD
                //
                // Exact ERP fields:
                //
                // from_date
                // to_date
                // company
                // optional_holiday_list
                // is_active
                // ============================================================

                var payload =
                    BuildLeavePeriodPayload(
                        model
                    );


                // ============================================================
                // ERP FIRST
                //
                // ERP performs authoritative overlap validation.
                // ============================================================

                string createResponse =
                    await _erpNextService.PostAsync(
                        "/api/resource/Leave%20Period",
                        payload
                    );


                JObject createObject =
                    JObject.Parse(
                        createResponse
                    );


                string erpId =
                    createObject["data"]?["name"]
                        ?.ToString();


                if (string.IsNullOrWhiteSpace(
                    erpId))
                {
                    throw new Exception(
                        "ERPNext did not return Leave Period ID."
                    );
                }


                // ============================================================
                // READ FULL ERP DOCUMENT
                // ============================================================

                string detailJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Leave%20Period/" +
                        Uri.EscapeDataString(
                            erpId
                        )
                    );


                JObject detailObject =
                    JObject.Parse(
                        detailJson
                    );


                LeavePeriod localModel =
                    MapErpLeavePeriod(
                        detailObject["data"]
                    );


                if (localModel == null)
                {
                    throw new Exception(
                        "Leave Period was created in ERPNext but could not be reloaded."
                    );
                }


                // ============================================================
                // SAVE LOCAL AFTER ERP SUCCESS
                // ============================================================

                int localId =
                    _leavePeriodService
                        .InsertOrUpdate(
                            localModel
                        );


                TempData["Success"] =
                    "Leave Period created successfully. ERPNext Ref: "
                    + erpId;


                return RedirectToAction(
                    "LeavePeriodDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanLeavePeriodErpError(
                        ex.Message
                    );


                return RedirectToAction(
                    "CreateLeavePeriod"
                );
            }
        }

        private LeavePeriod MapErpLeavePeriod(
    JToken doc)
        {
            if (doc == null)
                return null;


            var model =
                new LeavePeriod
                {
                    ErpNextId =
                        doc["name"]
                            ?.ToString()
                        ?? "",

                    Company =
                        doc["company"]
                            ?.ToString()
                        ?? "",

                    HolidayListForOptionalLeave =
                        doc["optional_holiday_list"]
                            ?.ToString()
                        ?? "",

                    IsActive =
                        (
                            doc["is_active"]
                                ?.ToObject<int>()
                            ?? 0
                        ) == 1
                };


            if (
                DateTime.TryParse(
                    doc["from_date"]
                        ?.ToString(),
                    out DateTime fromDate
                )
            )
            {
                model.FromDate =
                    fromDate;
            }


            if (
                DateTime.TryParse(
                    doc["to_date"]
                        ?.ToString(),
                    out DateTime toDate
                )
            )
            {
                model.ToDate =
                    toDate;
            }


            return model;
        }








