            }


            return RedirectToAction(
                "LeavePeriod"
            );
        }


        private string CleanLeavePeriodErpError(
      string rawError)
        {
            if (string.IsNullOrWhiteSpace(rawError))
            {
                return "ERPNext operation failed.";
            }

            try
            {
                int jsonStart =
                    rawError.IndexOf('{');

                if (jsonStart >= 0)
                {
                    string jsonPart =
                        rawError.Substring(
                            jsonStart
                        );

                    JObject json =
                        JObject.Parse(
                            jsonPart
                        );


                    // ========================================================
                    // FIRST: try ERPNext _server_messages
                    // ========================================================

                    string serverMessagesRaw =
                        json["_server_messages"]
                            ?.ToString();

                    if (!string.IsNullOrWhiteSpace(
                        serverMessagesRaw))
                    {
                        JArray serverMessages =
                            JArray.Parse(
                                serverMessagesRaw
                            );

                        if (serverMessages.Count > 0)
                        {
                            string firstMessageRaw =
                                serverMessages[0]
                                    ?.ToString();

                            if (!string.IsNullOrWhiteSpace(
                                firstMessageRaw))
                            {
                                JObject firstMessage =
                                    JObject.Parse(
                                        firstMessageRaw
                                    );

                                string message =
                                    firstMessage["message"]
                                        ?.ToString();

                                if (!string.IsNullOrWhiteSpace(
                                    message))
                                {
                                    return CleanShortErpMessage(
                                        message
                                    );
                                }
                            }
                        }
                    }


                    // ========================================================
                    // SECOND: exception field
                    // ========================================================

                    string exception =
                        json["exception"]
                            ?.ToString();

                    if (!string.IsNullOrWhiteSpace(
                        exception))
                    {
                        int colonIndex =
                            exception.IndexOf(':');

                        if (colonIndex >= 0 &&
                            colonIndex <
                            exception.Length - 1)
                        {
                            exception =
                                exception.Substring(
                                    colonIndex + 1
                                );
                        }

                        return CleanShortErpMessage(
                            exception
                        );
                    }
                }
            }
            catch
            {
                // fall through
            }


            // ============================================================
            // FALLBACK:
            // Never return huge traceback / JSON.
            // ============================================================

            string fallback =
                rawError;


            int braceIndex =
                fallback.IndexOf('{');

            if (braceIndex >= 0)
            {
                fallback =
                    fallback.Substring(
                        0,
                        braceIndex
                    );
            }


            fallback =
                fallback.Replace(
                    "ERPNext returned 417:",
                    ""
                )
                .Replace(
                    "ERPNext returned 400:",
                    ""
                )
                .Replace(
                    "ERPNext returned 403:",
                    ""
                )
                .Replace(
                    "ERPNext returned 404:",
                    ""
                )
                .Replace(
                    "ERPNext returned 500:",
                    ""
                )
                .Trim();


            if (string.IsNullOrWhiteSpace(
                fallback))
            {
                fallback =
                    "ERPNext validation failed.";
            }


            return CleanShortErpMessage(
                fallback
            );
        }



        private string CleanShortErpMessage(
    string message)
        {
            if (string.IsNullOrWhiteSpace(
                message))
            {
                return "ERPNext validation failed.";
            }


            // Remove HTML
            message =
                System.Text.RegularExpressions.Regex.Replace(
                    message,
                    "<[^>]*>",
                    " "
                );


            // HTML decode
            message =
                System.Net.WebUtility.HtmlDecode(
                    message
                );


            // Remove line breaks/tabs/multiple spaces
            message =
                System.Text.RegularExpressions.Regex.Replace(
                    message,
                    @"\s+",
                    " "
                )
                .Trim();


            // Never display huge traceback
            if (message.Length > 250)
            {
                message =
                    message.Substring(
                        0,
                        250
                    )
                    .Trim()
                    + "...";
            }


            return message;
        }


        private void ValidateLeavePeriodModel(
            LeavePeriod model)
        {
            if (model.FromDate == default(DateTime))
            {
                throw new Exception(
                    "From Date is required."
                );
            }

            if (model.ToDate == default(DateTime))
            {
                throw new Exception(
                    "To Date is required."
                );
            }

            if (string.IsNullOrWhiteSpace(
                model.Company))
            {
                throw new Exception(
                    "Company is required."
                );
            }

            if (model.FromDate.Date >= model.ToDate.Date)
            {
                throw new Exception(
                    "To date can not be equal or less than from date"
                );
            }
        }


        private Dictionary<string, object> BuildLeavePeriodPayload(
            LeavePeriod model)
        {
            return new Dictionary<string, object>
            {
                ["from_date"] =
                    model.FromDate.ToString(
                        "yyyy-MM-dd"
                    ),

                ["to_date"] =
                    model.ToDate.ToString(
                        "yyyy-MM-dd"
                    ),

                ["company"] =
                    model.Company,

                ["optional_holiday_list"] =
                    string.IsNullOrWhiteSpace(
                        model.HolidayListForOptionalLeave)
                        ? null
                        : model.HolidayListForOptionalLeave,

                ["is_active"] =
                    model.IsActive
                        ? 1
                        : 0
            };
        }


