        private async Task<(int inserted, int updated, int failed)> PullLeavePeriodsFromErpNext()
        {
            string listJson =
                await _erpNextService.GetAsync(
                    "/api/resource/Leave%20Period" +
                    "?fields=[\"name\"]" +
                    "&limit_page_length=5000"
                );


            JObject listObject =
                JObject.Parse(
                    listJson
                );


            JArray rows =
                listObject["data"]
                as JArray;


            int inserted = 0;
            int updated = 0;
            int failed = 0;
            var erpIds =
                new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase
                );


            if (rows != null)
            {
                foreach (JToken row in rows)
                {
                    try
                    {
                        string erpId =
                            row["name"]
                                ?.ToString();


                        if (string.IsNullOrWhiteSpace(
                            erpId))
                        {
                            continue;
                        }

                        erpIds.Add(
                            erpId
                        );


                        bool exists =
                            _leavePeriodService
                                .GetByErpNextId(
                                    erpId
                                ) != null;


                        string detailJson =
                            await _erpNextService.GetAsync(
                                "/api/resource/Leave%20Period/" +
                                Uri.EscapeDataString(
                                    erpId
                                )
                            );


                        JObject detailObject =
                            JObject.Parse(
                                detailJson
                            );


                        LeavePeriod model =
                            MapErpLeavePeriod(
                                detailObject["data"]
                            );


                        if (model == null)
                        {
                            failed++;
                            continue;
                        }


                        _leavePeriodService
                            .InsertOrUpdate(
                                model
                            );


                        if (exists)
                        {
                            updated++;
                        }
                        else
                        {
                            inserted++;
                        }
                    }
                    catch (Exception recordEx)
                    {
                        failed++;


                        System.Diagnostics.Debug.WriteLine(
                            "Leave Period sync error: "
                            + recordEx.Message
                        );
                    }
                }
            }

            SoftDeleteMissingErpDocuments(
                "LeavePeriods",
                "ErpNextId",
                erpIds
            );

            return (
                inserted,
                updated,
                failed
            );
        }





