        [HttpPost]
        [Route("HR/UpdateLeavePeriod/{id:int}")]
        public async Task<ActionResult> UpdateLeavePeriod(
            int id,
            LeavePeriod model)
        {
            var existing =
                _leavePeriodService.GetById(
                    id
                );

            if (existing == null)
            {
                return NotFound();
            }

            try
            {
                ValidateLeavePeriodModel(
                    model
                );

                model.Id =
                    id;

                model.ErpNextId =
                    string.IsNullOrWhiteSpace(
                        existing.ErpNextId)
                        ? null
                        : existing.ErpNextId;

                string erpId =
                    model.ErpNextId;

                if (string.IsNullOrWhiteSpace(
                    erpId))
                {
                    throw new Exception(
                        "ERPNext Leave Period ID is missing."
                    );
                }

                await _erpNextService.PutAsync(
                    "/api/resource/Leave%20Period/" +
                    Uri.EscapeDataString(
                        erpId
                    ),
                    BuildLeavePeriodPayload(
                        model
                    )
                );

                string detailJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Leave%20Period/" +
                        Uri.EscapeDataString(
                            erpId
                        )
                    );

                JObject detailObject =
                    JObject.Parse(
                        detailJson
                    );

                LeavePeriod updated =
                    MapErpLeavePeriod(
                        detailObject["data"]
                    );

                if (updated == null)
                {
                    throw new Exception(
                        "Leave Period was saved in ERPNext but could not be reloaded."
                    );
                }

                updated.Id =
                    id;

                _leavePeriodService.Update(
                    updated
                );

                TempData["Success"] =
                    "Leave Period updated in ERPNext and HRMS.";

                return RedirectToAction(
                    "LeavePeriodDetails",
                    new
                    {
                        id
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Leave Period update failed: "
                    + CleanLeavePeriodErpError(
                        ex.Message
                    );

                model.Id =
                    id;

                model.ErpNextId =
                    existing.ErpNextId;

                await LoadLeavePeriodDropdownsAsync();

                return View(
                    "LeavePeriodDetails",
                    model
                );
            }
        }


        [HttpPost]
        [Route("HR/DeleteLeavePeriod/{id:int}")]
        public async Task<ActionResult> DeleteLeavePeriod(
            int id)
        {
            var existing =
                _leavePeriodService.GetById(
                    id
                );

            if (existing == null)
            {
                return RedirectToAction(
                    "LeavePeriod"
                );
            }

            try
            {
                string erpId =
                    existing.ErpNextId;

                if (!string.IsNullOrWhiteSpace(
                    erpId))
                {
                    await _erpNextService.DeleteAsync(
                        "/api/resource/Leave%20Period/" +
                        Uri.EscapeDataString(
                            erpId
                        )
                    );
                }

                _leavePeriodService.MarkDeletedById(
                    id
                );

                TempData["Success"] =
                    "Leave Period deleted from ERPNext and HRMS.";

                return RedirectToAction(
                    "LeavePeriod"
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Leave Period delete failed: "
                    + CleanLeavePeriodErpError(
                        ex.Message
                    );

                return RedirectToAction(
                    "LeavePeriodDetails",
                    new
                    {
                        id
                    }
                );
            }
        }

