        [HttpPost]
        public async Task<ActionResult> CreateLeaveType(LeaveType model)
        {
            if (string.IsNullOrWhiteSpace(model.LeaveTypeName))
            {
                ModelState.AddModelError("LeaveTypeName", "Leave Type Name is required.");
                await LoadLeaveTypeDropdownsAsync();
                return View(model);
            }

            if (model.IsPartiallyPaidLeave && (model.FractionOfDailySalaryPerLeave == null || model.FractionOfDailySalaryPerLeave < 0 || model.FractionOfDailySalaryPerLeave > 1))
            {
                ModelState.AddModelError("FractionOfDailySalaryPerLeave", "The fraction of Daily Salary per Leave should be between 0 and 1");
                await LoadLeaveTypeDropdownsAsync();
                return View(model);
            }

            try
            {
                // 1. Save locally first in SQL DB
                int newId = _leaveTypeService.Insert(model);
                model.Id = newId;

                // 2. Prepare payload exactly as filled on your UI
                var payload = BuildLeaveTypePayload(model);

                string erpNextId = model.LeaveTypeName;

                // 3. Update existing record if present, otherwise create new
                try
                {
                    string checkUrl = $"/api/resource/{Uri.EscapeDataString("Leave Type")}/{Uri.EscapeDataString(model.LeaveTypeName)}";
                    await _erpNextService.GetAsync(checkUrl);

                    await _erpNextService.PutAsync(checkUrl, payload);
                    TempData["Success"] = $"Leave Type '{model.LeaveTypeName}' updated and synced to ERPNext.";
                }
                catch
                {
                    var resultJson = await _erpNextService.PostAsync(
                        $"/api/resource/{Uri.EscapeDataString("Leave Type")}", payload);

                    dynamic parsed = JsonConvert.DeserializeObject(resultJson);
                    erpNextId = parsed.data.name;
                    TempData["Success"] = $"Leave Type '{model.LeaveTypeName}' created and synced to ERPNext ({erpNextId}).";
                }

                // 4. Store ERPNext ID in local DB
                _leaveTypeService.UpdateErpNextId(model.Id, erpNextId);
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Saved locally, but ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("LeaveTypeDetails", new { id = model.Id });
        }

