        [HttpPost]
        [Route("HR/UpdateLeaveType/{id:int}")]
        public async Task<ActionResult> UpdateLeaveType(int id, LeaveType model)
        {
            var existing = _leaveTypeService.GetById(id);
            if (existing == null) return NotFound();

            if (string.IsNullOrWhiteSpace(model.LeaveTypeName))
            {
                ModelState.AddModelError("LeaveTypeName", "Leave Type Name is required.");
                await LoadLeaveTypeDropdownsAsync();
                return View("LeaveTypeDetails", model);
            }

            if (model.IsPartiallyPaidLeave && (model.FractionOfDailySalaryPerLeave == null || model.FractionOfDailySalaryPerLeave < 0 || model.FractionOfDailySalaryPerLeave > 1))
            {
                ModelState.AddModelError("FractionOfDailySalaryPerLeave", "The fraction of Daily Salary per Leave should be between 0 and 1");
                await LoadLeaveTypeDropdownsAsync();
                return View("LeaveTypeDetails", model);
            }

            try
            {
                model.Id = id;
                model.ErpNextId = string.IsNullOrWhiteSpace(existing.ErpNextId) ? existing.LeaveTypeName : existing.ErpNextId;
                var erpId = model.ErpNextId;
                var payload = BuildLeaveTypePayload(model);

                if (!string.Equals(existing.LeaveTypeName, model.LeaveTypeName, StringComparison.OrdinalIgnoreCase))
                {
                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.rename_doc", new
                    {
                        doctype = "Leave Type",
                        old_name = erpId,
                        new_name = model.LeaveTypeName,
                        merge = 0
                    });
                    erpId = model.LeaveTypeName;
                    model.ErpNextId = erpId;
                }

                await _erpNextService.PutAsync($"/api/resource/{Uri.EscapeDataString("Leave Type")}/{Uri.EscapeDataString(erpId)}", payload);
                model.ErpNextId = erpId;
                _leaveTypeService.Update(model);
                TempData["Success"] = $"Leave Type '{model.LeaveTypeName}' saved in ERPNext and HRMS.";
                return RedirectToAction("LeaveTypeDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Leave Type save failed: " + ExtractErpNextErrorMessage(ex.Message);
                await LoadLeaveTypeDropdownsAsync();
                return View("LeaveTypeDetails", model);
            }
        }

        [HttpPost]
        [Route("HR/DeleteLeaveType/{id:int}")]
        public async Task<ActionResult> DeleteLeaveType(int id)
        {
            var existing = _leaveTypeService.GetById(id);
            if (existing == null) return RedirectToAction("LeaveType");

            try
            {
                string erpId = !string.IsNullOrWhiteSpace(existing.ErpNextId) ? existing.ErpNextId : existing.LeaveTypeName;
                if (!string.IsNullOrWhiteSpace(erpId))
                {
                    await _erpNextService.DeleteAsync($"/api/resource/{Uri.EscapeDataString("Leave Type")}/{Uri.EscapeDataString(erpId)}");
                }

                _leaveTypeService.MarkDeletedById(id);
                TempData["Success"] = "Leave Type deleted from ERPNext and HRMS.";
                return RedirectToAction("LeaveType");
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Leave Type delete failed: " + ExtractErpNextErrorMessage(ex.Message);
                return RedirectToAction("LeaveTypeDetails", new { id });
            }
        }

        private async Task<(int imported, int updated)> PullLeaveTypesFromErpNext()
        {
            string listJson = await _erpNextService.GetAsync(
                $"/api/resource/{Uri.EscapeDataString("Leave Type")}?fields=[\"*\"]&limit_page_length=0");

            dynamic listParsed = JsonConvert.DeserializeObject(listJson);
            var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            int importedCount = 0;
            int updatedCount = 0;

            if (listParsed?.data != null)
            {
                foreach (var d in listParsed.data)
                {
                    string erpNextId = d.name?.ToString();
                    if (string.IsNullOrWhiteSpace(erpNextId)) continue;
                    erpIds.Add(erpNextId);

                    string typeName = d.leave_type_name != null ? d.leave_type_name.ToString() : erpNextId;
                    var model = MapLeaveTypeFromErp(d, erpNextId, typeName);

                    if (_leaveTypeService.ExistsByErpNextId(erpNextId))
                    {
                        _leaveTypeService.UpdateFromErpNext(model);
                        updatedCount++;
                    }
                    else
                    {
                        _leaveTypeService.InsertFromErpNext(model);
                        importedCount++;
                    }
                }
            }

            SoftDeleteMissingErpDocuments("LeaveTypes", "ErpNextId", erpIds);
            return (importedCount, updatedCount);
        }

        private LeaveType MapLeaveTypeFromErp(dynamic d, string erpNextId, string typeName)
        {
            return new LeaveType
            {
                LeaveTypeName = typeName,
                MaxLeavesAllowed = ToNullableDecimal(d.max_leaves_allowed),
                ApplicableAfterWorkingDays = ToNullableInt(d.applicable_after),
                MaxContinuousDaysAllowed = ToNullableInt(d.max_continuous_days_allowed),
                IsCarryForward = ToErpBool(d.is_carry_forward),
                IsLWP = ToErpBool(d.is_lwp),
                IsPartiallyPaidLeave = ToErpBool(d.is_ppl),
                IsOptionalLeave = ToErpBool(d.is_optional_leave),
                AllowNegativeBalance = ToErpBool(d.allow_negative),
                AllowOverAllocation = ToErpBool(d.allow_over_allocation),
                IncludeHolidaysWithinLeaves = ToErpBool(d.include_holiday),
                IsCompensatory = ToErpBool(d.is_compensatory),
                AllowEncashment = ToErpBool(d.allow_encashment),
                MaxEncashableLeaves = ToNullableDecimal(d.max_encashable_leaves),
                NonEncashableLeaves = ToNullableDecimal(d.non_encashable_leaves),
                EarningComponent = d.earning_component?.ToString(),
                IsEarnedLeave = ToErpBool(d.is_earned_leave),
                EarnedLeaveFrequency = d.earned_leave_frequency?.ToString(),
                AllocateOnDay = d.allocate_on_day?.ToString(),
                Rounding = ToNullableDecimal(d.rounding),
                MaxCarryForwardedLeaves = ToNullableDecimal(d.maximum_carry_forwarded_leaves),
                ExpireCarryForwardedLeaves = ToNullableInt(d.expire_carry_forwarded_leaves_after_days),
                FractionOfDailySalaryPerLeave = ToNullableDecimal(d.fraction_of_daily_salary_per_leave),
                ErpNextId = erpNextId
            };
        }

        private Dictionary<string, object> BuildLeaveTypePayload(LeaveType model)
        {
            var payload = new Dictionary<string, object>
            {
                ["leave_type_name"] = model.LeaveTypeName,
                ["max_leaves_allowed"] = model.MaxLeavesAllowed ?? 0,
                ["applicable_after"] = model.ApplicableAfterWorkingDays ?? 0,
                ["max_continuous_days_allowed"] = model.MaxContinuousDaysAllowed ?? 0,
                ["is_carry_forward"] = model.IsCarryForward ? 1 : 0,
                ["is_lwp"] = model.IsLWP ? 1 : 0,
                ["is_ppl"] = model.IsPartiallyPaidLeave ? 1 : 0,
                ["fraction_of_daily_salary_per_leave"] = model.IsPartiallyPaidLeave ? model.FractionOfDailySalaryPerLeave ?? 0 : 0,
                ["is_optional_leave"] = model.IsOptionalLeave ? 1 : 0,
                ["allow_negative"] = model.AllowNegativeBalance ? 1 : 0,
                ["allow_over_allocation"] = model.AllowOverAllocation ? 1 : 0,
                ["include_holiday"] = model.IncludeHolidaysWithinLeaves ? 1 : 0,
                ["is_compensatory"] = model.IsCompensatory ? 1 : 0,
                ["allow_encashment"] = model.AllowEncashment ? 1 : 0,
                ["is_earned_leave"] = model.IsEarnedLeave ? 1 : 0
            };

            if (model.AllowEncashment)
            {
                payload["max_encashable_leaves"] = model.MaxEncashableLeaves ?? 0;
                payload["non_encashable_leaves"] = model.NonEncashableLeaves ?? 0;
                payload["earning_component"] = model.EarningComponent;
            }

            if (model.IsEarnedLeave)
            {
                payload["earned_leave_frequency"] = model.EarnedLeaveFrequency;
                payload["allocate_on_day"] = model.AllocateOnDay;
                payload["rounding"] = model.Rounding ?? 0;
            }

            if (model.IsCarryForward)
            {
                payload["maximum_carry_forwarded_leaves"] = model.MaxCarryForwardedLeaves ?? 0;
                payload["expire_carry_forwarded_leaves_after_days"] = model.ExpireCarryForwardedLeaves ?? 0;
            }

            return payload;
        }

