        private static bool ToErpBool(dynamic value)
        {
            if (value == null) return false;
            int number;
            if (int.TryParse(value.ToString(), out number)) return number == 1;
            bool result;
            if (bool.TryParse(value.ToString(), out result)) return result;
            return false;
        }

        private static decimal? ToNullableDecimal(dynamic value)
        {
            if (value == null || string.IsNullOrWhiteSpace(value.ToString())) return null;
            return Convert.ToDecimal(value);
        }

        private static int? ToNullableInt(dynamic value)
        {
            if (value == null || string.IsNullOrWhiteSpace(value.ToString())) return null;
            return Convert.ToInt32(value);
        }
