        [HttpPost]
        [Route("HR/CreateHolidayList")]
        public async Task<ActionResult> CreateHolidayList(HolidayList model)
        {
            int localId = _holidayListService.Insert(model);

            try
            {
                var holidaysPayload = new List<object>();
                int idx = 1;

                if (model.Holidays != null)
                {
                    foreach (var h in model.Holidays)
                    {
                        holidaysPayload.Add(new
                        {
                            idx = idx++,
                            holiday_date = h.HolidayDate.ToString("yyyy-MM-dd"),
                            description = h.Description ?? string.Empty
                        });
                    }
                }

                var payload = new Dictionary<string, object>
        {
            { "holiday_list_name", model.HolidayListName },
            { "from_date", model.FromDate.ToString("yyyy-MM-dd") },
            { "to_date", model.ToDate.ToString("yyyy-MM-dd") },
            { "total_holidays", model.Holidays?.Count ?? 0 },
            { "color", model.Color ?? "#3788d8" },
            { "country", model.Country },
            { "subdivision", model.Subdivision },
            { "holidays", holidaysPayload }
        };

                await _erpNextService.PostAsync("/api/resource/Holiday%20List", payload);
                TempData["Success"] = "Holiday List saved and synced to ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Saved in HRMS but ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("HolidayListDetails", new { id = localId });
        }
