        [HttpGet]
        [Route("HR/SyncHolidayListsFromErpNext")]
        public async Task<ActionResult> SyncHolidayListsFromErpNext()
        {
            try
            {
                string listJson = await _erpNextService.GetAsync(
                    "/api/resource/Holiday%20List?fields=[\"name\"]&limit_page_length=500");

                dynamic listParsed = JsonConvert.DeserializeObject(listJson);

                int syncedCount = 0;

                if (listParsed?.data != null)
                {
                    foreach (var item in listParsed.data)
                    {
                        string docName = item.name?.ToString();
                        if (string.IsNullOrWhiteSpace(docName)) continue;

                        string detailJson = await _erpNextService.GetAsync(
                            "/api/resource/Holiday%20List/" + Uri.EscapeDataString(docName));

                        dynamic detailParsed = JsonConvert.DeserializeObject(detailJson);
                        var d = detailParsed?.data;
                        if (d == null) continue;

                        var holidays = new List<HolidayListDate>();

                        if (d.holidays != null)
                        {
                            foreach (var h in d.holidays)
                            {
                                if (h.holiday_date == null) continue;

                                holidays.Add(new HolidayListDate
                                {
                                    HolidayDate = Convert.ToDateTime(h.holiday_date.ToString()),
                                    Description = h.description?.ToString() ?? string.Empty
                                });
                            }
                        }

                        var model = new HolidayList
                        {
                            HolidayListName = d.holiday_list_name?.ToString() ?? d.name?.ToString() ?? docName,
                            FromDate = d.from_date != null ? Convert.ToDateTime(d.from_date.ToString()) : DateTime.Today,
                            ToDate = d.to_date != null ? Convert.ToDateTime(d.to_date.ToString()) : DateTime.Today,
                            TotalHolidays = holidays.Count,
                            Color = d.color?.ToString() ?? "#3788d8",
                            Country = d.country?.ToString(),
                            Subdivision = d.subdivision?.ToString(),
                            Holidays = holidays
                        };

                        _holidayListService.Insert(model);
                        syncedCount++;
                    }
                }

                TempData["Success"] = $"Synced {syncedCount} Holiday Lists from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Failed to sync from ERPNext: " + ex.Message;
            }

            return RedirectToAction("HolidayList");
        }  // GET: HR/CreateHolidayList
        [HttpGet]
        [Route("HR/CreateHolidayList")]
        public async Task<ActionResult> CreateHolidayList()
        {
            var model = new HolidayList
            {
                FromDate = DateTime.Today,
                ToDate = DateTime.Today.AddYears(1),
                Color = "#3788d8"
            };

            // Fetch Countries / Subdivisions dynamically if available in ERPNext
            try
            {
                var countryJson = await _erpNextService.GetAsync("/api/resource/Country?fields=[\"name\"]&limit_page_length=200");
                dynamic countryParsed = JsonConvert.DeserializeObject(countryJson);
                var countries = new List<string>();
                if (countryParsed?.data != null)
                {
                    foreach (var c in countryParsed.data) countries.Add(c.name.ToString());
                }
                ViewBag.Countries = countries.Any() ? countries : new List<string> { "India" };
            }
            catch
            {
                ViewBag.Countries = new List<string> { "India" };
            }

            return View("~/Views/HR/CreateHolidayList.cshtml", model);
        }

        // AJAX API: Get Subdivisions based on Country
        [HttpGet]
        [Route("HR/GetSubdivisions")]
        public async Task<JsonResult> GetSubdivisions(string country)
        {
            var list = new List<string>();

            if (string.IsNullOrWhiteSpace(country))
                return Json(list);

            try
            {
                string filters = Uri.EscapeDataString($"[[\"country\",\"=\",\"{country}\"]]");
                string fields = Uri.EscapeDataString("[\"name\"]");

                string response = await _erpNextService.GetAsync(
                    $"/api/resource/Subdivision?filters={filters}&fields={fields}&limit_page_length=1000&order_by=name%20asc");

                dynamic parsed = JsonConvert.DeserializeObject(response);

                if (parsed?.data != null)
                {
                    foreach (var item in parsed.data)
                    {
                        string name = item.name?.ToString();
                        if (!string.IsNullOrWhiteSpace(name))
                            list.Add(name);
                    }
                }
            }
            catch
            {
            }

            return Json(list);
        }
        // AJAX API: Fetch Local Holidays for a selected Subdivision from ERPNext
        [HttpGet]
        [Route("HR/GetLocalHolidaysBySubdivision")]
        public async Task<JsonResult> GetLocalHolidaysBySubdivision(string subdivision)
        {
            var holidays = new List<object>();
            try
            {
                // Fetch holiday lists from ERPNext to find the matching regional list
                var response = await _erpNextService.GetAsync("/api/resource/Holiday List?fields=[\"name\",\"holiday_list_name\",\"subdivision\"]&limit_page_length=200");
                dynamic parsed = JsonConvert.DeserializeObject(response);

                if (parsed?.data != null)
                {
                    string targetDocName = null;

                    foreach (var item in parsed.data)
                    {
                        string sub = item.subdivision?.ToString() ?? "";
                        string name = item.holiday_list_name?.ToString() ?? item.name?.ToString() ?? "";

                        // Match against subdivision code (e.g., "MH") or name
                        if (sub.Equals(subdivision, StringComparison.OrdinalIgnoreCase) ||
                            name.Contains(subdivision, StringComparison.OrdinalIgnoreCase))
                        {
                            targetDocName = item.name.ToString();
                            break;
                        }
                    }

                    if (!string.IsNullOrEmpty(targetDocName))
                    {
                        // Fetch full document including child table rows
                        var detailResponse = await _erpNextService.GetAsync($"/api/resource/Holiday List/{Uri.EscapeDataString(targetDocName)}");
                        dynamic detailParsed = JsonConvert.DeserializeObject(detailResponse);

                        if (detailParsed?.data?.holidays != null)
                        {
                            foreach (var h in detailParsed.data.holidays)
                            {
                                holidays.Add(new
                                {
                                    holiday_date = Convert.ToDateTime(h.holiday_date).ToString("yyyy-MM-dd"),
                                    description = h.description?.ToString() ?? ""
                                });
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                // Handle exception
            }

            return Json(holidays);
        }


        [HttpPost]
        [Route("HR/FetchHolidaysBySubdivision")]
        public async Task<ActionResult> FetchHolidaysBySubdivision(HolidayList model, List<HolidayListDate> Holidays)
        {
            model.Holidays = Holidays ?? new List<HolidayListDate>();

            try
            {
                if (string.IsNullOrWhiteSpace(model.Subdivision))
                {
                    TempData["ErpNextError"] = "Please enter subdivision.";
                    return View("~/Views/HR/CreateHolidayList.cshtml", model);
                }

                var response = await _erpNextService.GetAsync(
                    "/api/resource/Holiday%20List?fields=[\"name\",\"holiday_list_name\",\"from_date\",\"to_date\",\"country\",\"subdivision\",\"total_holidays\"]&limit_page_length=1000"
                );

                dynamic parsed = JsonConvert.DeserializeObject(response);

                string targetDocName = null;

                if (parsed?.data != null)
                {
                    foreach (var item in parsed.data)
                    {
                        string sub = item.subdivision?.ToString() ?? "";
                        int total = item.total_holidays != null ? Convert.ToInt32(item.total_holidays.ToString()) : 0;

                        if (sub.Equals(model.Subdivision, StringComparison.OrdinalIgnoreCase) && total > 0)
                        {
                            targetDocName = item.name?.ToString();

                            model.HolidayListName = item.holiday_list_name?.ToString() ?? targetDocName;
                            model.FromDate = item.from_date != null ? Convert.ToDateTime(item.from_date.ToString()) : model.FromDate;
                            model.ToDate = item.to_date != null ? Convert.ToDateTime(item.to_date.ToString()) : model.ToDate;
                            model.Country = item.country?.ToString() ?? model.Country;
                            model.Subdivision = item.subdivision?.ToString() ?? model.Subdivision;

                            break;
                        }
                    }
                }

                if (string.IsNullOrWhiteSpace(targetDocName))
                {
                    TempData["ErpNextError"] = "No ERPNext Holiday List with holidays found for subdivision: " + model.Subdivision;
                    return View("~/Views/HR/CreateHolidayList.cshtml", model);
                }

                var detailResponse = await _erpNextService.GetAsync(
                    "/api/resource/Holiday%20List/" + Uri.EscapeDataString(targetDocName)
                );

                dynamic detailParsed = JsonConvert.DeserializeObject(detailResponse);

                model.Holidays.Clear();

                if (detailParsed?.data?.holidays != null)
                {
                    foreach (var h in detailParsed.data.holidays)
                    {
                        model.Holidays.Add(new HolidayListDate
                        {
                            HolidayDate = h.holiday_date != null
                                ? Convert.ToDateTime(h.holiday_date.ToString())
                                : DateTime.Today,

                            Description = CleanHolidayDescription(h.description)
                        });
                    }
                }

                model.Holidays = model.Holidays.OrderBy(x => x.HolidayDate).ToList();
                model.TotalHolidays = model.Holidays.Count;
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Failed to fetch holidays from ERPNext: " + ShortErpNextError(ex.Message);
            }

            return View("~/Views/HR/CreateHolidayList.cshtml", model);
        }

        [HttpPost]
        [Route("HR/FetchWeeklyHolidays")]
        public ActionResult FetchWeeklyHolidays(HolidayList model, string weeklyOffDay)
        {
            var existingHolidays = model.Holidays ?? new List<HolidayListDate>();

            if (!string.IsNullOrEmpty(weeklyOffDay) && model.FromDate != default && model.ToDate != default)
            {
                var daysMap = new Dictionary<string, DayOfWeek>
                {
                    { "Sunday", DayOfWeek.Sunday },
                    { "Monday", DayOfWeek.Monday },
                    { "Tuesday", DayOfWeek.Tuesday },
                    { "Wednesday", DayOfWeek.Wednesday },
                    { "Thursday", DayOfWeek.Thursday },
                    { "Friday", DayOfWeek.Friday },
                    { "Saturday", DayOfWeek.Saturday }
                };

                if (daysMap.TryGetValue(weeklyOffDay, out var targetDay))
                {
                    var currentDate = model.FromDate;
                    while (currentDate.DayOfWeek != targetDay && currentDate <= model.ToDate)
                    {
                        currentDate = currentDate.AddDays(1);
                    }

                    while (currentDate <= model.ToDate)
                    {
                        bool exists = existingHolidays.Any(x => x.HolidayDate.Date == currentDate.Date);
                        if (!exists)
                        {
                            existingHolidays.Add(new HolidayListDate
                            {
                                HolidayDate = currentDate,
                                Description = weeklyOffDay
                            });
                        }
                        currentDate = currentDate.AddDays(7);
                    }
                }
            }

            model.Holidays = existingHolidays.OrderBy(x => x.HolidayDate).ToList();
            model.TotalHolidays = model.Holidays.Count;

            return View("~/Views/HR/CreateHolidayList.cshtml", model);
        }




