        [HttpPost]
        [Route("HR/UpdateLeaveAllocation/{id:int}")]
        public async Task<ActionResult> UpdateLeaveAllocation(int id, LeaveAllocation model)
        {
            var existing = _leaveAllocationService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                if (existing.DocStatus != 0)
                {
                    throw new Exception("You can not edit submitted or cancelled document.");
                }

                ValidateLeaveAllocation(model);
                model.Id = id;
                model.ErpNextId = string.IsNullOrWhiteSpace(existing.ErpNextId) ? existing.Series : existing.ErpNextId;

                await _erpNextService.PutAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Allocation")}/{Uri.EscapeDataString(model.ErpNextId)}",
                    BuildLeaveAllocationPayload(model));

                string detailJson = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Allocation")}/{Uri.EscapeDataString(model.ErpNextId)}");

                var updated = MapErpLeaveAllocation(JObject.Parse(detailJson)["data"]);
                updated.Id = id;
                _leaveAllocationService.Update(updated);

                TempData["Success"] = "Leave Allocation saved in ERPNext and HRMS.";
                return RedirectToAction("LeaveAllocationDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Leave Allocation update failed: " + ExtractErpNextErrorMessage(ex.Message);
                model.Id = id;
                model.ErpNextId = existing.ErpNextId;
                model.DocStatus = existing.DocStatus;
                model.Status = existing.Status;
                await PopulateAllocationDropdownsAsync();
                return View("LeaveAllocationDetails", model);
            }
        }

        [HttpPost]
        [Route("HR/SubmitLeaveAllocation/{id:int}")]
        public async Task<ActionResult> SubmitLeaveAllocation(int id, LeaveAllocation model)
        {
            var existing = _leaveAllocationService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                if (existing.DocStatus != 0)
                {
                    throw new Exception("Only Draft Leave Allocation can be submitted.");
                }

                ValidateLeaveAllocation(model);
                model.Id = id;
                model.ErpNextId = string.IsNullOrWhiteSpace(existing.ErpNextId) ? existing.Series : existing.ErpNextId;

                await _erpNextService.PutAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Allocation")}/{Uri.EscapeDataString(model.ErpNextId)}",
                    BuildLeaveAllocationPayload(model));

                string draftJson = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Allocation")}/{Uri.EscapeDataString(model.ErpNextId)}");

                var draftDoc = JObject.Parse(draftJson)["data"];
                if (draftDoc == null)
                {
                    throw new Exception("Submit failed: ERPNext Leave Allocation document not found.");
                }

                await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new { doc = draftDoc });

                string detailJson = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Allocation")}/{Uri.EscapeDataString(model.ErpNextId)}");

                var updated = MapErpLeaveAllocation(JObject.Parse(detailJson)["data"]);
                updated.Id = id;
                _leaveAllocationService.Update(updated);

                TempData["Success"] = "Leave Allocation submitted in ERPNext and HRMS.";
                return RedirectToAction("LeaveAllocationDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Leave Allocation submit failed: " + ExtractErpNextErrorMessage(ex.Message);
                model.Id = id;
                model.ErpNextId = existing.ErpNextId;
                model.DocStatus = existing.DocStatus;
                model.Status = existing.Status;
                await PopulateAllocationDropdownsAsync();
                return View("LeaveAllocationDetails", model);
            }
        }

        [HttpPost]
        [Route("HR/CancelLeaveAllocation/{id:int}")]
        public async Task<ActionResult> CancelLeaveAllocation(int id)
        {
            var existing = _leaveAllocationService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                if (existing.DocStatus != 1)
                {
                    throw new Exception("Only Submitted Leave Allocation can be cancelled.");
                }

                string erpId = string.IsNullOrWhiteSpace(existing.ErpNextId) ? existing.Series : existing.ErpNextId;
                await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                {
                    doctype = "Leave Allocation",
                    name = erpId
                });

                string detailJson = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Allocation")}/{Uri.EscapeDataString(erpId)}");

                var updated = MapErpLeaveAllocation(JObject.Parse(detailJson)["data"]);
                updated.Id = id;
                _leaveAllocationService.Update(updated);

                TempData["Success"] = "Leave Allocation cancelled in ERPNext and HRMS.";
                return RedirectToAction("LeaveAllocationDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Leave Allocation cancel failed: " + ExtractErpNextErrorMessage(ex.Message);
                return RedirectToAction("LeaveAllocationDetails", new { id });
            }
        }

        private async Task<(int imported, int updated)> PullLeaveAllocationsFromErpNext()
        {
            string listJson = await _erpNextService.GetAsync(
                $"/api/resource/{Uri.EscapeDataString("Leave Allocation")}?fields=[\"name\"]&limit_page_length=0");

            dynamic listParsed = JsonConvert.DeserializeObject(listJson);
            int importedCount = 0;
            int updatedCount = 0;
            var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (listParsed?.data != null)
            {
                foreach (var item in listParsed.data)
                {
                    string erpId = item.name?.ToString();
                    if (string.IsNullOrWhiteSpace(erpId)) continue;

                    erpIds.Add(erpId);
                    string detailJson = await _erpNextService.GetAsync(
                        $"/api/resource/{Uri.EscapeDataString("Leave Allocation")}/{Uri.EscapeDataString(erpId)}");

                    var model = MapErpLeaveAllocation(JObject.Parse(detailJson)["data"]);
                    if (model == null) continue;

                    if (_leaveAllocationService.ExistsByErpNextId(erpId))
                    {
                        _leaveAllocationService.UpdateFromErpNext(model);
                        updatedCount++;
                    }
                    else
                    {
                        _leaveAllocationService.InsertFromErpNext(model);
                        importedCount++;
                    }
                }
            }

            SoftDeleteMissingErpDocuments("LeaveAllocations", "ErpNextId", erpIds);
            return (importedCount, updatedCount);
        }

        private LeaveAllocation MapErpLeaveAllocation(JToken doc)
        {
            if (doc == null) return null;

            int docStatus = doc["docstatus"] != null ? doc["docstatus"].ToObject<int>() : 0;
            return new LeaveAllocation
            {
                Series = doc["naming_series"]?.ToString() ?? "HR-LAL-.YYYY.-",
                Employee = doc["employee"]?.ToString() ?? "",
                EmployeeName = doc["employee_name"]?.ToString() ?? "",
                Company = doc["company"]?.ToString() ?? "AITS",
                LeaveType = doc["leave_type"]?.ToString() ?? "",
                LeavePeriod = doc["leave_period"]?.ToString() ?? "",
                LeavePolicy = doc["leave_policy"]?.ToString() ?? "",
                NewLeavesAllocated = doc["new_leaves_allocated"] != null ? doc["new_leaves_allocated"].ToObject<decimal?>() : null,
                AddUnusedLeaves = ToErpBool(doc["carry_forward"] ?? doc["add_unused_leaves"] ?? doc["unused_leaves"]),
                Description = doc["description"]?.ToString() ?? "",
                FromDate = DateTime.TryParse(doc["from_date"]?.ToString(), out var fromDate) ? fromDate : DateTime.Today,
                ToDate = DateTime.TryParse(doc["to_date"]?.ToString(), out var toDate) ? toDate : DateTime.Today,
                Expired = ToErpBool(doc["expired"]),
                ErpNextId = doc["name"]?.ToString() ?? "",
                DocStatus = docStatus,
                Status = docStatus == 1 ? "Submitted" : docStatus == 2 ? "Cancelled" : "Draft"
            };
        }

        private Dictionary<string, object> BuildLeaveAllocationPayload(LeaveAllocation model)
        {
            return new Dictionary<string, object>
            {
                ["naming_series"] = string.IsNullOrWhiteSpace(model.Series) ? "HR-LAL-.YYYY.-" : model.Series.Trim(),
                ["employee"] = model.Employee?.Trim(),
                ["company"] = string.IsNullOrWhiteSpace(model.Company) ? "AITS" : model.Company.Trim(),
                ["leave_type"] = model.LeaveType?.Trim(),
                ["leave_period"] = string.IsNullOrWhiteSpace(model.LeavePeriod) ? null : model.LeavePeriod.Trim(),
                ["from_date"] = model.FromDate.ToString("yyyy-MM-dd"),
                ["to_date"] = model.ToDate.ToString("yyyy-MM-dd"),
                ["new_leaves_allocated"] = model.NewLeavesAllocated,
                ["carry_forward"] = model.AddUnusedLeaves ? 1 : 0,
                ["description"] = model.Description
            };
        }

        private void ValidateLeaveAllocation(LeaveAllocation model)
        {
            if (string.IsNullOrWhiteSpace(model.Employee)) throw new Exception("Employee is required.");
            if (string.IsNullOrWhiteSpace(model.LeaveType)) throw new Exception("Leave Type is required.");
            if (model.FromDate == default) throw new Exception("From Date is required.");
            if (model.ToDate == default) throw new Exception("To Date is required.");
            if (model.ToDate < model.FromDate) throw new Exception("To Date cannot be before From Date.");
        }


