        [HttpGet]
        [Route("HR/SyncVehiclesFromErpNext")]
        public async Task<ActionResult> SyncVehiclesFromErpNext()
        {
            try
            {
                string listJson = await _erpNextService.GetAsync(
                    "/api/resource/Vehicle?fields=[\"name\"]&limit_page_length=1000");

                dynamic listParsed = JsonConvert.DeserializeObject(listJson);

                int count = 0;

                if (listParsed?.data != null)
                {
                    foreach (var row in listParsed.data)
                    {
                        string erpName = row.name?.ToString();

                        if (string.IsNullOrWhiteSpace(erpName))
                            continue;

                        string detailJson = await _erpNextService.GetAsync(
                            "/api/resource/Vehicle/" + Uri.EscapeDataString(erpName));

                        dynamic parsed = JsonConvert.DeserializeObject(detailJson);
                        var d = parsed?.data;

                        if (d == null)
                            continue;

                        var vehicle = new Vehicle
                        {
                            ErpNextId = erpName,
                            VehicleCode = erpName,
                            LicensePlate = d.license_plate?.ToString() ?? erpName,
                            Make = d.make?.ToString(),
                            Model = d.model?.ToString(),
                            OdometerValueLast = d.last_odometer != null ? Convert.ToDecimal(d.last_odometer.ToString()) : 0,
                            ChassisNo = d.chassis_no?.ToString(),
                            AcquisitionDate = d.acquisition_date != null ? Convert.ToDateTime(d.acquisition_date.ToString()) : (DateTime?)null,
                            VehicleValue = d.vehicle_value != null ? Convert.ToDecimal(d.vehicle_value.ToString()) : (decimal?)null,
                            Location = d.location?.ToString(),
                            Employee = d.employee?.ToString(),
                            InsuranceCompany = d.insurance_company?.ToString(),
                            InsuranceStartDate = d.start_date != null ? Convert.ToDateTime(d.start_date.ToString()) : (DateTime?)null,
                            PolicyNo = d.policy_no?.ToString(),
                            InsuranceEndDate = d.end_date != null ? Convert.ToDateTime(d.end_date.ToString()) : (DateTime?)null,
                            FuelType = d.fuel_type?.ToString() ?? "Petrol",
                            Color = d.color?.ToString(),
                            FuelUOM = d.uom?.ToString(),
                            Wheels = d.wheels != null ? Convert.ToInt32(d.wheels.ToString()) : (int?)null,
                            LastCarbonCheck = d.last_carbon_check != null ? Convert.ToDateTime(d.last_carbon_check.ToString()) : (DateTime?)null,
                            Doors = d.doors != null ? Convert.ToInt32(d.doors.ToString()) : (int?)null
                        };

                        _vehicleService.UpsertFromErpNext(vehicle);
                        count++;
                    }
                }

                TempData["Success"] = $"Synced {count} Vehicles from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Vehicle sync from ERPNext failed: " + ex.Message;
            }

            return RedirectToAction("Vehicle");
        }

        private async Task<string> PushVehicleToErpNext(Vehicle model)
        {
            var payload = new Dictionary<string, object>
    {
        { "license_plate", model.LicensePlate },
        { "make", model.Make },
        { "model", model.Model },
        { "last_odometer", model.OdometerValueLast },
        { "chassis_no", model.ChassisNo },
        { "acquisition_date", model.AcquisitionDate?.ToString("yyyy-MM-dd") },
        { "vehicle_value", model.VehicleValue },
        { "location", model.Location },
        { "employee", model.Employee },
        { "insurance_company", model.InsuranceCompany },
        { "start_date", model.InsuranceStartDate?.ToString("yyyy-MM-dd") },
        { "policy_no", model.PolicyNo },
        { "end_date", model.InsuranceEndDate?.ToString("yyyy-MM-dd") },
        { "fuel_type", model.FuelType },
        { "color", model.Color },
        { "uom", model.FuelUOM },
        { "wheels", model.Wheels },
        { "last_carbon_check", model.LastCarbonCheck?.ToString("yyyy-MM-dd") },
        { "doors", model.Doors }
    };

            string response;

            if (!string.IsNullOrWhiteSpace(model.ErpNextId))
            {
                response = await _erpNextService.PutAsync(
                    "/api/resource/Vehicle/" + Uri.EscapeDataString(model.ErpNextId),
                    payload);
            }
            else
            {
                response = await _erpNextService.PostAsync("/api/resource/Vehicle", payload);
            }

            dynamic parsed = JsonConvert.DeserializeObject(response);
            return parsed?.data?.name?.ToString();
        }

