        private async Task<int> SyncJournalEntriesFromErpNextInternal()
        {
            int synced = 0;

            string listJson = await _erpNextService.GetAsync(
                "/api/resource/Journal%20Entry?fields=[\"name\"]&limit_page_length=200"
            );

            JObject listParsed = JObject.Parse(listJson);

            foreach (var item in listParsed["data"] ?? new JArray())
            {
                string erpId = item["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpId))
                    continue;

                string docJson = await _erpNextService.GetAsync(
                    "/api/resource/Journal%20Entry/" + Uri.EscapeDataString(erpId)
                );

                JObject docParsed = JObject.Parse(docJson);
                JObject doc = docParsed["data"] as JObject;

                if (doc == null)
                    continue;

                var model = new JournalEntry
                {
                    ErpNextId = erpId,
                    EntryType = doc["voucher_type"]?.ToString() ?? "Journal Entry",
                    FromTemplate = doc["from_template"]?.ToString() ?? "",
                    Series = doc["naming_series"]?.ToString() ?? "ACC-JV-.YYYY.-",
                    Company = doc["company"]?.ToString() ?? "",
                    CompanyGstin = doc["company_gstin"]?.ToString() ?? "",

                    PostingDate = string.IsNullOrWhiteSpace(doc["posting_date"]?.ToString())
                        ? DateTime.Now
                        : Convert.ToDateTime(doc["posting_date"]?.ToString()),

                    ReferenceNumber = doc["cheque_no"]?.ToString() ?? "",
                    ReferenceDate = string.IsNullOrWhiteSpace(doc["cheque_date"]?.ToString())
                        ? (DateTime?)null
                        : Convert.ToDateTime(doc["cheque_date"]?.ToString()),

                    BillNo = doc["bill_no"]?.ToString() ?? doc["cheque_no"]?.ToString() ?? "",
                    BillDate = string.IsNullOrWhiteSpace(doc["bill_date"]?.ToString())
                        ? (
                            string.IsNullOrWhiteSpace(doc["cheque_date"]?.ToString())
                                ? (DateTime?)null
                                : Convert.ToDateTime(doc["cheque_date"]?.ToString())
                          )
                        : Convert.ToDateTime(doc["bill_date"]?.ToString()),

                    DueDate = string.IsNullOrWhiteSpace(doc["due_date"]?.ToString())
                        ? (DateTime?)null
                        : Convert.ToDateTime(doc["due_date"]?.ToString()),

                    PayToRecdFrom = doc["pay_to_recd_from"]?.ToString() ?? "",
                    LetterHead = doc["letter_head"]?.ToString() ?? "",

                    // ERPNext field map: select_print_heading
                    PrintHeading = doc["select_print_heading"]?.ToString()
                        ?? doc["print_heading"]?.ToString()
                        ?? "",

                    TotalDebit = string.IsNullOrWhiteSpace(doc["total_debit"]?.ToString())
                        ? 0
                        : Convert.ToDecimal(doc["total_debit"]?.ToString()),

                    TotalCredit = string.IsNullOrWhiteSpace(doc["total_credit"]?.ToString())
                        ? 0
                        : Convert.ToDecimal(doc["total_credit"]?.ToString()),

                    DifferenceAmount = string.IsNullOrWhiteSpace(doc["difference"]?.ToString())
                        ? 0
                        : Convert.ToDecimal(doc["difference"]?.ToString()),

                    MultiCurrency = doc["multi_currency"]?.ToString() == "1",
                    UserRemark = doc["user_remark"]?.ToString() ?? "",
                    ModeOfPayment = doc["mode_of_payment"]?.ToString() ?? "",
                    IsOpening = doc["is_opening"]?.ToString() ?? "No",
                    Title = doc["title"]?.ToString() ?? ""
                };

                var accounts = new List<string>();
                var partyTypes = new List<string>();
                var parties = new List<string>();
                var modeOfPayments = new List<string>();
                var debits = new List<decimal>();
                var credits = new List<decimal>();

                foreach (var row in doc["accounts"] ?? new JArray())
                {
                    accounts.Add(row["account"]?.ToString() ?? "");
                    partyTypes.Add(row["party_type"]?.ToString() ?? "");
                    parties.Add(row["party"]?.ToString() ?? "");
                    modeOfPayments.Add(row["mode_of_payment"]?.ToString() ?? "");

                    debits.Add(string.IsNullOrWhiteSpace(row["debit_in_account_currency"]?.ToString())
                        ? 0
                        : Convert.ToDecimal(row["debit_in_account_currency"]?.ToString()));

                    credits.Add(string.IsNullOrWhiteSpace(row["credit_in_account_currency"]?.ToString())
                        ? 0
                        : Convert.ToDecimal(row["credit_in_account_currency"]?.ToString()));
                }

                if (model.TotalDebit == 0)
                    model.TotalDebit = debits.Sum();

                if (model.TotalCredit == 0)
                    model.TotalCredit = credits.Sum();

                model.DifferenceAmount = model.TotalDebit - model.TotalCredit;

                _journalEntryService.UpsertFromErpNext(
                    model,
                    accounts,
                    partyTypes,
                    parties,
                    modeOfPayments,
                    debits,
                    credits
                );

                synced++;
            }

            return synced;
        }










