        [HttpPost]
        public async Task<ActionResult> LegacyCreateJournalEntry(
            JournalEntry model,
            string[] Accounts,
            string[] PartyTypes,
            string[] Parties,
            string[] ModeOfPayments,
            decimal[] Debits,
            decimal[] Credits)
        {
            var accs = Accounts != null ? new List<string>(Accounts) : new List<string>();
            var pTypes = PartyTypes != null ? new List<string>(PartyTypes) : new List<string>();
            var pList = Parties != null ? new List<string>(Parties) : new List<string>();
            var modeList = ModeOfPayments != null ? new List<string>(ModeOfPayments) : new List<string>();
            var debits = Debits != null ? new List<decimal>(Debits) : new List<decimal>();
            var credits = Credits != null ? new List<decimal>(Credits) : new List<decimal>();

            model.TotalDebit = debits.Sum();
            model.TotalCredit = credits.Sum();
            model.DifferenceAmount = model.TotalDebit - model.TotalCredit;

            int newId = _journalEntryService.Insert(
                model,
                accs,
                pTypes,
                pList,
                modeList,
                debits,
                credits
            );

            try
            {
                var accountRows = new List<object>();

                for (int i = 0; i < accs.Count; i++)
                {
                    if (string.IsNullOrWhiteSpace(accs[i]))
                    {
                        continue;
                    }

                    accountRows.Add(new
                    {
                        account = accs[i],
                        party_type = i < pTypes.Count ? pTypes[i] : null,
                        party = i < pList.Count ? pList[i] : null,
                        mode_of_payment = i < modeList.Count ? modeList[i] : null,
                        debit_in_account_currency = i < debits.Count ? debits[i] : 0,
                        credit_in_account_currency = i < credits.Count ? credits[i] : 0
                    });
                }

                var payload = new
                {
                    voucher_type = model.EntryType,
                    from_template = model.FromTemplate,
                    naming_series = model.Series,
                    company = model.Company,
                    company_gstin = model.CompanyGstin,
                    posting_date = model.PostingDate.ToString("yyyy-MM-dd"),
                    cheque_no = model.ReferenceNumber,
                    cheque_date = model.ReferenceDate?.ToString("yyyy-MM-dd"),
                    user_remark = model.UserRemark,
                    multi_currency = model.MultiCurrency ? 1 : 0,
                    mode_of_payment = model.ModeOfPayment,
                    is_opening = model.IsOpening,
                    title = model.Title,
                    accounts = accountRows
                };

                string responseJson = await _erpNextService.PostAsync("/api/resource/Journal%20Entry", payload);
                dynamic responseParsed = JsonConvert.DeserializeObject(responseJson);
                string erpNextId = responseParsed?.data?.name;

                if (!string.IsNullOrWhiteSpace(erpNextId))
                {
                    _journalEntryService.UpdateErpNextId(newId, erpNextId);
                    TempData["Success"] = $"Journal Entry saved locally and pushed to ERPNext: {erpNextId}";
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Journal Entry saved locally, but ERPNext push failed: " + ex.Message;
            }

            return RedirectToAction("JournalEntryDetails", new { id = newId });
        }







