        [HttpPost]
        [Route("HR/SyncPaymentEntriesFromErpNext")]
        public async Task<ActionResult> SyncPaymentEntriesFromErpNext()
        {
            int inserted = 0;
            int updated = 0;
            int failed = 0;
            string firstError = "";

            try
            {
                string listJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Payment%20Entry"
                        + "?fields=[\"name\",\"modified\"]"
                        + "&order_by=modified%20desc"
                        + "&limit_page_length=50"
                    );

                JObject parsed = JObject.Parse(listJson);
                JArray rows = parsed["data"] as JArray;

                if (rows != null)
                {
                    foreach (JToken row in rows)
                    {
                        string erpId = row["name"]?.ToString();

                        try
                        {
                            if (string.IsNullOrWhiteSpace(erpId))
                                continue;

                            bool exists =
                                _paymentEntryService.GetByErpNextId(erpId) != null;

                            string detailJson =
                                await _erpNextService.GetAsync(
                                    "/api/resource/Payment%20Entry/"
                                    + Uri.EscapeDataString(erpId)
                                );

                            JObject detail = JObject.Parse(detailJson);

                            PaymentEntry model =
                                MapErpPaymentEntry(detail["data"]);

                            if (model == null)
                                throw new Exception("Could not map ERPNext Payment Entry.");

                            _paymentEntryService.InsertOrUpdate(model);

                            if (exists)
                                updated++;
                            else
                                inserted++;
                        }
                        catch (Exception rowEx)
                        {
                            failed++;

                            if (string.IsNullOrWhiteSpace(firstError))
                            {
                                firstError =
                                    "Failed ERP ID: "
                                    + erpId
                                    + " | Error: "
                                    + CleanPaymentEntryErpError(rowEx.Message);
                            }
                        }
                    }
                }

                if (!string.IsNullOrWhiteSpace(firstError))
                {
                    TempData["ErpNextError"] =
                        "Payment Entry sync completed with errors. New: "
                        + inserted
                        + ", Updated: "
                        + updated
                        + ", Failed: "
                        + failed
                        + ". First error: "
                        + firstError;
                }
                else
                {
                    TempData["Success"] =
                        "Payment Entry sync completed. New: "
                        + inserted
                        + ", Updated: "
                        + updated
                        + ", Failed: "
                        + failed
                        + ".";
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Payment Entry sync failed: "
                    + CleanPaymentEntryErpError(ex.Message);
            }

            return RedirectToAction("PaymentEntry");
        }

        private string CleanPaymentEntryErpError(
    string rawError)
        {
            if (string.IsNullOrWhiteSpace(rawError))
                return "ERPNext validation failed.";


            try
            {
                int start =
                    rawError.IndexOf('{');


                if (start >= 0)
                {
                    JObject json =
                        JObject.Parse(
                            rawError.Substring(start)
                        );


                    string serverMessages =
                        json["_server_messages"]
                            ?.ToString();


                    if (!string.IsNullOrWhiteSpace(
                        serverMessages))
                    {
                        JArray messages =
                            JArray.Parse(
                                serverMessages
                            );


                        if (messages.Count > 0)
                        {
                            JObject first =
                                JObject.Parse(
                                    messages[0]
                                        .ToString()
                                );


                            string message =
                                first["message"]
                                    ?.ToString();


                            if (!string.IsNullOrWhiteSpace(
                                message))
                            {
                                message =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        message,
                                        "<[^>]*>",
                                        " "
                                    );


                                message =
                                    System.Net.WebUtility
                                        .HtmlDecode(
                                            message
                                        );


                                message =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        message,
                                        @"\s+",
                                        " "
                                    )
                                    .Trim();


                                return message.Length > 300
                                    ? message.Substring(
                                        0,
                                        300
                                    ) + "..."
                                    : message;
                            }
                        }
                    }


                    string exception =
                        json["exception"]
                            ?.ToString();


                    if (!string.IsNullOrWhiteSpace(
                        exception))
                    {
                        int colon =
                            exception.IndexOf(':');


                        if (colon >= 0)
                        {
                            exception =
                                exception.Substring(
                                    colon + 1
                                );
                        }


                        return exception.Trim();
                    }
                }
            }
            catch
            {
            }


            int jsonIndex =
                rawError.IndexOf('{');


            if (jsonIndex >= 0)
            {
                rawError =
                    rawError.Substring(
                        0,
                        jsonIndex
                    );
            }


            rawError =
                rawError
                    .Replace(
                        "ERPNext returned 417:",
                        ""
                    )
                    .Replace(
                        "ERPNext returned 400:",
                        ""
                    )
                    .Replace(
                        "ERPNext returned 422:",
                        ""
                    )
                    .Replace(
                        "ERPNext returned 500:",
                        ""
                    )
                    .Trim();


            return string.IsNullOrWhiteSpace(
                rawError)
                ? "ERPNext validation failed."
                : rawError;
        }



        [HttpGet]
        [Route("HR/GetPaymentEntryModeOfPaymentDetails")]
        public async Task<JsonResult> GetPaymentEntryModeOfPaymentDetails(
            string modeOfPayment,
            string company)
        {
            if (string.IsNullOrWhiteSpace(modeOfPayment) ||
                string.IsNullOrWhiteSpace(company))
            {
                return Json(new { success = false });
            }

            try
            {
                string json = await _erpNextService.GetAsync(
                    "/api/resource/Mode%20of%20Payment/"
                    + Uri.EscapeDataString(modeOfPayment)
                );

                JObject doc = JObject.Parse(json)["data"] as JObject;

                string defaultAccount = "";

                if (doc?["accounts"] is JArray accounts)
                {
                    foreach (JToken row in accounts)
                    {
                        if (string.Equals(
                            row["company"]?.ToString(),
                            company,
                            StringComparison.OrdinalIgnoreCase))
                        {
                            defaultAccount =
                                row["default_account"]?.ToString() ?? "";
                            break;
                        }
                    }
                }

                return Json(new
                {
                    success = true,
                    defaultAccount
                });
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    success = false,
                    message = CleanPaymentEntryErpError(ex.Message)
                });
            }
        }













        [HttpPost]
        [Route("HR/SyncPaymentEntriesToServerToErpNext")]
        public async Task<ActionResult> SyncPaymentEntriesToServerToErpNext()
        {
            int successCount = 0;
            int failCount = 0;

            try
            {
                var allEntries =
                    _paymentEntryService.GetAll(null, null, null, null, null);

                foreach (var row in allEntries)
                {
                    if (!string.IsNullOrWhiteSpace(row.ErpNextId))
                        continue;

                    try
                    {
                        var model =
                            _paymentEntryService.GetById(row.Id);

                        if (model == null)
                            continue;

                        string targetCompany =
                            string.IsNullOrWhiteSpace(model.Company)
                                ? "Vinod Cookware India Private Limited"
                                : model.Company.Trim();

                        await EnsureDocExistsAsync("Company", targetCompany);

                        if (!string.IsNullOrWhiteSpace(model.ModeOfPayment))
                            await EnsureDocExistsAsync("Mode of Payment", model.ModeOfPayment);

                        if (!string.IsNullOrWhiteSpace(model.PaidFrom))
                            await EnsureDocExistsAsync("Account", model.PaidFrom);

                        if (!string.IsNullOrWhiteSpace(model.PaidTo))
                            await EnsureDocExistsAsync("Account", model.PaidTo);

                        if (!string.IsNullOrWhiteSpace(model.CostCenter))
                            await EnsureDocExistsAsync("Cost Center", model.CostCenter);

                        if (!string.IsNullOrWhiteSpace(model.Project))
                            await EnsureDocExistsAsync("Project", model.Project);

                        if (
                            model.PaymentType != "Internal Transfer" &&
                            !string.IsNullOrWhiteSpace(model.Party)
                        )
                        {
                            await EnsurePartyExistsAsync(model.PartyType, model.Party);
                        }

                        var taxesList = new List<object>();

                        if (model.Taxes != null)
                        {
                            foreach (var tax in model.Taxes)
                            {
                                if (tax == null)
                                    continue;

                                if (string.IsNullOrWhiteSpace(tax.AccountHead))
                                    continue;

                                await EnsureDocExistsAsync("Account", tax.AccountHead);

                                taxesList.Add(
                                    new
                                    {
                                        charge_type =
                                            string.IsNullOrWhiteSpace(tax.Type)
                                                ? "On Net Total"
                                                : tax.Type,

                                        account_head = tax.AccountHead,
                                        rate = tax.TaxRate ?? 0,
                                        tax_amount = tax.Amount ?? 0,
                                        total = tax.Total ?? 0
                                    }
                                );
                            }
                        }

                        decimal finalPaidAmount =
                            model.PaidAmount <= 0
                                ? 1.00m
                                : model.PaidAmount;

                        decimal finalReceivedAmount =
                            model.ReceivedAmount <= 0
                                ? finalPaidAmount
                                : model.ReceivedAmount;

                        var payloadDictionary =
                            new Dictionary<string, object>
                            {
                        {
                            "naming_series",
                            string.IsNullOrWhiteSpace(model.Series)
                                ? "ACC-PAY-.YYYY.-"
                                : model.Series
                        },

                        { "posting_date", model.PostingDate.ToString("yyyy-MM-dd") },
                        { "payment_type", model.PaymentType },
                        { "mode_of_payment", model.ModeOfPayment },
                        { "company", targetCompany },

                        {
                            "party_type",
                            model.PaymentType == "Internal Transfer"
                                ? null
                                : model.PartyType
                        },

                        {
                            "party",
                            model.PaymentType == "Internal Transfer"
                                ? null
                                : model.Party
                        },

                        {
                            "paid_from",
                            string.IsNullOrWhiteSpace(model.PaidFrom)
                                ? null
                                : model.PaidFrom
                        },

                        {
                            "paid_to",
                            string.IsNullOrWhiteSpace(model.PaidTo)
                                ? null
                                : model.PaidTo
                        },

                        { "paid_amount", finalPaidAmount },
                        { "received_amount", finalReceivedAmount },
                        { "source_exchange_rate", model.SourceExchangeRate <= 0 ? 1 : model.SourceExchangeRate },
                        { "target_exchange_rate", model.TargetExchangeRate <= 0 ? 1 : model.TargetExchangeRate },

                        { "company_address", model.CompanyAddress },
                        { "customer_address", model.CustomerAddress },
                        { "company_gstin", model.CompanyGstin },
                        { "billing_address_gstin", model.BillingAddressGstin },
                        { "place_of_supply", model.PlaceOfSupply },
                        { "gst_category", model.GstCategory },
                        { "project", model.Project },
                        { "cost_center", model.CostCenter },
                        { "bank_account", model.CompanyBankAccount },
                        { "party_bank_account", model.PartyBankAccount },
                        { "contact_person", model.ContactPerson }
                            };

                        if (
                            model.PartyType == "Customer" &&
                            !string.IsNullOrWhiteSpace(model.SalesTaxesChargesTemplate)
                        )
                        {
                            payloadDictionary["sales_taxes_and_charges_template"] =
                                model.SalesTaxesChargesTemplate;
                        }

                        if (
                            model.PartyType == "Supplier" &&
                            !string.IsNullOrWhiteSpace(model.PurchaseTaxesChargesTemplate)
                        )
                        {
                            payloadDictionary["purchase_taxes_and_charges_template"] =
                                model.PurchaseTaxesChargesTemplate;
                        }

                        if (taxesList.Count > 0)
                        {
                            payloadDictionary["taxes"] = taxesList;
                        }

                        string responseJson =
                            await _erpNextService.PostAsync(
                                "/api/resource/Payment%20Entry",
                                payloadDictionary
                            );

                        dynamic responseParsed =
                            JsonConvert.DeserializeObject(responseJson);

                        string erpNextId =
                            responseParsed?.data?.name;

                        if (!string.IsNullOrWhiteSpace(erpNextId))
                        {
                            _paymentEntryService.UpdateErpNextId(
                                model.Id,
                                erpNextId
                            );

                            successCount++;
                        }
                    }
                    catch
                    {
                        failCount++;
                    }
                }

                if (successCount > 0)
                {
                    TempData["Success"] =
                        $"Pushed {successCount} local payment entry/entries to ERPNext successfully!"
                        + (failCount > 0 ? $" ({failCount} failed)" : "");
                }
                else if (failCount > 0)
                {
                    TempData["ErpNextError"] =
                        $"Failed to push {failCount} payment entry/entries to ERPNext.";
                }
                else
                {
                    TempData["Success"] =
                        "All local payment entries are already synced with ERPNext!";
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Push error: " + CleanPaymentEntryErpError(ex.Message);
            }

            return RedirectToAction("PaymentEntry");
        }



      









        [HttpPost]
        [Route("HR/CreatePaymentEntry")]
        public async Task<ActionResult> CreatePaymentEntry(PaymentEntry model)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(model.Series))
                    throw new Exception("Series is required.");

                if (model.PostingDate == default(DateTime))
                    throw new Exception("Posting Date is required.");

                if (string.IsNullOrWhiteSpace(model.PaymentType))
                    throw new Exception("Payment Type is required.");

                if (
                    model.PaymentType != "Receive" &&
                    model.PaymentType != "Pay" &&
                    model.PaymentType != "Internal Transfer"
                )
                {
                    throw new Exception("Invalid Payment Type.");
                }

                if (string.IsNullOrWhiteSpace(model.Company))
                    throw new Exception("Company is required.");

                if (model.PaymentType == "Internal Transfer")
                {
                    model.PartyType = null;
                    model.Party = null;
                    model.PartyName = null;
                    model.PartyBankAccount = null;
                    model.ContactPerson = null;
                    model.ContactEmail = null;
                }
                else
                {
                    if (
                        !string.IsNullOrWhiteSpace(model.PartyType) &&
                        string.IsNullOrWhiteSpace(model.Party)
                    )
                    {
                        throw new Exception("Party is mandatory after selecting Party Type.");
                    }

                    if (
                        !string.IsNullOrWhiteSpace(model.Party) &&
                        string.IsNullOrWhiteSpace(model.PartyType)
                    )
                    {
                        throw new Exception("Party Type is mandatory.");
                    }
                }

                if (string.IsNullOrWhiteSpace(model.PaidFrom))
                    throw new Exception("Account Paid From is required.");

                if (string.IsNullOrWhiteSpace(model.PaidTo))
                    throw new Exception("Account Paid To is required.");

                if (
                    model.PaymentType == "Internal Transfer" &&
                    string.Equals(
                        model.PaidFrom,
                        model.PaidTo,
                        StringComparison.OrdinalIgnoreCase
                    )
                )
                {
                    throw new Exception("Paid From and Paid To accounts must be different.");
                }

                if (model.PaidAmount <= 0)
                    throw new Exception("Paid Amount is required.");

                if (model.ReceivedAmount <= 0)
                    throw new Exception("Received Amount is required.");

                if (model.SourceExchangeRate <= 0)
                    model.SourceExchangeRate = 1;

                if (model.TargetExchangeRate <= 0)
                    model.TargetExchangeRate = 1;

                var taxRows = new List<object>();

                if (
                    model.Taxes != null &&
                    (
                        model.PartyType == "Customer" ||
                        model.PartyType == "Supplier"
                    )
                )
                {
                    foreach (var tax in model.Taxes)
                    {
                        if (tax == null)
                            continue;

                        if (string.IsNullOrWhiteSpace(tax.AccountHead))
                            continue;

                        taxRows.Add(
                            new
                            {
                                charge_type =
                                    string.IsNullOrWhiteSpace(tax.Type)
                                        ? "On Net Total"
                                        : tax.Type,

                                account_head = tax.AccountHead,
                                rate = tax.TaxRate ?? 0,
                                tax_amount = tax.Amount ?? 0
                            }
                        );
                    }
                }

                var payload = new Dictionary<string, object>
        {
            { "naming_series", model.Series },
            { "posting_date", model.PostingDate.ToString("yyyy-MM-dd") },
            { "payment_type", model.PaymentType },
            { "company", model.Company },

            {
                "mode_of_payment",
                string.IsNullOrWhiteSpace(model.ModeOfPayment)
                    ? null
                    : model.ModeOfPayment
            },

            {
                "party_type",
                model.PaymentType == "Internal Transfer"
                    ? null
                    : model.PartyType
            },

            {
                "party",
                model.PaymentType == "Internal Transfer"
                    ? null
                    : model.Party
            },

            {
                "bank_account",
                string.IsNullOrWhiteSpace(model.CompanyBankAccount)
                    ? null
                    : model.CompanyBankAccount
            },

            {
                "party_bank_account",
                string.IsNullOrWhiteSpace(model.PartyBankAccount)
                    ? null
                    : model.PartyBankAccount
            },

            {
                "contact_person",
                string.IsNullOrWhiteSpace(model.ContactPerson)
                    ? null
                    : model.ContactPerson
            },

            { "paid_from", model.PaidFrom },
            { "paid_to", model.PaidTo },
            { "paid_amount", model.PaidAmount },
            { "received_amount", model.ReceivedAmount },
            { "source_exchange_rate", model.SourceExchangeRate },
            { "target_exchange_rate", model.TargetExchangeRate },

            {
                "project",
                string.IsNullOrWhiteSpace(model.Project)
                    ? null
                    : model.Project
            },

            {
                "cost_center",
                string.IsNullOrWhiteSpace(model.CostCenter)
                    ? null
                    : model.CostCenter
            },

            {
                "reference_no",
                string.IsNullOrWhiteSpace(model.ReferenceNo)
                    ? null
                    : model.ReferenceNo
            },

            {
                "reference_date",
                model.ReferenceDate.HasValue
                    ? model.ReferenceDate.Value.ToString("yyyy-MM-dd")
                    : null
            }
        };

                if (
                    model.PartyType == "Customer" &&
                    !string.IsNullOrWhiteSpace(model.SalesTaxesChargesTemplate)
                )
                {
                    payload["sales_taxes_and_charges_template"] =
                        model.SalesTaxesChargesTemplate;
                }

                if (
                    model.PartyType == "Supplier" &&
                    !string.IsNullOrWhiteSpace(model.PurchaseTaxesChargesTemplate)
                )
                {
                    payload["purchase_taxes_and_charges_template"] =
                        model.PurchaseTaxesChargesTemplate;
                }

                if (taxRows.Count > 0)
                {
                    payload["taxes"] = taxRows;
                }

                string createJson =
                    await _erpNextService.PostAsync(
                        "/api/resource/Payment%20Entry",
                        payload
                    );

                JObject createObject = JObject.Parse(createJson);

                string erpId =
                    createObject["data"]?["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpId))
                    throw new Exception("ERPNext did not return Payment Entry ID.");

                string detailJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Payment%20Entry/"
                        + Uri.EscapeDataString(erpId)
                    );

                JObject detailObject = JObject.Parse(detailJson);

                PaymentEntry localModel =
                    MapErpPaymentEntry(detailObject["data"]);

                if (localModel == null)
                    throw new Exception("Payment Entry was created in ERPNext but could not be reloaded.");

                int localId =
                    _paymentEntryService.InsertOrUpdate(localModel);

                TempData["Success"] =
                    "Payment Entry saved successfully. ERPNext Ref: " + erpId;

                return RedirectToAction(
                    "PaymentEntryDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanPaymentEntryErpError(ex.Message);

                await LoadPaymentEntryMasterDataAsync();

                return View(
                    "~/Views/HR/CreatePaymentEntry.cshtml",
                    model
                );
            }
        }


        private PaymentEntry MapErpPaymentEntry(JToken doc)
        {
            if (doc == null)
                return null;

            string ReadString(string field)
            {
                return doc[field]?.ToString() ?? "";
            }

            decimal ReadDecimal(string field)
            {
                decimal value;

                return decimal.TryParse(
                    doc[field]?.ToString(),
                    out value
                )
                    ? value
                    : 0;
            }

            DateTime ReadDateOrToday(string field)
            {
                DateTime value;

                return DateTime.TryParse(
                    doc[field]?.ToString(),
                    out value
                )
                    ? value
                    : DateTime.Today;
            }

            DateTime? ReadNullableDate(string field)
            {
                DateTime value;

                return DateTime.TryParse(
                    doc[field]?.ToString(),
                    out value
                )
                    ? value
                    : (DateTime?)null;
            }

            int ReadInt(string field)
            {
                int value;

                return int.TryParse(
                    doc[field]?.ToString(),
                    out value
                )
                    ? value
                    : 0;
            }

            decimal? ReadRowDecimalOrNull(JToken row, string field)
            {
                decimal value;

                return decimal.TryParse(
                    row[field]?.ToString(),
                    out value
                )
                    ? value
                    : (decimal?)null;
            }

            int docStatus = ReadInt("docstatus");

            string status = ReadString("status");

            if (string.IsNullOrWhiteSpace(status))
            {
                status = docStatus == 1
                    ? "Submitted"
                    : docStatus == 2
                        ? "Cancelled"
                        : "Draft";
            }

            var model = new PaymentEntry
            {
                ErpNextId = ReadString("name"),
                Series = ReadString("naming_series"),
                PostingDate = ReadDateOrToday("posting_date"),

                PaymentType = ReadString("payment_type"),
                Company = ReadString("company"),
                ModeOfPayment = ReadString("mode_of_payment"),

                PartyType = ReadString("party_type"),
                Party = ReadString("party"),
                PartyName = ReadString("party_name"),
                PartyBalance = ReadDecimal("party_balance"),

                CompanyBankAccount = ReadString("bank_account"),
                PartyBankAccount = ReadString("party_bank_account"),
                ContactPerson = ReadString("contact_person"),
                ContactEmail = ReadString("contact_email"),

                PaidFrom = ReadString("paid_from"),
                PaidFromAccountType = ReadString("paid_from_account_type"),
                PaidFromAccountCurrency = ReadString("paid_from_account_currency"),
                PaidFromAccountBalance = ReadDecimal("paid_from_account_balance"),

                PaidTo = ReadString("paid_to"),
                PaidToAccountType = ReadString("paid_to_account_type"),
                PaidToAccountCurrency = ReadString("paid_to_account_currency"),
                PaidToAccountBalance = ReadDecimal("paid_to_account_balance"),

                PaidAmount = ReadDecimal("paid_amount"),
                ReceivedAmount = ReadDecimal("received_amount"),
                SourceExchangeRate = ReadDecimal("source_exchange_rate"),
                TargetExchangeRate = ReadDecimal("target_exchange_rate"),

                TotalAllocatedAmount = ReadDecimal("total_allocated_amount"),
                UnallocatedAmount = ReadDecimal("unallocated_amount"),
                DifferenceAmount = ReadDecimal("difference_amount"),

                SalesTaxesChargesTemplate =
                    ReadString("sales_taxes_and_charges_template"),

                PurchaseTaxesChargesTemplate =
                    ReadString("purchase_taxes_and_charges_template"),

                CompanyAddress = ReadString("company_address"),
                CompanyGstin = ReadString("company_gstin"),
                CustomerAddress = ReadString("customer_address"),
                BillingAddressGstin = ReadString("billing_address_gstin"),
                PlaceOfSupply = ReadString("place_of_supply"),
                GstCategory = ReadString("gst_category"),

                ReferenceNo = ReadString("reference_no"),
                ReferenceDate = ReadNullableDate("reference_date"),

                Project = ReadString("project"),
                CostCenter = ReadString("cost_center"),

                DocStatus = docStatus,
                Status = status,

                Taxes = new List<PaymentEntryTax>()
            };

            if (doc["taxes"] is JArray taxes)
            {
                foreach (JToken row in taxes)
                {
                    model.Taxes.Add(
                        new PaymentEntryTax
                        {
                            Type = row["charge_type"]?.ToString() ?? "",
                            AccountHead = row["account_head"]?.ToString() ?? "",
                            TaxRate = ReadRowDecimalOrNull(row, "rate"),
                            Amount = ReadRowDecimalOrNull(row, "tax_amount"),
                            Total = ReadRowDecimalOrNull(row, "total")
                        }
                    );
                }
            }

            return model;
        }

























        // Helper method to ensure a Party exists in ERPNext before posting transactions
        private async Task EnsurePartyExistsAsync(string partyType, string partyName)
        {
            if (string.IsNullOrWhiteSpace(partyType) || string.IsNullOrWhiteSpace(partyName)) return;

            string doctype = partyType.Equals("Customer", StringComparison.OrdinalIgnoreCase) ? "Customer" :
                             (partyType.Equals("Supplier", StringComparison.OrdinalIgnoreCase) ? "Supplier" : "Customer");

            try
            {
                var checkResp = await _erpNextService.GetAsync($"/api/resource/{Uri.EscapeDataString(doctype)}/{Uri.EscapeDataString(partyName)}");
                dynamic parsed = JsonConvert.DeserializeObject(checkResp);
                if (parsed?.data != null) return; // Party exists
            }
            catch
            {
                // Party doesn't exist remotely; create it automatically
                try
                {
                    var createPayload = new Dictionary<string, object>
            {
                { doctype.ToLower() + "_name", partyName }
            };
                    await _erpNextService.PostAsync($"/api/resource/{Uri.EscapeDataString(doctype)}", createPayload);
                }
                catch { }
            }
        }
        private async Task EnsureDocExistsAsync(string doctype, string docName)
        {
            if (string.IsNullOrWhiteSpace(docName) || string.IsNullOrWhiteSpace(doctype)) return;

            bool exists = false;
            try
            {
                // 1. Check if the record already exists in ERPNext
                string checkUrl = $"/api/resource/{Uri.EscapeDataString(doctype)}/{Uri.EscapeDataString(docName)}";
                var response = await _erpNextService.GetAsync(checkUrl);
                if (!string.IsNullOrEmpty(response))
                {
                    exists = true;
                }
            }
            catch
            {
                exists = false; // It doesn't exist, so we need to create it!
            }

            // 2. If it does not exist, force-create it right now on the fly!
            if (!exists)
            {
                var payload = new Dictionary<string, object>();

                if (doctype.Equals("Health Insurance Provider", StringComparison.OrdinalIgnoreCase))
                {
                    payload["health_insurance_provider_name"] = docName;
                    payload["name"] = docName;
                }
                else if (doctype.Equals("Shift Type", StringComparison.OrdinalIgnoreCase))
                {
                    payload["shift_type_name"] = docName;
                    payload["name"] = docName;
                    payload["start_time"] = "09:00:00";
                }
                else if (doctype.Equals("Company", StringComparison.OrdinalIgnoreCase))
                {
                    payload["company_name"] = docName;
                    payload["name"] = docName;
                    payload["default_currency"] = "INR";
                }
                else
                {
                    // This is the universal handler: ANY missing dropdown or text you enter 
                    // will automatically use its title/name key and get created instantly!
                    payload["name"] = docName;
                }

                try
                {
                    await _erpNextService.PostAsync($"/api/resource/{Uri.EscapeDataString(doctype)}", payload);
                }
                catch (Exception createEx)
                {
                    System.Diagnostics.Debug.WriteLine($"Auto-creation of {doctype} '{docName}' failed: {createEx.Message}");
                }
            }
        }



