        [HttpPost]
        [Route("HR/CreateAttendance")]
        public async Task<ActionResult> CreateAttendance(Attendance model)
        {
            var service = new AttendanceService(_connectionString);

            try
            {
                model.DocStatus = 0;

                if (model.Status != "Half Day" && model.Status != "On Leave")
                {
                    model.LeaveType = null;
                }

                if (model.Status != "Half Day")
                {
                    model.StatusForOtherHalf = null;
                }

                var payload = new
                {
                    employee = model.Employee,
                    employee_name = model.EmployeeName,
                    company = model.Company,
                    attendance_date = model.AttendanceDate.ToString("yyyy-MM-dd"),
                    status = model.Status,
                    leave_type = model.LeaveType,
                    status_for_other_half = model.StatusForOtherHalf,
                    shift = model.Shift,
                    late_entry = model.LateEntry ? 1 : 0,
                    early_exit = model.EarlyExit ? 1 : 0,
                    docstatus = 0
                };

                var response = await _erpNextService.PostAsync("/api/resource/Attendance", payload);
                dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);
                string erpName = parsed?.data?.name?.ToString();

                if (string.IsNullOrWhiteSpace(erpName))
                {
                    TempData["ErpNextError"] = "ERPNext created attendance but did not return ID.";
                    return RedirectToAction("CreateAttendance");
                }

                model.ErpNextId = erpName;
                model.AttendanceCode = erpName;
                model.DocStatus = 0;

                int localId;
                var existing = service.GetByErpNextId(erpName);

                if (existing != null)
                {
                    model.Id = existing.Id;
                    service.UpdateAttendance(model);
                    localId = existing.Id;
                }
                else
                {
                    localId = service.InsertAttendance(model);
                }

                TempData["Success"] = "Attendance saved as Draft.";
                return RedirectToAction("AttendanceDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Creation failed: " + CleanErpNextError(ex);
                await LoadDropdownsToViewBag();
                return View("CreateAttendance", model);
            }
        }















        [HttpPost]
        [Route("HR/UpdateAttendance")]
        public async Task<ActionResult> UpdateAttendance(Attendance model)
        {
            var service = new AttendanceService(_connectionString);
            service.UpdateAttendance(model);

            try
            {
                if (!string.IsNullOrEmpty(model.ErpNextId))
                {
                    var payload = new
                    {
                        employee = model.Employee,
                        employee_name = model.EmployeeName,
                        company = model.Company,
                        attendance_date = model.AttendanceDate.ToString("yyyy-MM-dd"),
                        status = model.Status,
                        shift = model.Shift,
                        docstatus = model.DocStatus
                    };
                    await _erpNextService.PutAsync($"/api/resource/Attendance/{Uri.EscapeDataString(model.ErpNextId)}", Newtonsoft.Json.JsonConvert.SerializeObject(payload));
                }
                TempData["Success"] = "Attendance updated successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Updated locally, but ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("AttendanceDetails", new { id = model.Id });
        }



        [HttpPost]
        [Route("HR/SubmitAttendance/{id:int}")]
        public async Task<ActionResult> SubmitAttendance(int id)
        {
            var service = new AttendanceService(_connectionString);
            var record = service.GetById(id);
            if (record == null) return NotFound();

            try
            {
                if (!string.IsNullOrEmpty(record.ErpNextId))
                {
                    var payload = new
                    {
                        employee = record.Employee,
                        employee_name = record.EmployeeName,
                        company = record.Company,
                        attendance_date = record.AttendanceDate.ToString("yyyy-MM-dd"),
                        status = record.Status,
                        shift = record.Shift,
                        docstatus = 1 // 1 for Submit in ERPNext
                    };
                    await _erpNextService.PutAsync($"/api/resource/Attendance/{Uri.EscapeDataString(record.ErpNextId)}", Newtonsoft.Json.JsonConvert.SerializeObject(payload));
                }
                service.UpdateDocStatus(id, 1);
                TempData["Success"] = "Attendance submitted and synced with ERPNext successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Submission failed: " + ex.Message;
            }
            return RedirectToAction("AttendanceDetails", new { id });
        }


