        [HttpPost]
        [Route("HR/ProcessAttendanceAction")]
        public async Task<ActionResult> ProcessAttendanceAction(Attendance model, string actionCommand)
        {
            var service = new AttendanceService(_connectionString);
            var existing = service.GetById(model.Id);

            if (existing == null)
            {
                return NotFound();
            }

            if (existing.DocStatus == 2)
            {
                TempData["ErpNextError"] = "Cancelled Attendance cannot be changed.";
                return RedirectToAction("AttendanceDetails", new { id = model.Id });
            }

            if (string.IsNullOrWhiteSpace(model.Employee)) model.Employee = existing.Employee;
            if (string.IsNullOrWhiteSpace(model.EmployeeName)) model.EmployeeName = existing.EmployeeName;
            if (string.IsNullOrWhiteSpace(model.Company)) model.Company = existing.Company;
            if (string.IsNullOrWhiteSpace(model.Status)) model.Status = existing.Status;
            if (string.IsNullOrWhiteSpace(model.Shift)) model.Shift = existing.Shift;
            if (model.AttendanceDate < new DateTime(1753, 1, 1)) model.AttendanceDate = existing.AttendanceDate;

            if (model.Status != "Half Day" && model.Status != "On Leave")
            {
                model.LeaveType = null;
            }

            if (model.Status != "Half Day")
            {
                model.StatusForOtherHalf = null;
            }

            try
            {
                if (actionCommand == "Save")
                {
                    if (string.IsNullOrWhiteSpace(existing.ErpNextId))
                    {
                        TempData["ErpNextError"] = "Save failed: ERPNext ID is missing.";
                        return RedirectToAction("AttendanceDetails", new { id = model.Id });
                    }

                    var payload = new
                    {
                        employee = model.Employee,
                        employee_name = model.EmployeeName,
                        company = model.Company,
                        attendance_date = model.AttendanceDate.ToString("yyyy-MM-dd"),
                        status = model.Status,
                        leave_type = model.LeaveType,
                        status_for_other_half = model.StatusForOtherHalf,
                        shift = model.Shift,
                        late_entry = model.LateEntry ? 1 : 0,
                        early_exit = model.EarlyExit ? 1 : 0,
                        docstatus = 0
                    };

                    await _erpNextService.PutAsync(
                        $"/api/resource/Attendance/{Uri.EscapeDataString(existing.ErpNextId)}",
                        payload
                    );

                    model.ErpNextId = existing.ErpNextId;
                    model.AttendanceCode = existing.AttendanceCode;
                    model.DocStatus = 0;

                    service.UpdateAttendance(model);

                    TempData["Success"] = "Attendance saved successfully.";
                    return RedirectToAction("AttendanceDetails", new { id = model.Id });
                }

                if (actionCommand == "Submit")
                {
                    if (string.IsNullOrWhiteSpace(existing.ErpNextId))
                    {
                        TempData["ErpNextError"] = "Submit failed: ERPNext ID is missing.";
                        return RedirectToAction("AttendanceDetails", new { id = model.Id });
                    }

                    var payload = new
                    {
                        employee = model.Employee,
                        employee_name = model.EmployeeName,
                        company = model.Company,
                        attendance_date = model.AttendanceDate.ToString("yyyy-MM-dd"),
                        status = model.Status,
                        leave_type = model.LeaveType,
                        status_for_other_half = model.StatusForOtherHalf,
                        shift = model.Shift,
                        late_entry = model.LateEntry ? 1 : 0,
                        early_exit = model.EarlyExit ? 1 : 0,
                        docstatus = 0
                    };

                    await _erpNextService.PutAsync(
                        $"/api/resource/Attendance/{Uri.EscapeDataString(existing.ErpNextId)}",
                        payload
                    );

                    var latestDocResponse = await _erpNextService.GetAsync(
                        $"/api/resource/Attendance/{Uri.EscapeDataString(existing.ErpNextId)}"
                    );

                    var latestDocJson = Newtonsoft.Json.Linq.JObject.Parse(latestDocResponse);
                    var latestDoc = latestDocJson["data"];

                    if (latestDoc == null)
                    {
                        TempData["ErpNextError"] = "Submit failed: ERPNext Attendance document not found.";
                        return RedirectToAction("AttendanceDetails", new { id = model.Id });
                    }

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new
                    {
                        doc = latestDoc
                    });

                    model.ErpNextId = existing.ErpNextId;
                    model.AttendanceCode = existing.AttendanceCode;
                    model.DocStatus = 1;

                    service.UpdateAttendance(model);

                    TempData["Success"] = "Attendance submitted successfully.";
                    return RedirectToAction("AttendanceDetails", new { id = model.Id });
                }

                if (actionCommand == "Cancel")
                {
                    if (existing.DocStatus != 1)
                    {
                        TempData["ErpNextError"] = "Only submitted Attendance can be cancelled.";
                        return RedirectToAction("AttendanceDetails", new { id = model.Id });
                    }

                    if (string.IsNullOrWhiteSpace(existing.ErpNextId))
                    {
                        TempData["ErpNextError"] = "Cancel failed: ERPNext ID is missing.";
                        return RedirectToAction("AttendanceDetails", new { id = model.Id });
                    }

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                    {
                        doctype = "Attendance",
                        name = existing.ErpNextId
                    });

                    service.UpdateDocStatus(model.Id, 2);

                    TempData["Success"] = "Attendance cancelled successfully.";
                    return RedirectToAction("AttendanceDetails", new { id = model.Id });
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Action failed: " + CleanErpNextError(ex);
            }

            return RedirectToAction("AttendanceDetails", new { id = model.Id });
        }


        private async Task PullAttendanceFromErpNext()
        {
            var service = new AttendanceService(_connectionString);
            var erpCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            int limitStart = 0;
            int pageLength = 500;

            while (true)
            {
                var fields = Uri.EscapeDataString("[\"name\",\"employee\",\"employee_name\",\"company\",\"attendance_date\",\"status\",\"shift\",\"late_entry\",\"early_exit\",\"docstatus\"]");

                string url =
                    "/api/resource/Attendance" +
                    "?fields=" + fields +
                    "&limit_page_length=" + pageLength +
                    "&limit_start=" + limitStart;

                var response = await _erpNextService.GetAsync(url);
                var parsed = Newtonsoft.Json.Linq.JObject.Parse(response);
                var dataList = parsed["data"] as Newtonsoft.Json.Linq.JArray;

                if (dataList == null || dataList.Count == 0)
                    break;

                foreach (var item in dataList)
                {
                    string erpId = item["name"]?.ToString();
                    string emp = item["employee"]?.ToString();

                    if (string.IsNullOrWhiteSpace(erpId) || string.IsNullOrWhiteSpace(emp))
                        continue;

                    erpId = erpId.Trim();
                    erpCodes.Add(erpId);

                    DateTime attendanceDate = DateTime.Today;
                    if (DateTime.TryParse(item["attendance_date"]?.ToString(), out DateTime parsedDate))
                        attendanceDate = parsedDate;

                    var attendance = new Attendance
                    {
                        AttendanceCode = erpId,
                        ErpNextId = erpId,
                        Employee = emp,
                        EmployeeName = item["employee_name"]?.ToString() ?? "",
                        Company = item["company"]?.ToString() ?? "",
                        AttendanceDate = attendanceDate,
                        Status = item["status"]?.ToString() ?? "Present",
                        Shift = item["shift"]?.ToString() ?? "",
                        LateEntry = item["late_entry"]?.ToString() == "1",
                        EarlyExit = item["early_exit"]?.ToString() == "1",
                        DocStatus = int.TryParse(item["docstatus"]?.ToString(), out int ds) ? ds : 0
                    };

                    if (service.ExistsByErpNextId(erpId))
                    {
                        var existing = service.GetByErpNextId(erpId);
                        attendance.Id = existing.Id;
                        service.UpdateAttendance(attendance);
                    }
                    else
                    {
                        service.InsertAttendance(attendance);
                    }
                }

                if (dataList.Count < pageLength)
                    break;

                limitStart += pageLength;
            }

            service.MarkDeletedIfMissingFromErpNext(erpCodes);
        }

























        [HttpGet]
        [Route("HR/AmendAttendance/{id:int}")]
        public async Task<ActionResult> AmendAttendance(int id)
        {
            var service = new AttendanceService(_connectionString);
            var record = service.GetById(id);

            if (record == null) return NotFound();

            if (record.DocStatus != 2)
            {
                TempData["ErpNextError"] = "Only cancelled Attendance can be amended.";
                return RedirectToAction("AttendanceDetails", new { id });
            }

            try
            {
                var amendedPayload = new
                {
                    employee = record.Employee,
                    employee_name = record.EmployeeName,
                    company = record.Company,
                    attendance_date = record.AttendanceDate.ToString("yyyy-MM-dd"),
                    status = record.Status,
                    shift = record.Shift,
                    late_entry = record.LateEntry ? 1 : 0,
                    early_exit = record.EarlyExit ? 1 : 0,
                    amended_from = record.ErpNextId,
                    docstatus = 0
                };

                var response = await _erpNextService.PostAsync("/api/resource/Attendance", amendedPayload);
                dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);
                string newErpId = parsed?.data?.name?.ToString();

                if (string.IsNullOrWhiteSpace(newErpId))
                {
                    TempData["ErpNextError"] = "ERPNext did not return amended Attendance ID.";
                    return RedirectToAction("AttendanceDetails", new { id });
                }

                var amendedLocal = new Attendance
                {
                    AttendanceCode = newErpId,
                    ErpNextId = newErpId,
                    DocStatus = 0,
                    Employee = record.Employee,
                    EmployeeName = record.EmployeeName,
                    Company = record.Company,
                    AttendanceDate = record.AttendanceDate,
                    Status = record.Status,
                    Shift = record.Shift,
                    LateEntry = record.LateEntry,
                    EarlyExit = record.EarlyExit
                };

                int newLocalId = service.InsertAttendance(amendedLocal);

                TempData["Success"] = "Amended Attendance draft created. Make changes and submit.";
                return RedirectToAction("AttendanceDetails", new { id = newLocalId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Amend failed: " + CleanErpNextError(ex);
                return RedirectToAction("AttendanceDetails", new { id });
            }
        }









        [HttpPost]
        [Route("HR/DeleteAttendance/{id:int}")]
        public async Task<ActionResult> DeleteAttendance(int id)
        {
            var service = new AttendanceService(_connectionString);
            var record = service.GetById(id);

            if (record == null)
            {
                TempData["ErpNextError"] = "Delete failed: Attendance not found.";
                return RedirectToAction("Attendance");
            }

            try
            {
                if (!string.IsNullOrWhiteSpace(record.ErpNextId))
                {
                    string erpId = Uri.EscapeDataString(record.ErpNextId);

                    try
                    {
                        await _erpNextService.DeleteAsync($"/api/resource/Attendance/{erpId}");
                    }
                    catch
                    {
                        await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                        {
                            doctype = "Attendance",
                            name = record.ErpNextId
                        });

                        await _erpNextService.DeleteAsync($"/api/resource/Attendance/{erpId}");
                    }
                }

                service.SoftDeleteById(id);
                TempData["Success"] = "Attendance deleted successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Delete failed: " + CleanErpNextError(ex);
            }

            return RedirectToAction("Attendance");
        }























