        [HttpGet]
        [Route("HR/AttendanceDetails/{id:int}")]
        public async Task<ActionResult> AttendanceDetails(int id, bool edit = false)
        {
            var service = new AttendanceService(_connectionString);

            try
            {
                await PullAttendanceFromErpNext();
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = CleanErpNextError(ex);
            }

            var record = service.GetById(id);
            if (record == null) return NotFound();

            await LoadDropdownsToViewBag();
            ViewBag.EditMode = edit && record.DocStatus == 0;

            return View("AttendanceDetails", record);
        }




        [HttpGet]
        public async Task<JsonResult> GetEmployeeName(string employeeId)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(employeeId))
                {
                    return Json(new
                    {
                        success = false,
                        employeeName = "",
                        company = ""
                    });
                }

                var response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee/" +
                        Uri.EscapeDataString(employeeId)
                    );

                var json =
                    JObject.Parse(response);

                var employee =
                    json["data"];

                if (employee == null)
                {
                    return Json(new
                    {
                        success = false,
                        employeeName = "",
                        company = ""
                    });
                }

                return Json(new
                {
                    success = true,

                    employeeName =
                        employee["employee_name"]?.ToString()
                        ?? "",

                    company =
                        employee["company"]?.ToString()
                        ?? ""
                });
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    success = false,
                    employeeName = "",
                    company = "",
                    message = ex.Message
                });
            }
        }
