        [HttpPost]
        public async Task<ActionResult> CreateAppraisal(
    Appraisal model,
    string[] KraNames,
    string[] KraWeightages,
    string[] KraGoalCompletions,
    string[] KraGoalScores,
    string[] RatingCriteria,
    string[] RatingWeightages,
    string[] RatingValues)
        {
            try
            {
                // ===============================================
                // BUILD CHILD ROWS FROM FORM
                // ===============================================

                model.Kras = new List<AppraisalKra>();
                model.SelfRatings = new List<AppraisalSelfRating>();

                if (KraNames != null)
                {
                    for (int i = 0; i < KraNames.Length; i++)
                    {
                        if (string.IsNullOrWhiteSpace(KraNames[i]))
                            continue;

                        decimal weightage = 0;
                        decimal completion = 0;
                        decimal score = 0;

                        if (KraWeightages != null &&
                            i < KraWeightages.Length)
                        {
                            decimal.TryParse(
                                KraWeightages[i],
                                out weightage
                            );
                        }

                        if (KraGoalCompletions != null &&
                            i < KraGoalCompletions.Length)
                        {
                            decimal.TryParse(
                                KraGoalCompletions[i],
                                out completion
                            );
                        }

                        if (KraGoalScores != null &&
                            i < KraGoalScores.Length)
                        {
                            decimal.TryParse(
                                KraGoalScores[i],
                                out score
                            );
                        }

                        model.Kras.Add(new AppraisalKra
                        {
                            Kra = KraNames[i],
                            Weightage = weightage,
                            GoalCompletion = completion,
                            GoalScore = score
                        });
                    }
                }

                if (RatingCriteria != null)
                {
                    for (int i = 0; i < RatingCriteria.Length; i++)
                    {
                        if (string.IsNullOrWhiteSpace(
                            RatingCriteria[i]))
                        {
                            continue;
                        }

                        decimal weightage = 0;
                        decimal rating = 0;

                        if (RatingWeightages != null &&
                            i < RatingWeightages.Length)
                        {
                            decimal.TryParse(
                                RatingWeightages[i],
                                out weightage
                            );
                        }

                        if (RatingValues != null &&
                            i < RatingValues.Length)
                        {
                            decimal.TryParse(
                                RatingValues[i],
                                out rating
                            );
                        }

                        model.SelfRatings.Add(
                            new AppraisalSelfRating
                            {
                                Criteria = RatingCriteria[i],
                                Weightage = weightage,
                                Rating = rating
                            }
                        );
                    }
                }

                // ===============================================
                // LOAD APPRAISAL CYCLE FROM ERP
                // This makes ERP the authority.
                // ===============================================

                if (string.IsNullOrWhiteSpace(model.Employee))
                    throw new Exception("Employee is required.");

                if (string.IsNullOrWhiteSpace(model.AppraisalCycle))
                    throw new Exception("Appraisal Cycle is required.");

                var cycleResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal%20Cycle/" +
                        Uri.EscapeDataString(model.AppraisalCycle)
                    );

                var cycleJson = JObject.Parse(cycleResponse);

                var cycle = cycleJson["data"];

                if (cycle == null)
                    throw new Exception(
                        "Unable to load Appraisal Cycle from ERPNext."
                    );

                model.StartDate =
                    cycle["start_date"]?.ToObject<DateTime?>();

                model.EndDate =
                    cycle["end_date"]?.ToObject<DateTime?>();

                string evaluationMethod =
                    cycle["kra_evaluation_method"]?.ToString();

                model.RateGoalsManually =
                    string.Equals(
                        evaluationMethod,
                        "Manual Rating",
                        StringComparison.OrdinalIgnoreCase
                    );

                // ===============================================
                // FIND EMPLOYEE TEMPLATE FROM APPRAISEES
                // Same concept used by ERPNext
                // ===============================================

                var appraisees = cycle["appraisees"] as JArray;

                if (appraisees != null)
                {
                    var employeeRow = appraisees
                        .FirstOrDefault(x =>
                            string.Equals(
                                x["employee"]?.ToString(),
                                model.Employee,
                                StringComparison.OrdinalIgnoreCase
                            )
                        );

                    if (employeeRow != null)
                    {
                        model.AppraisalTemplate =
                            employeeRow["appraisal_template"]
                                ?.ToString();
                    }
                }

                if (string.IsNullOrWhiteSpace(
                    model.AppraisalTemplate))
                {
                    throw new Exception(
                        "No Appraisal Template is assigned to this Employee in the selected Appraisal Cycle."
                    );
                }

                // ===============================================
                // CREATE ERP PAYLOAD
                // ===============================================

                var payload = new JObject
                {
                    ["doctype"] = "Appraisal",
                    ["employee"] = model.Employee,
                    ["company"] = model.Company,
                    ["appraisal_cycle"] = model.AppraisalCycle,
                    ["appraisal_template"] =
                        model.AppraisalTemplate,

                    ["rate_goals_manually"] =
                        model.RateGoalsManually ? 1 : 0,

                    ["remarks"] = model.Remarks ?? "",
                    ["reflections"] = model.Reflections ?? ""
                };

                // ===============================================
                // AUTOMATIC KRA MODE
                // ===============================================

                if (!model.RateGoalsManually)
                {
                    payload["appraisal_kra"] =
                        JArray.FromObject(
                            model.Kras.Select(k => new
                            {
                                kra = k.Kra,

                                // IMPORTANT:
                                // ERPNext uses per_weightage
                                per_weightage = k.Weightage
                            })
                        );
                }
                else
                {
                    // ===========================================
                    // MANUAL GOAL RATING MODE
                    // ERPNext uses "goals", not appraisal_kra
                    // ===========================================

                    //payload["goals"] =
                    //    JArray.FromObject(
                    //        model.Kras.Select(k => new
                    //        {
                    //            kra = k.Kra,
                    //            per_weightage = k.Weightage,
                    //            score = k.GoalScore ?? 0
                    //        })
                    //    );
                    payload["goals"] =
    JArray.FromObject(
        model.Kras.Select(k => new
        {
            kra = k.Kra,
            per_weightage = k.Weightage,
            score = k.GoalScore
        })
    );
                }

                // ===============================================
                // SELF RATINGS
                // ===============================================

                payload["self_ratings"] =
                    JArray.FromObject(
                        model.SelfRatings.Select(r => new
                        {
                            criteria = r.Criteria,
                            per_weightage = r.Weightage,
                            rating = r.Rating
                        })
                    );

                // ===============================================
                // ERP FIRST
                //
                // ERP validation happens here:
                // - active employee
                // - active appraisal cycle
                // - duplicate appraisal
                // - overlapping period
                // - KRA weightage
                // - Self Rating weightage
                // - scoring calculations
                // ===============================================

                var createResponse =
                    await _erpNextService.PostAsync(
                        "/api/resource/Appraisal",
                        payload.ToString()
                    );

                var createdJson =
                    JObject.Parse(createResponse);

                string erpName =
                    createdJson["data"]?["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpName))
                {
                    throw new Exception(
                        "ERPNext created no Appraisal document name."
                    );
                }

                // ===============================================
                // READ ERP DOCUMENT BACK
                //
                // Never trust locally calculated scores.
                // ===============================================

                var fullResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal/" +
                        Uri.EscapeDataString(erpName)
                    );

                var fullJson = JObject.Parse(fullResponse);

                var doc = fullJson["data"];

                if (doc == null)
                    throw new Exception(
                        "Unable to reload created Appraisal from ERPNext."
                    );

                var localAppraisal =
                    MapErpAppraisal(doc);

                // ===============================================
                // SAVE LOCAL COPY ONLY AFTER ERP SUCCESS
                // ===============================================

                int localId =
                    _appraisalService.InsertOrUpdate(
                        localAppraisal
                    );

                TempData["Success"] =
                    "Appraisal " +
                    erpName +
                    " created successfully.";

                return RedirectToAction(
                    "AppraisalDetails",
                    new { id = localId }
                );
            }
            catch (Exception ex)
            {
                string title = "ERPNext Validation";
                string cleanMessage = ex.Message;

                try
                {
                    string raw = ex.Message;

                    int jsonStart = raw.IndexOf('{');

                    if (jsonStart >= 0)
                    {
                        string jsonPart =
                            raw.Substring(jsonStart);

                        var errorJson =
                            JObject.Parse(jsonPart);

                        // ==========================================
                        // ERPNext/Frappe server messages
                        // ==========================================

                        var serverMessagesToken =
                            errorJson["_server_messages"];

                        if (serverMessagesToken != null)
                        {
                            string serverMessagesText =
                                serverMessagesToken.ToString();

                            var messagesArray =
                                JArray.Parse(serverMessagesText);

                            if (messagesArray.Count > 0)
                            {
                                string firstMessageJson =
                                    messagesArray[0]?.ToString();

                                if (!string.IsNullOrWhiteSpace(
                                    firstMessageJson))
                                {
                                    var messageObject =
                                        JObject.Parse(
                                            firstMessageJson
                                        );

                                    title =
                                        messageObject["title"]
                                            ?.ToString()
                                        ?? title;

                                    cleanMessage =
                                        messageObject["message"]
                                            ?.ToString()
                                        ?? cleanMessage;
                                }
                            }
                        }
                        else
                        {
                            // Fallback to exception text
                            cleanMessage =
                                errorJson["exception"]
                                    ?.ToString()
                                ?? cleanMessage;
                        }
                    }
                }
                catch
                {
                    // If ERP response parsing fails,
                    // show a short fallback message instead
                    cleanMessage = ex.Message;
                }

                // Remove HTML tags such as:
                // <a href="...">...</a>
                // <strong>...</strong>
                cleanMessage =
                    System.Text.RegularExpressions.Regex.Replace(
                        cleanMessage ?? "",
                        "<.*?>",
                        ""
                    );

                cleanMessage =
                    System.Net.WebUtility.HtmlDecode(
                        cleanMessage
                    );

                TempData["ErpNextErrorTitle"] =
                    title;

                TempData["ErpNextError"] =
                    cleanMessage;

                return RedirectToAction(
                    "CreateAppraisal"
                );
            }
        }


        private Appraisal MapErpAppraisal(JToken doc)
        {
            var appraisal = new Appraisal
            {
                ErpNextId =
                    doc["name"]?.ToString() ?? "",

                Employee =
                    doc["employee"]?.ToString() ?? "",

                EmployeeName =
                    doc["employee_name"]?.ToString() ?? "",

                Company =
                    doc["company"]?.ToString() ?? "",

                AppraisalCycle =
                    doc["appraisal_cycle"]?.ToString() ?? "",

                AppraisalTemplate =
                    doc["appraisal_template"]?.ToString() ?? "",

                RateGoalsManually =
                    doc["rate_goals_manually"]
                        ?.ToObject<int>() == 1,

                StartDate =
                    doc["start_date"]
                        ?.ToObject<DateTime?>(),

                EndDate =
                    doc["end_date"]
                        ?.ToObject<DateTime?>(),

                TotalScore =
                    doc["total_score"]
                        ?.ToObject<decimal>() ?? 0m,

                FinalScore =
                    doc["final_score"]
                        ?.ToObject<decimal>() ?? 0m,

                GoalScorePercentage =
                    doc["goal_score_percentage"]
                        ?.ToObject<decimal>() ?? 0m,

                // ERP field is self_score
                TotalSelfScore =
                    doc["self_score"]
                        ?.ToObject<decimal>() ?? 0m,

                AvgFeedbackScore =
                    doc["avg_feedback_score"]
                        ?.ToObject<decimal>() ?? 0m,

                Remarks =
                    doc["remarks"]?.ToString() ?? "",

                Reflections =
                    doc["reflections"]?.ToString() ?? "",

                DocStatus =
                    doc["docstatus"]
                        ?.ToObject<int>() ?? 0,

                AmendedFrom =
                    doc["amended_from"]?.ToString() ?? "",

                ErpModified =
                    doc["modified"]
                        ?.ToObject<DateTime?>()
            };

            // ============================================
            // ERP APPRAISAL KRA
            // ============================================

            var kraArray =
                doc["appraisal_kra"] as JArray;

            if (kraArray != null)
            {
                foreach (var k in kraArray)
                {
                    appraisal.Kras.Add(
                        new AppraisalKra
                        {
                            Kra =
                                k["kra"]?.ToString() ?? "",

                            // IMPORTANT:
                            // per_weightage, not weightage
                            Weightage =
                                k["per_weightage"]
                                    ?.ToObject<decimal>()
                                ?? 0m,

                            GoalCompletion =
                                k["goal_completion"]
                                    ?.ToObject<decimal>()
                                ?? 0m,

                            GoalScore =
                                k["goal_score"]
                                    ?.ToObject<decimal>()
                                ?? 0m
                        }
                    );
                }
            }

            // ============================================
            // ERP SELF RATINGS
            // ============================================

            var ratingArray =
                doc["self_ratings"] as JArray;

            if (ratingArray != null)
            {
                foreach (var r in ratingArray)
                {
                    appraisal.SelfRatings.Add(
                        new AppraisalSelfRating
                        {
                            Criteria =
                                r["criteria"]?.ToString()
                                ?? "",

                            Weightage =
                                r["per_weightage"]
                                    ?.ToObject<decimal>()
                                ?? 0m,

                            Rating =
                                r["rating"]
                                    ?.ToObject<decimal>()
                                ?? 0m
                        }
                    );
                }
            }

            return appraisal;
        }

        private async Task PullAppraisalsFromErpNext()
        {
            var listResponse =
                await _erpNextService.GetAsync(
                    "/api/resource/Appraisal" +
                    "?fields=[\"name\"]" +
                    "&limit_page_length=1000"
                );

            var dataArray =
                JObject.Parse(listResponse)["data"] as JArray;

            if (dataArray == null)
                return;

            var erpNames =
                new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase
                );

            foreach (var item in dataArray)
            {
                string erpName =
                    item["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpName))
                    continue;

                erpNames.Add(erpName);

                var response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal/" +
                        Uri.EscapeDataString(erpName)
                    );

                var doc =
                    JObject.Parse(response)["data"];

                if (doc == null)
                    continue;

                _appraisalService.InsertOrUpdate(
                    MapErpAppraisal(doc)
                );
            }
        }

        private void BindAppraisalChildRows(
            Appraisal model,
            string[] KraNames,
            string[] KraWeightages,
            string[] KraGoalCompletions,
            string[] KraGoalScores,
            string[] RatingCriteria,
            string[] RatingWeightages,
            string[] RatingValues)
        {
            model.Kras = new List<AppraisalKra>();
            model.SelfRatings = new List<AppraisalSelfRating>();

            if (KraNames != null)
            {
                for (int i = 0; i < KraNames.Length; i++)
                {
                    if (string.IsNullOrWhiteSpace(KraNames[i]))
                        continue;

                    decimal.TryParse(KraWeightages != null && i < KraWeightages.Length ? KraWeightages[i] : null, out var weightage);
                    decimal.TryParse(KraGoalCompletions != null && i < KraGoalCompletions.Length ? KraGoalCompletions[i] : null, out var completion);
                    decimal.TryParse(KraGoalScores != null && i < KraGoalScores.Length ? KraGoalScores[i] : null, out var score);

                    model.Kras.Add(new AppraisalKra
                    {
                        Kra = KraNames[i],
                        Weightage = weightage,
                        GoalCompletion = completion,
                        GoalScore = score
                    });
                }
            }

            if (RatingCriteria != null)
            {
                for (int i = 0; i < RatingCriteria.Length; i++)
                {
                    if (string.IsNullOrWhiteSpace(RatingCriteria[i]))
                        continue;

                    decimal.TryParse(RatingWeightages != null && i < RatingWeightages.Length ? RatingWeightages[i] : null, out var weightage);
                    decimal.TryParse(RatingValues != null && i < RatingValues.Length ? RatingValues[i] : null, out var rating);

                    model.SelfRatings.Add(new AppraisalSelfRating
                    {
                        Criteria = RatingCriteria[i],
                        Weightage = weightage,
                        Rating = rating
                    });
                }
            }
        }

        private JObject BuildAppraisalPayload(Appraisal model)
        {
            var payload = new JObject
            {
                ["doctype"] = "Appraisal",
                ["employee"] = model.Employee,
                ["company"] = model.Company,
                ["appraisal_cycle"] = model.AppraisalCycle,
                ["appraisal_template"] = model.AppraisalTemplate,
                ["rate_goals_manually"] = model.RateGoalsManually ? 1 : 0,
                ["remarks"] = model.Remarks ?? "",
                ["reflections"] = model.Reflections ?? ""
            };

            if (!model.RateGoalsManually)
            {
                payload["appraisal_kra"] =
                    JArray.FromObject(
                        model.Kras.Select(k => new
                        {
                            kra = k.Kra,
                            per_weightage = k.Weightage
                        })
                    );
            }
            else
            {
                payload["goals"] =
                    JArray.FromObject(
                        model.Kras.Select(k => new
                        {
                            kra = k.Kra,
                            per_weightage = k.Weightage,
                            score = k.GoalScore
                        })
                    );
            }

            payload["self_ratings"] =
                JArray.FromObject(
                    model.SelfRatings.Select(r => new
                    {
                        criteria = r.Criteria,
                        per_weightage = r.Weightage,
                        rating = r.Rating
                    })
                );

            return payload;
        }





        [HttpGet]
        public async Task<JsonResult>
            GetAppraisalTemplateDetails(
                string templateName)
        {
            try
            {
                // ==========================================================
                // VALIDATION
                // ==========================================================

                if (string.IsNullOrWhiteSpace(
                    templateName))
                {
                    return Json(
                        new
                        {
                            success = false,
                            message =
                                "Appraisal Template is required."
                        }
                    );
                }


                // ==========================================================
                // GET APPRAISAL TEMPLATE FROM ERPNext
                // ==========================================================

                string url =
                    "/api/resource/Appraisal%20Template/" +
                    Uri.EscapeDataString(templateName);

                var response =
                    await _erpNextService.GetAsync(url);

                var json =
                    Newtonsoft.Json.Linq.JObject.Parse(
                        response
                    );

                var doc =
                    json["data"];


                if (doc == null)
                {
                    return Json(
                        new
                        {
                            success = false,
                            message =
                                "Appraisal Template was not found in ERPNext."
                        }
                    );
                }


                var kras =
                    new List<object>();

                var criteria =
                    new List<object>();


                // ==========================================================
                // LOAD KRAs
                //
                // ERPNext Appraisal Template:
                //
                // goals[]
                //      key_result_area
                //      per_weightage
                // ==========================================================

                var goalArray =
                    doc["goals"]
                    as Newtonsoft.Json.Linq.JArray;


                if (goalArray != null)
                {
                    foreach (var row in goalArray)
                    {
                        string kraName =
                            row["key_result_area"]
                                ?.ToString()
                            ?? "";


                        decimal weightage =
                            row["per_weightage"]
                                ?.ToObject<decimal>()
                            ?? 0m;


                        if (!string.IsNullOrWhiteSpace(
                            kraName))
                        {
                            kras.Add(
                                new
                                {
                                    kra =
                                        kraName,

                                    weightage =
                                        weightage
                                }
                            );
                        }
                    }
                }


                // ==========================================================
                // LOAD SELF APPRAISAL RATING CRITERIA
                //
                // ERPNext:
                //
                // rating_criteria[]
                //      criteria
                //      per_weightage
                // ==========================================================

                var ratingCriteriaArray =
                    doc["rating_criteria"]
                    as Newtonsoft.Json.Linq.JArray;


                if (ratingCriteriaArray != null)
                {
                    foreach (
                        var row
                        in ratingCriteriaArray)
                    {
                        string criteriaName =
                            row["criteria"]
                                ?.ToString()
                            ?? "";


                        decimal weightage =
                            row["per_weightage"]
                                ?.ToObject<decimal>()
                            ?? 0m;


                        if (!string.IsNullOrWhiteSpace(
                            criteriaName))
                        {
                            criteria.Add(
                                new
                                {
                                    criteria =
                                        criteriaName,

                                    weightage =
                                        weightage
                                }
                            );
                        }
                    }
                }


                // ==========================================================
                // RETURN TO CreateAppraisal.cshtml
                // ==========================================================

                return Json(
                    new
                    {
                        success = true,

                        template =
                            templateName,

                        kras =
                            kras,

                        criteria =
                            criteria
                    }
                );
            }
            catch (Exception ex)
            {
                return Json(
                    new
                    {
                        success = false,

                        message =
                            ex.Message
                    }
                );
            }
        }


        [HttpGet]
        public async Task<JsonResult> GetMasterKras()
        {
            var kraList = new List<object>();
            try
            {
                // Fetching from ERPNext KRA DocType
                var response = await _erpNextService.GetAsync("/api/resource/KRA?fields=[\"name\"]&limit_page_length=500");
                var json = Newtonsoft.Json.Linq.JObject.Parse(response);
                if (json["data"] is Newtonsoft.Json.Linq.JArray array)
                {
                    foreach (var item in array)
                    {
                        kraList.Add(new { name = item["name"]?.ToString() });
                    }
                }
            }
            catch (Exception)
            {
                // Fallback or empty handle
            }
            return Json(kraList);
        }










