            }
            return Json(criteriaList);
        }














        [HttpPost]
        public async Task<ActionResult> SyncAppraisalFromErpNext(int id, string erpNextId)
        {
            if (string.IsNullOrEmpty(erpNextId))
            {
                TempData["ErpNextError"] = "No linked ERPNext ID found for this appraisal.";
                return RedirectToAction("AppraisalDetails", new { id });
            }

            try
            {
                var response = await _erpNextService.GetAsync($"/api/resource/Appraisal/{Uri.EscapeDataString(erpNextId)}");
                var jsonResponse = Newtonsoft.Json.Linq.JObject.Parse(response);
                var data = jsonResponse["data"];

                if (data != null)
                {
                    var service = new AppraisalService(_connectionString);
                    var appraisal = service.GetById(id);
                    if (appraisal != null)
                    {
                        appraisal.Employee = data["employee"]?.ToString();
                        appraisal.EmployeeName = data["employee_name"]?.ToString();
                        appraisal.Company = data["company"]?.ToString();
                        appraisal.AppraisalCycle = data["appraisal_cycle"]?.ToString();
                        appraisal.AppraisalTemplate = data["appraisal_template"]?.ToString();

                        // Update local database with pulled ERPNext data
                        // (You can add an update method in AppraisalService to commit these fields)
                    }
                }
                TempData["Success"] = "Successfully synchronized with ERPNext!";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Synchronization failed: " + ex.Message;
            }

            return RedirectToAction("AppraisalDetails", new { id });
        }



