        [HttpGet]
        public async Task<JsonResult> GetActiveEmployees()
        {
            var employees = new List<object>();
            using (var conn = new SqlConnection(_connectionString))
            {
                conn.Open();
                using (var cmd = new SqlCommand("SELECT EmployeeId, EmployeeName FROM Employees WHERE IsActive = 1", conn))
                {
                    using (var reader = cmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            employees.Add(new { id = reader["EmployeeId"].ToString(), name = reader["EmployeeName"].ToString() });
                        }
                    }
                }
            }
            return Json(employees); // Removed JsonRequestBehavior for modern compatibility
        }

        [HttpGet]
        public async Task<JsonResult> GetAppraisalCycles()
        {
            var cycles = new List<string>();
            var response = await _erpNextService.GetAsync("/api/resource/Appraisal Cycle?fields=[\"name\"]");
            var json = Newtonsoft.Json.Linq.JObject.Parse(response);
            foreach (var item in json["data"])
            {
                cycles.Add(item["name"]?.ToString());
            }
            return Json(cycles); // Removed JsonRequestBehavior
        }




