        [HttpPost]
        public async Task<ActionResult> UpdateAppraisal(
            Appraisal model,
            string[] KraNames,
            string[] KraWeightages,
            string[] KraGoalCompletions,
            string[] KraGoalScores,
            string[] RatingCriteria,
            string[] RatingWeightages,
            string[] RatingValues)
        {
            var existing =
                _appraisalService.GetById(model.Id);

            if (existing == null)
                return NotFound();

            if (existing.DocStatus != 0)
            {
                TempData["ErpNextError"] =
                    "Submitted or cancelled Appraisal cannot be edited.";

                return RedirectToAction(
                    "AppraisalDetails",
                    new { id = model.Id }
                );
            }

            if (string.IsNullOrWhiteSpace(existing.ErpNextId))
            {
                TempData["ErpNextError"] =
                    "ERPNext Appraisal ID is missing.";

                return RedirectToAction(
                    "AppraisalDetails",
                    new { id = model.Id }
                );
            }

            try
            {
                model.ErpNextId = existing.ErpNextId;
                model.DocStatus = 0;
                model.RateGoalsManually = existing.RateGoalsManually;
                model.StartDate = existing.StartDate;
                model.EndDate = existing.EndDate;
                model.EmployeeName = string.IsNullOrWhiteSpace(model.EmployeeName)
                    ? existing.EmployeeName
                    : model.EmployeeName;

                BindAppraisalChildRows(
                    model,
                    KraNames,
                    KraWeightages,
                    KraGoalCompletions,
                    KraGoalScores,
                    RatingCriteria,
                    RatingWeightages,
                    RatingValues
                );

                var payload =
                    BuildAppraisalPayload(model);

                await _erpNextService.PutAsync(
                    "/api/resource/Appraisal/" +
                    Uri.EscapeDataString(existing.ErpNextId),
                    payload
                );

                var response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal/" +
                        Uri.EscapeDataString(existing.ErpNextId)
                    );

                var updated =
                    MapErpAppraisal(
                        JObject.Parse(response)["data"]
                    );

                updated.Id = existing.Id;

                int localId =
                    _appraisalService.InsertOrUpdate(updated);

                TempData["Success"] =
                    "Appraisal saved successfully.";

                return RedirectToAction(
                    "AppraisalDetails",
                    new { id = localId }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Save failed: " +
                    ExtractErpNextErrorMessage(ex.Message);

                return RedirectToAction(
                    "AppraisalDetails",
                    new { id = model.Id }
                );
            }
        }


        [HttpPost]
        public async Task<ActionResult>
    SyncAllAppraisalsFromErpNext()
        {
            try
            {
                var listResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=1000"
                    );

                var listJson =
                    JObject.Parse(listResponse);

                var dataArray =
                    listJson["data"] as JArray;

                int synced = 0;

                if (dataArray != null)
                {
                    foreach (var item in dataArray)
                    {
                        string erpName =
                            item["name"]?.ToString();

                        if (string.IsNullOrWhiteSpace(
                            erpName))
                        {
                            continue;
                        }

                        var response =
                            await _erpNextService.GetAsync(
                                "/api/resource/Appraisal/" +
                                Uri.EscapeDataString(erpName)
                            );

                        var json =
                            JObject.Parse(response);

                        var doc = json["data"];

                        if (doc == null)
                            continue;

                        Appraisal appraisal =
                            MapErpAppraisal(doc);

                        _appraisalService
                            .InsertOrUpdate(appraisal);

                        synced++;
                    }
                }

                TempData["Success"] =
                    synced +
                    " Appraisal(s) synchronized from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext synchronization failed: " +
                    ex.Message;
            }

            return RedirectToAction("Appraisal");
        }


        [HttpPost]
        public async Task<ActionResult>
    CancelAppraisal(int id)
        {
            var local =
                _appraisalService.GetById(id);

            if (local == null)
                return NotFound();

            if (string.IsNullOrWhiteSpace(
                local.ErpNextId))
            {
                TempData["ErpNextError"] =
                    "ERPNext Appraisal ID is missing.";

                return RedirectToAction(
                    "AppraisalDetails",
                    new { id }
                );
            }

            try
            {
                var payload = new JObject
                {
                    ["doctype"] = "Appraisal",
                    ["name"] = local.ErpNextId
                };

                await _erpNextService.PostMethodAsync(
                    "/api/method/frappe.client.cancel",
                    payload
                );

                var response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal/" +
                        Uri.EscapeDataString(
                            local.ErpNextId
                        )
                    );

                var json =
                    JObject.Parse(response);

                var updated =
                    MapErpAppraisal(json["data"]);

                _appraisalService
                    .InsertOrUpdate(updated);

                TempData["Success"] =
                    "Appraisal cancelled successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Cancel failed: " + ex.Message;
            }

            return RedirectToAction(
                "AppraisalDetails",
                new { id }
            );
        }


        [HttpPost]
        public async Task<ActionResult>
    SubmitAppraisal(int id)
        {
            var local =
                _appraisalService.GetById(id);

            if (local == null)
                return NotFound();

            if (string.IsNullOrWhiteSpace(
                local.ErpNextId))
            {
                TempData["ErpNextError"] =
                    "ERPNext Appraisal ID is missing.";

                return RedirectToAction(
                    "AppraisalDetails",
                    new { id }
                );
            }

            try
            {
                var response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal/" +
                        Uri.EscapeDataString(
                            local.ErpNextId
                        )
                    );

                var json =
                    JObject.Parse(response);

                var doc = json["data"];

                var submitPayload =
                    new JObject
                    {
                        ["doc"] = doc
                    };

                await _erpNextService.PostMethodAsync(
                    "/api/method/frappe.client.submit",
                    submitPayload
                );

                // Reload final submitted document
                response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal/" +
                        Uri.EscapeDataString(
                            local.ErpNextId
                        )
                    );

                json = JObject.Parse(response);

                var updated =
                    MapErpAppraisal(json["data"]);

                _appraisalService
                    .InsertOrUpdate(updated);

                TempData["Success"] =
                    "Appraisal submitted successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Submit failed: " + ex.Message;
            }

            return RedirectToAction(
                "AppraisalDetails",
                new { id }
            );
        }








