        private async Task<int> PullPurposeOfTravelFromErpNext()
        {
            string listJson = await _erpNextService.GetAsync(
                "/api/resource/Purpose%20of%20Travel?fields=[\"name\",\"purpose_of_travel\"]&limit_page_length=1000"
            );

            dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(listJson);
            int synced = 0;
            var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (parsed?.data != null)
            {
                foreach (var row in parsed.data)
                {
                    string erpName = row.name?.ToString();
                    string purpose = row.purpose_of_travel?.ToString() ?? erpName;

                    if (string.IsNullOrWhiteSpace(erpName) || string.IsNullOrWhiteSpace(purpose))
                        continue;

                    erpIds.Add(erpName);

                    var model = new PurposeOfTravel
                    {
                        ErpNextId = erpName,
                        Purpose = purpose
                    };

                    _purposeOfTravelService.UpsertFromErpNext(model);
                    synced++;
                }
            }

            _purposeOfTravelService.MarkDeletedIfMissingFromErpNext(erpIds);
            return synced;
        }

        private async Task<PurposeOfTravel> RefreshPurposeOfTravelFromErpNextAsync(PurposeOfTravel model)
        {
            if (model == null || string.IsNullOrWhiteSpace(model.ErpNextId))
                return model;

            string json = await _erpNextService.GetAsync(
                "/api/resource/Purpose%20of%20Travel/" +
                Uri.EscapeDataString(model.ErpNextId)
            );

            JObject parsed = JObject.Parse(json);
            JToken data = parsed["data"];

            if (data == null)
                return model;

            var refreshed = new PurposeOfTravel
            {
                ErpNextId = data["name"]?.ToString() ?? model.ErpNextId,
                Purpose = data["purpose_of_travel"]?.ToString() ?? data["name"]?.ToString() ?? model.Purpose
            };

            int id = _purposeOfTravelService.UpsertFromErpNext(refreshed);
            return _purposeOfTravelService.GetById(id);
        }


        [HttpPost]
        public async Task<ActionResult> SyncPurposeOfTravelFromErpNext()
        {
            try
            {
                int synced = await PullPurposeOfTravelFromErpNext();

                TempData["Success"] = synced + " Purpose of Travel records synced from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "ERPNext to HRMS sync failed: " + ex.Message;
            }

            return RedirectToAction("PurposeOfTravel");
        }



