        [HttpPost]
        public async Task<ActionResult> CreatePurposeOfTravel(PurposeOfTravel model)
        {
            int newId = _purposeOfTravelService.Insert(model);

            try
            {
                string erpNextId = await PushPurposeOfTravelToErpNext(_purposeOfTravelService.GetById(newId));

                if (!string.IsNullOrWhiteSpace(erpNextId))
                    _purposeOfTravelService.UpdateErpNextId(newId, erpNextId);

                TempData["Success"] = "Purpose of Travel saved and synced to ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Saved in HRMS but ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("PurposeOfTravelDetails", new { id = newId });
        }



        public async Task<ActionResult> PurposeOfTravelDetails(int id)
        {
            var model = _purposeOfTravelService.GetById(id);

            if (model == null)
                return NotFound();

            try
            {
                model = await RefreshPurposeOfTravelFromErpNextAsync(model);
            }
            catch (Exception ex)
            {
                TempData["Error"] = "ERPNext refresh failed: " + ex.Message;
            }

            return View(model);
        }

        [HttpPost]
        [Route("HR/UpdatePurposeOfTravel")]
        public async Task<ActionResult> UpdatePurposeOfTravel(PurposeOfTravel model)
        {
            if (model == null || model.Id <= 0)
                return RedirectToAction("PurposeOfTravel");

            var existing = _purposeOfTravelService.GetById(model.Id);

            if (existing == null)
                return NotFound();

            try
            {
                if (string.IsNullOrWhiteSpace(model.Purpose))
                    throw new Exception("Purpose of Travel is required.");

                string erpId = string.IsNullOrWhiteSpace(existing.ErpNextId)
                    ? existing.Purpose
                    : existing.ErpNextId;

                await _erpNextService.PutAsync(
                    "/api/resource/Purpose%20of%20Travel/" + Uri.EscapeDataString(erpId),
                    new
                    {
                        purpose_of_travel = model.Purpose
                    }
                );

                var refreshed = new PurposeOfTravel
                {
                    Id = existing.Id,
                    ErpNextId = erpId,
                    Purpose = model.Purpose
                };

                _purposeOfTravelService.Update(refreshed);

                TempData["Success"] = "Purpose of Travel saved successfully.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Save failed: " + ex.Message;
            }

            return RedirectToAction("PurposeOfTravelDetails", new { id = model.Id });
        }

        [HttpPost]
        [Route("HR/DeletePurposeOfTravel")]
        public async Task<ActionResult> DeletePurposeOfTravel(int id)
        {
            var existing = _purposeOfTravelService.GetById(id);

            if (existing == null)
                return RedirectToAction("PurposeOfTravel");

            try
            {
                string erpId = string.IsNullOrWhiteSpace(existing.ErpNextId)
                    ? existing.Purpose
                    : existing.ErpNextId;

                if (!string.IsNullOrWhiteSpace(erpId))
                {
                    await _erpNextService.DeleteAsync(
                        "/api/resource/Purpose%20of%20Travel/" + Uri.EscapeDataString(erpId)
                    );
                }

                _purposeOfTravelService.SoftDeleteById(id);
                TempData["Success"] = "Purpose of Travel deleted successfully.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Delete failed: " + ex.Message;
            }

            return RedirectToAction("PurposeOfTravel");
        }

        private async Task<string> PushPurposeOfTravelToErpNext(PurposeOfTravel model)
        {
            if (model == null || string.IsNullOrWhiteSpace(model.Purpose))
                return string.Empty;

            var payload = new
            {
                purpose_of_travel = model.Purpose
            };

            try
            {
                await _erpNextService.GetAsync(
                    "/api/resource/Purpose%20of%20Travel/" + Uri.EscapeDataString(model.Purpose)
                );

                await _erpNextService.PutAsync(
                    "/api/resource/Purpose%20of%20Travel/" + Uri.EscapeDataString(model.Purpose),
                    payload
                );

                return model.Purpose;
            }
            catch
            {
                string createJson = await _erpNextService.PostAsync(
                    "/api/resource/Purpose%20of%20Travel",
                    payload
                );

                dynamic created = Newtonsoft.Json.JsonConvert.DeserializeObject(createJson);
                return created?.data?.name?.ToString() ?? model.Purpose;
            }
        }





