        private async Task<(int total, int inserted, int updated)>
            PullExpenseClaimTypesFromErpNext()
        {
            string listJson =
                await _erpNextService.GetAsync(
                    "/api/resource/Expense%20Claim%20Type" +
                    "?fields=[\"name\"]" +
                    "&limit_page_length=5000"
                );

            JObject listObject =
                JObject.Parse(
                    listJson
                );

            JArray rows =
                listObject["data"]
                as JArray;

            int total = 0;
            int inserted = 0;
            int updated = 0;
            var erpIds =
                new HashSet<string>(
                    StringComparer.OrdinalIgnoreCase
                );

            if (rows != null)
            {
                foreach (JToken row in rows)
                {
                    string erpNextId =
                        row["name"]
                            ?.ToString();

                    if (string.IsNullOrWhiteSpace(
                        erpNextId))
                    {
                        continue;
                    }

                    erpIds.Add(
                        erpNextId
                    );

                    bool exists =
                        _expenseClaimTypeService
                            .GetByErpNextId(
                                erpNextId
                            )
                        != null;

                    string detailJson =
                        await _erpNextService.GetAsync(
                            "/api/resource/Expense%20Claim%20Type/" +
                            Uri.EscapeDataString(
                                erpNextId
                            )
                        );

                    JObject detailObject =
                        JObject.Parse(
                            detailJson
                        );

                    ExpenseClaimType model =
                        MapErpExpenseClaimType(
                            detailObject["data"]
                        );

                    if (model == null)
                    {
                        continue;
                    }

                    _expenseClaimTypeService
                        .InsertOrUpdate(
                            model
                        );

                    if (exists)
                    {
                        updated++;
                    }
                    else
                    {
                        inserted++;
                    }

                    total++;
                }
            }

            SoftDeleteMissingErpDocuments(
                "ExpenseClaimTypes",
                "ErpNextId",
                erpIds
            );

            return (total, inserted, updated);
        }

        private async Task<ExpenseClaimType>
            RefreshExpenseClaimTypeFromErpNextAsync(
                string erpNextId)
        {
            if (string.IsNullOrWhiteSpace(
                erpNextId))
            {
                return null;
            }

            string detailJson =
                await _erpNextService.GetAsync(
                    "/api/resource/Expense%20Claim%20Type/" +
                    Uri.EscapeDataString(
                        erpNextId
                    )
                );

            JObject detailObject =
                JObject.Parse(
                    detailJson
                );

            return MapErpExpenseClaimType(
                detailObject["data"]
            );
        }

        private Dictionary<string, object>
            BuildExpenseClaimTypePayload(
                ExpenseClaimType model)
        {
            var accountsPayload =
                new List<object>();

            if (model.Accounts != null)
            {
                var usedCompanies =
                    new HashSet<string>(
                        StringComparer.OrdinalIgnoreCase
                    );

                foreach (var row in model.Accounts)
                {
                    if (row == null)
                        continue;

                    bool completelyEmpty =
                        string.IsNullOrWhiteSpace(
                            row.Company
                        ) &&
                        string.IsNullOrWhiteSpace(
                            row.DefaultAccount
                        );

                    if (completelyEmpty)
                        continue;

                    if (string.IsNullOrWhiteSpace(
                        row.DefaultAccount))
                    {
                        throw new Exception(
                            "Default Account is required in Accounts table."
                        );
                    }

                    if (!string.IsNullOrWhiteSpace(
                        row.Company))
                    {
                        if (!usedCompanies.Add(
                            row.Company))
                        {
                            throw new Exception(
                                "Company "
                                + row.Company
                                + " is already present in Accounts table."
                            );
                        }
                    }

                    accountsPayload.Add(
                        new
                        {
                            company =
                                string.IsNullOrWhiteSpace(
                                    row.Company
                                )
                                    ? null
                                    : row.Company,

                            default_account =
                                row.DefaultAccount
                        }
                    );
                }
            }

            return new Dictionary<string, object>
            {
                ["expense_type"] =
                    model.Name?.Trim(),

                ["deferred_expense_account"] =
                    model.DeferredExpenseAccount
                        ? 1
                        : 0,

                ["accounts"] =
                    accountsPayload,

                ["description"] =
                    model.Description ?? ""
            };
        }

        [HttpPost]
        [Route("HR/SyncExpenseClaimTypesFromErpNext")]
        public async Task<ActionResult>
            SyncExpenseClaimTypesFromErpNext()
        {
            try
            {
                // ============================================================
                // 1. GET ALL ERP EXPENSE CLAIM TYPE IDS
                // ============================================================

                string listJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Expense%20Claim%20Type" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=5000"
                    );


                JObject listObject =
                    JObject.Parse(
                        listJson
                    );


                JArray rows =
                    listObject["data"]
                    as JArray;


                int inserted = 0;
                int updated = 0;
                int failed = 0;


                // ============================================================
                // 2. LOOP ERP DOCUMENTS
                // ============================================================

                if (rows != null)
                {
                    foreach (JToken row in rows)
                    {
                        try
                        {
                            string erpNextId =
                                row["name"]
                                    ?.ToString();


                            if (string.IsNullOrWhiteSpace(
                                erpNextId))
                            {
                                continue;
                            }


                            // Does it already exist locally?
                            bool exists =
                                _expenseClaimTypeService
                                    .GetByErpNextId(
                                        erpNextId
                                    )
                                != null;


                            // ====================================================
                            // GET COMPLETE ERP DOCUMENT
                            // Includes:
                            //
                            // expense_type
                            // deferred_expense_account
                            // description
                            // accounts
                            // ====================================================

                            string detailJson =
                                await _erpNextService.GetAsync(
                                    "/api/resource/Expense%20Claim%20Type/" +
                                    Uri.EscapeDataString(
                                        erpNextId
                                    )
                                );


                            JObject detailObject =
                                JObject.Parse(
                                    detailJson
                                );


                            JToken doc =
                                detailObject["data"];


                            if (doc == null)
                            {
                                failed++;
                                continue;
                            }


                            // ====================================================
                            // CORRECT ERP FIELD MAPPING IS DONE IN THIS MAPPER:
                            //
                            // deferred_expense_account
                            // ====================================================

                            ExpenseClaimType model =
                                MapErpExpenseClaimType(
                                    doc
                                );


                            if (model == null)
                            {
                                failed++;
                                continue;
                            }


                            // ====================================================
                            // INSERT OR UPDATE HRMS
                            // ====================================================

                            _expenseClaimTypeService
                                .InsertOrUpdate(
                                    model
                                );


                            if (exists)
                            {
                                updated++;
                            }
                            else
                            {
                                inserted++;
                            }
                        }
                        catch (Exception recordEx)
                        {
                            failed++;


                            System.Diagnostics.Debug.WriteLine(
                                "Expense Claim Type sync error: "
                                + recordEx.Message
                            );
                        }
                    }
                }


                TempData["Success"] =
                    "Expense Claim Type sync completed. "
                    + "New: "
                    + inserted
                    + ", Updated: "
                    + updated
                    + ", Failed: "
                    + failed
                    + ".";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Expense Claim Type sync failed: "
                    + CleanExpenseClaimTypeErpError(
                        ex.Message
                    );
            }


            return RedirectToAction(
                "ExpenseClaimType"
            );
        }





        [HttpPost]
        [Route("HR/CreateExpenseClaimType")]
        public async Task<ActionResult> CreateExpenseClaimType(
            ExpenseClaimType model)
        {
            try
            {
                // ============================================================
                // 1. REQUIRED VALIDATION
                // ============================================================

                if (string.IsNullOrWhiteSpace(model.Name))
                {
                    throw new Exception(
                        "Expense Claim Type is required."
                    );
                }

                model.Name = model.Name.Trim();


                // ============================================================
                // 2. BUILD ACCOUNTS CHILD TABLE
                // ============================================================

                var accountsPayload =
                    new List<object>();


                if (model.Accounts != null)
                {
                    var usedCompanies =
                        new HashSet<string>(
                            StringComparer.OrdinalIgnoreCase
                        );


                    foreach (var row in model.Accounts)
                    {
                        if (row == null)
                            continue;


                        bool completelyEmpty =
                            string.IsNullOrWhiteSpace(
                                row.Company
                            ) &&
                            string.IsNullOrWhiteSpace(
                                row.DefaultAccount
                            );


                        if (completelyEmpty)
                            continue;


                        // Default Account required
                        if (string.IsNullOrWhiteSpace(
                            row.DefaultAccount))
                        {
                            throw new Exception(
                                "Default Account is required in Accounts table."
                            );
                        }


                        // Prevent duplicate company rows
                        if (!string.IsNullOrWhiteSpace(
                            row.Company))
                        {
                            if (!usedCompanies.Add(
                                row.Company))
                            {
                                throw new Exception(
                                    "Company "
                                    + row.Company
                                    + " is already present in Accounts table."
                                );
                            }
                        }


                        // ====================================================
                        // VERIFY COMPANY EXISTS IN ERP
                        // ====================================================

                        if (!string.IsNullOrWhiteSpace(
                            row.Company))
                        {
                            await _erpNextService.GetAsync(
                                "/api/resource/Company/" +
                                Uri.EscapeDataString(
                                    row.Company
                                )
                            );
                        }


                        // ====================================================
                        // VERIFY ACCOUNT EXISTS IN ERP
                        // ====================================================

                        string accountResponse =
                            await _erpNextService.GetAsync(
                                "/api/resource/Account/" +
                                Uri.EscapeDataString(
                                    row.DefaultAccount
                                )
                            );


                        JObject accountObject =
                            JObject.Parse(
                                accountResponse
                            );


                        JToken accountDoc =
                            accountObject["data"];


                        if (accountDoc == null)
                        {
                            throw new Exception(
                                "Default Account "
                                + row.DefaultAccount
                                + " does not exist in ERPNext."
                            );
                        }


                        // Group account not allowed
                        bool isGroup =
                            (
                                accountDoc["is_group"]
                                    ?.ToObject<int>()
                                ?? 0
                            ) == 1;


                        if (isGroup)
                        {
                            throw new Exception(
                                "Default Account cannot be a Group Account."
                            );
                        }


                        // Disabled account not allowed
                        int disabled =
                            accountDoc["disabled"]
                                ?.ToObject<int>()
                            ?? 0;


                        if (disabled == 1)
                        {
                            throw new Exception(
                                "Default Account is disabled."
                            );
                        }


                        // Validate account company
                        string accountCompany =
                            accountDoc["company"]
                                ?.ToString()
                            ?? "";


                        if (
                            !string.IsNullOrWhiteSpace(
                                row.Company
                            ) &&
                            !string.IsNullOrWhiteSpace(
                                accountCompany
                            ) &&
                            !string.Equals(
                                row.Company,
                                accountCompany,
                                StringComparison.OrdinalIgnoreCase
                            )
                        )
                        {
                            throw new Exception(
                                "Default Account "
                                + row.DefaultAccount
                                + " belongs to Company "
                                + accountCompany
                                + ", not "
                                + row.Company
                                + "."
                            );
                        }


                        accountsPayload.Add(
                            new
                            {
                                company =
                                    string.IsNullOrWhiteSpace(
                                        row.Company
                                    )
                                        ? null
                                        : row.Company,

                                default_account =
                                    row.DefaultAccount
                            }
                        );
                    }
                }


                // ============================================================
                // 3. ERP PAYLOAD
                //
                // IMPORTANT CORRECT FIELD:
                //
                // deferred_expense_account
                //
                // NOT:
                // is_deferred_expense
                // ============================================================

                var payload =
                    new
                    {
                        expense_type =
                            model.Name,

                        deferred_expense_account =
                            model.DeferredExpenseAccount
                                ? 1
                                : 0,

                        accounts =
                            accountsPayload,

                        description =
                            model.Description ?? ""
                    };


                // ============================================================
                // 4. CREATE IN ERP FIRST
                // ============================================================

                string responseJson =
                    await _erpNextService.PostAsync(
                        "/api/resource/Expense%20Claim%20Type",
                        payload
                    );


                JObject response =
                    JObject.Parse(
                        responseJson
                    );


                string erpNextId =
                    response["data"]?["name"]
                        ?.ToString();


                if (string.IsNullOrWhiteSpace(
                    erpNextId))
                {
                    throw new Exception(
                        "ERPNext did not return Expense Claim Type ID."
                    );
                }


                // ============================================================
                // 5. READ FULL ERP DOCUMENT BACK
                // ============================================================

                string detailJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Expense%20Claim%20Type/" +
                        Uri.EscapeDataString(
                            erpNextId
                        )
                    );


                JObject detailObject =
                    JObject.Parse(
                        detailJson
                    );


                JToken doc =
                    detailObject["data"];


                if (doc == null)
                {
                    throw new Exception(
                        "Expense Claim Type was created in ERPNext but could not be reloaded."
                    );
                }


                // ============================================================
                // 6. MAP ERP RESPONSE
                //
                // CORRECT FIELD:
                // deferred_expense_account
                // ============================================================

                ExpenseClaimType localModel =
                    MapErpExpenseClaimType(
                        doc
                    );


                if (localModel == null)
                {
                    throw new Exception(
                        "Unable to map ERPNext Expense Claim Type."
                    );
                }


                // ============================================================
                // 7. SAVE / UPDATE LOCAL DB
                // ============================================================

                int localId =
                    _expenseClaimTypeService
                        .InsertOrUpdate(
                            localModel
                        );


                TempData["Success"] =
                    "Expense Claim Type created successfully. ERPNext Ref: "
                    + erpNextId;


                return RedirectToAction(
                    "ExpenseClaimTypeDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanExpenseClaimTypeErpError(
                        ex.Message
                    );


                return RedirectToAction(
                    "CreateExpenseClaimType"
                );
            }
        }
        private ExpenseClaimType
    MapErpExpenseClaimType(
        JToken doc)
        {
            if (doc == null)
                return null;


            var model =
                new ExpenseClaimType
                {
                    ErpNextId =
                        doc["name"]
                            ?.ToString()
                        ?? "",

                    Name =
                        doc["expense_type"]
                            ?.ToString()
                        ?? doc["name"]
                            ?.ToString()
                        ?? "",

                    DeferredExpenseAccount =
                        (
                            doc["deferred_expense_account"]
                                ?.ToObject<int>()
                            ?? 0
                        ) == 1,

                    Description =
                        doc["description"]
                            ?.ToString()
                        ?? "",

                    Accounts =
                        new List<ExpenseClaimTypeAccount>()
                };


            JArray accounts =
                doc["accounts"]
                as JArray;


            if (accounts != null)
            {
                foreach (
                    JToken row
                    in accounts)
                {
                    model.Accounts.Add(
                        new ExpenseClaimTypeAccount
                        {
                            Company =
                                row["company"]
                                    ?.ToString()
                                ?? "",

                            DefaultAccount =
                                row["default_account"]
                                    ?.ToString()
                                ?? ""
                        }
                    );
                }
            }


            return model;
        }











        // GET: HR/ExpenseClaimTypeDetails/{id}
        [HttpGet]
        [Route("HR/ExpenseClaimTypeDetails/{id}")]
        public async Task<ActionResult> ExpenseClaimTypeDetails(int id)
        {
            var model = _expenseClaimTypeService.GetById(id);
            if (model == null)
            {
                return NotFound();
            }

            try
            {
                if (!string.IsNullOrWhiteSpace(
                    model.ErpNextId))
                {
                    var refreshed =
                        await RefreshExpenseClaimTypeFromErpNextAsync(
                            model.ErpNextId
                        );

                    if (refreshed != null)
                    {
                        int refreshedId =
                            _expenseClaimTypeService
                                .InsertOrUpdate(
                                    refreshed
                                );

                        model =
                            _expenseClaimTypeService
                                .GetById(
                                    refreshedId
                                );
                    }
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext refresh failed: "
                    + CleanExpenseClaimTypeErpError(
                        ex.Message
                    );
            }

            await PopulateExpenseClaimTypeDropdownsAsync();

            return View("~/Views/HR/ExpenseClaimTypeDetails.cshtml", model);
        }

        [HttpPost]
        [Route("HR/UpdateExpenseClaimType")]
        public async Task<ActionResult> UpdateExpenseClaimType(
            int id,
            ExpenseClaimType model)
        {
            var existing =
                _expenseClaimTypeService.GetById(
                    id
                );

            if (existing == null)
            {
                return NotFound();
            }

            try
            {
                if (string.IsNullOrWhiteSpace(
                    model.Name))
                {
                    throw new Exception(
                        "Expense Claim Type is required."
                    );
                }

                string erpNextId =
                    string.IsNullOrWhiteSpace(
                        existing.ErpNextId
                    )
                        ? existing.Name
                        : existing.ErpNextId;

                await _erpNextService.PutAsync(
                    "/api/resource/Expense%20Claim%20Type/" +
                    Uri.EscapeDataString(
                        erpNextId
                    ),
                    BuildExpenseClaimTypePayload(
                        model
                    )
                );

                var refreshed =
                    await RefreshExpenseClaimTypeFromErpNextAsync(
                        erpNextId
                    );

                int localId =
                    refreshed == null
                        ? _expenseClaimTypeService
                            .InsertOrUpdate(
                                model
                            )
                        : _expenseClaimTypeService
                            .InsertOrUpdate(
                                refreshed
                            );

                TempData["Success"] =
                    "Expense Claim Type saved successfully.";

                return RedirectToAction(
                    "ExpenseClaimTypeDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanExpenseClaimTypeErpError(
                        ex.Message
                    );

                return RedirectToAction(
                    "ExpenseClaimTypeDetails",
                    new
                    {
                        id
                    }
                );
            }
        }

        [HttpPost]
        [Route("HR/DeleteExpenseClaimType")]
        public async Task<ActionResult> DeleteExpenseClaimType(
            int id)
        {
            var existing =
                _expenseClaimTypeService.GetById(
                    id
                );

            if (existing == null)
            {
                return RedirectToAction(
                    "ExpenseClaimType"
                );
            }

            try
            {
                string erpNextId =
                    string.IsNullOrWhiteSpace(
                        existing.ErpNextId
                    )
                        ? existing.Name
                        : existing.ErpNextId;

                if (!string.IsNullOrWhiteSpace(
                    erpNextId))
                {
                    await _erpNextService.DeleteAsync(
                        "/api/resource/Expense%20Claim%20Type/" +
                        Uri.EscapeDataString(
                            erpNextId
                        )
                    );
                }

                _expenseClaimTypeService
                    .SoftDeleteById(
                        id
                    );

                TempData["Success"] =
                    "Expense Claim Type deleted successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Delete failed: "
                    + CleanExpenseClaimTypeErpError(
                        ex.Message
                    );
            }

            return RedirectToAction(
                "ExpenseClaimType"
            );
        }
