        [HttpPost]
        public ActionResult CreateExpenseClaimType(ExpenseClaimType model, string[] Companies, string[] DefaultAccounts)
        {
            if (Companies != null)
            {
                for (int i = 0; i < Companies.Length; i++)
                {
                    if (string.IsNullOrWhiteSpace(Companies[i]) &&
                        (DefaultAccounts == null || i >= DefaultAccounts.Length || string.IsNullOrWhiteSpace(DefaultAccounts[i])))
                        continue;

                    model.Accounts.Add(new ExpenseClaimTypeAccount
                    {
                        Company = Companies[i],
                        DefaultAccount = (DefaultAccounts != null && i < DefaultAccounts.Length) ? DefaultAccounts[i] : null
                    });
                }
            }

            int newId = _expenseClaimTypeService.Insert(model);
            return RedirectToAction("ExpenseClaimTypeDetails", new { id = newId });
        }

