                            new
                            {
                                expense_type =
                                    model.Name,

                                deferred_expense_account =
                                    model.DeferredExpenseAccount
                                        ? 1
                                        : 0,

                                accounts =
                                    accountsPayload,

                                description =
                                    model.Description ?? ""
                            };


                        string responseJson =
                            await _erpNextService.PostAsync(
                                "/api/resource/Expense%20Claim%20Type",
                                payload
                            );


                        JObject response =
                            JObject.Parse(
                                responseJson
                            );


                        string erpNextId =
                            response["data"]?["name"]
                                ?.ToString();


                        if (string.IsNullOrWhiteSpace(
                            erpNextId))
                        {
                            throw new Exception(
                                "ERPNext did not return document ID."
                            );
                        }


                        _expenseClaimTypeService
                            .UpdateErpNextId(
                                model.Id,
                                erpNextId
                            );


                        successCount++;
                    }
                    catch (Exception rowEx)
                    {
                        failCount++;


                        System.Diagnostics.Debug.WriteLine(
                            "Expense Claim Type push error: "
                            + rowEx.Message
                        );
                    }
                }


                TempData["Success"] =
                    "Push completed. Success: "
                    + successCount
                    + ", Failed: "
                    + failCount
                    + ".";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanExpenseClaimTypeErpError(
                        ex.Message
                    );
            }


            return RedirectToAction(
                "ExpenseClaimType"
            );
        }

        private string CleanExpenseClaimTypeErpError(
    string rawError)
        {
            if (string.IsNullOrWhiteSpace(
                rawError))
            {
                return "ERPNext operation failed.";
            }


            try
            {
                int jsonStart =
                    rawError.IndexOf('{');


                if (jsonStart >= 0)
                {
                    string jsonPart =
                        rawError.Substring(
                            jsonStart
                        );


                    JObject json =
                        JObject.Parse(
                            jsonPart
                        );


                    JToken messages =
                        json["_server_messages"];


                    if (messages != null)
                    {
                        JArray array =
                            JArray.Parse(
                                messages.ToString()
                            );


                        if (array.Count > 0)
                        {
                            JObject messageObject =
                                JObject.Parse(
                                    array[0]
                                        .ToString()
                                );


                            string message =
                                messageObject["message"]
                                    ?.ToString();


                            if (!string.IsNullOrWhiteSpace(
                                message))
                            {
                                message =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        message,
                                        "<[^>]*>",
                                        " "
                                    );


                                message =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        message,
                                        @"\s+",
                                        " "
                                    )
                                    .Trim();


                                return System.Net.WebUtility
                                    .HtmlDecode(
                                        message
                                    );
                            }
                        }
                    }
                }
            }
            catch
            {
                // Return original error below
            }


            return rawError;
        }






