        private async Task<int> PullActivityTypesFromErpNext()
        {
            string listJson = await _erpNextService.GetAsync(
                "/api/resource/Activity%20Type?fields=[\"name\"]&limit_page_length=1000"
            );

                dynamic listParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(listJson);
                int synced = 0;

                foreach (var row in listParsed.data)
                {
                    string erpName = row.name?.ToString();

                    if (string.IsNullOrWhiteSpace(erpName))
                        continue;

                    string detailJson = await _erpNextService.GetAsync(
                        "/api/resource/Activity%20Type/" + Uri.EscapeDataString(erpName)
                    );

                    dynamic detailParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(detailJson);
                    var d = detailParsed.data;

                    decimal billingRate;
                    decimal costingRate;

                    var model = new ActivityType
                    {
                        Name = d.activity_type?.ToString() ?? erpName,
                        DefaultBillingRate = d.billing_rate == null || string.IsNullOrWhiteSpace(d.billing_rate.ToString())
                            ? null
                            : decimal.TryParse(d.billing_rate.ToString(), out billingRate) ? billingRate : null,
                        DefaultCostingRate = d.costing_rate == null || string.IsNullOrWhiteSpace(d.costing_rate.ToString())
                            ? null
                            : decimal.TryParse(d.costing_rate.ToString(), out costingRate) ? costingRate : null,
                        Disabled = d.disabled != null && d.disabled.ToString() == "1"
                    };

                    _activityTypeService.UpsertFromErpNext(model);
                    synced++;
                }

            return synced;
        }

