        private async Task<string> PushActivityTypeToErpNext(ActivityType model)
        {
            if (model == null || string.IsNullOrWhiteSpace(model.Name))
                return string.Empty;

            var payload = new
            {
                activity_type = model.Name,
                billing_rate = model.DefaultBillingRate,
                costing_rate = model.DefaultCostingRate,
                disabled = model.Disabled ? 1 : 0
            };

            try
            {
                await _erpNextService.GetAsync(
                    "/api/resource/Activity%20Type/" + Uri.EscapeDataString(model.Name)
                );

                await _erpNextService.PutAsync(
                    "/api/resource/Activity%20Type/" + Uri.EscapeDataString(model.Name),
                    payload
                );

                return model.Name;
            }
            catch
            {
                string createJson = await _erpNextService.PostAsync(
                    "/api/resource/Activity%20Type",
                    payload
                );

                dynamic created = Newtonsoft.Json.JsonConvert.DeserializeObject(createJson);
                return created?.data?.name?.ToString() ?? model.Name;
            }
        }



