        private async Task<int> PullActivityCostsFromErpNext()
        {
            string listJson = await _erpNextService.GetAsync(
                "/api/resource/Activity%20Cost?fields=[\"name\"]&limit_page_length=1000"
            );

                dynamic listParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(listJson);
                int synced = 0;

                foreach (var row in listParsed.data)
                {
                    string erpName = row.name?.ToString();

                    if (string.IsNullOrWhiteSpace(erpName))
                        continue;

                    string detailJson = await _erpNextService.GetAsync(
                        "/api/resource/Activity%20Cost/" + Uri.EscapeDataString(erpName)
                    );

                    dynamic detailParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(detailJson);
                    var d = detailParsed.data;

                    decimal billingRate;
                    decimal costingRate;

                    var model = new ActivityCost
                    {
                        ErpNextId = erpName,
                        ActivityType = d.activity_type?.ToString(),
                        Employee = d.employee?.ToString(),
                        BillingRate = d.billing_rate == null || string.IsNullOrWhiteSpace(d.billing_rate.ToString())
                            ? 0
                            : decimal.TryParse(d.billing_rate.ToString(), out billingRate) ? billingRate : 0,
                        CostingRate = d.costing_rate == null || string.IsNullOrWhiteSpace(d.costing_rate.ToString())
                            ? 0
                            : decimal.TryParse(d.costing_rate.ToString(), out costingRate) ? costingRate : 0
                    };

                    _activityCostService.UpsertFromErpNext(model);
                    synced++;
                }

            return synced;
        }

