        private async Task<string> PushActivityCostToErpNext(ActivityCost model)
        {
            if (model == null || string.IsNullOrWhiteSpace(model.ActivityType))
                return string.Empty;

            var payload = new
            {
                activity_type = model.ActivityType,
                employee = model.Employee,
                billing_rate = model.BillingRate,
                costing_rate = model.CostingRate
            };

            if (!string.IsNullOrWhiteSpace(model.ErpNextId))
            {
                await _erpNextService.PutAsync(
                    "/api/resource/Activity%20Cost/" + Uri.EscapeDataString(model.ErpNextId),
                    payload
                );

                return model.ErpNextId;
            }

            string createJson = await _erpNextService.PostAsync(
                "/api/resource/Activity%20Cost",
                payload
            );

            dynamic created = Newtonsoft.Json.JsonConvert.DeserializeObject(createJson);
            return created?.data?.name?.ToString();
        }

