        [HttpPost]
        [Route("HR/CreateTimesheet")]
        public async Task<ActionResult> CreateTimesheet(TimeSheet model)
        {
            try
            {
                // Filter out empty rows where no ActivityType or Hours were given
                if (model.TimeLogs != null)
                {
                    model.TimeLogs = model.TimeLogs
                        .Where(x => !string.IsNullOrWhiteSpace(x.ActivityType) || x.Hrs > 0)
                        .ToList();
                }
                else
                {
                    model.TimeLogs = new List<TimeSheetDetail>();
                }

                // Calculate total working hours automatically on the server
                decimal total = 0;
                foreach (var log in model.TimeLogs)
                {
                    total += log.Hrs;
                }
                model.TotalWorkingHours = total;

                var timeLogsPayload = new List<object>();
                foreach (var log in model.TimeLogs)
                {
                    timeLogsPayload.Add(new
                    {
                        activity_type = log.ActivityType,
                        from_time = log.FromTime?.ToString("yyyy-MM-dd HH:mm:ss"),
                        to_time = log.ToTime?.ToString("yyyy-MM-dd HH:mm:ss"),
                        hours = log.Hrs,
                        project = log.Project,
                        task = log.Task,
                        is_billable = log.IsBillable ? 1 : 0
                    });
                }

                var erpPayload = new
                {
                    company = model.Company,
                    parent_project = model.Project,
                    customer = model.Customer,
                    currency = model.Currency,
                    exchange_rate = model.ExchangeRate,
                    employee = model.Employee,
                    note = model.Note,
                    time_logs = timeLogsPayload
                };

                var createJson = await _erpNextService.PostAsync("/api/resource/Timesheet", erpPayload);
                model.ErpNextId = ExtractErpDocName(createJson);
                model.Series = model.ErpNextId;

                var service = new TimeSheetService(_connectionString);
                var newId = service.InsertOrUpdate(model);

                TempData["Success"] = "Timesheet saved in ERPNext and HRMS successfully!";
                return RedirectToAction("TimesheetDetails", "HR", new { id = newId });
            }
            catch (Exception ex)
            {
                TempData["Error"] = "ERPNext validation failed: " + ExtractErpNextErrorMessage(ex.Message);
                return RedirectToAction("CreateTimesheet", "HR");
            }
        }





