            var existing = _timeSheetService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                bool existingSubmitted = string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase);
                bool existingCancelled = string.Equals(existing.Status, "Cancelled", StringComparison.OrdinalIgnoreCase);

                model.Id = id;
                model.ErpNextId = !string.IsNullOrWhiteSpace(existing.ErpNextId) ? existing.ErpNextId : existing.Series;
                model.Series = !string.IsNullOrWhiteSpace(existing.Series) ? existing.Series : model.ErpNextId;

                if (string.Equals(actionCommand, "Cancel", StringComparison.OrdinalIgnoreCase))
                {
                    if (!existingSubmitted)
                        throw new Exception("Only submitted Timesheet can be cancelled.");

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                    {
                        doctype = "Timesheet",
                        name = model.ErpNextId
                    });

                    existing.Status = "Cancelled";
                    _timeSheetService.Update(existing);
                    TempData["Success"] = "Timesheet cancelled in ERPNext and HRMS.";
                    return RedirectToAction("TimesheetDetails", new { id });
                }

                if (existingSubmitted || existingCancelled)
                    throw new Exception("You cannot edit submitted or cancelled Timesheet.");

                model.TimeLogs = (model.TimeLogs ?? new List<TimeSheetDetail>())
                    .Where(x => !string.IsNullOrWhiteSpace(x.ActivityType) || x.Hrs > 0)
                    .ToList();
                model.TotalWorkingHours = model.TimeLogs.Sum(x => x.Hrs);

                var payload = new
                {
                    company = model.Company,
                    parent_project = model.Project,
                    customer = model.Customer,
                    currency = model.Currency,
                    exchange_rate = model.ExchangeRate,
                    employee = model.Employee,
                    note = model.Note,
                    time_logs = model.TimeLogs.Select(log => new
                    {
                        activity_type = log.ActivityType,
                        from_time = log.FromTime?.ToString("yyyy-MM-dd HH:mm:ss"),
                        to_time = log.ToTime?.ToString("yyyy-MM-dd HH:mm:ss"),
                        hours = log.Hrs,
                        project = log.Project,
                        task = log.Task,
                        is_billable = log.IsBillable ? 1 : 0
                    }).ToList()
                };

                await _erpNextService.PutAsync($"/api/resource/Timesheet/{Uri.EscapeDataString(model.ErpNextId)}", payload);

                if (string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase))
                {
                    var latestDocResponse = await _erpNextService.GetAsync($"/api/resource/Timesheet/{Uri.EscapeDataString(model.ErpNextId)}");
                    var latestDocJson = Newtonsoft.Json.Linq.JObject.Parse(latestDocResponse);
                    var latestDoc = latestDocJson["data"];

                    if (latestDoc == null)
                        throw new Exception("Submit failed: ERPNext Timesheet document not found.");

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new
                    {
                        doc = latestDoc
                    });

                    model.Status = "Submitted";
                }
                else
                {
                    model.Status = "Draft";
                }

                _timeSheetService.Update(model);
                TempData["Success"] = string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase)
                    ? "Timesheet submitted in ERPNext and HRMS."
                    : "Timesheet saved in ERPNext and HRMS.";
                return RedirectToAction("TimesheetDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Timesheet update failed: " + ExtractErpNextErrorMessage(ex.Message);
                await LoadTimesheetDropdownsAsync();
                ViewBag.IsEdit = true;
                return View("TimesheetDetails", model);
            }
        }

        [HttpPost]
        [Route("HR/DeleteTimesheet/{id:int}")]
        public async Task<ActionResult> DeleteTimesheet(int id)
        {
            var existing = _timeSheetService.GetById(id);
            if (existing == null) return RedirectToAction("Timesheet");

            try
            {
                string erpId = !string.IsNullOrWhiteSpace(existing.ErpNextId) ? existing.ErpNextId : existing.Series;
                if (!string.IsNullOrWhiteSpace(erpId))
                {
                    await _erpNextService.DeleteAsync($"/api/resource/Timesheet/{Uri.EscapeDataString(erpId)}");
