                _timeSheetService.MarkDeletedById(id);
                TempData["Success"] = "Timesheet deleted from ERPNext and HRMS.";
                return RedirectToAction("Timesheet");
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Timesheet delete failed: " + ExtractErpNextErrorMessage(ex.Message);
                return RedirectToAction("TimesheetDetails", new { id });
            }
        }

