        // Downloads a CSV template with the correct columns
        public ActionResult GetAttendanceTemplate(DateTime fromDate, DateTime toDate)
        {
            var sb = new System.Text.StringBuilder();
            sb.AppendLine("Employee,EmployeeName,Company,AttendanceDate,Status,Shift");

            // One sample row per day in the range, left blank for the user to fill in
            for (var d = fromDate.Date; d <= toDate.Date; d = d.AddDays(1))
            {
                sb.AppendLine($",,AITS,{d:yyyy-MM-dd},,");
            }

            var bytes = System.Text.Encoding.UTF8.GetBytes(sb.ToString());
            return File(bytes, "text/csv", $"AttendanceTemplate_{fromDate:yyyyMMdd}_{toDate:yyyyMMdd}.csv");
        }

        // Handles the uploaded CSV through ERPNext first, then mirrors accepted rows locally.
        [HttpPost]
        public async Task<ActionResult> ImportAttendanceFile(IFormFile file)
        {
            if (file == null || file.Length == 0)
            {
                TempData["Error"] = "No file uploaded.";
                return RedirectToAction("UploadAttendance");
            }

            int successCount = 0;
            int errorCount = 0;

            using (var reader = new StreamReader(file.OpenReadStream()))
            {
                string headerLine = reader.ReadLine(); // skip header row
                string line;

                while ((line = reader.ReadLine()) != null)
                {
                    if (string.IsNullOrWhiteSpace(line)) continue;

                    var cols = line.Split(',');
                    if (cols.Length < 6) { errorCount++; continue; }

                    try
                    {
                        var model = new Attendance
                        {
                            Employee = cols[0].Trim(),
                            EmployeeName = cols[1].Trim(),
                            Company = cols[2].Trim(),
                            AttendanceDate = DateTime.Parse(cols[3].Trim()),
                            Status = cols[4].Trim(),
                            Shift = cols[5].Trim()
                        };

                        if (string.IsNullOrEmpty(model.Employee) || string.IsNullOrEmpty(model.Status))
                        {
                            errorCount++;
                            continue;
                        }

                        await CreateAttendanceInErpNextAndMirrorAsync(model);
                        successCount++;
                    }
                    catch
                    {
                        errorCount++;
                    }
                }
            }

            TempData["Success"] = $"{successCount} attendance record(s) imported successfully. {errorCount} row(s) skipped due to errors.";
            return RedirectToAction("UploadAttendance");
        }

