        [HttpPost]
        public async Task<ActionResult> MarkAttendance(DateTime date, string shift, bool lateEntry, bool earlyExit, string company, string status,
            string[] employeeCodes, string[] employeeNames)
        {
            int successCount = 0;
            var errors = new List<string>();

            if (employeeCodes != null)
            {
                for (int i = 0; i < employeeCodes.Length; i++)
                {
                    try
                    {
                        var model = new Attendance
                        {
                            Employee = employeeCodes[i],
                            EmployeeName = (employeeNames != null && i < employeeNames.Length) ? employeeNames[i] : null,
                            Company = company,
                            AttendanceDate = date,
                            Status = status,
                            Shift = shift,
                            LateEntry = lateEntry,
                            EarlyExit = earlyExit
                        };

                        await CreateAttendanceInErpNextAndMirrorAsync(model);
                        successCount++;
                    }
                    catch (Exception ex)
                    {
                        errors.Add($"{employeeCodes[i]}: {ExtractErpNextErrorMessage(ex.Message)}");
                    }
                }
            }

            if (successCount > 0)
                TempData["Success"] = $"{successCount} attendance record(s) marked in ERPNext and HRMS.";

            if (errors.Count > 0)
                TempData["ErpNextError"] = "Attendance mark failed for " + errors.Count + " employee(s): " + string.Join(" | ", errors.Take(5));

            return RedirectToAction("EmployeeAttendanceTool");
        }

        private async Task<Attendance> CreateAttendanceInErpNextAndMirrorAsync(Attendance model)
        {
            if (model == null)
                throw new Exception("Attendance data is missing.");

            if (string.IsNullOrWhiteSpace(model.Employee))
                throw new Exception("Employee is required.");

            if (model.AttendanceDate < new DateTime(1753, 1, 1))
                throw new Exception("Attendance Date is required.");

            if (string.IsNullOrWhiteSpace(model.Status))
                model.Status = "Present";

            if (string.IsNullOrWhiteSpace(model.EmployeeName))
                model.EmployeeName = await GetErpEmployeeFieldAsync(model.Employee, "employee_name");

            if (string.IsNullOrWhiteSpace(model.Company))
                model.Company = await GetErpEmployeeFieldAsync(model.Employee, "company");

            var payload = new
            {
                employee = model.Employee,
                employee_name = model.EmployeeName,
                company = model.Company,
                attendance_date = model.AttendanceDate.ToString("yyyy-MM-dd"),
                status = model.Status,
                shift = model.Shift,
                late_entry = model.LateEntry ? 1 : 0,
                early_exit = model.EarlyExit ? 1 : 0,
                docstatus = 0
            };

            var createJson = await _erpNextService.PostAsync("/api/resource/Attendance", payload);
            var erpName = ExtractErpDocName(createJson);

            if (string.IsNullOrWhiteSpace(erpName))
                throw new Exception("ERPNext created Attendance but did not return document name.");

            model.ErpNextId = erpName;
            model.AttendanceCode = erpName;
            model.DocStatus = 0;

            var existing = _attendanceService.GetByErpNextId(erpName);
            if (existing != null)
            {
                model.Id = existing.Id;
                _attendanceService.UpdateAttendance(model);
            }
            else
            {
                model.Id = _attendanceService.InsertAttendance(model);
            }

            return model;
        }

        private async Task<List<object>> GetUnmarkedEmployeesForToolFromErpAsync(DateTime date, string company, string employmentType, string designation, string department, string employeeGrade, string branch)
        {
            var employeeFilters = new JArray
            {
                new JArray("status", "=", "Active")
            };

            AddErpFilter(employeeFilters, "company", company);
            AddErpFilter(employeeFilters, "employment_type", employmentType);
            AddErpFilter(employeeFilters, "designation", designation);
            AddErpFilter(employeeFilters, "department", department);
            AddErpFilter(employeeFilters, "grade", employeeGrade);
            AddErpFilter(employeeFilters, "branch", branch);

            var empFields = Uri.EscapeDataString("[\"name\",\"employee_name\"]");
            var empUrl = "/api/resource/Employee?fields=" + empFields
                + "&filters=" + Uri.EscapeDataString(employeeFilters.ToString(Formatting.None))
                + "&limit_page_length=1000";

            var employeeResponse = await _erpNextService.GetAsync(empUrl);
            var employees = JObject.Parse(employeeResponse)["data"] as JArray ?? new JArray();

            var attendanceFilters = new JArray
            {
                new JArray("attendance_date", "=", date.ToString("yyyy-MM-dd"))
            };
            AddErpFilter(attendanceFilters, "company", company);

            var attFields = Uri.EscapeDataString("[\"employee\"]");
            var attUrl = "/api/resource/Attendance?fields=" + attFields
                + "&filters=" + Uri.EscapeDataString(attendanceFilters.ToString(Formatting.None))
                + "&limit_page_length=1000";

            var attendanceResponse = await _erpNextService.GetAsync(attUrl);
            var markedEmployees = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (var row in JObject.Parse(attendanceResponse)["data"] as JArray ?? new JArray())
            {
                var employee = row["employee"]?.ToString();
                if (!string.IsNullOrWhiteSpace(employee))
                    markedEmployees.Add(employee);
            }

            var results = new List<object>();
            foreach (var emp in employees)
            {
                var employeeCode = emp["name"]?.ToString();
                if (string.IsNullOrWhiteSpace(employeeCode) || markedEmployees.Contains(employeeCode))
                    continue;

                results.Add(new
                {
                    employeeCode,
                    fullName = emp["employee_name"]?.ToString() ?? employeeCode
                });
            }

            return results;
        }

        private async Task<List<object>> GetMarkedAttendanceForToolFromErpAsync(DateTime date, string company, string employmentType, string designation, string department, string employeeGrade, string branch)
        {
            var attendanceFilters = new JArray
            {
                new JArray("attendance_date", "=", date.ToString("yyyy-MM-dd"))
            };
            AddErpFilter(attendanceFilters, "company", company);

            var fields = Uri.EscapeDataString("[\"name\",\"employee\",\"employee_name\",\"company\",\"attendance_date\",\"status\",\"shift\",\"leave_type\",\"late_entry\",\"early_exit\",\"docstatus\"]");
            var url = "/api/resource/Attendance?fields=" + fields
                + "&filters=" + Uri.EscapeDataString(attendanceFilters.ToString(Formatting.None))
                + "&limit_page_length=1000";

            var response = await _erpNextService.GetAsync(url);
            var data = JObject.Parse(response)["data"] as JArray ?? new JArray();
            var results = new List<object>();

            foreach (var row in data)
            {
                var employee = row["employee"]?.ToString();
                if (string.IsNullOrWhiteSpace(employee))
                    continue;

                if (!await ErpEmployeeMatchesFiltersAsync(employee, employmentType, designation, department, employeeGrade, branch))
                    continue;

                MirrorAttendanceFromErpToken(row);
                results.Add(new
                {
                    employee,
                    employeeName = row["employee_name"]?.ToString() ?? "",
                    status = row["status"]?.ToString() ?? "",
                    shift = row["shift"]?.ToString() ?? "",
                    leaveType = row["leave_type"]?.ToString() ?? ""
                });
            }

            return results;
        }

        private void MirrorAttendanceFromErpToken(JToken item)
        {
            var erpId = item["name"]?.ToString();
            var employee = item["employee"]?.ToString();

            if (string.IsNullOrWhiteSpace(erpId) || string.IsNullOrWhiteSpace(employee))
                return;

            DateTime attendanceDate = DateTime.Today;
            DateTime.TryParse(item["attendance_date"]?.ToString(), out attendanceDate);

            var attendance = new Attendance
            {
                AttendanceCode = erpId,
                ErpNextId = erpId,
                Employee = employee,
                EmployeeName = item["employee_name"]?.ToString() ?? "",
                Company = item["company"]?.ToString() ?? "",
                AttendanceDate = attendanceDate,
                Status = item["status"]?.ToString() ?? "Present",
                Shift = item["shift"]?.ToString() ?? "",
                LateEntry = item["late_entry"]?.ToString() == "1",
                EarlyExit = item["early_exit"]?.ToString() == "1",
                DocStatus = int.TryParse(item["docstatus"]?.ToString(), out int ds) ? ds : 0
            };

            var existing = _attendanceService.GetByErpNextId(erpId);
            if (existing != null)
            {
                attendance.Id = existing.Id;
                _attendanceService.UpdateAttendance(attendance);
            }
            else
            {
                _attendanceService.InsertAttendance(attendance);
            }
        }

        private async Task<bool> ErpEmployeeMatchesFiltersAsync(string employee, string employmentType, string designation, string department, string employeeGrade, string branch)
        {
            if (string.IsNullOrWhiteSpace(employmentType)
                && string.IsNullOrWhiteSpace(designation)
                && string.IsNullOrWhiteSpace(department)
                && string.IsNullOrWhiteSpace(employeeGrade)
                && string.IsNullOrWhiteSpace(branch))
                return true;

            var response = await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(employee)}");
            var doc = JObject.Parse(response)["data"];
            if (doc == null)
                return false;

            return MatchesErpValue(doc, "employment_type", employmentType)
                && MatchesErpValue(doc, "designation", designation)
                && MatchesErpValue(doc, "department", department)
                && MatchesErpValue(doc, "grade", employeeGrade)
                && MatchesErpValue(doc, "branch", branch);
        }

        private async Task<string> GetErpEmployeeFieldAsync(string employee, string fieldName)
        {
            if (string.IsNullOrWhiteSpace(employee) || string.IsNullOrWhiteSpace(fieldName))
                return "";

            try
            {
                var response = await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(employee)}");
                return JObject.Parse(response)["data"]?[fieldName]?.ToString() ?? "";
            }
            catch
            {
                return "";
            }
        }

        private static void AddErpFilter(JArray filters, string fieldName, string value)
        {
            if (!string.IsNullOrWhiteSpace(value))
                filters.Add(new JArray(fieldName, "=", value.Trim()));
        }

        private static bool MatchesErpValue(JToken doc, string fieldName, string expected)
        {
            return string.IsNullOrWhiteSpace(expected)
                || string.Equals(doc[fieldName]?.ToString(), expected.Trim(), StringComparison.OrdinalIgnoreCase);
        }

