        [HttpGet]
        [Route("HR/ShiftAssignmentTool")]
        public async Task<ActionResult> ShiftAssignmentTool(
            string shiftType,
            string startDate,
            string branch,
            string department,
            string designation,
            string grade,
            string employmentType)
        {
            try
            {
                var shiftTypeResp = await _erpNextService.GetAsync("/api/resource/Shift%20Type?fields=[\"name\"]&limit_page_length=100");
                ViewBag.ShiftTypes = ExtractNamesList(shiftTypeResp);

                var shiftLocationResp = await _erpNextService.GetAsync("/api/resource/Shift%20Location?fields=[\"name\"]&limit_page_length=100");
                ViewBag.ShiftLocations = ExtractNamesList(shiftLocationResp);

                var branchResp = await _erpNextService.GetAsync("/api/resource/Branch?fields=[\"name\"]&limit_page_length=100");
                ViewBag.Branches = ExtractNamesList(branchResp);

                var deptResp = await _erpNextService.GetAsync("/api/resource/Department?fields=[\"name\"]&limit_page_length=100");
                ViewBag.Departments = ExtractNamesList(deptResp);

                var desigResp = await _erpNextService.GetAsync("/api/resource/Designation?fields=[\"name\"]&limit_page_length=100");
                ViewBag.Designations = ExtractNamesList(desigResp);

                var gradeResp = await _erpNextService.GetAsync("/api/resource/Employee%20Grade?fields=[\"name\"]&limit_page_length=100");
                ViewBag.Grades = ExtractNamesList(gradeResp);

                var empTypeResp = await _erpNextService.GetAsync("/api/resource/Employment%20Type?fields=[\"name\"]&limit_page_length=100");
                ViewBag.EmploymentTypes = ExtractNamesList(empTypeResp);

                // Fetch Employees based on quick filters if applied
                var filters = new List<string> { "[\"status\", \"=\", \"Active\"]" };
                if (!string.IsNullOrEmpty(branch)) filters.Add($"[\"branch\", \"=\", \"{branch}\"]");
                if (!string.IsNullOrEmpty(department)) filters.Add($"[\"department\", \"=\", \"{department}\"]");
                if (!string.IsNullOrEmpty(designation)) filters.Add($"[\"designation\", \"=\", \"{designation}\"]");
                if (!string.IsNullOrEmpty(employmentType)) filters.Add($"[\"employment_type\", \"=\", \"{employmentType}\"]");
                if (!string.IsNullOrEmpty(grade)) filters.Add($"[\"grade\", \"=\", \"{grade}\"]");

                string filterString = "[" + string.Join(",", filters) + "]";
                string empUrl = $"/api/resource/Employee?fields=[\"name\",\"employee_name\",\"branch\",\"department\",\"default_shift\"]&filters={Uri.EscapeDataString(filterString)}&limit_page_length=100";

                var empResp = await _erpNextService.GetAsync(empUrl);
                dynamic parsedEmp = Newtonsoft.Json.JsonConvert.DeserializeObject(empResp);
                var empList = new List<object>();

                if (parsedEmp?.data != null)
                {
                    foreach (var item in parsedEmp.data)
                    {
                        empList.Add(new
                        {
                            EmployeeId = item.name?.ToString(),
                            EmployeeName = item.employee_name?.ToString(),
                            Branch = item.branch?.ToString(),
                            Department = item.department?.ToString(),
                            DefaultShift = item.default_shift?.ToString()
                        });
                    }
                }
                ViewBag.EmployeesList = empList;
            }
            catch
            {
                ViewBag.ShiftTypes = new List<string>();
                ViewBag.ShiftLocations = new List<string>();
                ViewBag.Branches = new List<string>();
                ViewBag.Departments = new List<string>();
                ViewBag.Designations = new List<string>();
                ViewBag.Grades = new List<string>();
                ViewBag.EmploymentTypes = new List<string>();
                ViewBag.EmployeesList = new List<object>();
            }

            return View("~/Views/HR/ShiftAssignmentTool.cshtml");
        }


















        [HttpGet]
        [Route("HR/SearchEmployeesForShiftTool")]
        public async Task<JsonResult> SearchEmployeesForShiftTool(string branch, string department, string designation, string employmentType, string grade)
        {
            try
            {
                var filters = new List<string>();
                filters.Add("[\"status\", \"=\", \"Active\"]");

                if (!string.IsNullOrEmpty(branch)) filters.Add($"[\"branch\", \"=\", \"{branch}\"]");
                if (!string.IsNullOrEmpty(department)) filters.Add($"[\"department\", \"=\", \"{department}\"]");
                if (!string.IsNullOrEmpty(designation)) filters.Add($"[\"designation\", \"=\", \"{designation}\"]");
                if (!string.IsNullOrEmpty(employmentType)) filters.Add($"[\"employment_type\", \"=\", \"{employmentType}\"]");
                if (!string.IsNullOrEmpty(grade)) filters.Add($"[\"grade\", \"=\", \"{grade}\"]");

                string filterString = "[" + string.Join(",", filters) + "]";
                string url = $"/api/resource/Employee?fields=[\"name\",\"employee_name\",\"branch\",\"department\",\"default_shift\"]&filters={Uri.EscapeDataString(filterString)}&limit_page_length=100";

                var response = await _erpNextService.GetAsync(url);
                dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);
                var results = new List<object>();

                if (parsed?.data != null)
                {
                    foreach (var item in parsed.data)
                    {
                        results.Add(new
                        {
                            employee = item.name?.ToString(),
                            employeeName = item.employee_name?.ToString(),
                            branch = item.branch?.ToString(),
                            department = item.department?.ToString(),
                            defaultShift = item.default_shift?.ToString()
                        });
                    }
                }

                return Json(results);
            }
            catch
            {
                return Json(new List<object>());
            }
        }

        [HttpPost]
        [Route("HR/ProcessShiftAssignmentTool")]
        public async Task<ActionResult> ProcessShiftAssignmentTool(string Action, string Company, string ShiftSchedule, string ShiftType, string ShiftLocation,
            DateTime StartDate, DateTime? EndDate, string Status, string[] SelectedEmployees, string[] SelectedEmployeeNames)
        {
            var shiftValue = string.IsNullOrWhiteSpace(ShiftType) ? ShiftSchedule : ShiftType;
            int successCount = 0;
            var errors = new List<string>();

            if (SelectedEmployees != null && SelectedEmployees.Length > 0)
            {
                for (int i = 0; i < SelectedEmployees.Length; i++)
                {
                    try
                    {
                        var employeeName = SelectedEmployeeNames != null && i < SelectedEmployeeNames.Length
                            ? SelectedEmployeeNames[i]
                            : await GetErpEmployeeFieldAsync(SelectedEmployees[i], "employee_name");

                        if (string.Equals(Action, "Assign Shift Schedule", StringComparison.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(ShiftSchedule))
                        {
                            var schedulePayload = new
                            {
                                employee = SelectedEmployees[i],
                                employee_name = employeeName,
                                company = Company,
                                shift_schedule = ShiftSchedule,
                                shift_location = ShiftLocation,
                                enabled = 1,
                                start_date = StartDate.ToString("yyyy-MM-dd"),
                                status = string.IsNullOrWhiteSpace(Status) ? "Active" : Status
                            };

                            var createJson = await _erpNextService.PostAsync("/api/resource/Shift%20Schedule%20Assignment", schedulePayload);
                            var assignment = new HRShiftScheduleAssignment
                            {
                                ErpNextId = ExtractErpDocName(createJson),
                                Employee = SelectedEmployees[i],
                                EmployeeName = employeeName,
                                Company = Company,
                                ShiftSchedule = ShiftSchedule,
                                ShiftLocation = ShiftLocation,
                                Enabled = true,
                                CreateShiftsAfter = StartDate,
                                ShiftStatus = string.IsNullOrWhiteSpace(Status) ? "Active" : Status
                            };

                            _hrShiftScheduleAssignmentService.InsertOrUpdate(assignment);
                        }
                        else
                        {
                            if (string.IsNullOrWhiteSpace(shiftValue))
                                throw new Exception("Please select Shift Type.");

                            var shiftPayload = new
                            {
                                employee = SelectedEmployees[i],
                                employee_name = employeeName,
                                company = Company,
                                shift_type = shiftValue,
                                shift_location = ShiftLocation,
                                start_date = StartDate.ToString("yyyy-MM-dd"),
                                end_date = EndDate?.ToString("yyyy-MM-dd"),
                                status = string.IsNullOrWhiteSpace(Status) ? "Active" : Status
                            };

                            var createJson = await _erpNextService.PostAsync("/api/resource/Shift%20Assignment", shiftPayload);
                            var assignment = new HRShiftAssignment
                            {
                                ErpNextId = ExtractErpDocName(createJson),
                                Employee = SelectedEmployees[i],
                                EmployeeName = employeeName,
                                Company = Company,
                                ShiftType = shiftValue,
                                ShiftLocation = ShiftLocation,
                                StartDate = StartDate,
                                EndDate = EndDate,
                                Status = string.IsNullOrWhiteSpace(Status) ? "Active" : Status
                            };

                            _hrShiftAssignmentService.InsertOrUpdate(assignment);
                        }

                        successCount++;
                    }
                    catch (Exception ex)
                    {
                        errors.Add($"{SelectedEmployees[i]}: {ExtractErpNextErrorMessage(ex.Message)}");
                    }
                }
            }
            else
            {
                TempData["ErpNextError"] = "Please select at least one employee.";
                return RedirectToAction("ShiftAssignmentTool");
            }

            if (successCount > 0)
                TempData["Success"] = $"{successCount} shift assignment(s) created in ERPNext and HRMS.";

            if (errors.Count > 0)
                TempData["ErpNextError"] = "Shift assignment failed for " + errors.Count + " employee(s): " + string.Join(" | ", errors.Take(5));

            return RedirectToAction("HRShiftAssignmentList");
        }


