        [HttpPost]
        [Route("HR/UpdateShiftSchedule/{id:int}")]
        public async Task<ActionResult> UpdateShiftSchedule(int id, HRShiftSchedule model, string[] Days, string actionCommand)
        {
            var existing = _hrShiftScheduleService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                bool existingSubmitted = string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase);
                bool existingCancelled = string.Equals(existing.Status, "Cancelled", StringComparison.OrdinalIgnoreCase);

                model.Id = id;
                model.Name = string.IsNullOrWhiteSpace(model.Name) ? existing.Name : model.Name.Trim();
                model.ShiftType = string.IsNullOrWhiteSpace(model.ShiftType) ? existing.ShiftType : model.ShiftType;
                model.Frequency = string.IsNullOrWhiteSpace(model.Frequency) ? existing.Frequency : model.Frequency;
                model.Status = string.IsNullOrWhiteSpace(model.Status) ? existing.Status : model.Status;
                model.Days = (Days ?? Array.Empty<string>())
                    .Where(x => !string.IsNullOrWhiteSpace(x))
                    .Select(x => new HRShiftScheduleDay { Day = x })
                    .ToList();

                if (string.Equals(actionCommand, "Cancel", StringComparison.OrdinalIgnoreCase))
                {
                    if (!existingSubmitted)
                        throw new Exception("Only submitted Shift Schedule can be cancelled.");

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                    {
                        doctype = "Shift Schedule",
                        name = existing.Name
                    });

                    existing.Status = "Cancelled";
                    _hrShiftScheduleService.Update(existing);
                    TempData["Success"] = "Shift Schedule cancelled in ERPNext and HRMS.";
                    return RedirectToAction("HRShiftScheduleDetails", new { id });
                }

                if (existingSubmitted || existingCancelled)
                    throw new Exception("You cannot edit submitted or cancelled Shift Schedule.");

                var erpName = existing.Name;
                if (!string.Equals(existing.Name, model.Name, StringComparison.OrdinalIgnoreCase))
                {
                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.rename_doc", new
                    {
                        doctype = "Shift Schedule",
                        old_name = existing.Name,
                        new_name = model.Name,
                        merge = 0
                    });
                    erpName = model.Name;
                }

                var payload = new
                {
                    shift_type = model.ShiftType,
                    frequency = model.Frequency,
                    repeat_on_days = model.Days.Select(d => new { day = d.Day }).ToList()
                };

                await _erpNextService.PutAsync($"/api/resource/Shift%20Schedule/{Uri.EscapeDataString(erpName)}", payload);

                if (string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase))
                {
                    var latestDocResponse = await _erpNextService.GetAsync($"/api/resource/Shift%20Schedule/{Uri.EscapeDataString(erpName)}");
                    var latestDocJson = Newtonsoft.Json.Linq.JObject.Parse(latestDocResponse);
                    var latestDoc = latestDocJson["data"];

                    if (latestDoc == null)
                        throw new Exception("Submit failed: ERPNext Shift Schedule document not found.");

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new
                    {
                        doc = latestDoc
                    });

                    model.Status = "Submitted";
                }

                _hrShiftScheduleService.Update(model);
                TempData["Success"] = string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase)
                    ? "Shift Schedule submitted in ERPNext and HRMS."
                    : "Shift Schedule saved in ERPNext and HRMS.";
                return RedirectToAction("HRShiftScheduleDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Shift Schedule update failed: " + ExtractErpNextErrorMessage(ex.Message);
                await LoadShiftScheduleDropdownsAsync();
                return View("HRShiftScheduleDetails", model);
            }
        }

