        [HttpGet]
        [Route("HR/CreateShiftAssignment")]
        public async Task<ActionResult> CreateShiftAssignment()
        {
            var model = new HRShiftAssignment { StartDate = DateTime.Now };
            try
            {
                // Employees dropdown data
                var empResp = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=100");
                dynamic empParsed = JsonConvert.DeserializeObject(empResp);
                var employeesList = new List<object>();
                if (empParsed?.data != null)
                {
                    foreach (var e in empParsed.data)
                    {
                        employeesList.Add(new
                        {
                            EmployeeId = e.name?.ToString(),
                            EmployeeName = e.employee_name?.ToString() ?? e.name?.ToString()
                        });
                    }
                }
                ViewBag.EmployeesList = employeesList;

                // Company dropdown data
                var compResp = await _erpNextService.GetAsync("/api/resource/Company?fields=[\"name\"]&limit_page_length=100");
                ViewBag.Companies = ExtractNamesList(compResp);

                // Shift Type dropdown data
                var stResp = await _erpNextService.GetAsync("/api/resource/Shift%20Type?fields=[\"name\"]&limit_page_length=100");
                ViewBag.ShiftTypes = ExtractNamesList(stResp);

                // Shift Location dropdown data
                var locResp = await _erpNextService.GetAsync("/api/resource/Shift%20Location?fields=[\"name\"]&limit_page_length=100");
                ViewBag.ShiftLocations = ExtractNamesList(locResp);
            }
            catch
