                ViewBag.EmployeesList = new List<object>();
                ViewBag.Companies = new List<string>();
                ViewBag.ShiftTypes = new List<string>();
                ViewBag.ShiftLocations = new List<string>();
            }

            return View("~/Views/HR/CreateShiftAssignment.cshtml", model);
        }



        [HttpPost]
        [Route("HR/CreateShiftAssignment")]
        public async Task<ActionResult> CreateShiftAssignment(HRShiftAssignment model)
        {
            try
            {
                model ??= new HRShiftAssignment();
                model.Employee = string.IsNullOrWhiteSpace(model.Employee) ? Request.Form["Employee"].ToString() : model.Employee;
                model.EmployeeName = string.IsNullOrWhiteSpace(model.EmployeeName) ? Request.Form["EmployeeName"].ToString() : model.EmployeeName;
                model.Company = string.IsNullOrWhiteSpace(model.Company) ? Request.Form["Company"].ToString() : model.Company;
                model.ShiftType = string.IsNullOrWhiteSpace(model.ShiftType) ? Request.Form["ShiftType"].ToString() : model.ShiftType;
                model.ShiftLocation = string.IsNullOrWhiteSpace(model.ShiftLocation) ? Request.Form["ShiftLocation"].ToString() : model.ShiftLocation;
                model.Status = string.IsNullOrWhiteSpace(model.Status) ? Request.Form["Status"].ToString() : model.Status;
                model.Status = string.IsNullOrWhiteSpace(model.Status) ? "Active" : model.Status;

                if (DateTime.TryParse(Request.Form["StartDate"].ToString(), out var postedStartDate))
                    model.StartDate = postedStartDate;

                if (DateTime.TryParse(Request.Form["EndDate"].ToString(), out var postedEndDate))
                    model.EndDate = postedEndDate;

                if (string.IsNullOrWhiteSpace(model.Employee) || string.IsNullOrWhiteSpace(model.Company) || string.IsNullOrWhiteSpace(model.ShiftType))
                    throw new Exception("Please select Employee, Company and Shift Type.");

                var erpPayload = new
                {
                    employee = model.Employee,
                    employee_name = model.EmployeeName,
                    company = model.Company,
                    shift_type = model.ShiftType,
                    shift_location = model.ShiftLocation,
                    start_date = model.StartDate.ToString("yyyy-MM-dd"),
                    end_date = model.EndDate?.ToString("yyyy-MM-dd"),
                    status = model.Status
                };

                var createJson = await _erpNextService.PostAsync("/api/resource/Shift%20Assignment", erpPayload);
                model.ErpNextId = ExtractErpDocName(createJson);

                var service = new HRShiftAssignmentService(_connectionString);
                var newId = service.InsertOrUpdate(model);

                TempData["Success"] = "Shift Assignment saved in ERPNext and HRMS successfully.";

                return RedirectToAction("HRShiftAssignmentDetails", new { id = newId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext validation failed: " + ExtractErpNextErrorMessage(ex.Message);
                await LoadShiftAssignmentDropdownsAsync();
                return View("~/Views/HR/CreateShiftAssignment.cshtml", model);
            }
        }














