        [HttpPost]
        [Route("HR/UpdateShiftAssignment/{id:int}")]
        public async Task<ActionResult> UpdateShiftAssignment(int id, HRShiftAssignment model, string actionCommand)
        {
            var existing = _hrShiftAssignmentService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                bool existingSubmitted = string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase);
                bool existingCancelled = string.Equals(existing.Status, "Cancelled", StringComparison.OrdinalIgnoreCase);

                model.Id = id;
                model.ErpNextId = existing.ErpNextId;
                model.Employee = string.IsNullOrWhiteSpace(model.Employee) ? existing.Employee : model.Employee;
                model.EmployeeName = string.IsNullOrWhiteSpace(model.EmployeeName) ? existing.EmployeeName : model.EmployeeName;
                model.Company = string.IsNullOrWhiteSpace(model.Company) ? existing.Company : model.Company;
                model.ShiftType = string.IsNullOrWhiteSpace(model.ShiftType) ? existing.ShiftType : model.ShiftType;
                model.ShiftLocation = string.IsNullOrWhiteSpace(model.ShiftLocation) ? existing.ShiftLocation : model.ShiftLocation;
                model.StartDate = model.StartDate == default ? existing.StartDate : model.StartDate;
                model.Status = string.IsNullOrWhiteSpace(model.Status) ? existing.Status : model.Status;

                if (string.IsNullOrWhiteSpace(model.ErpNextId))
                    throw new Exception("ERPNext ID is missing.");

                if (string.Equals(actionCommand, "Cancel", StringComparison.OrdinalIgnoreCase))
                {
                    if (!existingSubmitted)
                        throw new Exception("Only submitted Shift Assignment can be cancelled.");

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                    {
                        doctype = "Shift Assignment",
                        name = existing.ErpNextId
                    });

                    model.Employee = existing.Employee;
                    model.EmployeeName = existing.EmployeeName;
                    model.Company = existing.Company;
                    model.ShiftType = existing.ShiftType;
                    model.ShiftLocation = existing.ShiftLocation;
                    model.StartDate = existing.StartDate;
                    model.EndDate = existing.EndDate;
                    model.Status = "Cancelled";
                    _hrShiftAssignmentService.Update(model);
                    TempData["Success"] = "Shift Assignment cancelled in ERPNext and HRMS.";
                    return RedirectToAction("HRShiftAssignmentDetails", new { id });
                }

                if (existingSubmitted || existingCancelled)
                    throw new Exception("You cannot edit submitted or cancelled Shift Assignment.");

                var payload = new
                {
                    employee = model.Employee,
                    employee_name = model.EmployeeName,
                    company = model.Company,
                    shift_type = model.ShiftType,
                    shift_location = model.ShiftLocation,
                    start_date = model.StartDate.ToString("yyyy-MM-dd"),
                    end_date = model.EndDate?.ToString("yyyy-MM-dd"),
                    status = model.Status
                };

                await _erpNextService.PutAsync($"/api/resource/Shift%20Assignment/{Uri.EscapeDataString(model.ErpNextId)}", payload);

                if (string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase))
                {
                    var latestDocResponse = await _erpNextService.GetAsync($"/api/resource/Shift%20Assignment/{Uri.EscapeDataString(model.ErpNextId)}");
                    var latestDocJson = Newtonsoft.Json.Linq.JObject.Parse(latestDocResponse);
                    var latestDoc = latestDocJson["data"];

                    if (latestDoc == null)
                        throw new Exception("Submit failed: ERPNext Shift Assignment document not found.");

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new
                    {
                        doc = latestDoc
                    });

                    model.Status = "Submitted";
                }

                _hrShiftAssignmentService.Update(model);
                TempData["Success"] = string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase)
                    ? "Shift Assignment submitted in ERPNext and HRMS."
                    : "Shift Assignment saved in ERPNext and HRMS.";
                return RedirectToAction("HRShiftAssignmentDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Shift Assignment update failed: " + ExtractErpNextErrorMessage(ex.Message);
                await LoadShiftAssignmentDropdownsAsync();
                ViewBag.IsEdit = true;
                return View("HRShiftAssignmentDetails", model);
            }
        }

