        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateShiftType/{id:int}")]
        public async Task<ActionResult> UpdateShiftType(int id, ShiftType model)
        {
            var existing = _shiftTypeService.GetById(id);
            if (existing == null)
            {
                return NotFound();
            }

            model.Id = id;

            // Shift Type Name should remain readonly, so always keep old name.
            model.Name = existing.Name;
            model.ShiftTypeCode = existing.ShiftTypeCode;

            if (string.IsNullOrWhiteSpace(model.HolidayList))
            {
                TempData["ErpNextError"] = "Holiday List is required.";
                return RedirectToAction("ShiftTypeDetails", new { id, edit = true });
            }

            if (string.IsNullOrWhiteSpace(model.StartTime))
            {
                TempData["ErpNextError"] = "Start Time is required.";
                return RedirectToAction("ShiftTypeDetails", new { id, edit = true });
            }

            if (string.IsNullOrWhiteSpace(model.EndTime))
            {
                TempData["ErpNextError"] = "End Time is required.";
                return RedirectToAction("ShiftTypeDetails", new { id, edit = true });
            }

            if (model.StartTime == model.EndTime)
            {
                TempData["ErpNextError"] = "Start time and end time cannot be same.";
                return RedirectToAction("ShiftTypeDetails", new { id, edit = true });
            }

            model.RosterColor = string.IsNullOrWhiteSpace(model.RosterColor)
                ? "Blue"
                : model.RosterColor;

            try
            {
                var payload = new
                {
                    start_time = model.StartTime,
                    end_time = model.EndTime,
                    holiday_list = model.HolidayList,
                    color = model.RosterColor,
                    enable_auto_attendance = model.EnableAutoAttendance ? 1 : 0
                };

                await _erpNextService.PutAsync(
                    "/api/resource/Shift%20Type/" + Uri.EscapeDataString(existing.Name),
                    payload
                );

                _shiftTypeService.Update(model);

                TempData["Success"] = "Shift Type updated successfully in HRMS and ERPNext.";
                return RedirectToAction("ShiftTypeDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext update failed: " + ExtractErpNextErrorMessage(ex.Message);
                return RedirectToAction("ShiftTypeDetails", new { id, edit = true });
            }
        }
