        [HttpPost]
        [Route("HR/UpdateShiftRequest/{id:int}")]
        public async Task<ActionResult> UpdateShiftRequest(int id, ShiftRequest model, string actionCommand)
        {
            var existing = _shiftRequestService.GetById(id);
            if (existing == null) return NotFound();

            try
            {
                bool existingSubmitted = existing.DocStatus == 1 || string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase);
                bool existingCancelled = existing.DocStatus == 2 || string.Equals(existing.Status, "Cancelled", StringComparison.OrdinalIgnoreCase);

                model.Id = id;
                model.ShiftRequestCode = existing.ShiftRequestCode;
                model.AmendedFrom = existing.AmendedFrom;
                model.ShiftType = string.IsNullOrWhiteSpace(model.ShiftType) ? existing.ShiftType : model.ShiftType;
                model.Company = string.IsNullOrWhiteSpace(model.Company) ? existing.Company : model.Company;
                model.Employee = string.IsNullOrWhiteSpace(model.Employee) ? existing.Employee : model.Employee;
                model.EmployeeName = string.IsNullOrWhiteSpace(model.EmployeeName) ? existing.EmployeeName : model.EmployeeName;
                model.Department = string.IsNullOrWhiteSpace(model.Department) ? existing.Department : model.Department;
                model.Approver = string.IsNullOrWhiteSpace(model.Approver) ? existing.Approver : model.Approver;
                model.Status = string.IsNullOrWhiteSpace(model.Status) ? existing.Status : model.Status;
                model.FromDate = model.FromDate ?? existing.FromDate;
                model.ToDate = model.ToDate ?? existing.ToDate;

                if (string.IsNullOrWhiteSpace(model.ShiftRequestCode))
                    throw new Exception("ERPNext Shift Request ID is missing.");

                if (string.Equals(actionCommand, "Cancel", StringComparison.OrdinalIgnoreCase))
                {
                    if (!existingSubmitted)
                        throw new Exception("Only submitted Shift Request can be cancelled.");

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                    {
                        doctype = "Shift Request",
                        name = existing.ShiftRequestCode
                    });

                    existing.DocStatus = 2;
                    existing.Status = "Cancelled";
                    _shiftRequestService.InsertOrUpdate(existing);

                    TempData["Success"] = "Shift Request cancelled in ERPNext and HRMS.";
                    return RedirectToAction("ShiftRequestDetails", new { id });
                }

                if (existingSubmitted || existingCancelled)
                    throw new Exception("You can't edit submitted document.");

                var payload = new
                {
                    shift_type = model.ShiftType,
                    company = model.Company,
                    employee = model.Employee,
                    employee_name = model.EmployeeName,
                    department = model.Department,
                    approver = model.Approver,
                    status = string.IsNullOrWhiteSpace(model.Status) ? "Draft" : model.Status,
                    from_date = model.FromDate?.ToString("yyyy-MM-dd"),
                    to_date = model.ToDate?.ToString("yyyy-MM-dd")
                };

                await _erpNextService.PutAsync($"/api/resource/Shift%20Request/{Uri.EscapeDataString(model.ShiftRequestCode)}", payload);

                model.DocStatus = 0;
                model.Status = string.IsNullOrWhiteSpace(model.Status) ? "Draft" : model.Status;

                if (string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase))
                {
                    if (!string.Equals(model.Status, "Approved", StringComparison.OrdinalIgnoreCase) &&
                        !string.Equals(model.Status, "Rejected", StringComparison.OrdinalIgnoreCase))
                    {
                        throw new Exception("Please set Status to Approved or Rejected before submitting Shift Request.");
                    }

                    var latestDocResponse = await _erpNextService.GetAsync($"/api/resource/Shift%20Request/{Uri.EscapeDataString(model.ShiftRequestCode)}");
                    var latestDocJson = JObject.Parse(latestDocResponse);
                    var latestDoc = latestDocJson["data"];

                    if (latestDoc == null)
                        throw new Exception("Submit failed: ERPNext Shift Request document not found.");

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new
                    {
                        doc = latestDoc
                    });

                    model.DocStatus = 1;
                    model.Status = "Submitted";
                }

                _shiftRequestService.InsertOrUpdate(model);
                TempData["Success"] = string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase)
                    ? "Shift Request submitted in ERPNext and HRMS."
                    : "Shift Request saved in ERPNext and HRMS.";
                return RedirectToAction("ShiftRequestDetails", new { id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Shift Request update failed: " + ExtractErpNextErrorMessage(ex.Message);
                await LoadShiftRequestDropdownsAsync();
                ViewBag.IsEdit = true;
                return View("ShiftRequestDetails", model);
            }
        }

