        [HttpPost]
        public async Task<ActionResult> SyncEmployeeFeedbackCriteriaFromErpNext()
        {
            try
            {
                int count = await SyncEmployeeFeedbackCriteriaFromErpNextInternal();

                TempData["Success"] = count + " Employee Feedback Criteria synced from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "ERPNext fetch failed: " + ExtractErpNextErrorMessage(ex.Message);
            }

            return RedirectToAction("EmployeeFeedbackCriteria");
        }

        private async Task<int> SyncEmployeeFeedbackCriteriaFromErpNextInternal()
        {
            string response = await _erpNextService.GetAsync(
                "/api/resource/Employee%20Feedback%20Criteria?fields=[\"name\",\"criteria\"]&limit_page_length=1000"
            );

            dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);

            int count = 0;
            var erpNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (parsed?.data != null)
            {
                foreach (var row in parsed.data)
                {
                    string erpName = row.name?.ToString();
                    string criteria = row.criteria?.ToString();

                    if (string.IsNullOrWhiteSpace(criteria))
                        criteria = erpName;

                    if (!string.IsNullOrWhiteSpace(erpName) &&
                        !string.IsNullOrWhiteSpace(criteria))
                    {
                        _employeeFeedbackCriteriaService.UpsertFromErpNext(erpName, criteria);
                        erpNames.Add(erpName);
                        count++;
                    }
                }
            }

            _employeeFeedbackCriteriaService.SoftDeleteMissingErpRecords(erpNames);

            return count;
        }

        [HttpPost]
        public async Task<ActionResult> SyncEmployeeFeedbackCriteriaToErpNext()
        {
            int success = 0;
            int failed = 0;

            var list = _employeeFeedbackCriteriaService.GetAll();

            foreach (var item in list)
            {
                try
                {
                    string erpName = await PushEmployeeFeedbackCriteriaToErpNext(item);

                    if (string.IsNullOrWhiteSpace(item.CriteriaCode) || item.CriteriaCode.StartsWith("EFC-"))
                    {
                        _employeeFeedbackCriteriaService.UpdateCriteriaCode(item.Id, erpName);
                    }

                    success++;
                }
                catch
                {
                    failed++;
                }
            }

            TempData["Success"] = $"ERPNext push completed. Success: {success}, Failed: {failed}.";
            return RedirectToAction("EmployeeFeedbackCriteria");
        }



        private async Task<string> PushEmployeePromotionToErpNext(EmployeePromotion model)
        {
            var promotionDetails = new List<object>();

            if (model.Details != null)
            {
                foreach (var d in model.Details)
                {
                    promotionDetails.Add(new
                    {
                        fieldname = d.FieldName,
                        property = d.Property,
                        current = d.CurrentValue,
                        @new = d.NewValue
                    });
                }
            }

            var payload = new
            {
                employee = model.Employee,
                promotion_date = model.PromotionDate.ToString("yyyy-MM-dd"),
                company = model.Company,
                salary_currency = model.SalaryCurrency,
                current_ctc = model.CurrentCTC,
                promotion_details = promotionDetails
            };

            if (!string.IsNullOrWhiteSpace(model.ErpNextId))
            {
                await _erpNextService.PutAsync(
                    "/api/resource/Employee%20Promotion/" + Uri.EscapeDataString(model.ErpNextId),
                    payload
                );

                return model.ErpNextId;
            }

            string response = await _erpNextService.PostAsync("/api/resource/Employee%20Promotion", payload);
            dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);

            return parsed?.data?.name?.ToString();
        }





















