        private async Task<string> PushEmployeeFeedbackCriteriaToErpNext(EmployeeFeedbackCriteria model)
        {
            if (string.IsNullOrWhiteSpace(model.Criteria))
                throw new Exception("Criteria is required.");

            if (model.Criteria.Trim().Length > 140)
                throw new Exception("Criteria cannot be more than 140 characters.");

            var payload = new
            {
                criteria = model.Criteria.Trim()
            };

            if (!string.IsNullOrWhiteSpace(model.CriteriaCode) && !model.CriteriaCode.StartsWith("EFC-"))
            {
                await _erpNextService.PutAsync(
                    "/api/resource/Employee%20Feedback%20Criteria/" + Uri.EscapeDataString(model.CriteriaCode),
                    payload
                );

                return model.CriteriaCode;
            }
            else
            {
                string response = await _erpNextService.PostAsync(
                    "/api/resource/Employee%20Feedback%20Criteria",
                    payload
                );

                dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);
                string erpName = parsed?.data?.name?.ToString();

                return string.IsNullOrWhiteSpace(erpName) ? model.Criteria.Trim() : erpName;
            }
        }














