        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> QuickCreateKRA(string Title)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(Title))
                    throw new Exception("KRA Title is required.");

                var payload = new
                {
                    title = Title.Trim()
                };

                // Save in ERPNext first.
                string response = await _erpNextService.PostAsync(
                    "/api/resource/KRA",
                    payload
                );

                JObject json = JObject.Parse(response);

                string erpName = json["data"]?["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpName))
                    throw new Exception("ERPNext did not return the KRA document name.");

                // Read ERPNext record back and synchronize into HRMS.
                int localId = await _kraService.SyncOneFromErpNextAsync(
                    _erpNextService,
                    erpName
                );

                TempData["Success"] =
                    "KRA saved in ERPNext and HRMS successfully: " + erpName;

                return RedirectToAction("KRADetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "KRA Save failed: " + ex.Message;

                return RedirectToAction("KRA");
            }
        }


