        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> CreateKRA(KRA model)
        {
            try
            {
                if (model == null ||
                    string.IsNullOrWhiteSpace(model.Title))
                {
                    throw new Exception("KRA Title is required.");
                }

                var payload = new
                {
                    title = model.Title.Trim(),
                    description = model.Description ?? ""
                };

                // Step 1: Create KRA in ERPNext.
                string response = await _erpNextService.PostAsync(
                    "/api/resource/KRA",
                    payload
                );

                JObject json = JObject.Parse(response);

                string erpName = json["data"]?["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpName))
                    throw new Exception(
                        "ERPNext did not return the saved KRA document name.");

                // Step 2: Fetch the saved ERPNext document.
                // Insert/update the corresponding HRMS record.
                int localId = await _kraService.SyncOneFromErpNextAsync(
                    _erpNextService,
                    erpName
                );

                TempData["Success"] =
                    "KRA saved successfully in ERPNext and HRMS: " + erpName;

                return RedirectToAction("KRADetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "KRA Save failed: " + ex.Message;

                return View("~/Views/HR/CreateKRA.cshtml", model);
            }
        }


