        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateKRA/{id:int}")]
        public async Task<ActionResult> UpdateKRA(int id, KRA model)
        {
            var existing = _kraService.GetById(id);

            if (existing == null)
                return NotFound();

            try
            {
                if (string.IsNullOrWhiteSpace(existing.ErpName))
                    throw new Exception("ERPNext KRA ID is missing.");

                if (model == null || string.IsNullOrWhiteSpace(model.Title))
                    throw new Exception("KRA Title is required.");

                var payload = new
                {
                    title = model.Title.Trim(),
                    description = model.Description ?? ""
                };

                string response = await _erpNextService.PutAsync(
                    "/api/resource/KRA/" + Uri.EscapeDataString(existing.ErpName),
                    payload
                );

                string erpName =
                    ExtractErpDocName(response) ?? existing.ErpName;

                int localId = await _kraService.SyncOneFromErpNextAsync(
                    _erpNextService,
                    erpName
                );

                TempData["Success"] =
                    "KRA updated in ERPNext and HRMS successfully.";

                return RedirectToAction("KRADetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "KRA update failed: " +
                    ExtractErpNextErrorMessage(ex.Message);

                return RedirectToAction("KRADetails", new { id });
            }
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteKRA/{id:int}")]
        public async Task<ActionResult> DeleteKRA(int id)
        {
            var model = _kraService.GetById(id);

            if (model == null)
                return NotFound();

            try
            {
                if (!string.IsNullOrWhiteSpace(model.ErpName))
                {
                    await _erpNextService.DeleteAsync(
                        "/api/resource/KRA/" + Uri.EscapeDataString(model.ErpName)
                    );
                }

                _kraService.MarkDeletedById(id);

                TempData["Success"] =
                    "KRA deleted from ERPNext and HRMS successfully.";

                return RedirectToAction("KRA");
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "KRA delete failed: " +
                    ExtractErpNextErrorMessage(ex.Message);

                return RedirectToAction("KRADetails", new { id });
            }
        }

