        [HttpPost]
        public async Task<ActionResult> CreateEmployeePromotion(
      EmployeePromotion model,
      string[] PropertyFieldNames,
      string[] PropertyNames,
      string[] CurrentValues,
      string[] NewValues)
        {
            var fieldNames = PropertyFieldNames != null ? new List<string>(PropertyFieldNames) : new List<string>();
            var props = PropertyNames != null ? new List<string>(PropertyNames) : new List<string>();
            var currents = CurrentValues != null ? new List<string>(CurrentValues) : new List<string>();
            var news = NewValues != null ? new List<string>(NewValues) : new List<string>();

            int newId = _employeePromotionService.Insert(model, fieldNames, props, currents, news);

            try
            {
                var saved = _employeePromotionService.GetById(newId);
                string erpNextId = await PushEmployeePromotionToErpNext(saved);

                if (!string.IsNullOrWhiteSpace(erpNextId))
                    _employeePromotionService.UpdateErpNextId(newId, erpNextId);
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Saved in HRMS but ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("EmployeePromotionDetails", new { id = newId });
        }

