        private async Task LoadEmployeePromotionDropdowns()
        {
            try
            {
                string empJson = await _erpNextService.GetAsync(
                    "/api/resource/Employee?fields=[\"name\",\"employee_name\",\"company\",\"salary_currency\",\"ctc\"]&filters=[[\"status\",\"=\",\"Active\"]]&limit_page_length=1000"
                );

                dynamic empParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(empJson);
                var employees = new List<object>();

                if (empParsed?.data != null)
                {
                    foreach (var item in empParsed.data)
                    {
                        employees.Add(new
                        {
                            name = item.name?.ToString(),
                            employee_name = item.employee_name?.ToString(),
                            company = item.company?.ToString(),
                            salary_currency = item.salary_currency?.ToString(),
                            ctc = item.ctc?.ToString()
                        });
                    }
                }

                ViewBag.Employees = employees;

                string companyJson = await _erpNextService.GetAsync(
                    "/api/resource/Company?fields=[\"name\"]&limit_page_length=1000"
                );

                ViewBag.Companies = ExtractNamesList(companyJson);
            }
            catch
            {
                ViewBag.Employees = new List<object>();
                ViewBag.Companies = new List<string>();
            }
        }

