        [HttpGet]
        [Route("HR/GetEmployeePromotionEmployeeFields")]
        public async Task<JsonResult> GetEmployeePromotionEmployeeFields()
        {
            try
            {
                string json = await _erpNextService.GetAsync(
                    "/api/method/frappe.desk.form.load.getdoctype?doctype=Employee&with_parent=1"
                );

                var parsed = Newtonsoft.Json.Linq.JObject.Parse(json);
                var docs = parsed["docs"] as Newtonsoft.Json.Linq.JArray;

                var fields = new List<object>();

                var excludeFields = new HashSet<string>
        {
            "naming_series",
            "employee",
            "first_name",
            "middle_name",
            "last_name",
            "marital_status",
            "ctc",
            "employee_name",
            "status",
            "image",
            "gender",
            "date_of_birth",
            "date_of_joining",
            "lft",
            "rgt",
            "old_parent"
        };

                var excludeTypes = new HashSet<string>
        {
            "HTML",
            "Section Break",
            "Column Break",
            "Button",
            "Read Only",
            "Tab Break",
            "Table"
        };

                if (docs != null)
                {
                    foreach (var doc in docs)
                    {
                        if (doc["name"]?.ToString() != "Employee")
                            continue;

                        var metaFields = doc["fields"] as Newtonsoft.Json.Linq.JArray;
                        if (metaFields == null)
                            continue;

                        foreach (var f in metaFields)
                        {
                            string fieldname = f["fieldname"]?.ToString();
                            string label = f["label"]?.ToString();
                            string fieldtype = f["fieldtype"]?.ToString();
                            string options = f["options"]?.ToString();
                            bool hidden = f["hidden"]?.ToString() == "1";
                            bool readOnly = f["read_only"]?.ToString() == "1";

                            if (string.IsNullOrWhiteSpace(fieldname))
                                continue;

                            if (string.IsNullOrWhiteSpace(label))
                                continue;

                            if (excludeFields.Contains(fieldname))
                                continue;

                            if (excludeTypes.Contains(fieldtype))
                                continue;

                            if (hidden || readOnly)
                                continue;

                            fields.Add(new
                            {
                                value = fieldname,
                                label = label + " (" + fieldname + ")",
                                fieldtype = fieldtype,
                                options = options
                            });
                        }
                    }
                }

                return Json(new { success = true, data = fields });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message, data = new List<object>() });
            }
        }

        [HttpGet]
        [Route("HR/GetEmployeePromotionFieldProperty")]
        public async Task<JsonResult> GetEmployeePromotionFieldProperty(string employee, string fieldname)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(employee))
                    return Json(new { success = false, message = "Please select Employee first." });

                if (string.IsNullOrWhiteSpace(fieldname))
                    return Json(new { success = false, message = "Please select property." });

                string response = await _erpNextService.PostMethodAsync(
                    "/api/method/hrms.hr.utils.get_employee_field_property",
                    new
                    {
                        employee = employee,
                        fieldname = fieldname
                    }
                );

                dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);
                var msg = parsed?.message;

                string value = msg?.value?.ToString();
                string datatype = msg?.datatype?.ToString();
                string label = msg?.label?.ToString();
                string options = msg?.options?.ToString();

                var optionList = new List<string>();

                if (datatype == "Select" && !string.IsNullOrWhiteSpace(options))
                {
                    optionList = options
                        .Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries)
                        .Select(x => x.Trim())
                        .Where(x => !string.IsNullOrWhiteSpace(x))
                        .ToList();
                }
                else if (datatype == "Link" && !string.IsNullOrWhiteSpace(options))
                {
                    try
                    {
                        string linkJson = await _erpNextService.GetAsync(
                            "/api/resource/" + Uri.EscapeDataString(options) + "?fields=[\"name\"]&limit_page_length=1000"
                        );

                        optionList = ExtractNamesList(linkJson);
                    }
                    catch
                    {
                        optionList = new List<string>();
                    }
                }

                return Json(new
                {
                    success = true,
                    value = value,
                    datatype = datatype,
                    label = label,
                    options = options,
                    optionList = optionList
                });
            }
            catch (Exception ex)
            {
                return Json(new { success = false, message = ex.Message });
            }
        }




















        [HttpPost]
        [Route("HR/NewShiftRequest")]
        public async Task<ActionResult>
            NewShiftRequest(
                ShiftRequest model)
        {
            try
            {
                // ============================================
                // REQUIRED
                // ============================================

                if (string.IsNullOrWhiteSpace(
                    model.ShiftType))
                {
                    throw new Exception(
                        "Shift Type is required."
                    );
                }


                if (string.IsNullOrWhiteSpace(
                    model.Employee))
                {
                    throw new Exception(
                        "Employee is required."
                    );
                }


                if (string.IsNullOrWhiteSpace(
                    model.Company))
                {
                    throw new Exception(
                        "Company is required."
                    );
                }


                if (string.IsNullOrWhiteSpace(
                    model.Approver))
                {
                    throw new Exception(
                        "Approver is required."
                    );
                }


                if (!model.FromDate.HasValue)
                {
                    throw new Exception(
                        "From Date is required."
                    );
                }


                // ============================================
                // DATE VALIDATION
                // ============================================

                if (
                    model.ToDate.HasValue &&
                    model.ToDate.Value.Date <
                    model.FromDate.Value.Date
                )
                {
                    throw new Exception(
                        "To Date cannot be before From Date."
                    );
                }


                // ============================================
                // GET EMPLOYEE FROM ERP
                // ============================================

                string employeeJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee/" +
                        Uri.EscapeDataString(
                            model.Employee
                        )
                    );


                JObject employeeObject =
                    JObject.Parse(
                        employeeJson
                    );


                JToken employee =
                    employeeObject["data"];


                if (employee == null)
                {
                    throw new Exception(
                        "Employee does not exist in ERPNext."
                    );
                }


                string employeeStatus =
                    employee["status"]
                        ?.ToString()
                    ?? "";


                if (!string.Equals(
                    employeeStatus,
                    "Active",
                    StringComparison.OrdinalIgnoreCase))
                {
                    throw new Exception(
                        "Only Active Employees can create Shift Requests."
                    );
                }


                model.EmployeeName =
                    employee["employee_name"]
                        ?.ToString()
                    ?? "";


                model.Department =
                    employee["department"]
                        ?.ToString()
                    ?? "";


                string employeeCompany =
                    employee["company"]
                        ?.ToString()
                    ?? "";


                if (!string.IsNullOrWhiteSpace(
                    employeeCompany))
                {
                    model.Company =
                        employeeCompany;
                }


                string defaultShift =
                    employee["default_shift"]
                        ?.ToString()
                    ?? "";


                // ============================================
                // ERP rule: default shift cannot be requested
                // ============================================

                if (
                    !string.IsNullOrWhiteSpace(
                        defaultShift
                    ) &&
                    string.Equals(
                        defaultShift,
                        model.ShiftType,
                        StringComparison.OrdinalIgnoreCase
                    )
                )
                {
                    throw new Exception(
                        "You cannot request your Default Shift: "
                        + defaultShift
                        + "."
                    );
                }


                // ============================================
                // CREATE PAYLOAD
                //
                // Do NOT create local record first.
                // ERP is authoritative validator.
                // ============================================

                var payload =
                    new Dictionary<string, object>
                    {
                {
                    "shift_type",
                    model.ShiftType
                },

                {
                    "employee",
                    model.Employee
                },

                {
                    "company",
                    model.Company
                },

                {
                    "approver",
                    model.Approver
                },

                {
                    "status",
                    string.IsNullOrWhiteSpace(
                        model.Status
                    )
                        ? "Draft"
                        : model.Status
                },

                {
                    "from_date",
                    model.FromDate.Value
                        .ToString(
                            "yyyy-MM-dd"
                        )
                }
                    };


                if (model.ToDate.HasValue)
                {
                    payload.Add(
                        "to_date",
                        model.ToDate.Value
                            .ToString(
                                "yyyy-MM-dd"
                            )
                    );
                }


                // ============================================
                // ERP FIRST
                // ============================================

                string responseJson =
                    await _erpNextService.PostAsync(
                        "/api/resource/Shift%20Request",
                        payload
                    );


                JObject response =
                    JObject.Parse(
                        responseJson
                    );


                string erpId =
                    response["data"]?["name"]
                        ?.ToString();


                if (string.IsNullOrWhiteSpace(
                    erpId))
                {
                    throw new Exception(
                        "ERPNext did not return Shift Request ID."
                    );
                }


                // ============================================
                // READ ERP DOCUMENT BACK
                // ============================================

                string detailJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Shift%20Request/" +
                        Uri.EscapeDataString(
                            erpId
                        )
                    );


                JObject detailObject =
                    JObject.Parse(
                        detailJson
                    );


                ShiftRequest local =
                    MapErpShiftRequest(
                        detailObject["data"]
                    );


                int localId =
                    _shiftRequestService
                        .InsertOrUpdate(
                            local
                        );


                TempData["Success"] =
                    "Shift Request created successfully. ERPNext Ref: "
                    + erpId;


                return RedirectToAction(
                    "ShiftRequestDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    ExtractErpNextErrorMessage(
                        ex.Message
                    );


                return RedirectToAction(
                    "NewShiftRequest"
                );
            }
        }



        private ShiftRequest MapErpShiftRequest(
    JToken doc)
        {
            if (doc == null)
                return null;


            var model =
                new ShiftRequest
                {
                    ShiftRequestCode =
                        doc["name"]
                            ?.ToString()
                        ?? "",

                    ShiftType =
                        doc["shift_type"]
                            ?.ToString()
                        ?? "",

                    Company =
                        doc["company"]
                            ?.ToString()
                        ?? "",

                    Employee =
                        doc["employee"]
                            ?.ToString()
                        ?? "",

                    EmployeeName =
                        doc["employee_name"]
                            ?.ToString()
                        ?? "",

                    Department =
                        doc["department"]
                            ?.ToString()
                        ?? "",

                    Approver =
                        doc["approver"]
                            ?.ToString()
                        ?? "",

                    DocStatus =
                        doc["docstatus"]
                            ?.ToObject<int>()
                        ?? 0,

                    AmendedFrom =
                        doc["amended_from"]
                            ?.ToString()
                        ?? ""
                };

            model.Status = model.DocStatus == 1
                ? "Submitted"
                : model.DocStatus == 2
                    ? "Cancelled"
                    : doc["status"]?.ToString() ?? "Draft";


            DateTime fromDate;

            if (
                DateTime.TryParse(
                    doc["from_date"]
                        ?.ToString(),
                    out fromDate
                )
            )
            {
                model.FromDate =
                    fromDate;
            }


            DateTime toDate;

            if (
                DateTime.TryParse(
                    doc["to_date"]
                        ?.ToString(),
                    out toDate
                )
            )
            {
                model.ToDate =
                    toDate;
            }


            return model;
        }






















