        [HttpGet]
        [Route("HR/GetShiftRequestEmployeeDetails")]
        public async Task<JsonResult>
    GetShiftRequestEmployeeDetails(
        string employee)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(
                    employee))
                {
                    return Json(
                        new
                        {
                            success = false,
                            message =
                                "Employee is required."
                        }
                    );
                }


                // ============================================
                // Get employee
                // ============================================

                string employeeJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee/" +
                        Uri.EscapeDataString(
                            employee
                        )
                    );


                JObject employeeObject =
                    JObject.Parse(
                        employeeJson
                    );


                JToken doc =
                    employeeObject["data"];


                if (doc == null)
                {
                    return Json(
                        new
                        {
                            success = false,
                            message =
                                "Employee not found."
                        }
                    );
                }


                string employeeName =
                    doc["employee_name"]
                        ?.ToString()
                    ?? "";


                string company =
                    doc["company"]
                        ?.ToString()
                    ?? "";


                string department =
                    doc["department"]
                        ?.ToString()
                    ?? "";


                string employeeApprover =
                    doc["shift_request_approver"]
                        ?.ToString()
                    ?? "";


                string defaultShift =
                    doc["default_shift"]
                        ?.ToString()
                    ?? "";


                var approvers =
                    new HashSet<string>(
                        StringComparer.OrdinalIgnoreCase
                    );


                if (!string.IsNullOrWhiteSpace(
                    employeeApprover))
                {
                    approvers.Add(
                        employeeApprover
                    );
                }


                // ============================================
                // Department Shift Request Approvers
                // ============================================

                if (!string.IsNullOrWhiteSpace(
                    department))
                {
                    try
                    {
                        string departmentJson =
                            await _erpNextService.GetAsync(
                                "/api/resource/Department/" +
                                Uri.EscapeDataString(
                                    department
                                )
                            );


                        JObject departmentObject =
                            JObject.Parse(
                                departmentJson
                            );


                        JArray departmentApprovers =
                            departmentObject["data"]
                                ?["shift_request_approver"]
                            as JArray;


                        if (departmentApprovers != null)
                        {
                            foreach (
                                JToken row
                                in departmentApprovers
                            )
                            {
                                string approver =
                                    row["approver"]
                                        ?.ToString();


                                if (!string.IsNullOrWhiteSpace(
                                    approver))
                                {
                                    approvers.Add(
                                        approver
                                    );
                                }
                            }
                        }
                    }
                    catch
                    {
                        // Employee-level approver can still be used.
                    }
                }


                return Json(
                    new
                    {
                        success = true,

                        employeeName =
                            employeeName,

                        company =
                            company,

                        department =
                            department,

                        defaultShift =
                            defaultShift,

                        approvers =
                            approvers.ToList()
                    }
                );
            }
            catch (Exception ex)
            {
                return Json(
                    new
                    {
                        success = false,
                        message = ex.Message
                    }
                );
            }
        }

        [HttpPost]
        public async Task<ActionResult> SyncEmployeePromotionsFromErpNext()
        {
            try
            {
                string listJson = await _erpNextService.GetAsync(
                    "/api/resource/Employee%20Promotion?fields=[\"name\"]&limit_page_length=1000"
                );

                dynamic listParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(listJson);
                int count = 0;

                if (listParsed?.data != null)
                {
                    foreach (var row in listParsed.data)
                    {
                        string erpName = row.name?.ToString();

                        if (string.IsNullOrWhiteSpace(erpName))
                            continue;

                        string detailJson = await _erpNextService.GetAsync(
                            "/api/resource/Employee%20Promotion/" + Uri.EscapeDataString(erpName)
                        );

                        dynamic detailParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(detailJson);
                        var d = detailParsed?.data;

                        if (d == null)
                            continue;

                        decimal? currentCtc = null;

                        if (d.current_ctc != null)
                        {
                            decimal tempCtc;

                            if (decimal.TryParse(d.current_ctc.ToString(), out tempCtc))
                            {
                                currentCtc = tempCtc;
                            }
                        }

                        var model = new EmployeePromotion
                        {
                            ErpNextId = erpName,
                            Employee = d.employee?.ToString(),
                            EmployeeName = d.employee_name?.ToString(),
                            PromotionDate = d.promotion_date != null
                                ? Convert.ToDateTime(d.promotion_date.ToString())
                                : DateTime.Now,
                            SalaryCurrency = d.salary_currency?.ToString() ?? "INR",
                            Company = d.company?.ToString(),
                            CurrentCTC = currentCtc
                        };

                        var fieldNames = new List<string>();
                        var properties = new List<string>();
                        var currents = new List<string>();
                        var news = new List<string>();

                        if (d.promotion_details != null)
                        {
                            foreach (var item in d.promotion_details)
                            {
                                fieldNames.Add(item.fieldname?.ToString());
                                properties.Add(item.property?.ToString());
                                currents.Add(item.current?.ToString());
                                news.Add(item.@new?.ToString());
                            }
                        }

                        _employeePromotionService.UpsertFromErpNext(
                            model,
                            fieldNames,
                            properties,
                            currents,
                            news
                        );

                        count++;
                    }
                }

                TempData["Success"] = count + " Employee Promotions synced from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "ERPNext to HRMS sync failed: " + ex.Message;
            }

            return RedirectToAction("EmployeePromotion");
        }



        [HttpPost]
        public async Task<ActionResult> SyncAppraisalCyclesFromErpNext()
        {
