                                empTemplates.Add(item.appraisal_template?.ToString());
                                empDepts.Add(item.department?.ToString());
                                empDesigs.Add(item.designation?.ToString());
                                empBranches.Add(item.branch?.ToString());
                            }
                        }

                        _appraisalCycleService.UpsertFromErpNext(
                            model,
                            empCodes,
                            empNames,
                            empTemplates,
                            empDepts,
                            empDesigs,
                            empBranches
                        );

                        count++;
                    }
                }

                TempData["Success"] = count + " Appraisal Cycles synced from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "ERPNext to HRMS sync failed: " + ex.Message;
            }

            return RedirectToAction("AppraisalCycle");
        }

        private string StripHtml(string html)
        {
            if (string.IsNullOrWhiteSpace(html))
                return string.Empty;

            string text = System.Text.RegularExpressions.Regex.Replace(html, "<.*?>", string.Empty);
            return System.Net.WebUtility.HtmlDecode(text).Trim();
        }




        private async Task<string> PushAppraisalCycleToErpNext(AppraisalCycle model)
        {
            var appraisees = new List<object>();

            if (model.Employees != null)
            {
                foreach (var e in model.Employees)
                {
                    appraisees.Add(new
                    {
                        employee = e.Employee,
                        employee_name = e.EmployeeName,
                        appraisal_template = e.AppraisalTemplate,
                        department = e.Department,
                        designation = e.Designation,
                        branch = e.Branch
                    });
                }
            }

            var payload = new
            {
                cycle_name = model.CycleName,
                company = model.Company,
                status = model.Status,
                start_date = model.StartDate.ToString("yyyy-MM-dd"),
                end_date = model.EndDate.ToString("yyyy-MM-dd"),
                description = model.Description,
                kra_evaluation_method = model.KRAEvaluationMethod,
                calculate_final_score_based_on_formula = model.CalculateFinalScoreFormula ? 1 : 0,
                final_score_formula = model.FinalScoreFormula,
                branch = model.Branch,
                department = model.Department,
                designation = model.Designation,
                appraisees = appraisees
            };

            if (!string.IsNullOrWhiteSpace(model.ErpNextId))
            {
                await _erpNextService.PutAsync(
                    "/api/resource/Appraisal%20Cycle/" + Uri.EscapeDataString(model.ErpNextId),
                    payload
                );

                return model.ErpNextId;
            }

            string response = await _erpNextService.PostAsync("/api/resource/Appraisal%20Cycle", payload);
            dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);

            return parsed?.data?.name?.ToString();
        }













        [HttpPost]
        [Route("HR/SyncShiftRequestsFromErpNext")]
        public async Task<ActionResult>
            SyncShiftRequestsFromErpNext()
        {
            try
            {
                string listJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Shift%20Request" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=5000"
                    );


                JObject listObject =
                    JObject.Parse(
                        listJson
                    );


                JArray rows =
                    listObject["data"]
                    as JArray;


                int inserted = 0;
                int updated = 0;
                int failed = 0;
                var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);


                if (rows != null)
                {
                    foreach (JToken row in rows)
                    {
                        try
                        {
                            string erpId =
                                row["name"]
                                    ?.ToString();


                            if (string.IsNullOrWhiteSpace(
                                erpId))
                            {
                                continue;
                            }
                            erpIds.Add(erpId);


                            bool exists =
                                _shiftRequestService
                                    .GetByErpNextId(
                                        erpId
                                    ) != null;


                            string detailJson =
                                await _erpNextService.GetAsync(
                                    "/api/resource/Shift%20Request/" +
                                    Uri.EscapeDataString(
                                        erpId
                                    )
                                );


                            JObject detailObject =
                                JObject.Parse(
                                    detailJson
                                );


                            ShiftRequest model =
                                MapErpShiftRequest(
                                    detailObject["data"]
                                );


                            if (model == null)
                            {
                                failed++;
                                continue;
                            }


                            _shiftRequestService
                                .InsertOrUpdate(
                                    model
                                );


                            if (exists)
                                updated++;
                            else
                                inserted++;
                        }
                        catch (Exception recordEx)
                        {
                            failed++;

                            System.Diagnostics.Debug.WriteLine(
                                "Shift Request sync error: "
                                + recordEx.Message
                            );
                        }
                    }
                }


                TempData["Success"] =
                    "Shift Request sync completed. New: "
                    + inserted
                    + ", Updated: "
                    + updated
                    + ", Failed: "
                    + failed
                    + ".";

                SoftDeleteMissingErpDocuments("ShiftRequests", "ShiftRequestCode", erpIds);
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Failed to sync Shift Requests from ERPNext: "
                    + ex.Message;
            }


            return RedirectToAction(
                "ShiftRequest"
            );
        }

