        [HttpPost]
        public async Task<ActionResult> CreateEnergyPointSettings(
     EnergyPointSettings model,
     string[] LevelNames,
     string[] Roles,
     int[] ReviewPointsArr)
        {
            var levelNames = LevelNames != null ? new List<string>(LevelNames) : new List<string>();
            var roles = Roles != null ? new List<string>(Roles) : new List<string>();
            var points = ReviewPointsArr != null ? new List<int>(ReviewPointsArr) : new List<int>();

            _energyPointSettingsService.SaveSettings(model, levelNames, roles, points);

            try
            {
                var saved = _energyPointSettingsService.GetSettings();
                await PushEnergyPointSettingsToErpNext(saved);
                TempData["Success"] = "Energy Point Settings saved and synced to ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Saved in HRMS but ERPNext sync failed: " + ex.Message;
            }

            return RedirectToAction("CreateEnergyPointSettings");
        }

        [HttpPost]
        public async Task<ActionResult> SyncEnergyPointSettingsFromErpNext()
        {
            try
            {
                string json = await _erpNextService.GetAsync(
                    "/api/resource/Energy%20Point%20Settings/Energy%20Point%20Settings"
                );

                dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(json);
                var d = parsed?.data;

                if (d == null)
                    throw new Exception("Energy Point Settings data not found in ERPNext.");

                var model = new EnergyPointSettings
                {
                    Enabled = d.enabled != null && d.enabled.ToString() == "1",
                    PointAllocationPeriodicity = d.point_allocation_periodicity?.ToString() ?? "Weekly",
                    LastPointAllocationDate = d.last_point_allocation_date == null ||
                                              string.IsNullOrWhiteSpace(d.last_point_allocation_date.ToString())
                        ? null
                        : Convert.ToDateTime(d.last_point_allocation_date.ToString())
                };

                var levelNames = new List<string>();
                var roles = new List<string>();
                var points = new List<int>();

                if (d.review_levels != null)
                {
                    foreach (var row in d.review_levels)
                    {
                        levelNames.Add(row.level_name?.ToString() ?? string.Empty);
                        roles.Add(row.role?.ToString() ?? string.Empty);

                        int reviewPoint = 0;
                        int.TryParse(row.review_points?.ToString(), out reviewPoint);
                        points.Add(reviewPoint);
                    }
                }

                _energyPointSettingsService.SaveSettings(model, levelNames, roles, points);

                TempData["Success"] = "Energy Point Settings synced from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "ERPNext to HRMS sync failed: " + ex.Message;
            }

            return RedirectToAction("EnergyPointSettings");
        }

        [HttpPost]
        public async Task<ActionResult> GiveReviewPoints(string UserId, int Points)
        {
            if (string.IsNullOrWhiteSpace(UserId))
            {
                TempData["Error"] = "Please select user.";
                return RedirectToAction("EnergyPointSettings");
            }

            if (Points <= 0)
            {
                TempData["Error"] = "Points must be greater than 0.";
                return RedirectToAction("EnergyPointSettings");
            }

            try
            {
                await _erpNextService.PostMethodAsync(
                    "/api/method/frappe.social.doctype.energy_point_log.energy_point_log.add_review_points",
                    new
                    {
                        user = UserId,
                        points = Points
                    }
                );

                TempData["Success"] = "Review points submitted successfully.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Give Review Points failed: " + ex.Message;
            }

            return RedirectToAction("EnergyPointSettings");
        }

