        private async Task PushEnergyPointSettingsToErpNext(EnergyPointSettings model)
        {
            var reviewLevels = new List<object>();

            if (model.ReviewLevels != null)
            {
                foreach (var row in model.ReviewLevels)
                {
                    if (string.IsNullOrWhiteSpace(row.LevelName))
                        continue;

                    reviewLevels.Add(new
                    {
                        level_name = row.LevelName,
                        role = row.Role,
                        review_points = row.ReviewPoints
                    });
                }
            }

            var payload = new
            {
                enabled = model.Enabled ? 1 : 0,
                review_levels = reviewLevels,
                point_allocation_periodicity = model.PointAllocationPeriodicity,
                last_point_allocation_date = model.LastPointAllocationDate?.ToString("yyyy-MM-dd")
            };

            await _erpNextService.PutAsync(
                "/api/resource/Energy%20Point%20Settings/Energy%20Point%20Settings",
                payload
            );
        }












