        [HttpGet]
        public async Task<JsonResult> GetEnergyPointRuleDocFields(string doctype)
        {
            if (string.IsNullOrWhiteSpace(doctype))
                return Json(new List<object>());

            try
            {
                string json = await _erpNextService.GetAsync(
                    "/api/method/frappe.desk.form.load.getdoctype?doctype=" +
                    Uri.EscapeDataString(doctype) +
                    "&with_parent=1"
                );

                dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(json);
                var fields = new List<object>();

                foreach (var doc in parsed.docs)
                {
                    if (doc.name?.ToString() != doctype)
                        continue;

                    foreach (var field in doc.fields)
                    {
                        string fieldname = field.fieldname?.ToString();
                        string label = field.label?.ToString();
                        string fieldtype = field.fieldtype?.ToString();

                        if (string.IsNullOrWhiteSpace(fieldname))
                            continue;

                        if (fieldtype == "Int" ||
                            fieldtype == "Float" ||
                            fieldtype == "Currency" ||
                            fieldtype == "Percent")
                        {
                            fields.Add(new
                            {
                                value = fieldname,
                                text = string.IsNullOrWhiteSpace(label)
                                    ? fieldname
                                    : label + " (" + fieldname + ")"
                            });
                        }
                    }
                }

                return Json(fields);
            }
            catch
            {
                return Json(new List<object>());
            }
        }




