        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> CreateAppraisalTemplate(
            AppraisalTemplate model,
            string[] KraNames,
            decimal[] KraWeightages,
            string[] CriteriaNames,
            decimal[] CriteriaWeightages)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(model.AppraisalTemplateTitle))
                    throw new Exception("Appraisal Template Title is required.");

                var goals = new List<object>();
                var criteria = new List<object>();

                for (int i = 0; i < (KraNames?.Length ?? 0); i++)
                {
                    if (string.IsNullOrWhiteSpace(KraNames[i]))
                        continue;

                    decimal weight = i < (KraWeightages?.Length ?? 0)
                        ? KraWeightages[i] : 0;

                    if (weight < 0 || weight > 100)
                        throw new Exception("KRA weightage must be between 0 and 100.");

                    goals.Add(new
                    {
                        key_result_area = KraNames[i].Trim(),
                        per_weightage = weight
                    });
                }

                for (int i = 0; i < (CriteriaNames?.Length ?? 0); i++)
                {
                    if (string.IsNullOrWhiteSpace(CriteriaNames[i]))
                        continue;

                    decimal weight = i < (CriteriaWeightages?.Length ?? 0)
                        ? CriteriaWeightages[i] : 0;

                    if (weight < 0 || weight > 100)
                        throw new Exception("Criteria weightage must be between 0 and 100.");

                    criteria.Add(new
                    {
                        criteria = CriteriaNames[i].Trim(),
                        per_weightage = weight
                    });
                }

                if (goals.Count == 0)
                    throw new Exception("Add at least one KRA.");

                var payload = new
                {
                    template_title = model.AppraisalTemplateTitle.Trim(),
                    description = model.Description ?? "",
                    goals = goals,
                    rating_criteria = criteria
                };

                // STEP 1: Save in ERPNext first.
                // ERPNext performs its own document validations.
                string response = await _erpNextService.PostAsync(
                    "/api/resource/Appraisal%20Template",
                    payload
                );

                JObject parsed = JObject.Parse(response);

                string erpName = parsed["data"]?["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpName))
                    throw new Exception("ERPNext did not return the saved document name.");

                // STEP 2: Fetch the saved document and sync it into local HRMS.
                await _appraisalTemplateService.SyncOneFromErpNextAsync(
                    _erpNextService,
                    erpName
                );

                TempData["Success"] =
                    "Appraisal Template saved in ERPNext and HRMS: " + erpName;

                int localId = _appraisalTemplateService.GetLocalIdByErpName(erpName);

                return localId > 0
                    ? RedirectToAction("AppraisalTemplateDetails", new { id = localId })
                    : RedirectToAction("AppraisalTemplate");
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Save failed: " + ExtractErpNextErrorMessage(ex.Message);

                return View(
                    "~/Views/HR/CreateAppraisalTemplate.cshtml",
                    model
                );
            }
        }



