        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateAppraisalTemplate/{id:int}")]
        public async Task<ActionResult> UpdateAppraisalTemplate(
            int id,
            AppraisalTemplate model,
            string[] KraNames,
            decimal[] KraWeightages,
            string[] CriteriaNames,
            decimal[] CriteriaWeightages)
        {
            var existing = _appraisalTemplateService.GetById(id);

            if (existing == null)
                return NotFound();

            try
            {
                if (string.IsNullOrWhiteSpace(existing.ErpName))
                    throw new Exception("ERPNext Appraisal Template ID is missing.");

                if (string.IsNullOrWhiteSpace(model.AppraisalTemplateTitle))
                    throw new Exception("Appraisal Template Title is required.");

                var goals = BuildAppraisalTemplateChildRows(
                    KraNames,
                    KraWeightages,
                    "KRA",
                    "key_result_area");

                var criteria = BuildAppraisalTemplateChildRows(
                    CriteriaNames,
                    CriteriaWeightages,
                    "Criteria",
                    "criteria");

                if (goals.Count == 0)
                    throw new Exception("Add at least one KRA.");

                var payload = new
                {
                    template_title = model.AppraisalTemplateTitle.Trim(),
                    description = model.Description ?? "",
                    goals,
                    rating_criteria = criteria
                };

                string response = await _erpNextService.PutAsync(
                    "/api/resource/Appraisal%20Template/" +
                    Uri.EscapeDataString(existing.ErpName),
                    payload
                );

                string erpName =
                    ExtractErpDocName(response) ?? existing.ErpName;

                await _appraisalTemplateService.SyncOneFromErpNextAsync(
                    _erpNextService,
                    erpName
                );

                int localId = _appraisalTemplateService.GetLocalIdByErpName(erpName);

                TempData["Success"] =
                    "Appraisal Template updated in ERPNext and HRMS.";

                return RedirectToAction(
                    "AppraisalTemplateDetails",
                    new { id = localId > 0 ? localId : id });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Update failed: " +
                    ExtractErpNextErrorMessage(ex.Message);

                return RedirectToAction("AppraisalTemplateDetails", new { id });
            }
        }

