        private List<object> BuildAppraisalTemplateChildRows(
            string[] names,
            decimal[] weightages,
            string label,
            string erpFieldName)
        {
            var rows = new List<object>();

            for (int i = 0; i < (names?.Length ?? 0); i++)
            {
                if (string.IsNullOrWhiteSpace(names[i]))
                    continue;

                decimal weight = i < (weightages?.Length ?? 0)
                    ? weightages[i]
                    : 0m;

                if (weight < 0 || weight > 100)
                    throw new Exception(label + " weightage must be between 0 and 100.");

                if (erpFieldName == "key_result_area")
                {
                    rows.Add(new
                    {
                        key_result_area = names[i].Trim(),
                        per_weightage = weight
                    });
                }
                else
                {
                    rows.Add(new
                    {
                        criteria = names[i].Trim(),
                        per_weightage = weight
                    });
                }
            }

            return rows;
        }

