        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/StartAppraisalCycle/{id:int}")]
        public async Task<ActionResult> StartAppraisalCycle(int id)
        {
            var cycle = _appraisalCycleService.GetById(id);
            if (cycle == null) return NotFound();

            if (!string.Equals(cycle.Status, "Not Started", StringComparison.OrdinalIgnoreCase))
            {
                TempData["Error"] = "Only an Appraisal Cycle with status Not Started can be started.";
                return RedirectToAction("AppraisalCycleDetails", new { id });
            }

            if (string.IsNullOrWhiteSpace(cycle.ErpNextId))
            {
                TempData["Error"] = "The ERPNext Appraisal Cycle ID is missing. Refresh the cycle from ERPNext first.";
                return RedirectToAction("AppraisalCycleDetails", new { id });
            }

            var appraisees = cycle.Employees
                .Where(x => !string.IsNullOrWhiteSpace(x.Employee))
                .ToList();

            if (!appraisees.Any())
            {
                TempData["Error"] = "Add at least one employee in Applicable For before starting this Appraisal Cycle.";
                return RedirectToAction("AppraisalCycleDetails", new { id });
            }

            try
            {
                await SetAppraisalCycleStatusInErpNext(cycle, "In Progress");

                foreach (var appraisee in appraisees)
                    await EnsureAppraisalExistsForCycleEmployee(cycle, appraisee);

                _appraisalCycleService.UpdateStatus(id, "In Progress");
                TempData["Success"] = "Appraisal Cycle started and Appraisals were created for " + appraisees.Count + " employee(s).";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Unable to start the Appraisal Cycle: " + ExtractErpNextErrorMessage(ex.Message);
            }

            return RedirectToAction("AppraisalCycleDetails", new { id });
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/CompleteAppraisalCycle/{id:int}")]
        public async Task<ActionResult> CompleteAppraisalCycle(int id)
        {
            var cycle = _appraisalCycleService.GetById(id);
            if (cycle == null) return NotFound();

            if (!string.Equals(cycle.Status, "In Progress", StringComparison.OrdinalIgnoreCase))
            {
                TempData["Error"] = "Only an Appraisal Cycle in progress can be marked as completed.";
                return RedirectToAction("AppraisalCycleDetails", new { id });
            }

            try
            {
                // Refresh statuses first so ERPNext remains the source of truth for submission.
                await PullAppraisalsFromErpNext();

                string cycleName = string.IsNullOrWhiteSpace(cycle.ErpNextId)
                    ? cycle.CycleName
                    : cycle.ErpNextId;
                var appraisals = _appraisalService.GetAll(null, null, null, cycleName, null);
                var pendingEmployees = cycle.Employees
                    .Where(x => !string.IsNullOrWhiteSpace(x.Employee))
                    .Where(employee => !appraisals.Any(appraisal =>
                        string.Equals(appraisal.Employee, employee.Employee, StringComparison.OrdinalIgnoreCase)
                        && appraisal.DocStatus == 1))
                    .Select(employee => string.IsNullOrWhiteSpace(employee.EmployeeName)
                        ? employee.Employee
                        : employee.EmployeeName + " (" + employee.Employee + ")")
                    .ToList();

                if (pendingEmployees.Any())
                {
                    TempData["Error"] = "Submit the Appraisal for every applicable employee before marking this cycle as completed. Pending: "
                        + string.Join(", ", pendingEmployees) + ".";
                    return RedirectToAction("AppraisalCycleDetails", new { id });
                }

                await SetAppraisalCycleStatusInErpNext(cycle, "Completed");
                _appraisalCycleService.UpdateStatus(id, "Completed");
                TempData["Success"] = "Appraisal Cycle marked as completed.";
            }
            catch (Exception ex)
            {
                TempData["Error"] = "Unable to complete the Appraisal Cycle: " + ExtractErpNextErrorMessage(ex.Message);
            }

            return RedirectToAction("AppraisalCycleDetails", new { id });
        }

        private async Task SetAppraisalCycleStatusInErpNext(AppraisalCycle cycle, string status)
        {
            await _erpNextService.PutAsync(
                "/api/resource/Appraisal%20Cycle/" + Uri.EscapeDataString(cycle.ErpNextId),
                new Dictionary<string, object> { ["status"] = status });
        }

        private async Task EnsureAppraisalExistsForCycleEmployee(
            AppraisalCycle cycle,
            AppraisalCycleEmployee employee)
        {
            string filters = JsonConvert.SerializeObject(new object[]
            {
                new object[] { "Appraisal", "employee", "=", employee.Employee },
                new object[] { "Appraisal", "appraisal_cycle", "=", cycle.ErpNextId }
            });
            string existingJson = await _erpNextService.GetAsync(
                "/api/resource/Appraisal?fields=[\"name\"]&limit_page_length=1&filters="
                + Uri.EscapeDataString(filters));
            var existingRows = JObject.Parse(existingJson)["data"] as JArray;
            string appraisalId = existingRows?.FirstOrDefault()?["name"]?.ToString();

            if (string.IsNullOrWhiteSpace(appraisalId))
            {
                var payload = new JObject
                {
                    ["doctype"] = "Appraisal",
                    ["employee"] = employee.Employee,
                    ["company"] = cycle.Company,
                    ["appraisal_cycle"] = cycle.ErpNextId,
                    ["appraisal_template"] = employee.AppraisalTemplate,
                    ["rate_goals_manually"] = string.Equals(cycle.KRAEvaluationMethod, "Manual Rating", StringComparison.OrdinalIgnoreCase) ? 1 : 0
                };
                string createdJson = await _erpNextService.PostAsync("/api/resource/Appraisal", payload.ToString());
                appraisalId = JObject.Parse(createdJson)["data"]?["name"]?.ToString();
            }

            if (string.IsNullOrWhiteSpace(appraisalId))
                throw new Exception("ERPNext did not return an Appraisal ID for " + employee.Employee + ".");

            string detailJson = await _erpNextService.GetAsync(
                "/api/resource/Appraisal/" + Uri.EscapeDataString(appraisalId));
            var doc = JObject.Parse(detailJson)["data"];
            if (doc == null)
                throw new Exception("ERPNext could not load Appraisal " + appraisalId + ".");

            _appraisalService.InsertOrUpdate(MapErpAppraisal(doc));
        }


