        [HttpPost]
        [Route("HR/SyncGoalsFromErpNext")]
        public async Task<ActionResult>
            SyncGoalsFromErpNext()
        {
            try
            {
                var result = await SyncGoalsFromErpNextInternal();

                TempData["Success"] =
                    "Goal sync completed. New: "
                    + result.inserted
                    + ", Updated: "
                    + result.updated
                    + ", Failed: "
                    + result.failed
                    + ".";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Goal sync failed: "
                    + CleanGoalErpError(ex.Message);
            }


            return RedirectToAction(
                "Goal"
            );
