        private async Task<(int inserted, int updated, int failed)> SyncGoalsFromErpNextInternal()
        {
            string listJson =
                await _erpNextService.GetAsync(
                    "/api/resource/Goal" +
                    "?fields=[\"name\"]" +
                    "&limit_page_length=5000"
                );

            JObject listObject = JObject.Parse(listJson);
            JArray rows = listObject["data"] as JArray;

            int inserted = 0;
            int updated = 0;
            int failed = 0;
            var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (rows != null)
            {
                foreach (JToken row in rows)
                {
                    try
                    {
                        string erpId = row["name"]?.ToString();

                        if (string.IsNullOrWhiteSpace(erpId))
                            continue;

                        erpIds.Add(erpId);

                        bool exists = _goalService.GetByErpNextId(erpId) != null;
                        await SyncOneGoalFromErpNext(erpId);

                        if (exists)
                            updated++;
                        else
                            inserted++;
                    }
                    catch
                    {
                        failed++;
                    }
                }
            }

            _goalService.MarkMissingErpRecordsDeleted(erpIds);

            return (inserted, updated, failed);
        }

        private async Task<int> SyncOneGoalFromErpNext(string erpId)
        {
            string detailJson =
                await _erpNextService.GetAsync(
                    "/api/resource/Goal/" +
                    Uri.EscapeDataString(erpId)
                );

            JObject detailObject = JObject.Parse(detailJson);
            Goal goal = MapErpGoal(detailObject["data"]);

            if (goal == null)
                throw new Exception("Goal not found in ERPNext.");

            return _goalService.InsertOrUpdate(goal);
        }




        // POST: HR/SyncGoalsToServerToErpNext
        // POST: HR/SyncGoalsToServerToErpNext
        [HttpPost]
        [Route("HR/SyncGoalsToServerToErpNext")]
        public async Task<ActionResult> SyncGoalsToServerToErpNext()
        {
            int successCount = 0;
            int failCount = 0;

            try
            {
                var unsynced = _goalService.GetUnsynced();

                foreach (var model in unsynced)
                {
                    try
                    {
                        if (!string.IsNullOrWhiteSpace(model.Employee))
                        {
                            await EnsureDocExistsAsync("Employee", model.Employee);
                        }

                        string goalNameVal = string.IsNullOrWhiteSpace(model.GoalName) ? "New Goal" : model.GoalName;

                        string parentGoalVal = null;
                        if (!string.IsNullOrWhiteSpace(model.ParentGoal))
                        {
                            try
                            {
                                var parentCheck = await _erpNextService.GetAsync($"/api/resource/Goal/{Uri.EscapeDataString(model.ParentGoal)}");
                                dynamic parentParsed = JsonConvert.DeserializeObject(parentCheck);
                                if (parentParsed?.data != null) parentGoalVal = model.ParentGoal.Trim();
                            }
                            catch { parentGoalVal = null; }
                        }

                        var payload = new Dictionary<string, object>
                {
                    { "goal_name", goalNameVal },
                    { "title", goalNameVal },
                    { "progress", model.Progress ?? 0 },
                    { "status", string.IsNullOrWhiteSpace(model.Status) ? "Pending" : model.Status },
                    { "is_group", model.IsGroup ? 1 : 0 },
                    { "employee", model.Employee },
                    { "employee_name", model.EmployeeName },
                    { "company", model.Company },
                    { "start_date", model.StartDate?.ToString("yyyy-MM-dd") },
                    { "end_date", model.EndDate?.ToString("yyyy-MM-dd") },
                    { "appraisal_cycle", string.IsNullOrWhiteSpace(model.AppraisalCycle) ? null : model.AppraisalCycle },
                    { "kra", string.IsNullOrWhiteSpace(model.Kra) ? null : model.Kra },
                    { "description", model.Description }
                };

                        if (!string.IsNullOrWhiteSpace(parentGoalVal))
                        {
                            payload.Add("parent_goal", parentGoalVal);
                        }

                        var responseJson = await _erpNextService.PostAsync("/api/resource/Goal", payload);
                        dynamic responseParsed = JsonConvert.DeserializeObject(responseJson);
                        string erpNextId = responseParsed?.data?.name;

                        if (!string.IsNullOrEmpty(erpNextId))
                        {
                            _goalService.UpdateErpNextId(model.Id, erpNextId);
                            successCount++;
                        }
                    }
                    catch
                    {
                        failCount++;
                    }
                }

                if (successCount > 0)
                {
                    TempData["Success"] = $"Pushed {successCount} local goal(s) to ERPNext successfully!";
                }
                else if (failCount > 0)
                {
                    TempData["ErpNextError"] = $"Failed to push {failCount} goal(s) to ERPNext.";
                }
                else
                {
                    TempData["Success"] = "All local goals are already in sync with ERPNext!";
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Push error: " + ex.Message;
            }

            return RedirectToAction("Goal");
        }



        // POST: HR/CreateGoal
        // POST: HR/CreateGoal
        // POST: HR/CreateGoal
        [HttpPost]
        [Route("HR/CreateGoal")]
        public async Task<ActionResult> CreateGoal(
    Goal model)
        {
            try
            {
                // ============================================================
                // BASIC VALIDATION
                // ============================================================

                if (string.IsNullOrWhiteSpace(
                    model.GoalName))
                {
                    throw new Exception(
                        "Goal is required."
                    );
                }


                if (string.IsNullOrWhiteSpace(
                    model.Employee))
                {
                    throw new Exception(
                        "Employee is required."
                    );
                }


                if (
                    model.Progress.HasValue &&
                    (
                        model.Progress.Value < 0 ||
                        model.Progress.Value > 100
                    )
                )
                {
                    throw new Exception(
                        "Goal progress percentage cannot be more than 100."
                    );
                }


                // ============================================================
                // GET EMPLOYEE FROM ERP
                // Do not trust browser employee_name/company
                // ============================================================

                string employeeJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee/" +
                        Uri.EscapeDataString(
                            model.Employee
                        )
                    );


                JObject employeeObject =
                    JObject.Parse(
                        employeeJson
                    );


                JToken employeeDoc =
                    employeeObject["data"];


                if (employeeDoc == null)
                {
                    throw new Exception(
                        "Employee does not exist in ERPNext."
                    );
                }


                model.EmployeeName =
                    employeeDoc["employee_name"]
                        ?.ToString()
                    ?? "";


                model.Company =
                    employeeDoc["company"]
                        ?.ToString()
                    ?? "";


                // ============================================================
                // PARENT GOAL VALIDATION
                // ERP also validates these rules.
                // ============================================================

                if (!string.IsNullOrWhiteSpace(
                    model.ParentGoal))
                {
                    string parentJson =
                        await _erpNextService.GetAsync(
                            "/api/resource/Goal/" +
                            Uri.EscapeDataString(
                                model.ParentGoal
                            )
                        );


                    JObject parentObject =
                        JObject.Parse(
                            parentJson
                        );


                    JToken parent =
                        parentObject["data"];


                    if (parent == null)
                    {
                        throw new Exception(
                            "Parent Goal does not exist."
                        );
                    }


                    string parentEmployee =
                        parent["employee"]
                            ?.ToString()
                        ?? "";


                    if (!string.Equals(
                        parentEmployee,
                        model.Employee,
                        StringComparison.OrdinalIgnoreCase))
                    {
                        throw new Exception(
                            "Goal should be owned by the same employee as its parent goal."
                        );
                    }


                    // ERP fields inherit from parent
                    model.Kra =
                        parent["kra"]
                            ?.ToString()
                        ?? "";


                    model.AppraisalCycle =
                        parent["appraisal_cycle"]
                            ?.ToString()
                        ?? "";
                }


                // ============================================================
                // APPRAISAL CYCLE VALIDATION
                // ============================================================

                if (!string.IsNullOrWhiteSpace(
                    model.AppraisalCycle))
                {
                    string cycleJson =
                        await _erpNextService.GetAsync(
                            "/api/resource/Appraisal%20Cycle/" +
                            Uri.EscapeDataString(
                                model.AppraisalCycle
                            )
                        );


                    JObject cycleObject =
                        JObject.Parse(
                            cycleJson
                        );


                    JToken cycle =
                        cycleObject["data"];


                    if (cycle == null)
                    {
                        throw new Exception(
                            "Selected Appraisal Cycle does not exist."
                        );
                    }


                    // ERP Goal fetches dates from cycle if empty
                    if (!model.StartDate.HasValue)
                    {
                        DateTime startDate;

                        if (
                            DateTime.TryParse(
                                cycle["start_date"]
                                    ?.ToString(),
                                out startDate
                            )
                        )
                        {
                            model.StartDate =
                                startDate;
                        }
                    }


                    if (!model.EndDate.HasValue)
                    {
                        DateTime endDate;

                        if (
                            DateTime.TryParse(
                                cycle["end_date"]
                                    ?.ToString(),
                                out endDate
                            )
                        )
                        {
                            model.EndDate =
                                endDate;
                        }
                    }
                }


                // ============================================================
                // KRA RULE
                //
                // Current ERP schema:
                // if appraisal_cycle exists and no parent_goal,
                // KRA becomes mandatory.
                // ============================================================

                if (
                    !string.IsNullOrWhiteSpace(
                        model.AppraisalCycle
                    ) &&
                    string.IsNullOrWhiteSpace(
                        model.ParentGoal
                    ) &&
                    string.IsNullOrWhiteSpace(
                        model.Kra
                    )
                )
                {
                    throw new Exception(
                        "KRA is required when Appraisal Cycle is selected."
                    );
                }


                // ============================================================
                // DATE VALIDATION
                // ============================================================

                if (
                    model.StartDate.HasValue &&
                    model.EndDate.HasValue &&
                    model.EndDate.Value <
                    model.StartDate.Value
                )
                {
                    throw new Exception(
                        "End Date cannot be before Start Date."
                    );
                }


                // ============================================================
                // STATUS IS ERP CONTROLLED
                // ============================================================

                decimal progress =
                    model.Progress ?? 0;


                if (progress == 0)
                {
                    model.Status =
                        "Pending";
                }
                else if (progress >= 100)
                {
                    model.Status =
                        "Completed";
                }
                else
                {
                    model.Status =
                        "In Progress";
                }


                // Group Goals start with 0 progress in ERP
                if (model.IsGroup)
                {
                    model.Progress = 0;
                    model.Status = "Pending";
                }


                // ============================================================
                // ERP PAYLOAD
                // ============================================================

                var payload =
                    new Dictionary<string, object>
                    {
                {
                    "goal_name",
                    model.GoalName
                },

                {
                    "progress",
                    model.Progress ?? 0
                },

                {
                    "is_group",
                    model.IsGroup ? 1 : 0
                },

                {
                    "employee",
                    model.Employee
                },

                {
                    "start_date",
                    model.StartDate.HasValue
                        ? model.StartDate.Value
                            .ToString("yyyy-MM-dd")
                        : null
                },

                {
                    "end_date",
                    model.EndDate.HasValue
                        ? model.EndDate.Value
                            .ToString("yyyy-MM-dd")
                        : null
                },

                {
                    "appraisal_cycle",
                    string.IsNullOrWhiteSpace(
                        model.AppraisalCycle
                    )
                        ? null
                        : model.AppraisalCycle
                },

                {
                    "kra",
                    string.IsNullOrWhiteSpace(
                        model.Kra
                    )
                        ? null
                        : model.Kra
                },

                {
                    "description",
                    string.IsNullOrWhiteSpace(
                        model.Description
                    )
                        ? null
                        : model.Description
                }
                    };


                if (!string.IsNullOrWhiteSpace(
                    model.ParentGoal))
                {
                    payload.Add(
                        "parent_goal",
                        model.ParentGoal
                    );
                }


                // ============================================================
                // ERP FIRST
                // ============================================================

                string createResponse =
                    await _erpNextService.PostAsync(
                        "/api/resource/Goal",
                        payload
                    );


                JObject createObject =
                    JObject.Parse(
                        createResponse
                    );


                string erpId =
                    createObject["data"]?["name"]
                        ?.ToString();


                if (string.IsNullOrWhiteSpace(
                    erpId))
                {
                    throw new Exception(
                        "ERPNext did not return Goal ID."
                    );
                }


                // ============================================================
                // RELOAD FULL ERP DOCUMENT
                // ============================================================

                string fullResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Goal/" +
                        Uri.EscapeDataString(
                            erpId
                        )
                    );


                JObject fullObject =
                    JObject.Parse(
                        fullResponse
                    );


                Goal localGoal =
                    MapErpGoal(
                        fullObject["data"]
                    );


                int localId =
                    _goalService.InsertOrUpdate(
                        localGoal
                    );


                TempData["Success"] =
                    "Goal created successfully. ERPNext Ref: "
                    + erpId;


                return RedirectToAction(
                    "GoalDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanGoalErpError(
                        ex.Message
                    );


                return RedirectToAction(
                    "CreateGoal"
                );
            }
        }



        private Goal MapErpGoal(
    JToken doc)
        {
            if (doc == null)
                return null;


            var goal =
                new Goal
                {
                    ErpNextId =
                        doc["name"]
                            ?.ToString()
                        ?? "",

                    GoalName =
                        doc["goal_name"]
                            ?.ToString()
                        ?? "",

                    Status =
                        doc["status"]
                            ?.ToString()
                        ?? "Pending",

                    IsGroup =
                        doc["is_group"]
                            ?.ToObject<int>()
                        == 1,

                    ParentGoal =
                        doc["parent_goal"]
                            ?.ToString()
                        ?? "",

                    Employee =
                        doc["employee"]
                            ?.ToString()
                        ?? "",

                    EmployeeName =
                        doc["employee_name"]
                            ?.ToString()
                        ?? "",

                    Company =
                        doc["company"]
                            ?.ToString()
                        ?? "",

                    AppraisalCycle =
                        doc["appraisal_cycle"]
                            ?.ToString()
                        ?? "",

                    Kra =
                        doc["kra"]
                            ?.ToString()
                        ?? "",

                    Description =
                        doc["description"]
                            ?.ToString()
                        ?? ""
                };


            if (
                decimal.TryParse(
                    doc["progress"]
                        ?.ToString(),
                    out decimal progress
                )
            )
            {
                goal.Progress =
                    progress;
            }


            if (
                DateTime.TryParse(
                    doc["start_date"]
                        ?.ToString(),
                    out DateTime startDate
                )
            )
            {
                goal.StartDate =
                    startDate;
            }


            if (
                DateTime.TryParse(
                    doc["end_date"]
                        ?.ToString(),
                    out DateTime endDate
                )
            )
            {
                goal.EndDate =
                    endDate;
            }


            return goal;
        }














