        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateGoal/{id:int}")]
        public async Task<ActionResult> UpdateGoal(int id, Goal model)
        {
            var existing = _goalService.GetById(id);

            if (existing == null)
                return NotFound();

            try
            {
                if (string.IsNullOrWhiteSpace(existing.ErpNextId))
                    throw new Exception("ERPNext document ID is missing.");

                model.ErpNextId = existing.ErpNextId;

                var payload = BuildGoalPayload(model);

                await _erpNextService.PutAsync(
                    "/api/resource/Goal/" + Uri.EscapeDataString(existing.ErpNextId),
                    payload
                );

                int localId = await SyncOneGoalFromErpNext(existing.ErpNextId);

                TempData["Success"] = "Goal saved in ERPNext and HRMS.";
                return RedirectToAction("GoalDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = CleanGoalErpError(ex.Message);
                return RedirectToAction("GoalDetails", new { id });
            }
        }

