            catch (Exception ex)
            {
                TempData["ErpNextError"] = CleanGoalErpError(ex.Message);
                return RedirectToAction("GoalDetails", new { id });
            }
        }

        private Dictionary<string, object> BuildGoalPayload(Goal model)
        {
            decimal progress = model.Progress ?? 0;

            if (progress < 0 || progress > 100)
                throw new Exception("Goal progress percentage cannot be more than 100.");

            if (model.IsGroup)
                progress = 0;

            string status = "Pending";

            if (progress >= 100)
                status = "Completed";
            else if (progress > 0)
                status = "In Progress";

            var payload = new Dictionary<string, object>
            {
                { "goal_name", model.GoalName },
                { "progress", progress },
                { "status", status },
                { "is_group", model.IsGroup ? 1 : 0 },
                { "employee", model.Employee },
                { "start_date", model.StartDate.HasValue ? model.StartDate.Value.ToString("yyyy-MM-dd") : null },
                { "end_date", model.EndDate.HasValue ? model.EndDate.Value.ToString("yyyy-MM-dd") : null },
                { "appraisal_cycle", string.IsNullOrWhiteSpace(model.AppraisalCycle) ? null : model.AppraisalCycle },
                { "kra", string.IsNullOrWhiteSpace(model.Kra) ? null : model.Kra },
                { "description", string.IsNullOrWhiteSpace(model.Description) ? null : model.Description }
            };

            if (!string.IsNullOrWhiteSpace(model.ParentGoal))
                payload.Add("parent_goal", model.ParentGoal);

            return payload;
        }


