        private object BuildEmployeePerformanceFeedbackPayload(EmployeePerformanceFeedback model)
        {
            var ratingsPayload = new List<object>();

            if (model.FeedbackRatings != null)
            {
                foreach (var row in model.FeedbackRatings)
                {
                    if (row == null || string.IsNullOrWhiteSpace(row.Criteria))
                        continue;

                    ratingsPayload.Add(new
                    {
                        criteria = row.Criteria,
                        per_weightage = row.Weightage,
                        rating = row.Rating
                    });
                }
            }

            return new
            {
                employee = model.ForEmployee,
                reviewer = model.Reviewer,
                added_on = model.AddedOn.ToString("yyyy-MM-dd HH:mm:ss"),
                appraisal = model.Appraisal,
                feedback = string.IsNullOrWhiteSpace(model.Feedback) ? null : model.Feedback,
                feedback_ratings = ratingsPayload
            };
        }
        public async Task<ActionResult> Appraisal(string id, string employee, string employeeName, string appraisalCycle, string appraisalTemplate)
