                await PullAppraisalsFromErpNext();
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext refresh failed: " + ExtractErpNextErrorMessage(ex.Message);
            }

            var list = _appraisalService.GetAll(id, employee, employeeName, appraisalCycle, appraisalTemplate);
            ViewBag.IdFilter = id;
            ViewBag.EmployeeFilter = employee;
            ViewBag.EmployeeNameFilter = employeeName;
            ViewBag.AppraisalCycleFilter = appraisalCycle;
            ViewBag.AppraisalTemplateFilter = appraisalTemplate;
            return View(list);
        }

