        [HttpGet]
        public async Task<ActionResult> CreateAppraisal()
        {
            var viewModel =
                new Appraisal();

            try
            {
                // =====================================================
                // 1. EMPLOYEE DROPDOWN FROM ERPNext
                // =====================================================

                var empResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee" +
                        "?fields=[\"name\",\"employee_name\",\"company\",\"status\"]" +
                        "&limit_page_length=1000"
                    );

                var empJson =
                    JObject.Parse(empResponse);

                var employeeList =
                    new List<SelectListItem>();

                if (empJson["data"] is JArray empArray)
                {
                    foreach (var emp in empArray)
                    {
                        string employeeId =
                            emp["name"]?.ToString()
                            ?? "";

                        string employeeName =
                            emp["employee_name"]?.ToString()
                            ?? "";

                        string status =
                            emp["status"]?.ToString()
                            ?? "";

                        // Appraisal should normally use active employees
                        if (!string.Equals(
                            status,
                            "Active",
                            StringComparison.OrdinalIgnoreCase))
                        {
                            continue;
                        }

                        employeeList.Add(
                            new SelectListItem
                            {
                                Value = employeeId,

                                Text =
                                    employeeId +
                                    " - " +
                                    employeeName
                            }
                        );
                    }
                }

                ViewBag.EmployeeList =
                    employeeList;


                // =====================================================
                // 2. COMPANY DROPDOWN FROM ERPNext
                // Exact ERPNext Company master
                // =====================================================

                var companyResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Company" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=1000"
                    );

                var companyJson =
                    JObject.Parse(companyResponse);

                var companyList =
                    new List<SelectListItem>();

                if (companyJson["data"] is JArray companyArray)
                {
                    foreach (var company in companyArray)
                    {
                        string companyName =
                            company["name"]?.ToString()
                            ?? "";

                        if (string.IsNullOrWhiteSpace(
                            companyName))
                        {
                            continue;
                        }

                        companyList.Add(
                            new SelectListItem
                            {
                                Value = companyName,
                                Text = companyName
                            }
                        );
                    }
                }

                ViewBag.CompanyList =
                    companyList;


                // =====================================================
                // 3. APPRAISAL CYCLE DROPDOWN
                // =====================================================

                var cycleResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal%20Cycle" +
                        "?fields=[\"name\",\"company\",\"status\"]" +
                        "&limit_page_length=1000"
                    );

                var cycleJson =
                    JObject.Parse(cycleResponse);

                var cycleList =
                    new List<SelectListItem>();

                if (cycleJson["data"] is JArray cycleArray)
                {
                    foreach (var cycle in cycleArray)
                    {
                        string cycleName =
                            cycle["name"]?.ToString()
                            ?? "";

                        if (string.IsNullOrWhiteSpace(
                            cycleName))
                        {
                            continue;
                        }

                        cycleList.Add(
                            new SelectListItem
                            {
                                Value = cycleName,
                                Text = cycleName
                            }
                        );
                    }
                }

                ViewBag.AppraisalCycleList =
                    cycleList;


                // =====================================================
                // 4. APPRAISAL TEMPLATE DROPDOWN
                // =====================================================

                var templateResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Appraisal%20Template" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=1000"
                    );

                var templateJson =
                    JObject.Parse(templateResponse);

                var templateList =
                    new List<SelectListItem>();

                if (templateJson["data"] is JArray templateArray)
                {
                    foreach (var template in templateArray)
                    {
                        string templateName =
                            template["name"]?.ToString()
                            ?? "";

                        if (string.IsNullOrWhiteSpace(
                            templateName))
                        {
                            continue;
                        }

                        templateList.Add(
                            new SelectListItem
                            {
                                Value = templateName,
                                Text = templateName
                            }
                        );
                    }
                }

                ViewBag.AppraisalTemplateList =
                    templateList;
            }
            catch (Exception ex)
            {
                ViewBag.EmployeeList =
                    new List<SelectListItem>();

                ViewBag.CompanyList =
                    new List<SelectListItem>();

                ViewBag.AppraisalCycleList =
                    new List<SelectListItem>();

                ViewBag.AppraisalTemplateList =
                    new List<SelectListItem>();

                TempData["ErpNextError"] =
                    "Unable to load ERPNext Appraisal masters: "
                    + ex.Message;
            }

            return View(viewModel);
        }




