        public async Task<ActionResult> CreateJobOffer(bool returnToOnboarding = false)
{
    ViewBag.ReturnToOnboarding = returnToOnboarding;

    try
    {
        var json = await _erpNextService.GetAsync(
            "/api/resource/Job%20Applicant" +
            "?fields=[\"name\",\"applicant_name\",\"status\"]" +
            "&limit_page_length=1000");

        ViewBag.JobApplicants =
            JsonConvert.DeserializeObject<dynamic>(json)?.data;
    }
    catch
    {
        ViewBag.JobApplicants = null;
    }

    try
    {
        var json = await _erpNextService.GetAsync(
            "/api/resource/Designation" +
            "?fields=[\"name\"]" +
            "&limit_page_length=1000");

        ViewBag.Designations =
            JsonConvert.DeserializeObject<dynamic>(json)?.data;
    }
    catch
    {
        ViewBag.Designations = null;
    }

    try
    {
        var json = await _erpNextService.GetAsync(
            "/api/resource/Company" +
            "?fields=[\"name\"]" +
            "&limit_page_length=1000");

        ViewBag.Companies =
            JsonConvert.DeserializeObject<dynamic>(json)?.data;
    }
    catch
    {
        ViewBag.Companies = null;
    }

    try
    {
        var json = await _erpNextService.GetAsync(
            "/api/resource/Terms%20and%20Conditions" +
            "?fields=[\"name\",\"title\"]" +
            "&limit_page_length=1000");

        ViewBag.TermsAndConditions =
            JsonConvert.DeserializeObject<dynamic>(json)?.data;
    }
    catch
    {
        ViewBag.TermsAndConditions = null;
    }

    try
    {
        var json = await _erpNextService.GetAsync(
            "/api/resource/Offer%20Term" +
            "?fields=[\"name\"]" +
            "&limit_page_length=1000");

        ViewBag.OfferTerms =
            JsonConvert.DeserializeObject<dynamic>(json)?.data;
    }
    catch
    {
        ViewBag.OfferTerms = null;
    }

    return View(new JobOffer
    {
        Status = "Awaiting Response",
        OfferDate = DateTime.Now,
        Company = "AITS"
    });
}









        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> CreateJobOffer(
     JobOffer model,
     bool returnToOnboarding,
     List<string> OfferTerms,
     List<string> OfferTermValues)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(model.JobApplicant))
                    throw new Exception("Job Applicant is required.");

                if (string.IsNullOrWhiteSpace(model.Designation))
                    throw new Exception("Designation is required.");

                if (string.IsNullOrWhiteSpace(model.Company))
                    throw new Exception("Company is required.");

                var offerTermsPayload = new List<object>();

                if (OfferTerms != null)
                {
                    for (int i = 0; i < OfferTerms.Count; i++)
                    {
                        if (string.IsNullOrWhiteSpace(OfferTerms[i]))
                            continue;

                        offerTermsPayload.Add(new
                        {
                            offer_term = OfferTerms[i],
                            value = OfferTermValues != null && i < OfferTermValues.Count
                                ? OfferTermValues[i]
                                : ""
                        });
                    }
                }

                var payload = new
                {
                    job_applicant = model.JobApplicant,
                    applicant_name = model.ApplicantName,
                    status = model.Status,
                    offer_date = model.OfferDate.ToString("yyyy-MM-dd"),
                    designation = model.Designation,
                    company = model.Company,
                    offer_term_template = model.JobOfferTermTemplate,
                    select_terms = model.SelectTermsAndConditions,
                    terms = model.TermsAndConditions,
                    letter_head = model.LetterHead,
                    select_print_heading = model.PrintHeading,
                    offer_terms = offerTermsPayload
                };

                var responseJson = await _erpNextService.PostAsync(
                    "/api/resource/Job%20Offer",
                    payload);

                dynamic parsed = JsonConvert.DeserializeObject(responseJson);

                string erpJobOfferName =
                    parsed?.data?.name?.ToString();

                if (string.IsNullOrWhiteSpace(erpJobOfferName))
                    throw new Exception("ERPNext did not return Job Offer name.");

                _jobOfferService.InsertOffer(model);

                TempData["Success"] = "Job Offer created successfully.";

                if (returnToOnboarding)
                {
                    return RedirectToAction(
                        "CreateEmployeeOnboarding",
                        new { selectedJobOffer = erpJobOfferName });
                }

                return RedirectToAction("JobOffer");
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Job Offer create failed: " + ShortErpNextError(ex.Message);

                return RedirectToAction(
                    "CreateJobOffer",
                    new { returnToOnboarding });
            }
        }


