        public ActionResult EmployeeLeaveBalance(DateTime? fromDate, DateTime? toDate, string department, string employee, string status = "Active")
        {
            ViewBag.FromDate = fromDate;
            ViewBag.ToDate = toDate;
            ViewBag.Department = department;
            ViewBag.Employee = employee;
            ViewBag.Status = status;

            if (fromDate == null || toDate == null)
            {
                return View(new List<LeaveBalanceRow>());
            }

            var employees = _employeeService.GetEmployeesForReport(department, employee, status);
            var rows = new List<LeaveBalanceRow>();

            foreach (var emp in employees)
            {
                int taken = _leaveService.GetLeavesTakenForEmployee(emp.EmployeeCode, fromDate.Value, toDate.Value);

                rows.Add(new LeaveBalanceRow
                {
                    EmployeeCode = emp.EmployeeCode,
                    EmployeeName = emp.FullName,
                    Department = emp.Department,
                    LeavesTaken = taken,
                    TotalAllocated = 0,
                    Balance = 0 - taken
                });
            }

            return View(rows);
        }

        // ---- Employee Analytics report action ----

        public ActionResult EmployeeAnalytics(string company = "AITS", string parameter = null)
        {
            List<dynamic> result = new List<dynamic>();

            if (!string.IsNullOrEmpty(parameter))
            {
                var employees = _employeeService.GetAllEmployees(null);

                if (!string.IsNullOrEmpty(company))
                {
                    employees = employees.Where(e => e.Company == company).ToList();
                }

                IEnumerable<IGrouping<string, Employee>> grouped;

                switch (parameter)
                {
                    case "Department":
                        grouped = employees.GroupBy(e => string.IsNullOrEmpty(e.Department) ? "Not Set" : e.Department);
                        break;
                    case "Designation":
                        grouped = employees.GroupBy(e => string.IsNullOrEmpty(e.Designation) ? "Not Set" : e.Designation);
                        break;
                    case "Grade":
                        grouped = employees.GroupBy(e => string.IsNullOrEmpty(e.Grade) ? "Not Set" : e.Grade);
                        break;
                    case "Gender":
                        grouped = employees.GroupBy(e => string.IsNullOrEmpty(e.Gender) ? "Not Set" : e.Gender);
                        break;
                    case "EmploymentType":
                        grouped = employees.GroupBy(e => string.IsNullOrEmpty(e.EmploymentType) ? "Not Set" : e.EmploymentType);
                        break;
                    default:
                        grouped = employees.GroupBy(e => "All");
                        break;
                }

                result = grouped
                    .Select(g => (dynamic)new { Label = g.Key, Count = g.Count() })
                    .OrderByDescending(g => g.Count)
                    .ToList();
            }

            ViewBag.Company = company;
            ViewBag.Parameter = parameter;
            return View(result);
        }

