        public ActionResult EmployeeBirthday(string month = null, string company = "AITS")
        {
            var allEmployees = _employeeService.GetAllEmployees(null);

            string selectedMonth = string.IsNullOrEmpty(month) ? DateTime.Now.ToString("MMM") : month;

            var employees = allEmployees
                .Where(e => e.DateOfBirth.HasValue
                            && e.DateOfBirth.Value.ToString("MMM") == selectedMonth
                            && (string.IsNullOrEmpty(company) || e.Company == company))
                .ToList();

            ViewBag.Month = selectedMonth;
            ViewBag.Company = company;
            return View(employees);
        }


