        [HttpGet]
        [Route("HR/SyncShiftSchedulesFromErpNext")]
        public async Task<ActionResult> SyncShiftSchedulesFromErpNext()
        {
            try
            {
                var listResponse = await _erpNextService.GetAsync("/api/resource/Shift%20Schedule?limit_page_length=500");
                dynamic listParsed = JsonConvert.DeserializeObject(listResponse);

                var service = new HRShiftScheduleService(_connectionString);
                var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                int inserted = 0;
                int updated = 0;

                if (listParsed?.data != null)
                {
                    foreach (var listItem in listParsed.data)
                    {
                        string docName = listItem.name?.ToString();
                        if (string.IsNullOrEmpty(docName)) continue;
                        erpIds.Add(docName);

                        try
                        {
                            var detailResponse = await _erpNextService.GetAsync($"/api/resource/Shift%20Schedule/{Uri.EscapeDataString(docName)}");
                            dynamic detailParsed = JsonConvert.DeserializeObject(detailResponse);
                            var item = detailParsed?.data;

                            if (item != null)
                            {
                                string scheduleName = item.name?.ToString();
                                bool exists = service.GetByName(scheduleName) != null;
                                var schedule = new HRShiftSchedule
                                {
                                    Name = scheduleName,
                                    ShiftType = item.shift_type?.ToString() ?? string.Empty,
                                    Frequency = item.frequency?.ToString() ?? "Every Week",
                                    Status = GetDocStatusLabel(item.docstatus)
                                };

                                if (item.repeat_on_days != null)
                                {
                                    foreach (var dayItem in item.repeat_on_days)
                                    {
                                        schedule.Days.Add(new HRShiftScheduleDay
                                        {
                                            Day = dayItem.day?.ToString() ?? string.Empty
                                        });
                                    }
                                }

                                service.InsertOrUpdate(schedule);
                                if (exists) updated++; else inserted++;
                            }
                        }
                        catch (Exception innerEx)
                        {
                            System.Diagnostics.Debug.WriteLine("Shift Schedule sync error: " + innerEx.Message);
                        }
                    }
                }
                SoftDeleteMissingErpDocuments("HRShiftSchedules", "Name", erpIds);
                TempData["Success"] = $"Shift Schedules synced from ERPNext. New: {inserted}, Updated: {updated}.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Sync failed: " + ExtractErpNextErrorMessage(ex.Message);
            }

            return RedirectToAction("ShiftSchedule", "HR");
        }

