        [HttpPost]
        [Route("HR/CreateShiftSchedule")]
        public async Task<ActionResult> CreateShiftSchedule(HRShiftSchedule model, string[] Days)
        {
            try
            {
                model ??= new HRShiftSchedule();
                model.Name = string.IsNullOrWhiteSpace(model.Name) ? Request.Form["Name"].ToString() : model.Name;
                model.ShiftType = string.IsNullOrWhiteSpace(model.ShiftType) ? Request.Form["ShiftType"].ToString() : model.ShiftType;
                model.Frequency = string.IsNullOrWhiteSpace(model.Frequency) ? Request.Form["Frequency"].ToString() : model.Frequency;
                model.Frequency = string.IsNullOrWhiteSpace(model.Frequency) ? "Every Week" : model.Frequency;
                model.Status = "Draft";

                // Pure server-side binding: ignore any blank "-- Select Day --" rows
                if (Days != null)
                {
                    foreach (var d in Days)
                    {
                        if (!string.IsNullOrWhiteSpace(d))
                        {
                            model.Days.Add(new HRShiftScheduleDay { Day = d });
                        }
                    }
                }

                var daysPayload = new List<object>();
                if (model.Days != null && model.Days.Count > 0)
                {
                    foreach (var d in model.Days)
                    {
                        daysPayload.Add(new { day = d.Day });
                    }
                }

                var erpPayload = new
                {
                    name = model.Name,
                    shift_type = model.ShiftType,
                    frequency = model.Frequency,
                    repeat_on_days = daysPayload
                };

                await _erpNextService.PostAsync("/api/resource/Shift%20Schedule", erpPayload);

                var service = new HRShiftScheduleService(_connectionString);
                var newId = service.InsertOrUpdate(model);
                TempData["Success"] = "Shift Schedule saved in ERPNext and HRMS successfully.";

                return RedirectToAction("HRShiftScheduleDetails", new { id = newId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext validation failed: " + ExtractErpNextErrorMessage(ex.Message);
                await LoadShiftScheduleDropdownsAsync();
                return View("~/Views/HR/CreateHRShiftSchedule.cshtml", model ?? new HRShiftSchedule());
            }
        }











