                var listResponse = await _erpNextService.GetAsync("/api/resource/Shift%20Schedule%20Assignment?limit_page_length=500");
                dynamic listParsed = JsonConvert.DeserializeObject(listResponse);

                var service = new HRShiftScheduleAssignmentService(_connectionString);
                var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                int inserted = 0;
                int updated = 0;

                if (listParsed?.data != null)
                {
                    foreach (var listItem in listParsed.data)
                    {
                        string docName = listItem.name?.ToString();
                        if (string.IsNullOrEmpty(docName)) continue;
                        erpIds.Add(docName);

                        try
                        {
                            var detailResponse = await _erpNextService.GetAsync($"/api/resource/Shift%20Schedule%20Assignment/{Uri.EscapeDataString(docName)}");
                            dynamic detailParsed = JsonConvert.DeserializeObject(detailResponse);
                            var item = detailParsed?.data;

                            if (item != null)
                            {
                                bool exists = service.GetByErpNextId(docName) != null;
                                var assignment = new HRShiftScheduleAssignment
                                {
                                    ErpNextId = docName,
                                    Employee = item.employee?.ToString() ?? string.Empty,
                                    EmployeeName = item.employee_name?.ToString() ?? string.Empty,
                                    Company = item.company?.ToString() ?? string.Empty,
                                    ShiftSchedule = item.shift_schedule?.ToString() ?? string.Empty,
                                    ShiftLocation = item.shift_location?.ToString() ?? string.Empty,
                                    Enabled = item.enabled != null && Convert.ToBoolean(item.enabled),
                                    CreateShiftsAfter = item.start_date != null ? Convert.ToDateTime(item.start_date) : DateTime.Now,
