        [HttpPost]
        public ActionResult UploadTravelAttachment(IFormFile file)
        {
            if (file != null && file.Length > 0)
            {
                var uploadsFolder = Path.Combine("wwwroot", "uploads", "travel-request");
                Directory.CreateDirectory(uploadsFolder);
                var fileName = Guid.NewGuid() + Path.GetExtension(file.FileName);
                var filePath = Path.Combine(uploadsFolder, fileName);

                using (var stream = new FileStream(filePath, FileMode.Create))
                {
                    file.CopyTo(stream);
                }

                return Json(new { fileUrl = "/uploads/travel-request/" + fileName, fileName = file.FileName });
            }

            return Json(new { error = "No file uploaded" });
        }


