        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateEmployeeCheckin/{id:int}")]
        public async Task<ActionResult> UpdateEmployeeCheckin(int id, EmployeeCheckin model)
        {
            var existing = _employeeCheckinService.GetById(id);

            if (existing == null)
                return NotFound();

            model.Id = id;
            model.EmployeeCheckinCode = existing.EmployeeCheckinCode;

            // Shift field removed from page, so keep existing Shift value.
            model.Shift = existing.Shift;

            if (string.IsNullOrWhiteSpace(model.Employee))
            {
                TempData["ErpNextError"] = "Employee is required.";
                return RedirectToAction("EmployeeCheckinDetails", new { id, edit = true });
            }

            if (!model.Time.HasValue)
            {
                TempData["ErpNextError"] = "Time is required.";
                return RedirectToAction("EmployeeCheckinDetails", new { id, edit = true });
            }

            try
            {
                var payload = new
                {
                    employee = model.Employee,
                    time = model.Time.Value.ToString("yyyy-MM-dd HH:mm:ss"),
                    log_type = string.IsNullOrWhiteSpace(model.LogType) ? null : model.LogType,
                    device_id = string.IsNullOrWhiteSpace(model.LocationDeviceId) ? null : model.LocationDeviceId,
                    skip_auto_attendance = model.SkipAutoAttendance ? 1 : 0,
                    shift = string.IsNullOrWhiteSpace(model.Shift) ? null : model.Shift
                };

                await _erpNextService.PutAsync(
                    "/api/resource/Employee%20Checkin/" + Uri.EscapeDataString(existing.EmployeeCheckinCode),
                    payload
                );

                _employeeCheckinService.UpdateCheckinById(model);

                TempData["Success"] = "Employee Checkin updated successfully.";
                return RedirectToAction("EmployeeCheckinDetails", new { id });
            }
