        [HttpGet]
        [Route("HR/AttendanceRequest")]
        public async Task<ActionResult> AttendanceRequest()
        {
            try
            {
                await PullAttendanceRequestsFromErpNext();
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = CleanErpNextError(ex);
            }

            var requests = _attendanceRequestService.GetAllAttendanceRequests();
            return View(requests);
        }

        private async Task PullAttendanceRequestsFromErpNext()
        {
            var erpCodes = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            var fields = Uri.EscapeDataString("[\"name\",\"employee\",\"employee_name\",\"company\",\"from_date\",\"to_date\",\"half_day\",\"half_day_date\",\"include_holidays\",\"shift\",\"reason\",\"explanation\",\"docstatus\"]");

            var json = await _erpNextService.GetAsync($"/api/resource/Attendance%20Request?fields={fields}&limit_page_length=5000");

            var parsed = Newtonsoft.Json.Linq.JObject.Parse(json);
            var data = parsed["data"] as Newtonsoft.Json.Linq.JArray;

            if (data == null)
                return;

            foreach (var item in data)
            {
                string erpId = item["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpId))
                    continue;

                erpCodes.Add(erpId);

                DateTime? fromDate = DateTime.TryParse(item["from_date"]?.ToString(), out var fd) ? fd : null;
                DateTime? toDate = DateTime.TryParse(item["to_date"]?.ToString(), out var td) ? td : null;
                DateTime? halfDayDate = DateTime.TryParse(item["half_day_date"]?.ToString(), out var hdd) ? hdd : null;

                var model = new AttendanceRequest
                {
                    AttendanceRequestCode = erpId,
                    ErpNextId = erpId,
                    Employee = item["employee"]?.ToString(),
                    EmployeeName = item["employee_name"]?.ToString(),
                    Company = item["company"]?.ToString(),
                    FromDate = fromDate,
                    ToDate = toDate,
                    HalfDay = item["half_day"]?.ToString() == "1",
                    HalfDayDate = halfDayDate,
                    IncludeHolidays = item["include_holidays"]?.ToString() == "1",
                    Shift = item["shift"]?.ToString(),
                    Reason = item["reason"]?.ToString(),
                    Explanation = item["explanation"]?.ToString(),
                    DocStatus = int.TryParse(item["docstatus"]?.ToString(), out int ds) ? ds : 0
                };

                var existing = _attendanceRequestService.GetByErpNextId(erpId);

                if (existing == null)
                {
                    _attendanceRequestService.InsertAttendanceRequest(model);
                }
                else
                {
                    model.Id = existing.Id;
                    _attendanceRequestService.UpdateAttendanceRequest(model);
                }
            }

            _attendanceRequestService.MarkDeletedIfMissingFromErpNext(erpCodes);
        }

        // POST: HR/SyncAttendanceRequestsFromErpNext
        [HttpPost]
        [Route("HR/SyncAttendanceRequestsFromErpNext")]
        public async Task<ActionResult> SyncAttendanceRequestsFromErpNext()
        {
            int syncCount = 0;

            try
            {
                // Fetch attendance requests from ERPNext
                string json = await _erpNextService.GetAsync("/api/resource/Attendance Request?fields=[\"name\",\"employee\",\"employee_name\",\"company\",\"from_date\",\"to_date\",\"half_day\",\"include_holidays\",\"shift\",\"reason\",\"explanation\"]&limit_page_length=1000");
                dynamic parsed = JsonConvert.DeserializeObject(json);

                if (parsed?.data != null)
                {
                    var existingRequests = _attendanceRequestService.GetAllAttendanceRequests();
                    var existingCodes = new HashSet<string>(existingRequests.Select(r => r.AttendanceRequestCode));

                    foreach (var item in parsed.data)
                    {
                        string reqCode = item.name?.ToString();

                        if (!string.IsNullOrEmpty(reqCode) && !existingCodes.Contains(reqCode))
                        {
                            var newReq = new AttendanceRequest
                            {
                                AttendanceRequestCode = reqCode,
                                Employee = item.employee?.ToString(),
                                EmployeeName = item.employee_name?.ToString() ?? item.employee?.ToString(),
                                Company = item.company?.ToString() ?? "AITS",
                                FromDate = item.from_date != null ? Convert.ToDateTime(item.from_date) : (DateTime?)null,
                                ToDate = item.to_date != null ? Convert.ToDateTime(item.to_date) : (DateTime?)null,
                                HalfDay = item.half_day != null && Convert.ToBoolean(item.half_day),
                                IncludeHolidays = item.include_holidays != null && Convert.ToBoolean(item.include_holidays),
                                Shift = item.shift?.ToString(),
                                Reason = item.reason?.ToString() ?? "Work From Home",
                                Explanation = item.explanation?.ToString()
                            };

                            _attendanceRequestService.InsertAttendanceRequest(newReq);
                            syncCount++;
                        }
                    }
                }

                TempData["Success"] = $"Successfully synced {syncCount} new attendance request(s) from ERPNext!";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Sync failed: " + ex.Message;
            }

            return RedirectToAction("AttendanceRequest");
        }





        // POST: HR/SyncAttendanceRequestsToServerToErpNext
        [HttpPost]
        [Route("HR/SyncAttendanceRequestsToServerToErpNext")]
        public async Task<ActionResult> SyncAttendanceRequestsToServerToErpNext()
        {
            int successCount = 0;
            int failCount = 0;

            try
            {
                string connStr = _configuration.GetConnectionString("DefaultConnection");
                var allRequests = _attendanceRequestService.GetAllAttendanceRequests();

                foreach (var row in allRequests)
                {
                    // If it hasn't been synced to ERPNext yet (ErpNextId is empty/null)
                    if (string.IsNullOrEmpty(row.ErpNextId))
                    {
                        try
                        {
                            // Ensure mandatory fields exist on ERPNext first
                            string targetCompany = string.IsNullOrWhiteSpace(row.Company) ? "AITS" : row.Company.Trim();
                            await EnsureDocExistsAsync("Company", targetCompany);

                            var payloadDictionary = new Dictionary<string, object>
                    {
                        { "employee", row.Employee },
                        { "company", targetCompany },
                        { "from_date", row.FromDate?.ToString("yyyy-MM-dd") },
                        { "to_date", row.ToDate?.ToString("yyyy-MM-dd") },
                        { "half_day", row.HalfDay ? 1 : 0 },
                        { "include_holidays", row.IncludeHolidays ? 1 : 0 },
                        { "reason", string.IsNullOrWhiteSpace(row.Reason) ? "Work From Home" : row.Reason },
                        { "explanation", row.Explanation }
                    };

                            if (!string.IsNullOrWhiteSpace(row.Shift))
                            {
                                payloadDictionary["shift"] = row.Shift;
                            }

                            var responseJson = await _erpNextService.PostAsync("/api/resource/Attendance%20Request", payloadDictionary);
                            dynamic responseParsed = JsonConvert.DeserializeObject(responseJson);
                            string erpNextId = responseParsed?.data?.name;

                            if (!string.IsNullOrEmpty(erpNextId))
                            {
                                // Update local SQL record with the generated ERPNext ID
                                using (var conn = new SqlConnection(connStr))
                                {
                                    conn.Open();
                                    using (var cmd = new SqlCommand("UPDATE AttendanceRequests SET ErpNextId = @ErpNextId WHERE Id = @Id", conn))
                                    {
                                        cmd.Parameters.AddWithValue("@ErpNextId", erpNextId);
                                        cmd.Parameters.AddWithValue("@Id", row.Id);
                                        cmd.ExecuteNonQuery();
                                    }
                                }
                                successCount++;
                            }
                        }
                        catch
                        {
                            failCount++;
                        }
                    }
                }

                if (successCount > 0)
                {
                    TempData["Success"] = $"Successfully pushed {successCount} local attendance request(s) to ERPNext!";
                }
                else if (failCount > 0)
                {
                    TempData["ErpNextError"] = $"Failed to push {failCount} attendance request(s) to ERPNext.";
                }
                else
                {
                    TempData["Success"] = "All local attendance requests are already synced with ERPNext!";
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Push sync error: " + ex.Message;
            }

            return RedirectToAction("AttendanceRequest");
        }
