        [HttpPost]
        [Route("HR/ProcessAttendanceRequestAction")]
        public async Task<ActionResult> ProcessAttendanceRequestAction(AttendanceRequest model, string actionCommand)
        {
            var existing = _attendanceRequestService.GetById(model.Id);
            if (existing == null) return NotFound();

            if (existing.DocStatus == 2)
            {
                TempData["ErpNextError"] = "Cancelled Attendance Request cannot be changed.";
                return RedirectToAction("AttendanceRequestDetails", new { id = model.Id });
            }

            if (string.IsNullOrWhiteSpace(model.Employee)) model.Employee = existing.Employee;
            if (string.IsNullOrWhiteSpace(model.EmployeeName)) model.EmployeeName = existing.EmployeeName;
            if (string.IsNullOrWhiteSpace(model.Company)) model.Company = existing.Company;
            if (string.IsNullOrWhiteSpace(model.Reason)) model.Reason = existing.Reason;
            if (model.FromDate == null) model.FromDate = existing.FromDate;
            if (model.ToDate == null) model.ToDate = existing.ToDate;

            try
            {
                if (actionCommand == "Save")
                {
                    var payload = BuildAttendanceRequestPayload(model, 0);

                    await _erpNextService.PutAsync(
                        $"/api/resource/Attendance%20Request/{Uri.EscapeDataString(existing.ErpNextId)}",
                        payload
                    );

                    model.ErpNextId = existing.ErpNextId;
                    model.AttendanceRequestCode = existing.AttendanceRequestCode;
                    model.DocStatus = 0;
                    _attendanceRequestService.UpdateAttendanceRequest(model);

                    TempData["Success"] = "Attendance Request saved successfully.";
                    return RedirectToAction("AttendanceRequestDetails", new { id = model.Id });
                }

                if (actionCommand == "Submit")
                {
                    var payload = BuildAttendanceRequestPayload(model, 0);

                    await _erpNextService.PutAsync(
                        $"/api/resource/Attendance%20Request/{Uri.EscapeDataString(existing.ErpNextId)}",
                        payload
                    );

                    var latest = await _erpNextService.GetAsync(
                        $"/api/resource/Attendance%20Request/{Uri.EscapeDataString(existing.ErpNextId)}"
                    );

                    var latestDoc = Newtonsoft.Json.Linq.JObject.Parse(latest)["data"];

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new
                    {
                        doc = latestDoc
                    });

                    model.ErpNextId = existing.ErpNextId;
                    model.AttendanceRequestCode = existing.AttendanceRequestCode;
                    model.DocStatus = 1;
                    _attendanceRequestService.UpdateAttendanceRequest(model);

                    TempData["Success"] = "Attendance Request submitted successfully.";
                    return RedirectToAction("AttendanceRequestDetails", new { id = model.Id });
                }

                if (actionCommand == "Cancel")
                {
                    if (existing.DocStatus != 1)
                    {
                        TempData["ErpNextError"] = "Only submitted Attendance Request can be cancelled.";
                        return RedirectToAction("AttendanceRequestDetails", new { id = model.Id });
                    }

                    await CancelLinkedAttendanceDocuments(existing.ErpNextId);

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                    {
                        doctype = "Attendance Request",
                        name = existing.ErpNextId
                    });

                    _attendanceRequestService.UpdateDocStatus(model.Id, 2);

                    TempData["Success"] = "Attendance Request and linked Attendance cancelled successfully.";
                    return RedirectToAction("AttendanceRequestDetails", new { id = model.Id });
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Action failed: " + CleanErpNextError(ex);
            }

            return RedirectToAction("AttendanceRequestDetails", new { id = model.Id });
        }


        private Dictionary<string, object> BuildAttendanceRequestPayload(AttendanceRequest model, int docStatus)
        {
            var payload = new Dictionary<string, object>
    {
        { "employee", model.Employee },
        { "company", string.IsNullOrWhiteSpace(model.Company) ? "AITS" : model.Company },
        { "from_date", model.FromDate?.ToString("yyyy-MM-dd") },
        { "to_date", model.ToDate?.ToString("yyyy-MM-dd") },
        { "half_day", model.HalfDay ? 1 : 0 },
        { "include_holidays", model.IncludeHolidays ? 1 : 0 },
        { "reason", string.IsNullOrWhiteSpace(model.Reason) ? "Work From Home" : model.Reason },
        { "explanation", model.Explanation ?? "" },
        { "docstatus", docStatus }
    };

            if (model.HalfDay)
            {
                payload["half_day_date"] = model.HalfDayDate?.ToString("yyyy-MM-dd");
            }
            else
            {
                payload["half_day_date"] = null;
            }

            if (!string.IsNullOrWhiteSpace(model.Shift))
            {
                payload["shift"] = model.Shift;
            }

            return payload;
        }
        private async Task CancelLinkedAttendanceDocuments(string attendanceRequestId)
        {
            if (string.IsNullOrWhiteSpace(attendanceRequestId)) return;

            var filters = Uri.EscapeDataString("[[\"Attendance\",\"attendance_request\",\"=\",\"" + attendanceRequestId + "\"],[\"Attendance\",\"docstatus\",\"=\",1]]");
            var fields = Uri.EscapeDataString("[\"name\"]");

            var json = await _erpNextService.GetAsync($"/api/resource/Attendance?fields={fields}&filters={filters}&limit_page_length=500");
            var data = Newtonsoft.Json.Linq.JObject.Parse(json)["data"] as Newtonsoft.Json.Linq.JArray;

            if (data == null) return;

            foreach (var row in data)
            {
                string attendanceId = row["name"]?.ToString();
                if (string.IsNullOrWhiteSpace(attendanceId)) continue;

                await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                {
                    doctype = "Attendance",
                    name = attendanceId
                });

                using (var conn = new SqlConnection(_connectionString))
                {
                    conn.Open();
                    using (var cmd = new SqlCommand(@"
                UPDATE Attendances
                SET DocStatus = 2
                WHERE ErpNextId = @ErpNextId OR AttendanceCode = @ErpNextId", conn))
                    {
                        cmd.Parameters.AddWithValue("@ErpNextId", attendanceId);
                        cmd.ExecuteNonQuery();
                    }
                }
            }
        }


