        [Route("HR/DeleteAttendanceRequest/{id:int}")]
        public async Task<ActionResult> DeleteAttendanceRequest(int id)
        {
            var model = _attendanceRequestService.GetById(id);
            if (model == null) return RedirectToAction("AttendanceRequest");

            try
            {
