                    );
                }

                _attendanceRequestService.SoftDeleteById(id);
                TempData["Success"] = "Attendance Request deleted successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Delete failed: " + CleanErpNextError(ex);
            }

            return RedirectToAction("AttendanceRequest");
        }








