        [HttpPost]
        [Route("HR/CreateAttendanceRequest")]
        public async Task<ActionResult> CreateAttendanceRequest(AttendanceRequest model)
        {
            try
            {
                string targetCompany = string.IsNullOrWhiteSpace(model.Company) ? "AITS" : model.Company.Trim();
                DateTime fromDate = model.FromDate ?? DateTime.Today;
                DateTime toDate = model.ToDate ?? fromDate;
                if (toDate < fromDate) toDate = fromDate;

                model.DocStatus = 0;
                model.Company = targetCompany;
                model.FromDate = fromDate;
                model.ToDate = toDate;

                var payload = new Dictionary<string, object>
        {
            { "employee", model.Employee },
            { "company", targetCompany },
            { "from_date", fromDate.ToString("yyyy-MM-dd") },
            { "to_date", toDate.ToString("yyyy-MM-dd") },
            { "half_day", model.HalfDay ? 1 : 0 },
            { "include_holidays", model.IncludeHolidays ? 1 : 0 },
            { "reason", string.IsNullOrWhiteSpace(model.Reason) ? "Work From Home" : model.Reason },
            { "explanation", model.Explanation ?? "" },
            { "docstatus", 0 }
        };

                if (!string.IsNullOrWhiteSpace(model.Shift))
                    payload["shift"] = model.Shift;

                var response = await _erpNextService.PostAsync("/api/resource/Attendance%20Request", payload);
                dynamic parsed = JsonConvert.DeserializeObject(response);
                string erpId = parsed?.data?.name?.ToString();

                if (string.IsNullOrWhiteSpace(erpId))
                {
                    TempData["ErpNextError"] = "ERPNext created Attendance Request but did not return ID.";
                    await LoadAttendanceRequestDropdowns();
                    return View("CreateAttendanceRequest", model);
                }

                model.ErpNextId = erpId;
                model.AttendanceRequestCode = erpId;

                int localId = _attendanceRequestService.InsertAttendanceRequest(model);

                TempData["Success"] = "Attendance Request saved as Draft.";
                return RedirectToAction("AttendanceRequestDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Creation failed: " + CleanErpNextError(ex);
                await LoadAttendanceRequestDropdowns();
                return View("CreateAttendanceRequest", model);
            }
        }





