        private async Task LoadAttendanceRequestDropdowns()
        {
            try
            {
                var shiftResp = await _erpNextService.GetAsync("/api/resource/Shift%20Type?fields=[\"name\"]&limit_page_length=500");
                ViewBag.Shifts = ExtractNamesList(shiftResp);

                var empResp = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=5000");
                dynamic parsedEmp = JsonConvert.DeserializeObject(empResp);
                ViewBag.Employees = parsedEmp?.data;

                var compResp = await _erpNextService.GetAsync("/api/resource/Company?fields=[\"name\"]&limit_page_length=500");
                dynamic parsedComp = JsonConvert.DeserializeObject(compResp);
                ViewBag.Companies = parsedComp?.data;
            }
            catch
            {
                ViewBag.Shifts = new List<string>();
                ViewBag.Employees = new List<object>();
                ViewBag.Companies = new List<object>();
            }
        }












        // Dedicated helper to guarantee 'Shift Type' is created in ERPNext if it doesn't exist
        private async Task EnsureShiftTypeExistsAsync(string shiftName)
        {
            if (string.IsNullOrWhiteSpace(shiftName)) return;

            try
            {
                // Check if Shift Type already exists
                string checkUrl = $"/api/resource/Shift%20Type/{Uri.EscapeDataString(shiftName)}";
                await _erpNextService.GetAsync(checkUrl);
            }
            catch
            {
                // If it doesn't exist, create it with mandatory start and end times
                var payload = new Dictionary<string, object>
        {
            { "shift_type_name", shiftName },
            { "start_time", "09:00:00" },
            { "end_time", "18:00:00" },
            { "holiday_list", "" }
        };

                try
                {
                    await _erpNextService.PostAsync("/api/resource/Shift%20Type", payload);
                }
                catch { }
            }
        }


