        [HttpPost]
        [ValidateAntiForgeryToken]

        public async Task<ActionResult> CreateEmployee(Employee model)
        {
            ApplyEmployeeChildTablesFromRequest(model);
            model.FullName = BuildEmployeeFullName(model);

            if (!model.DateOfJoining.HasValue)
            {
                ModelState.AddModelError("DateOfJoining", "Date of Joining is required.");
                TempData["ErpNextError"] = "Date of Joining is required before creating Employee in ERPNext.";
                await LoadEmployeeDropdownsAsync();
                return View(model);
            }

            if (string.IsNullOrWhiteSpace(model.Company))
            {
                ModelState.AddModelError("Company", "Company is required.");
                TempData["ErpNextError"] = "Company is required before creating Employee in ERPNext.";
                await LoadEmployeeDropdownsAsync();
                return View(model);
            }

            if (string.IsNullOrWhiteSpace(model.FirstName) && string.IsNullOrWhiteSpace(model.FullName))
            {
                ModelState.AddModelError("FirstName", "First Name is required.");
                TempData["ErpNextError"] = "First Name is required before creating Employee in ERPNext.";
                await LoadEmployeeDropdownsAsync();
                return View(model);
            }

            string erpNextId = null;

            try
            {
                var erpEmployeeFields = await GetErpNextEmployeeFieldnamesAsync();
                var payload = FilterEmployeePayload(BuildEmployeeErpNextPayload(model), erpEmployeeFields);

                payload["date_of_joining"] = model.DateOfJoining.Value.ToString("yyyy-MM-dd");

                var resultJson = await _erpNextService.PostResourceAsync("Employee", payload);
                erpNextId = JObject.Parse(resultJson)["data"]?["name"]?.ToString();

                model.ErpNextId = erpNextId;
                model.EmployeeCode = string.IsNullOrWhiteSpace(erpNextId)
                    ? _employeeService.GetNextEmployeeCode()
                    : erpNextId;
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext employee create failed: " + ShortErpNextError(ex.Message);
                await LoadEmployeeDropdownsAsync();
                return View(model);
            }

            try
            {
                if (_employeeService.ExistsByErpNextIdOrCode(model.EmployeeCode))
                {
                    model.Id = _employeeService.UpsertFromErpNext(model);
                }
                else
                {
                    model.Id = _employeeService.InsertEmployee(model);
                }

                TempData["Success"] = $"Employee created in ERPNext and HRMS successfully. ERPNext Ref: {erpNextId}";
                return RedirectToAction("EmployeeDetails", new { id = model.Id });
            }
            catch (Exception ex)
            {
                if (!string.IsNullOrWhiteSpace(erpNextId))
                {
                    try
                    {
                        await _erpNextService.DeleteAsync($"/api/resource/Employee/{Uri.EscapeDataString(erpNextId)}");
                    }
                    catch
                    {
                    }
                }

                TempData["ErpNextError"] = "Local HRMS database save failed: " + ex.Message;
                await LoadEmployeeDropdownsAsync();
                return View(model);
            }
        }











        private async Task EnsureEmployeeHealthInsuranceExistsAsync(string providerName)
        {
            if (string.IsNullOrWhiteSpace(providerName)) return;

            string doctype = "Employee Health Insurance";
            try
            {
                string checkUrl = $"/api/resource/{Uri.EscapeDataString(doctype)}/{Uri.EscapeDataString(providerName)}";
                await _erpNextService.GetAsync(checkUrl);
            }
            catch
            {
                var payload = new Dictionary<string, object>
        {
            { "employee_health_insurance_name", providerName },
            { "name", providerName }
        };

                try
                {
                    await _erpNextService.PostAsync($"/api/resource/{Uri.EscapeDataString(doctype)}", payload);
                }
                catch { }
            }
        }




        // POST: HR/SyncBranchesFromErpNext
        // POST: HR/SyncBranchesFromErpNext
        [HttpPost]
        [Route("HR/SyncBranchesFromErpNext")]
        public async Task<ActionResult> SyncBranchesFromErpNext()
        {
            int syncedCount = 0;
            int skippedCount = 0;

            try
            {
                // Fetch branches using fields=["*"] to prevent field restriction errors
                var json = await _erpNextService.GetAsync("/api/resource/Branch?fields=[\"*\"]&limit_page_length=1000");
                dynamic parsed = JsonConvert.DeserializeObject(json);
                var items = parsed?.data;

                if (items != null)
                {
                    var existingBranches = _branchService.GetAllBranches();
                    var existingNames = new HashSet<string>(existingBranches.Select(b => b.BranchName), StringComparer.OrdinalIgnoreCase);

                    foreach (var item in items)
                    {
                        // Branch name is stored directly in item.name
                        string branchName = item.name?.ToString();

                        if (!string.IsNullOrWhiteSpace(branchName) && !existingNames.Contains(branchName))
                        {
                            _branchService.InsertBranch(branchName.Trim());
                            existingNames.Add(branchName.Trim());
                            syncedCount++;
                        }
                        else
                        {
                            skippedCount++;
                        }
                    }
                }

                TempData["Success"] = $"Successfully synced {syncedCount} branch(es) from ERPNext! ({skippedCount} already existed)";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Error syncing branches from ERPNext: " + ex.Message;
            }

            return RedirectToAction("Branches");
        }

        [HttpGet]
        [Route("HR/LeaveControlPanel")]
        public async Task<ActionResult> LeaveControlPanel()
        {
            // 1. Populate dropdowns from ERPNext
            await SyncAndPopulateControlPanelDropdownsAsync();

            // 2. Fetch employees using your database connection string directly (bypassing missing service method errors)
            var employees = new List<Erp_Aits.Models.Employee>();
            using (var conn = new Microsoft.Data.SqlClient.SqlConnection(_connectionString))
            {
                conn.Open();
                string query = "SELECT * FROM Employees WHERE IsDeleted = 0";
                using (var cmd = new Microsoft.Data.SqlClient.SqlCommand(query, conn))
                {
                    using (var reader = cmd.ExecuteReader())
                    {
                        while (reader.Read())
                        {
                            employees.Add(new Erp_Aits.Models.Employee
                            {
                                EmployeeCode = reader["EmployeeCode"]?.ToString() ?? reader["Employee"]?.ToString() ?? "",
                                FullName = reader["FullName"]?.ToString() ?? reader["EmployeeName"]?.ToString() ?? "",
                                Company = reader["Company"]?.ToString() ?? "AITS",
                                Department = reader["Department"]?.ToString() ?? ""
                            });
                        }
                    }
                }
            }
            ViewBag.Employees = employees;

            return View("~/Views/HR/LeaveControlPanel.cshtml");
        }
        private async Task SyncAndPopulateControlPanelDropdownsAsync()
        {
            var companies = new List<string>();
            var leavePolicyNames = new List<string>();
            var leavePeriodNames = new List<string>();
            var employmentTypes = new List<string>();
            var branches = new List<string>();
            var designations = new List<string>();
            var departments = new List<string>();
            var employeeGrades = new List<string>();

            try
            {
                // Fetch Companies from ERPNext "Company" resource
                var compResponse = await _erpNextService.GetAsync("/api/resource/Company?fields=[\"name\"]&limit_page_length=100");
                companies = ExtractNamesList(compResponse);

                // Fetch Leave Policies from ERPNext "Leave Policy" resource (using leave_policy name/title)
                var lpolResponse = await _erpNextService.GetAsync("/api/resource/Leave Policy?fields=[\"name\"]&limit_page_length=100");
                leavePolicyNames = ExtractNamesList(lpolResponse);

                // Fetch Leave Periods
                var lpResponse = await _erpNextService.GetAsync("/api/resource/Leave Period?fields=[\"name\"]&limit_page_length=100");
                leavePeriodNames = ExtractNamesList(lpResponse);

                // Fetch Employment Types
                var etResponse = await _erpNextService.GetAsync("/api/resource/Employment Type?fields=[\"name\"]&limit_page_length=100");
                employmentTypes = ExtractNamesList(etResponse);

                // Fetch Branches
                var bResponse = await _erpNextService.GetAsync("/api/resource/Branch?fields=[\"name\"]&limit_page_length=100");
                branches = ExtractNamesList(bResponse);

                // Fetch Designations
                var desResponse = await _erpNextService.GetAsync("/api/resource/Designation?fields=[\"name\"]&limit_page_length=100");
                designations = ExtractNamesList(desResponse);

                // Fetch Departments
                var deptResponse = await _erpNextService.GetAsync("/api/resource/Department?fields=[\"name\"]&limit_page_length=100");
                departments = ExtractNamesList(deptResponse);

                // Fetch Employee Grades
                var egResponse = await _erpNextService.GetAsync("/api/resource/Employee Grade?fields=[\"name\"]&limit_page_length=100");
                employeeGrades = ExtractNamesList(egResponse);
            }
            catch
            {
                companies.Add("Vinod Cookware India Private Limited");
                leavePolicyNames.Add("Standard Policy");
                leavePeriodNames.Add("2026-2027");
                employmentTypes.Add("Full-time");
                branches.Add("Pune");
                designations.Add("Software Engineer");
                departments.Add("Development");
                employeeGrades.Add("Grade A");
            }

            ViewBag.Companies = companies;
            ViewBag.LeavePoliciesStrings = leavePolicyNames;
            ViewBag.LeavePeriodsStrings = leavePeriodNames;
            ViewBag.EmploymentTypes = employmentTypes;
            ViewBag.Branches = branches;
            ViewBag.Designations = designations;
            ViewBag.Departments = departments;
            ViewBag.EmployeeGrades = employeeGrades;
        }

