        // POST: HR/SyncLocalBranchesToErpNext
        // POST: HR/SyncLocalBranchesToErpNext
        [HttpPost]
        [Route("HR/SyncLocalBranchesToErpNext")]
        public async Task<ActionResult> SyncLocalBranchesToErpNext()
        {
            int pushedCount = 0;
            int skippedCount = 0;

            try
            {
                // 1. Get all local branches from your database
                var localBranches = _branchService.GetAllBranches();

                foreach (var branch in localBranches)
                {
                    if (string.IsNullOrWhiteSpace(branch.BranchName)) continue;

                    string branchName = branch.BranchName.Trim();

                    try
                    {
                        // 2. Check if the branch already exists in ERPNext
                        string checkUrl = $"/api/resource/Branch/{Uri.EscapeDataString(branchName)}";
                        await _erpNextService.GetAsync(checkUrl);

                        // If no exception, it already exists on ERPNext
                        skippedCount++;
                    }
                    catch
                    {
                        // 3. If missing, push to ERPNext with the mandatory "branch" field
                        var payload = new Dictionary<string, object>
                {
                    { "branch", branchName },
                    { "branch_name", branchName },
                    { "name", branchName }
                };

                        await _erpNextService.PostAsync("/api/resource/Branch", payload);
                        pushedCount++;
                    }
                }

                TempData["Success"] = $"Successfully pushed {pushedCount} local branch(es) to ERPNext! ({skippedCount} already existed)";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Error pushing branches to ERPNext: " + ex.Message;
            }

            return RedirectToAction("Branches");
        }









