        // Helper — only adds a field to the payload if it actually has a value.
        // This avoids sending garbage/empty strings for ERPNext Link fields
        // (Department, Designation, Branch, Reports To, etc.), which is what
        // caused the earlier LinkValidationError.
        private void AddIfNotEmpty(Dictionary<string, object?> payload, string key, string value)
        {
            if (!string.IsNullOrWhiteSpace(value))
            {
                payload[key] = value.Trim();
            }
        }



        private static void SetText(Dictionary<string, object?> payload, string key, string value)
        {
            payload[key] = string.IsNullOrWhiteSpace(value) ? null : value.Trim();
        }

        private static void SetDate(Dictionary<string, object?> payload, string key, DateTime? value)
        {
            payload[key] = value.HasValue ? value.Value.ToString("yyyy-MM-dd") : null;
        }







        private async Task LoadEmployeeDropdownsAsync()
        {
            var employeeFields = await GetEmployeeDocFieldsForDropdownsAsync();

            // ERPNext Select fields
            ViewBag.Genders = GetEmployeeSelectOptions(employeeFields, new[] { "gender" }, "Female", "Male", "Other");
            ViewBag.Statuses = GetEmployeeSelectOptions(employeeFields, new[] { "status" }, "Active", "Inactive", "Suspended", "Left");
            ViewBag.PreferredContactEmails = GetEmployeeSelectOptions(employeeFields, new[] { "prefered_contact_email", "preferred_contact_email" }, "Company Email", "Personal Email", "User ID");
            ViewBag.AddressTypes = GetEmployeeSelectOptions(employeeFields, new[] { "current_accommodation_type", "permanent_accommodation_type" }, "Rented", "Owned", "Company Provided", "Relative");
            ViewBag.SalaryModes = GetEmployeeSelectOptions(employeeFields, new[] { "salary_mode" }, "Bank", "Cash", "Cheque");
            ViewBag.MaritalStatuses = GetEmployeeSelectOptions(employeeFields, new[] { "marital_status" }, "Single", "Married", "Divorced", "Widowed");
            ViewBag.BloodGroups = GetEmployeeSelectOptions(employeeFields, new[] { "blood_group" }, "A+", "A-", "B+", "B-", "AB+", "AB-", "O+", "O-");
            ViewBag.LeaveEncashedOptions = GetEmployeeSelectOptions(employeeFields, new[] { "leave_encashed" }, "Yes", "No");

            // ERPNext Link fields
            ViewBag.Companies = await LoadEmployeeLinkOptionsAsync(employeeFields, "company", "Company", 200);
            ViewBag.Salutations = await LoadEmployeeLinkOptionsAsync(employeeFields, "salutation", "Salutation", 200);
            ViewBag.Departments = await LoadEmployeeLinkOptionsAsync(employeeFields, "department", "Department", 500);
            ViewBag.Designations = await LoadEmployeeLinkOptionsAsync(employeeFields, "designation", "Designation", 500);
            ViewBag.Branches = await LoadEmployeeLinkOptionsAsync(employeeFields, "branch", "Branch", 500);
            ViewBag.EmployeeGrades = await LoadEmployeeLinkOptionsAsync(employeeFields, "grade", "Employee Grade", 300);
            ViewBag.EmploymentTypes = await LoadEmployeeLinkOptionsAsync(employeeFields, "employment_type", "Employment Type", 300);
            ViewBag.HolidayLists = await LoadEmployeeLinkOptionsAsync(employeeFields, "holiday_list", "Holiday List", 300);
            ViewBag.ShiftTypes = await LoadEmployeeLinkOptionsAsync(employeeFields, "default_shift", "Shift Type", 300);
            ViewBag.Currencies = await LoadEmployeeLinkOptionsAsync(employeeFields, "salary_currency", "Currency", 300);
            ViewBag.CostCenters = await LoadEmployeeLinkOptionsAsync(employeeFields, "payroll_cost_center", "Cost Center", 500);
            ViewBag.HealthInsuranceProviders = await LoadEmployeeLinkOptionsAsync(employeeFields, "health_insurance_provider", "Employee Health Insurance", 300);

            // Link fields needing extra display text
            ViewBag.Users = await FetchErpNextDropdownOptionsAsync("User", "[\"name\",\"full_name\"]", 1000);
            ViewBag.ReportsToEmployees = await FetchErpNextDropdownOptionsAsync("Employee", "[\"name\",\"employee_name\",\"reports_to\",\"user_id\"]", 1000);
            ViewBag.JobApplicants = await FetchErpNextDropdownOptionsAsync("Job Applicant", "[\"name\",\"applicant_name\"]", 1000);

            // Used in Profile child table if Level is dropdown/link
            ViewBag.EducationalLevels = await FetchErpNextDropdownOptionsAsync("Educational Qualification", "[\"name\"]", 300);
        }




        private async Task<JArray> GetEmployeeDocFieldsForDropdownsAsync()
        {
            try
            {
                var metaJson = await _erpNextService.GetAsync("/api/method/frappe.desk.form.load.getdoctype?doctype=Employee");
                var docs = JObject.Parse(metaJson)["docs"] as JArray;

                var employeeDoc = docs?
                    .OfType<JObject>()
                    .FirstOrDefault(doc =>
                        string.Equals(doc["doctype"]?.ToString(), "DocType", StringComparison.OrdinalIgnoreCase)
                        && string.Equals(doc["name"]?.ToString(), "Employee", StringComparison.OrdinalIgnoreCase));

                return employeeDoc?["fields"] as JArray ?? new JArray();
            }
            catch
            {
                return new JArray();
            }
        }

        private async Task<JArray> LoadEmployeeLinkOptionsAsync(JArray employeeFields, string fieldName, string fallbackDoctype, int limit)
        {
            var field = FindEmployeeField(employeeFields, fieldName);
            var linkedDoctype = field?["options"]?.ToString();

            if (string.IsNullOrWhiteSpace(linkedDoctype))
            {
                linkedDoctype = fallbackDoctype;
            }

            return await FetchErpNextDropdownOptionsAsync(linkedDoctype, "[\"name\"]", limit);
        }

        private async Task<JArray> FetchErpNextDropdownOptionsAsync(string doctype, string fieldsJson, int limit)
        {
            try
            {
                var url = "/api/resource/" + Uri.EscapeDataString(doctype)
                    + "?fields=" + Uri.EscapeDataString(fieldsJson)
                    + "&limit_page_length=" + limit;

                var response = await _erpNextService.GetAsync(url);
                return JObject.Parse(response)["data"] as JArray ?? new JArray();
            }
            catch
            {
                return new JArray();
            }
        }

        private static JObject FindEmployeeField(JArray employeeFields, params string[] fieldNames)
        {
            return employeeFields
                .OfType<JObject>()
                .FirstOrDefault(field =>
                    fieldNames.Any(fieldName =>
                        string.Equals(field["fieldname"]?.ToString(), fieldName, StringComparison.OrdinalIgnoreCase)));
        }

        private static JArray GetEmployeeSelectOptions(JArray employeeFields, string[] fieldNames, params string[] fallbackOptions)
        {
            var result = new JArray();
            var field = FindEmployeeField(employeeFields, fieldNames);
            var optionsText = field?["options"]?.ToString();

            if (!string.IsNullOrWhiteSpace(optionsText))
            {
                foreach (var option in optionsText.Replace("\r", "").Split('\n'))
                {
                    AddEmployeeSelectOption(result, option);
                }
            }

            if (!result.Any())
            {
                foreach (var option in fallbackOptions)
                {
                    AddEmployeeSelectOption(result, option);
                }
            }

            return result;
        }

        private static void AddEmployeeSelectOption(JArray result, string option)
        {
            option = (option ?? string.Empty).Trim();

            if (string.IsNullOrWhiteSpace(option))
            {
                return;
            }

            var alreadyExists = result
                .OfType<JObject>()
                .Any(item => string.Equals(item["name"]?.ToString(), option, StringComparison.OrdinalIgnoreCase));

            if (!alreadyExists)
            {
                result.Add(new JObject
                {
                    ["name"] = option
                });
            }
        }

        private async Task<HashSet<string>> GetErpNextEmployeeFieldnamesAsync()
        {
            var fieldnames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            try
            {
                var metaJson = await _erpNextService.GetAsync("/api/method/frappe.desk.form.load.getdoctype?doctype=Employee");
                var docs = JObject.Parse(metaJson)["docs"] as JArray;

                var employeeDoc = docs?
                    .OfType<JObject>()
                    .FirstOrDefault(doc =>
                        string.Equals(doc["doctype"]?.ToString(), "DocType", StringComparison.OrdinalIgnoreCase)
                        && string.Equals(doc["name"]?.ToString(), "Employee", StringComparison.OrdinalIgnoreCase));

                var fields = employeeDoc?["fields"] as JArray;

                if (fields != null)
                {
                    foreach (var field in fields)
                    {
                        string fieldname = field["fieldname"]?.ToString();
                        if (!string.IsNullOrWhiteSpace(fieldname))
                        {
                            fieldnames.Add(fieldname);
                        }
                    }
                }
            }
            catch
            {
                // If metadata fails, standard fields below will still be allowed.
            }

            fieldnames.Add("education");
            fieldnames.Add("external_work_history");
            fieldnames.Add("internal_work_history");
            fieldnames.Add("prefered_email");
            fieldnames.Add("pan_number");
            fieldnames.Add("provident_fund_account");
            fieldnames.Add("micr_code");
            fieldnames.Add("iban");
            fieldnames.Add("health_insurance_no");
            fieldnames.Add("encashment_date");

            return fieldnames;
        }

        private Dictionary<string, object?> FilterEmployeePayload(Dictionary<string, object?> payload, HashSet<string> allowedFields)
        {
            if (allowedFields == null || allowedFields.Count == 0)
            {
                return payload;
            }

            return payload
                .Where(item => allowedFields.Contains(item.Key))
                .ToDictionary(item => item.Key, item => item.Value);
        }

        private Dictionary<string, object?> BuildEmployeeErpNextPayload(Employee model)
        {
