            SetText(payload, "first_name", FirstNonEmpty(model.FirstName, model.FullName, model.EmployeeCode));
            SetText(payload, "middle_name", model.MiddleName);
            SetText(payload, "last_name", model.LastName);
            SetText(payload, "employee_name", BuildEmployeeFullName(model));
            SetText(payload, "salutation", model.Salutation);
            SetText(payload, "gender", model.Gender);
            SetDate(payload, "date_of_birth", model.DateOfBirth);
            SetDate(payload, "date_of_joining", model.DateOfJoining);
            SetText(payload, "status", string.IsNullOrWhiteSpace(model.Status) ? "Active" : model.Status);

            SetText(payload, "company", model.Company);
            SetText(payload, "department", model.Department);
            SetText(payload, "designation", model.Designation);
            SetText(payload, "grade", model.Grade);
            SetText(payload, "employment_type", model.EmploymentType);
            SetText(payload, "reports_to", model.ReportsTo);
            SetText(payload, "employee_number", model.EmployeeNumber);
            SetText(payload, "branch", model.Branch);
            SetText(payload, "user_id", model.UserId);

            SetText(payload, "job_applicant", model.JobApplicant);
            SetDate(payload, "scheduled_confirmation_date", model.OfferDate);
            SetDate(payload, "final_confirmation_date", model.ConfirmationDate);
            SetInt(payload, "notice_number_of_days", model.NoticeDays);
            SetDate(payload, "contract_end_date", model.ContractEndDate);
            SetDate(payload, "date_of_retirement", model.DateOfRetirement);

            SetText(payload, "cell_number", model.Mobile);
            SetText(payload, "personal_email", model.PersonalEmail);
            SetText(payload, "company_email", model.CompanyEmail);
            SetText(payload, "prefered_contact_email", model.PreferredContactEmail);
            //SetText(payload, "prefered_email", model.PreferredEmail);
            SetCheck(payload, "unsubscribed", model.Unsubscribed);
            SetText(payload, "current_address", model.CurrentAddress);
            SetText(payload, "permanent_address", model.PermanentAddress);
            SetText(payload, "current_accommodation_type", model.CurrentAddressIs);
            SetText(payload, "permanent_accommodation_type", model.PermanentAddressIs);
            SetText(payload, "person_to_be_contacted", model.EmergencyContactName);
            SetText(payload, "emergency_phone_number", model.EmergencyPhone);
            SetText(payload, "relation", model.Relation);

            SetText(payload, "attendance_device_id", model.AttendanceDeviceId);
            SetText(payload, "holiday_list", model.HolidayList);
            SetText(payload, "default_shift", model.DefaultShift);
            SetText(payload, "expense_approver", model.ExpenseApprover);
            SetText(payload, "shift_request_approver", model.ShiftRequestApprover);
            SetText(payload, "leave_approver", model.LeaveApprover);

            SetDecimal(payload, "ctc", model.CTC);
            SetText(payload, "salary_currency", model.SalaryCurrency);
            SetText(payload, "payroll_cost_center", model.PayrollCostCenter);
            SetText(payload, "salary_mode", model.SalaryMode);
            SetText(payload, "bank_name", model.BankName);
            SetText(payload, "bank_ac_no", model.BankAccountNo);
            SetText(payload, "ifsc_code", model.IFSCCode);


            SetText(payload, "marital_status", model.MaritalStatus);
            SetText(payload, "blood_group", model.BloodGroup);
            SetText(payload, "family_background", model.FamilyBackground);
            SetText(payload, "health_details", model.HealthDetails);
            SetText(payload, "health_insurance_provider", model.HealthInsuranceProvider);
            SetText(payload, "passport_number", model.PassportNumber);
            SetDate(payload, "date_of_issue", model.PassportDateOfIssue);
            SetDate(payload, "valid_upto", model.PassportValidUpto);
            SetText(payload, "place_of_issue", model.PassportPlaceOfIssue);
            SetText(payload, "bio", model.Bio);
            SetText(payload, "micr_code", model.MICRCode);
            SetText(payload, "iban", model.IBAN);

            SetDate(payload, "resignation_letter_date", model.ResignationLetterDate);
            SetDate(payload, "relieving_date", model.RelievingDate);
            SetDate(payload, "held_on", model.ExitInterviewHeldOn);
            var leaveEncashedValue = model.LeaveEncashed?.Trim();

            if (string.Equals(leaveEncashedValue, "true", StringComparison.OrdinalIgnoreCase) ||
                string.Equals(leaveEncashedValue, "on", StringComparison.OrdinalIgnoreCase))
            {
                leaveEncashedValue = "Yes";
            }
            else if (string.Equals(leaveEncashedValue, "false", StringComparison.OrdinalIgnoreCase))
            {
                leaveEncashedValue = "No";
            }

            SetText(payload, "leave_encashed", leaveEncashedValue);
            SetText(payload, "new_workplace", model.NewWorkplace);
            SetText(payload, "reason_for_leaving", model.ReasonForLeaving);
            SetText(payload, "feedback", model.Feedback);
            AddEmployeeChildTablePayloads(payload, model);

            return payload;
        }





        private static void AddEmployeeChildTablePayloads(Dictionary<string, object?> payload, Employee model)
        {
            if (model.ChildTablesPosted || (model.EducationRows != null && model.EducationRows.Any(HasEmployeeEducationData)))
            {
                payload["education"] = (model.EducationRows ?? new List<EmployeeEducationRow>())
                    .Where(HasEmployeeEducationData)
                    .Select(row =>
                    {
                        var child = new Dictionary<string, object?>();
                        SetText(child, "school_univ", row.SchoolUniversity);
                        SetText(child, "qualification", row.Qualification);
                        SetText(child, "level", row.Level);
                        SetInt(child, "year_of_passing", row.YearOfPassing);
                        SetText(child, "class_per", row.ClassPercentage);
                        SetText(child, "maj_opt_subj", row.MajorOptionalSubjects);
                        return child;
                    })
                    .ToList();
            }

            if (model.ChildTablesPosted || (model.ExternalWorkHistoryRows != null && model.ExternalWorkHistoryRows.Any(HasEmployeeExternalWorkHistoryData)))
            {
                payload["external_work_history"] = (model.ExternalWorkHistoryRows ?? new List<EmployeeExternalWorkHistoryRow>())
                    .Where(HasEmployeeExternalWorkHistoryData)
                    .Select(row =>
                    {
                        var child = new Dictionary<string, object?>();
                        SetText(child, "company_name", row.CompanyName);
                        SetText(child, "designation", row.Designation);
                        SetDecimal(child, "salary", row.Salary);
                        SetText(child, "address", row.Address);
                        SetText(child, "contact", row.Contact);
                        SetText(child, "total_experience", row.TotalExperience);
                        return child;
                    })
                    .ToList();
            }

            if (model.ChildTablesPosted || (model.InternalWorkHistoryRows != null && model.InternalWorkHistoryRows.Any(HasEmployeeInternalWorkHistoryData)))
            {
                payload["internal_work_history"] = (model.InternalWorkHistoryRows ?? new List<EmployeeInternalWorkHistoryRow>())
                    .Where(HasEmployeeInternalWorkHistoryData)
                    .Select(row =>
                    {
                        var child = new Dictionary<string, object?>();
                        SetText(child, "branch", row.Branch);
                        SetText(child, "department", row.Department);
                        SetText(child, "designation", row.Designation);
                        SetDate(child, "from_date", row.FromDate);
                        SetDate(child, "to_date", row.ToDate);
                        return child;
                    })
                    .ToList();
            }
        }



















