        private static List<EmployeeEducationRow> MapEmployeeEducationRows(JArray rows)
        {
            var result = new List<EmployeeEducationRow>();
            if (rows == null) return result;

            foreach (var doc in rows.OfType<JObject>())
            {
                var row = new EmployeeEducationRow
                {
                    SchoolUniversity = ReadText(doc, "school_univ"),
                    Qualification = ReadText(doc, "qualification"),
                    Level = ReadText(doc, "level"),
                    YearOfPassing = ReadInt(doc, "year_of_passing"),
                    ClassPercentage = ReadText(doc, "class_per"),
                    MajorOptionalSubjects = ReadText(doc, "maj_opt_subj")
                };

                if (HasEmployeeEducationData(row))
                {
                    result.Add(row);
                }
            }

            return result;
        }

        private static List<EmployeeExternalWorkHistoryRow> MapEmployeeExternalWorkHistoryRows(JArray rows)
        {
            var result = new List<EmployeeExternalWorkHistoryRow>();
            if (rows == null) return result;

            foreach (var doc in rows.OfType<JObject>())
            {
                var row = new EmployeeExternalWorkHistoryRow
                {
                    CompanyName = ReadText(doc, "company_name"),
                    Designation = ReadText(doc, "designation"),
                    Salary = ReadDecimal(doc, "salary"),
                    Address = ReadText(doc, "address"),
                    Contact = ReadText(doc, "contact"),
                    TotalExperience = ReadText(doc, "total_experience")
                };

                if (HasEmployeeExternalWorkHistoryData(row))
                {
                    result.Add(row);
                }
            }

            return result;
        }

        private static List<EmployeeInternalWorkHistoryRow> MapEmployeeInternalWorkHistoryRows(JArray rows, string parentBranch)
        {
            var result = new List<EmployeeInternalWorkHistoryRow>();
            if (rows == null) return result;

            foreach (var doc in rows.OfType<JObject>())
            {
