                    ToDate = ReadDate(doc, "to_date")
                };

                if (HasEmployeeInternalWorkHistoryData(row))
                {
                    result.Add(row);
                }
            }

            return result;
        }



















        private async Task<bool> ErpNextEmployeeExistsAsync(string erpNextId)
        {
            if (string.IsNullOrWhiteSpace(erpNextId)) return false;

            try
            {
                await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(erpNextId)}");
                return true;
            }
            catch (Exception ex) when (IsErpNextMissing(ex))
            {
                return false;
            }
        }





        private static bool IsErpNextModifiedConflict(Exception ex)
        {
            var message = ex.Message ?? "";

            return message.Contains("Document has been modified after you have opened it", StringComparison.OrdinalIgnoreCase)
                || message.Contains("TimestampMismatchError", StringComparison.OrdinalIgnoreCase)
                || message.Contains("Please refresh to get the latest document", StringComparison.OrdinalIgnoreCase);
        }

        private async Task PutErpNextEmployeeWithRetryAsync(string employeeId, Dictionary<string, object?> payload)
        {
            RemoveErpNextSystemFields(payload);

            for (int attempt = 1; attempt <= 2; attempt++)
            {
                try
                {
                    await _erpNextService.PutResourceAsync("Employee", employeeId, payload);
                    return;
                }
                catch (Exception ex) when (attempt == 1 && IsErpNextModifiedConflict(ex))
                {
                    await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(employeeId)}");
                    await Task.Delay(700);
                }
            }

            await _erpNextService.PutResourceAsync("Employee", employeeId, payload);
        }

        private static void RemoveErpNextSystemFields(Dictionary<string, object?> payload)
        {
            payload.Remove("modified");
            payload.Remove("modified_by");
            payload.Remove("creation");
            payload.Remove("owner");
            payload.Remove("docstatus");
            payload.Remove("idx");
            payload.Remove("_user_tags");
            payload.Remove("_comments");
            payload.Remove("_assign");
            payload.Remove("_liked_by");
        }






































        // ---- Employee Details ----
        public async Task<ActionResult> EmployeeDetails(int id)
        {
            var model = _employeeService.GetById(id);
            if (model == null) return NotFound();

            if (!string.IsNullOrWhiteSpace(model.ErpNextId))
            {
                try
                {
                    var response = await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(model.ErpNextId)}");
                    var doc = JObject.Parse(response)["data"] as JObject;

                    if (doc != null)
                    {
                        var latestFromErpNext = MapEmployeeFromErpNext(doc);

                        latestFromErpNext.Id = model.Id;
                        latestFromErpNext.Branch = FirstNonEmpty(latestFromErpNext.Branch, model.Branch);
                        latestFromErpNext.EmployeeCode = string.IsNullOrWhiteSpace(latestFromErpNext.EmployeeCode)
                            ? model.EmployeeCode
                            : latestFromErpNext.EmployeeCode;

                        latestFromErpNext.ErpNextId = string.IsNullOrWhiteSpace(latestFromErpNext.ErpNextId)
                            ? model.ErpNextId
                            : latestFromErpNext.ErpNextId;

                        _employeeService.UpdateEmployeeFull(latestFromErpNext);
                        model = _employeeService.GetById(id) ?? latestFromErpNext;
                    }
                }
                catch (Exception ex)
                {
                    TempData["ErpNextError"] = "ERPNext refresh failed: " + ShortErpNextError(ex.Message);
                }
            }

            await LoadEmployeeDropdownsAsync();
            return View(model);
        }

