            payload["reason_for_leaving"] = model.ReasonForLeaving;
            payload["feedback"] = model.Feedback;
            payload["date_of_birth"] = model.DateOfBirth?.ToString("yyyy-MM-dd");
            payload["date_of_joining"] = model.DateOfJoining?.ToString("yyyy-MM-dd");
            payload["scheduled_confirmation_date"] = model.OfferDate?.ToString("yyyy-MM-dd");
            payload["final_confirmation_date"] = model.ConfirmationDate?.ToString("yyyy-MM-dd");
            payload["contract_end_date"] = model.ContractEndDate?.ToString("yyyy-MM-dd");
            payload["date_of_retirement"] = model.DateOfRetirement?.ToString("yyyy-MM-dd");
            payload["date_of_issue"] = model.PassportDateOfIssue?.ToString("yyyy-MM-dd");
            payload["valid_upto"] = model.PassportValidUpto?.ToString("yyyy-MM-dd");
            payload["resignation_letter_date"] = model.ResignationLetterDate?.ToString("yyyy-MM-dd");
            payload["relieving_date"] = model.RelievingDate?.ToString("yyyy-MM-dd");
            payload["held_on"] = model.ExitInterviewHeldOn?.ToString("yyyy-MM-dd");

            try
            {
                string remoteId = model.ErpNextId;

                if (!string.IsNullOrWhiteSpace(remoteId) && await ErpNextEmployeeExistsAsync(remoteId))
                {
                    //await _erpNextService.PutResourceAsync("Employee", remoteId, payload);
                    await PutErpNextEmployeeWithRetryAsync(remoteId, payload);
                    var namePayload = new Dictionary<string, object?>
                    {
                        ["salutation"] = model.Salutation,
                        ["first_name"] = model.FirstName,
                        ["middle_name"] = model.MiddleName,
                        ["last_name"] = model.LastName,
                        ["employee_name"] = model.FullName
                    };

                    //await _erpNextService.PutResourceAsync("Employee", remoteId, namePayload);
                    await PutErpNextEmployeeWithRetryAsync(remoteId, namePayload);

                    var mismatches = await VerifyErpNextEmployeePayloadAsync(remoteId, payload);

                    if (mismatches.Any())
                    {
                        TempData["ErpNextError"] =
                            "ERPNext did not save these fields: " +
                            string.Join("; ", mismatches.Take(12)) +
                            (mismatches.Count > 12 ? $" ... and {mismatches.Count - 12} more." : "");

                        await LoadEmployeeDropdownsAsync();
                        return View(model);
                    }
                }
                else
                {
                    var resultJson = await _erpNextService.PostResourceAsync("Employee", payload);
                    remoteId = JObject.Parse(resultJson)["data"]?["name"]?.ToString();

                    if (!string.IsNullOrWhiteSpace(remoteId))
                    {
                        model.ErpNextId = remoteId;
                        model.EmployeeCode = string.IsNullOrWhiteSpace(model.EmployeeCode) ? remoteId : model.EmployeeCode;
                    }
                }

                _employeeService.UpdateEmployeeFull(model);
                TempData["Success"] = $"Employee updated in ERPNext and HRMS successfully. ERPNext Ref: {model.ErpNextId}";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext validation failed. Local employee was not updated: " + ShortErpNextError(ex.Message);
                await LoadEmployeeDropdownsAsync();
                return View(model);
            }

            return RedirectToAction("EmployeeDetails", new { id = model.Id });
        }






        private async Task DeleteEmployeeDependenciesInErpNextAsync(string employeeId)
        {
            if (string.IsNullOrWhiteSpace(employeeId))
            {
                return;
            }

            try
            {
                await DeleteErpNextDocsLinkedToEmployeeAsync("Employee Skill Map", employeeId);
            }
            catch (Exception ex) when (IsErpNextMissing(ex))
            {
                // Dependency was already missing. Do not stop employee delete.
            }
        }

        private async Task DeleteErpNextDocsLinkedToEmployeeAsync(string doctype, string employeeId)
        {
            string fields = Uri.EscapeDataString("[\"name\"]");

            string filtersJson = new JArray(
                new JArray(doctype, "employee", "=", employeeId)
            ).ToString(Newtonsoft.Json.Formatting.None);

            string filters = Uri.EscapeDataString(filtersJson);

            string url =
                $"/api/resource/{Uri.EscapeDataString(doctype)}?fields={fields}&filters={filters}&limit_page_length=1000";

            string response = await _erpNextService.GetAsync(url);
            var rows = JObject.Parse(response)["data"] as JArray;

            if (rows == null || rows.Count == 0)
            {
                return;
            }

            foreach (var row in rows.OfType<JObject>())
            {
                string name = ReadText(row, "name");

                if (string.IsNullOrWhiteSpace(name))
                {
                    continue;
                }

                try
                {
                    await _erpNextService.DeleteAsync(
                        $"/api/resource/{Uri.EscapeDataString(doctype)}/{Uri.EscapeDataString(name)}"
                    );
                }
                catch (Exception ex) when (IsErpNextMissing(ex))
                {
                    // Linked document was already deleted. Continue.
                }
            }
        }















