        [HttpPost]
        public async Task<ActionResult> DeleteEmployee(int id)
        {
            var model = _employeeService.GetById(id);

            if (model == null)
            {
                TempData["ErpNextError"] = "Employee not found locally.";
                return RedirectToAction("Employee");
            }

            string erpEmployeeId = FirstNonEmpty(model.ErpNextId, model.EmployeeCode);

            try
            {
                if (!string.IsNullOrWhiteSpace(erpEmployeeId))
                {
                    await DeleteEmployeeDependenciesInErpNextAsync(erpEmployeeId);

                    try
                    {
                        await _erpNextService.DeleteAsync($"/api/resource/Employee/{Uri.EscapeDataString(erpEmployeeId)}");
                    }
                    catch (Exception ex) when (IsErpNextMissing(ex))
                    {
                        bool employeeStillExists = await ErpNextEmployeeStillExistsAsync(erpEmployeeId);

                        if (employeeStillExists)
                        {
                            throw;
                        }

                        // Employee is already gone in ERPNext. Continue local delete.
                    }

                    if (await ErpNextEmployeeStillExistsAsync(erpEmployeeId))
                    {
                        TempData["ErpNextError"] = "ERPNext delete failed. Employee still exists in ERPNext, so local employee was not deleted.";
                        return RedirectToAction("Employee");
                    }
                }

                _employeeSkillMapService.DeleteByEmployee(erpEmployeeId);
                _employeeService.DeleteEmployee(id);

                TempData["Success"] = !string.IsNullOrWhiteSpace(erpEmployeeId)
                    ? "Employee deleted from ERPNext and HRMS successfully."
                    : "Employee deleted from HRMS. No ERPNext ID was linked.";
            }
            catch (Exception ex) when (IsErpNextMissing(ex))
            {
                if (!string.IsNullOrWhiteSpace(erpEmployeeId) && await ErpNextEmployeeStillExistsAsync(erpEmployeeId))
                {
                    TempData["ErpNextError"] = "ERPNext delete failed. Employee still exists in ERPNext, so local employee was not deleted: " + ShortErpNextError(ex.Message);
                    return RedirectToAction("Employee");
                }

                _employeeSkillMapService.DeleteByEmployee(erpEmployeeId);
                _employeeService.DeleteEmployee(id);
                TempData["Success"] = "Employee was already missing in ERPNext, so it was deleted from HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext delete failed. Local employee was not deleted: " + ShortErpNextError(ex.Message);
            }

            return RedirectToAction("Employee");
        }




        private async Task<bool> ErpNextEmployeeStillExistsAsync(string employeeId)
        {
            if (string.IsNullOrWhiteSpace(employeeId))
            {
                return false;
            }

            try
            {
                await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(employeeId)}");
                return true;
            }
            catch (Exception ex) when (IsErpNextMissing(ex))
            {
                return false;
            }
        }














        [HttpPost]
        [Route("HR/ERPNextWebhook/Employee")]
        public async Task<IActionResult> EmployeeWebhook()
        {
            string webhookEmployeeName = null;

            try
            {
                using var reader = new StreamReader(Request.Body);
                string requestBody = await reader.ReadToEndAsync();
                var json = string.IsNullOrWhiteSpace(requestBody) ? new JObject() : JObject.Parse(requestBody);
                var data = json["data"] as JObject ?? json["doc"] as JObject ?? json;
                string employeeName = FirstNonEmpty(ReadText(data, "name"), ReadText(json, "docname"));
                string eventName = FirstNonEmpty(Request.Headers["X-Frappe-Webhook-Event"].FirstOrDefault(), ReadText(json, "event"), ReadText(json, "doc_event"));
                webhookEmployeeName = employeeName;

                if (string.IsNullOrWhiteSpace(employeeName))
                {
                    return BadRequest(new { success = false, error = "Employee name was not supplied by ERPNext webhook." });
                }

                if (eventName.Contains("delete", StringComparison.OrdinalIgnoreCase)
      || eventName.Contains("trash", StringComparison.OrdinalIgnoreCase))
                {
                    _employeeSkillMapService.DeleteByEmployee(employeeName);
                    _employeeService.DeleteEmployeeByErpNextId(employeeName);
                    return Ok(new { success = true, action = "deleted" });
                }

                var detailResponse = await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(employeeName)}");
                var doc = JObject.Parse(detailResponse)["data"] as JObject;

                if (doc != null)
                {
                    _employeeService.UpsertFromErpNext(MapEmployeeFromErpNext(doc));
                }

                return Ok(new { success = true, action = "upserted" });
            }
            catch (Exception ex) when (IsErpNextMissing(ex))
            {
                string employeeName = FirstNonEmpty(webhookEmployeeName, Request.Query["name"].FirstOrDefault());
                _employeeSkillMapService.DeleteByEmployee(employeeName);
                _employeeService.DeleteEmployeeByErpNextId(employeeName);
                return Ok(new { success = true, action = "deleted" });
            }
            catch (Exception ex)
            {
                return BadRequest(new { success = false, error = ShortErpNextError(ex.Message) });
            }
        }






