        public ActionResult EmployeeInformation(string empId, string empName)
        {
            var employees = _employeeService.GetAllEmployees(null);
            if (!string.IsNullOrEmpty(empId))
            {
                employees = employees.Where(e => e.EmployeeCode != null && e.EmployeeCode.Contains(empId, StringComparison.OrdinalIgnoreCase)).ToList();
            }
            if (!string.IsNullOrEmpty(empName))
            {
                employees = employees.Where(e => e.FullName != null && e.FullName.Contains(empName, StringComparison.OrdinalIgnoreCase)).ToList();
            }

            ViewBag.EmpId = empId;
            ViewBag.EmpName = empName;
            return View(employees);
        }

