        // GET: HR/SyncCompensatoryLeaveRequestsFromErpNext
        [HttpGet]
        [Route("HR/SyncCompensatoryLeaveRequestsFromErpNext")]
        public async Task<ActionResult> SyncCompensatoryLeaveRequestsFromErpNext()
        {
            int inserted = 0;
            int updated = 0;
            var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            try
            {
                string fields = Uri.EscapeDataString("[\"name\",\"employee\",\"employee_name\",\"leave_type\",\"work_from_date\",\"work_end_date\",\"half_day\",\"reason\",\"docstatus\"]");
                string json = await _erpNextService.GetAsync($"/api/resource/{Uri.EscapeDataString("Compensatory Leave Request")}?fields={fields}&limit_page_length=1000&order_by=creation%20desc");
                dynamic parsed = JsonConvert.DeserializeObject(json);

                if (parsed?.data != null)
                {
                    foreach (var item in parsed.data)
                    {
                        string erpNextId = item.name?.ToString();
                        if (!string.IsNullOrWhiteSpace(erpNextId))
                        {
                            erpIds.Add(erpNextId);
                        }

                        if (!string.IsNullOrEmpty(erpNextId))
                        {
                            int docStatus = item.docstatus != null ? Convert.ToInt32(item.docstatus) : 0;
                            var request = new CompensatoryLeaveRequest
                            {
                                ErpNextId = erpNextId,
                                Employee = item.employee?.ToString(),
                                EmployeeName = item.employee_name?.ToString() ?? item.employee?.ToString(),
                                LeaveType = item.leave_type?.ToString(),
                                WorkFromDate = item.work_from_date != null ? Convert.ToDateTime(item.work_from_date) : (DateTime?)null,
                                WorkEndDate = item.work_end_date != null ? Convert.ToDateTime(item.work_end_date) : (DateTime?)null,
                                HalfDay = item.half_day != null && Convert.ToBoolean(item.half_day),
                                Reason = item.reason?.ToString(),
                                Status = docStatus == 1 ? "Submitted" : docStatus == 2 ? "Cancelled" : "Draft"
                            };

                            if (_compensatoryLeaveRequestService.ExistsByErpNextId(erpNextId))
                            {
                                _compensatoryLeaveRequestService.UpdateFromErpNext(request);
                                updated++;
                            }
                            else
                            {
                                _compensatoryLeaveRequestService.InsertFromErpNext(request);
                                inserted++;
                            }
                        }
                    }
                }

                SoftDeleteMissingErpDocuments("CompensatoryLeaveRequests", "ErpNextId", erpIds);
                TempData["Success"] = $"Compensatory Leave Requests synced from ERPNext. New: {inserted}, Updated: {updated}.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Sync failed: " + ex.Message;
            }

            return RedirectToAction("CompensatoryLeaveRequestList");
        }
