        [HttpPost]
        [Route("HR/SyncEmployeeGroupsFromErpNext")]
        public async Task<ActionResult> SyncEmployeeGroupsFromErpNext()
        {
            try
            {
                // ============================================================
                // 1. GET ALL EMPLOYEE GROUP IDS FROM ERPNext
                // ============================================================

                var listResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Group" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=1000"
                    );

                var listJson =
                    JObject.Parse(listResponse);

                var groups =
                    listJson["data"] as JArray;

                int syncedCount = 0;


                if (groups != null)
                {
                    foreach (var item in groups)
                    {
                        string erpId =
                            item["name"]?.ToString();

                        if (string.IsNullOrWhiteSpace(erpId))
                            continue;


                        // ====================================================
                        // 2. GET COMPLETE EMPLOYEE GROUP DOCUMENT
                        //    INCLUDING employee_list
                        // ====================================================

                        var detailResponse =
                            await _erpNextService.GetAsync(
                                "/api/resource/Employee%20Group/" +
                                Uri.EscapeDataString(erpId)
                            );

                        var detailJson =
                            JObject.Parse(detailResponse);

                        var doc =
                            detailJson["data"];

                        if (doc == null)
                            continue;


                        // ====================================================
                        // 3. MAP ERP DATA TO HRMS MODEL
                        // ====================================================

                        var group =
                            new EmployeeGroup
                            {
                                ErpNextId =
                                    doc["name"]?.ToString()
                                    ?? "",

                                GroupCode =
                                    doc["name"]?.ToString()
                                    ?? "",

                                GroupName =
                                    doc["employee_group_name"]?.ToString()
                                    ?? doc["name"]?.ToString()
                                    ?? "",

                                Members =
                                    new List<EmployeeGroupMember>()
                            };


                        // ====================================================
                        // 4. MAP ERP CHILD TABLE employee_list
                        // ====================================================

                        var employeeList =
                            doc["employee_list"] as JArray;


                        if (employeeList != null)
                        {
                            foreach (var member in employeeList)
                            {
                                group.Members.Add(
                                    new EmployeeGroupMember
                                    {
                                        Employee =
                                            member["employee"]?.ToString()
                                            ?? "",

                                        EmployeeName =
                                            member["employee_name"]?.ToString()
                                            ?? "",

                                        ERPNextUserId =
                                            member["user_id"]?.ToString()
                                            ?? ""
                                    }
                                );
                            }
                        }


                        // ====================================================
                        // 5. INSERT NEW OR UPDATE EXISTING HRMS RECORD
                        // ====================================================

                        _employeeGroupService
                            .InsertOrUpdate(group);


                        syncedCount++;
                    }
                }


                TempData["Success"] =
                    syncedCount +
                    " Employee Group(s) synced successfully from ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "ERPNext sync failed: " +
                    ex.Message;
            }


            return RedirectToAction(
                "EmployeeGroups",
                "HR"
            );
        }








        [HttpGet]
        [Route("HR/CreateTravelRequest")]
        public async Task<ActionResult> CreateTravelRequest()
        {
            TravelRequest modelToRestore = null;

            var purposeList = new List<string> { "Conference", "Client Meeting", "Training", "+ Create New Purpose of Travel" };
            var idTypesList = new List<string> { "Passport", "National ID", "Aadhar", "+ Create New Identification Document" };
            var grievanceTypesList = new List<string> { "General", "Harassment", "Workplace", "+ Create New Grievance Type" };

            try
            {
                // Restore form data if returning from creating a master record
                if (TempData["RestoredForm"] != null)
                {
                    modelToRestore = JsonConvert.DeserializeObject<TravelRequest>(TempData["RestoredForm"].ToString());
                }

                try
                {
                    var empJson = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=500");
                    dynamic empParsed = JsonConvert.DeserializeObject(empJson);
                    ViewBag.Employees = empParsed?.data;
                }
                catch { ViewBag.Employees = new List<object>(); }

                try
                {
                    var ccJson = await _erpNextService.GetAsync("/api/resource/Cost Center?fields=[\"name\"]&limit_page_length=500");
                    dynamic ccParsed = JsonConvert.DeserializeObject(ccJson);
                    ViewBag.CostCenters = ccParsed?.data;
                }
                catch { ViewBag.CostCenters = new List<object>(); }

                try
                {
                    var expJson = await _erpNextService.GetAsync("/api/resource/Expense Claim Type?fields=[\"name\"]&limit_page_length=500");
                    dynamic expParsed = JsonConvert.DeserializeObject(expJson);
                    ViewBag.ExpenseTypes = expParsed?.data;
                }
                catch { ViewBag.ExpenseTypes = new List<object>(); }

                try
                {
                    var purpJson = await _erpNextService.GetAsync("/api/resource/Purpose of Travel?fields=[\"name\"]&limit_page_length=500");
                    dynamic purpParsed = JsonConvert.DeserializeObject(purpJson);
                    if (purpParsed?.data != null)
                    {
                        purposeList.Clear();
                        foreach (var p in purpParsed.data)
                        {
                            purposeList.Add(p.name.ToString());
                        }
                        purposeList.Add("+ Create New Purpose of Travel");
                    }
                }
                catch { }

                try
                {
                    var idJson = await _erpNextService.GetAsync("/api/resource/Identification Document Type?fields=[\"name\"]&limit_page_length=500");
                    dynamic idParsed = JsonConvert.DeserializeObject(idJson);
                    if (idParsed?.data != null)
                    {
                        idTypesList.Clear();
                        foreach (var i in idParsed.data)
                        {
                            idTypesList.Add(i.name.ToString());
                        }
                        idTypesList.Add("+ Create New Identification Document");
                    }
                }
                catch { }

                try
                {
                    var gJson = await _erpNextService.GetAsync("/api/resource/Grievance Type?fields=[\"name\"]&limit_page_length=500");
                    dynamic gParsed = JsonConvert.DeserializeObject(gJson);
                    if (gParsed?.data != null)
                    {
                        grievanceTypesList.Clear();
                        foreach (var g in gParsed.data)
                        {
                            grievanceTypesList.Add(g.name.ToString());
                        }
                        grievanceTypesList.Add("+ Create New Grievance Type");
                    }
                }
                catch { }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Connection warning: Could not reach ERPNext cloud. Loaded with default options. (" + ex.Message + ")";
            }

            ViewBag.PurposeOfTravelOptions = purposeList;
            ViewBag.IdentificationDocumentTypes = idTypesList;
            ViewBag.GrievanceTypes = grievanceTypesList;
            ViewBag.TravelTypes = new List<string> { "Domestic", "International" };
            ViewBag.TravelFunding = new List<string> { "Require Full Funding", "Fully Sponsored", "Partially Sponsored, Require Partial Funding" };
            ViewBag.ModesOfTravel = new List<string> { "Flight", "Train", "Taxi", "Bus" };

            return View("~/Views/HR/CreateTravelRequest.cshtml", modelToRestore ?? new TravelRequest());
        }

        private async Task<TravelRequest> RefreshTravelRequestFromErpNextAsync(string code)
        {
            if (string.IsNullOrWhiteSpace(code))
                return null;

            string detailJson = await _erpNextService.GetAsync(
                "/api/resource/Travel%20Request/" +
                Uri.EscapeDataString(code)
            );

            JToken doc = JObject.Parse(detailJson)["data"];

            if (doc == null)
                return null;

            TravelRequest request =
                _travelRequestService.MapErpTravelRequest(doc, code);

            _travelRequestService.InsertOrUpdateTravelRequest(request);

            return _travelRequestService.GetByCode(code);
        }

        private Dictionary<string, object> BuildTravelRequestPayload(TravelRequest model)
        {
            var itinerary = (model.Itineraries ?? new List<TravelItinerary>())
                .Where(x =>
                    !string.IsNullOrWhiteSpace(x.TravelFrom) ||
                    !string.IsNullOrWhiteSpace(x.TravelTo))
                .Select(x => new Dictionary<string, object>
                {
                    ["travel_from"] = x.TravelFrom,
                    ["travel_to"] = x.TravelTo,
                    ["mode_of_travel"] = x.ModeOfTravel,
                    ["departure_date"] = x.DepartureDatetime?.ToString("yyyy-MM-dd HH:mm:ss")
                })
                .Cast<object>()
                .ToList();

            var costing = (model.Costings ?? new List<TravelCosting>())
                .Where(x => !string.IsNullOrWhiteSpace(x.ExpenseType))
                .Select(x => new Dictionary<string, object>
                {
                    ["expense_type"] = x.ExpenseType,
                    ["sponsored_amount"] = x.SponsoredAmount,
                    ["funded_amount"] = x.FundedAmount,
                    ["total_amount"] = x.TotalAmount
                })
                .Cast<object>()
                .ToList();

            return new Dictionary<string, object>
            {
                ["travel_type"] = model.TravelType,
                ["purpose_of_travel"] = model.PurposeOfTravel,
                ["travel_funding"] = model.TravelFunding,
                ["details_of_sponsor"] = model.DetailsOfSponsor,
                ["travel_proof"] = model.CopyOfInvitation,
                ["employee"] = model.Employee,
                ["company"] = model.Company,
                ["personal_id_type"] = model.IdentificationDocumentType,
                ["personal_id_number"] = model.IdentificationDocumentNumber,
                ["cell_number"] = model.ContactNumber,
                ["prefered_email"] = model.ContactEmail,
                ["passport_number"] = model.PassportNumber,
                ["description"] = model.OtherDetailsDescription,
                ["itinerary"] = itinerary,
                ["costings"] = costing,
                ["cost_center"] = model.CostCenter,
                ["name_of_organizer"] = model.NameOfOrganizer,
                ["address_of_organizer"] = model.AddressOfOrganizer,
                ["other_details"] = model.EventOtherDetails
            };
        }

        private async Task PrepareTravelRequestForErpAsync(TravelRequest model)
        {
            if (string.IsNullOrWhiteSpace(model.TravelType))
                throw new Exception("Select Travel Type.");

            if (string.IsNullOrWhiteSpace(model.PurposeOfTravel))
                throw new Exception("Select Purpose of Travel.");

            if (string.IsNullOrWhiteSpace(model.Employee))
                throw new Exception("Select Employee.");

            string empJson = await _erpNextService.GetAsync(
                "/api/resource/Employee/" +
                Uri.EscapeDataString(model.Employee)
            );

            JToken emp = JObject.Parse(empJson)["data"];

            if (emp == null)
                throw new Exception("Employee not found in ERPNext.");

            if (emp["status"]?.ToString() != "Active")
                throw new Exception("Employee must be active.");

            model.EmployeeName = emp["employee_name"]?.ToString();
            model.DateOfBirth = DateTime.TryParse(emp["date_of_birth"]?.ToString(), out var dob)
                ? dob
                : model.DateOfBirth;
            model.ContactNumber = string.IsNullOrWhiteSpace(model.ContactNumber)
                ? emp["cell_number"]?.ToString()
                : model.ContactNumber;
            model.ContactEmail = string.IsNullOrWhiteSpace(model.ContactEmail)
                ? emp["company_email"]?.ToString() ?? emp["personal_email"]?.ToString()
                : model.ContactEmail;
            model.PassportNumber = string.IsNullOrWhiteSpace(model.PassportNumber)
                ? emp["passport_number"]?.ToString()
                : model.PassportNumber;
            model.Company = string.IsNullOrWhiteSpace(model.Company)
                ? emp["company"]?.ToString()
                : model.Company;

            if (string.IsNullOrWhiteSpace(model.Company))
                throw new Exception("Select Company.");

            await _erpNextService.GetAsync(
                "/api/resource/Company/" +
                Uri.EscapeDataString(model.Company)
            );

            await _erpNextService.GetAsync(
                "/api/resource/Purpose%20of%20Travel/" +
                Uri.EscapeDataString(model.PurposeOfTravel)
            );

            if (!string.IsNullOrWhiteSpace(model.IdentificationDocumentType))
            {
                await _erpNextService.GetAsync(
                    "/api/resource/Identification%20Document%20Type/" +
                    Uri.EscapeDataString(model.IdentificationDocumentType)
                );
            }

            if (!string.IsNullOrWhiteSpace(model.CostCenter))
            {
                await _erpNextService.GetAsync(
                    "/api/resource/Cost%20Center/" +
                    Uri.EscapeDataString(model.CostCenter)
                );
            }
        }

