        [HttpGet]
        [Route("HR/GetAppraisalDropdown")]
        public async Task<JsonResult> GetAppraisalDropdown(
            string field,
            string search = "")
        {
            string doctype;

            switch (field)
            {
                case "key_result_area":
                    doctype = "KRA";
                    break;

                case "criteria":
                    doctype = "Employee Feedback Criteria";
                    break;

                default:
                    return Json(new
                    {
                        success = false,
                        message = "Invalid dropdown field."
                    });
            }

            try
            {
                string url =
                    "/api/method/frappe.desk.search.search_link" +
                    "?doctype=" + Uri.EscapeDataString(doctype) +
                    "&txt=" + Uri.EscapeDataString(search ?? "") +
                    "&reference_doctype=" +
                        Uri.EscapeDataString("Appraisal Template") +
                    "&page_length=100";

                string response = await _erpNextService.GetAsync(url);

                var json = Newtonsoft.Json.Linq.JObject.Parse(response);

                var records = json["message"] as Newtonsoft.Json.Linq.JArray
                              ?? new Newtonsoft.Json.Linq.JArray();

                return Json(new
                {
                    success = true,
                    items = records.Select(x => new
                    {
                        value = x["value"]?.ToString(),
                        description = x["description"]?.ToString()
                    }).ToList()
                });
            }
            catch (Exception ex)
            {
                return Json(new
                {
                    success = false,
                    message = ex.Message
                });
            }
        }





        [HttpPost]
        [Route("HR/CreateTravelRequest")]
        public async Task<ActionResult> CreateTravelRequest(TravelRequest model)
        {
            try
            {
                await PrepareTravelRequestForErpAsync(model);
                var payload = BuildTravelRequestPayload(model);

                // ERP FIRST: let ERPNext validate and generate the document ID.
                string resultJson = await _erpNextService.PostAsync(
                    "/api/resource/Travel%20Request",
                    payload
                );

                var result = Newtonsoft.Json.Linq.JObject.Parse(resultJson);

                string erpId = result["data"]?["name"]?.ToString();

                if (string.IsNullOrWhiteSpace(erpId))
                    throw new Exception("ERPNext did not return Travel Request ID.");

                // Fetch the saved ERP document.
                string detailJson = await _erpNextService.GetAsync(
                    "/api/resource/Travel%20Request/" +
                    Uri.EscapeDataString(erpId)
                );

                var doc = Newtonsoft.Json.Linq.JObject.Parse(detailJson)["data"];

                if (doc == null)
                    throw new Exception(
                        "Created in ERPNext, but could not retrieve saved details. ERP ID: " +
                        erpId
                    );

                TravelRequest saved =
                    _travelRequestService.MapErpTravelRequest(doc, erpId);

                _travelRequestService.InsertOrUpdateTravelRequest(saved);

                TempData["Success"] =
                    "Travel Request created in ERPNext and HRMS: " + erpId;

                return RedirectToAction(
                    "TravelRequestDetails",
                    new { code = erpId }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanTravelRequestErpError(ex.Message);

                return RedirectToAction("CreateTravelRequest");
            }
        }























