        [HttpPost]
        [Route("HR/CreateLeavePolicyAssignment")]
        public async Task<ActionResult>
     CreateLeavePolicyAssignment(
         LeavePolicyAssignment model)
        {
            try
            {
                // ============================================================
                // REQUIRED
                // ============================================================

                if (string.IsNullOrWhiteSpace(model.Employee))
                    throw new Exception("Employee is required.");

                if (string.IsNullOrWhiteSpace(model.LeavePolicy))
                    throw new Exception("Leave Policy is required.");


                // ============================================================
                // GET EMPLOYEE FROM ERP
                //
                // company and employee_name are fetched fields in ERP.
                // ============================================================

                string employeeJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee/" +
                        Uri.EscapeDataString(
                            model.Employee
                        )
                    );


                JObject employeeObject =
                    JObject.Parse(employeeJson);


                JToken employee =
                    employeeObject["data"];


                if (employee == null)
                    throw new Exception("Employee not found in ERPNext.");


                model.EmployeeName =
                    employee["employee_name"]?.ToString() ?? "";


                model.Company =
                    employee["company"]?.ToString() ?? "";


                // ============================================================
                // VALIDATE LEAVE POLICY EXISTS
                // ============================================================

                await _erpNextService.GetAsync(
                    "/api/resource/Leave%20Policy/" +
                    Uri.EscapeDataString(
                        model.LeavePolicy
                    )
                );


                // ============================================================
                // ASSIGNMENT BASED ON
                // ============================================================

                if (model.AssignmentBasedOn == "Leave Period")
                {
                    if (string.IsNullOrWhiteSpace(model.LeavePeriod))
                    {
                        throw new Exception(
                            "Leave Period is required when Assignment Based On is Leave Period."
                        );
                    }


                    // Load actual dates from ERP Leave Period.
                    string periodJson =
                        await _erpNextService.GetAsync(
                            "/api/resource/Leave%20Period/" +
                            Uri.EscapeDataString(
                                model.LeavePeriod
                            )
                        );


                    JObject periodObject =
                        JObject.Parse(periodJson);


                    JToken period =
                        periodObject["data"];


                    if (period == null)
                        throw new Exception("Leave Period not found.");


                    if (!DateTime.TryParse(
                        period["from_date"]?.ToString(),
                        out DateTime fromDate))
                    {
                        throw new Exception(
                            "Leave Period From Date is invalid."
                        );
                    }


                    if (!DateTime.TryParse(
                        period["to_date"]?.ToString(),
                        out DateTime toDate))
                    {
                        throw new Exception(
                            "Leave Period To Date is invalid."
                        );
                    }


                    model.EffectiveFrom = fromDate;
                    model.EffectiveTo = toDate;
                }
                else if (model.AssignmentBasedOn == "Joining Date")
                {
                    string joiningDateValue =
                        employee["date_of_joining"]?.ToString();


                    if (!DateTime.TryParse(
                        joiningDateValue,
                        out DateTime joiningDate))
                    {
                        throw new Exception(
                            "Date of Joining is required for this Employee."
                        );
                    }


                    model.EffectiveFrom =
                        joiningDate;


                    // ERP sets this automatically if empty.
                    if (model.EffectiveTo == default(DateTime))
                    {
                        model.EffectiveTo =
                            joiningDate
                                .AddMonths(12);


                        model.EffectiveTo =
                            new DateTime(
                                model.EffectiveTo.Year,
                                model.EffectiveTo.Month,
                                DateTime.DaysInMonth(
                                    model.EffectiveTo.Year,
                                    model.EffectiveTo.Month
                                )
                            );
                    }
                }
                else
                {
                    // ERP technically allows blank Assignment Based On,
                    // but then dates must be provided.
                    if (model.EffectiveFrom == default(DateTime))
                        throw new Exception("Effective From is required.");

                    if (model.EffectiveTo == default(DateTime))
                        throw new Exception("Effective To is required.");
                }


                if (model.EffectiveTo < model.EffectiveFrom)
                {
                    throw new Exception(
                        "Effective To cannot be before Effective From."
                    );
                }


                // ============================================================
                // ERP PAYLOAD
                //
                // IMPORTANT FIELD:
                // carry_forward
                // not add_unused_leaves
                // ============================================================

                var payload =
                    new
                    {
                        employee =
                            model.Employee,

                        leave_policy =
                            model.LeavePolicy,

                        assignment_based_on =
                            string.IsNullOrWhiteSpace(
                                model.AssignmentBasedOn
                            )
                                ? null
                                : model.AssignmentBasedOn,

                        leave_period =
                            model.AssignmentBasedOn == "Leave Period"
                                ? model.LeavePeriod
                                : null,

                        effective_from =
                            model.EffectiveFrom
                                .ToString("yyyy-MM-dd"),

                        effective_to =
                            model.EffectiveTo
                                .ToString("yyyy-MM-dd"),

                        carry_forward =
                            model.AddUnusedLeaves
                                ? 1
                                : 0
                    };


                // ============================================================
                // CREATE ERP DRAFT FIRST
                //
                // ERP validates overlap + date derivation + links.
                // ============================================================

                string createJson =
                    await _erpNextService.PostAsync(
                        "/api/resource/Leave%20Policy%20Assignment",
                        payload
                    );


                JObject createObject =
                    JObject.Parse(createJson);


                string erpId =
                    createObject["data"]?["name"]
                        ?.ToString();


                if (string.IsNullOrWhiteSpace(erpId))
                {
                    throw new Exception(
                        "ERPNext did not return Leave Policy Assignment ID."
                    );
                }


                // ============================================================
                // RELOAD EXACT ERP RESULT
                // ============================================================

                string detailJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Leave%20Policy%20Assignment/" +
                        Uri.EscapeDataString(
                            erpId
                        )
                    );


                JObject detailObject =
                    JObject.Parse(detailJson);


                LeavePolicyAssignment local =
                    MapErpLeavePolicyAssignment(
                        detailObject["data"]
                    );


                int localId =
                    _leavePolicyAssignmentService
                        .InsertOrUpdate(
                            local
                        );


                TempData["Success"] =
                    "Leave Policy Assignment saved as Draft. ERPNext Ref: "
                    + erpId;


                return RedirectToAction(
                    "LeavePolicyAssignmentDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanLeavePolicyAssignmentErpError(
                        ex.Message
                    );


                await PopulatePolicyAssignmentDropdownsAsync();


                return View(
                    "~/Views/HR/CreateLeavePolicyAssignment.cshtml",
                    model
                );
            }
        }




        private LeavePolicyAssignment
    MapErpLeavePolicyAssignment(
        JToken doc)
        {
            if (doc == null)
                return null;


            var model =
                new LeavePolicyAssignment
                {
                    ErpNextId =
                        doc["name"]?.ToString() ?? "",

                    Employee =
                        doc["employee"]?.ToString() ?? "",

                    EmployeeName =
                        doc["employee_name"]?.ToString() ?? "",

                    Company =
                        doc["company"]?.ToString() ?? "",

                    LeavePolicy =
                        doc["leave_policy"]?.ToString() ?? "",

                    AssignmentBasedOn =
                        doc["assignment_based_on"]?.ToString() ?? "",

                    LeavePeriod =
                        doc["leave_period"]?.ToString() ?? "",

                    AddUnusedLeaves =
                        (
                            doc["carry_forward"]?.ToObject<int>()
                            ?? 0
                        ) == 1,

                    LeavesAllocated =
                        (
                            doc["leaves_allocated"]?.ToObject<int>()
                            ?? 0
                        ) == 1,

                    DocStatus =
                        doc["docstatus"]?.ToObject<int>()
                        ?? 0,

                    AmendedFrom =
                        doc["amended_from"]?.ToString() ?? ""
                };


            if (DateTime.TryParse(
                doc["effective_from"]?.ToString(),
                out DateTime from))
            {
                model.EffectiveFrom = from;
            }


            if (DateTime.TryParse(
                doc["effective_to"]?.ToString(),
                out DateTime to))
            {
                model.EffectiveTo = to;
            }


            return model;
        }

        private async Task PrepareLeavePolicyAssignmentForErpAsync(
            LeavePolicyAssignment model)
        {
            if (string.IsNullOrWhiteSpace(model.Employee))
                throw new Exception("Employee is required.");

            if (string.IsNullOrWhiteSpace(model.LeavePolicy))
                throw new Exception("Leave Policy is required.");

            string employeeJson =
                await _erpNextService.GetAsync(
                    "/api/resource/Employee/" +
                    Uri.EscapeDataString(model.Employee)
                );

            JObject employeeObject = JObject.Parse(employeeJson);
            JToken employee = employeeObject["data"];

            if (employee == null)
                throw new Exception("Employee not found in ERPNext.");

            model.EmployeeName = employee["employee_name"]?.ToString() ?? "";
            model.Company = employee["company"]?.ToString() ?? "";

            await _erpNextService.GetAsync(
                "/api/resource/Leave%20Policy/" +
                Uri.EscapeDataString(model.LeavePolicy)
            );

            if (model.AssignmentBasedOn == "Leave Period")
            {
                if (string.IsNullOrWhiteSpace(model.LeavePeriod))
                    throw new Exception(
                        "Leave Period is required when Assignment Based On is Leave Period."
                    );

                string periodJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Leave%20Period/" +
                        Uri.EscapeDataString(model.LeavePeriod)
                    );

                JObject periodObject = JObject.Parse(periodJson);
                JToken period = periodObject["data"];

                if (period == null)
                    throw new Exception("Leave Period not found.");

                if (!DateTime.TryParse(
                        period["from_date"]?.ToString(),
                        out DateTime fromDate))
                {
                    throw new Exception("Leave Period From Date is invalid.");
                }

                if (!DateTime.TryParse(
                        period["to_date"]?.ToString(),
                        out DateTime toDate))
                {
                    throw new Exception("Leave Period To Date is invalid.");
                }

                model.EffectiveFrom = fromDate;
                model.EffectiveTo = toDate;
            }
            else if (model.AssignmentBasedOn == "Joining Date")
            {
                string joiningDateValue =
                    employee["date_of_joining"]?.ToString();

                if (!DateTime.TryParse(
                        joiningDateValue,
                        out DateTime joiningDate))
                {
                    throw new Exception(
                        "Date of Joining is required for this Employee."
                    );
                }

                model.EffectiveFrom = joiningDate;

                if (model.EffectiveTo == default(DateTime))
                {
                    DateTime endDate = joiningDate.AddMonths(12);
                    model.EffectiveTo =
                        new DateTime(
                            endDate.Year,
                            endDate.Month,
                            DateTime.DaysInMonth(
                                endDate.Year,
                                endDate.Month
                            )
                        );
                }
            }
            else
            {
                if (model.EffectiveFrom == default(DateTime))
                    throw new Exception("Effective From is required.");

                if (model.EffectiveTo == default(DateTime))
                    throw new Exception("Effective To is required.");
            }

            if (model.EffectiveTo < model.EffectiveFrom)
                throw new Exception("Effective To cannot be before Effective From.");
        }


        private Dictionary<string, object> BuildLeavePolicyAssignmentPayload(
            LeavePolicyAssignment model)
        {
            return new Dictionary<string, object>
            {
                ["employee"] = model.Employee,
                ["leave_policy"] = model.LeavePolicy,
                ["assignment_based_on"] =
                    string.IsNullOrWhiteSpace(model.AssignmentBasedOn)
                        ? null
                        : model.AssignmentBasedOn,
                ["leave_period"] =
                    model.AssignmentBasedOn == "Leave Period"
                        ? model.LeavePeriod
                        : null,
                ["effective_from"] = model.EffectiveFrom.ToString("yyyy-MM-dd"),
                ["effective_to"] = model.EffectiveTo.ToString("yyyy-MM-dd"),
                ["carry_forward"] = model.AddUnusedLeaves ? 1 : 0
            };
        }


        private async Task<LeavePolicyAssignment>
            RefreshLeavePolicyAssignmentFromErpNextAsync(string erpId)
        {
            string detailJson =
                await _erpNextService.GetAsync(
                    "/api/resource/Leave%20Policy%20Assignment/" +
                    Uri.EscapeDataString(erpId)
                );

            JObject detailObject = JObject.Parse(detailJson);

            return MapErpLeavePolicyAssignment(detailObject["data"]);
        }


        private async Task<(int inserted, int updated, int failed)>
            PullLeavePolicyAssignmentsFromErpNext()
        {
            string listJson =
                await _erpNextService.GetAsync(
                    "/api/resource/Leave%20Policy%20Assignment" +
                    "?fields=[\"name\"]" +
                    "&limit_page_length=5000"
                );

            JObject listObject = JObject.Parse(listJson);
            JArray rows = listObject["data"] as JArray;

            int inserted = 0;
            int updated = 0;
            int failed = 0;
            var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            if (rows != null)
            {
                foreach (JToken row in rows)
                {
                    try
                    {
                        string erpId = row["name"]?.ToString();

                        if (string.IsNullOrWhiteSpace(erpId))
                            continue;

                        erpIds.Add(erpId);

                        bool exists =
                            _leavePolicyAssignmentService
                                .GetByErpNextId(erpId) != null;

                        LeavePolicyAssignment model =
                            await RefreshLeavePolicyAssignmentFromErpNextAsync(
                                erpId
                            );

                        if (model == null)
                        {
                            failed++;
                            continue;
                        }

                        _leavePolicyAssignmentService.InsertOrUpdate(model);

                        if (exists)
                            updated++;
                        else
                            inserted++;
                    }
                    catch (Exception recordEx)
                    {
                        failed++;

                        System.Diagnostics.Debug.WriteLine(
                            recordEx.Message
                        );
                    }
                }
            }

            SoftDeleteMissingErpDocuments(
                "LeavePolicyAssignments",
                "ErpNextId",
                erpIds
            );

            return (inserted, updated, failed);
        }


        [HttpGet]
        [Route("HR/SyncLeavePolicyAssignmentsFromErpNext")]
        public async Task<ActionResult>
            SyncLeavePolicyAssignmentsFromErpNext()
        {
            try
            {
                var result = await PullLeavePolicyAssignmentsFromErpNext();


                TempData["Success"] =
                    "Leave Policy Assignment sync completed. New: "
                    + result.inserted
                    + ", Updated: "
                    + result.updated
                    + ", Failed: "
                    + result.failed
                    + ".";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanLeavePolicyAssignmentErpError(
                        ex.Message
                    );
            }


            return RedirectToAction(
                "LeavePolicyAssignment"
            );
        }

        [HttpPost]
        [Route("HR/UpdateLeavePolicyAssignment")]
        public async Task<ActionResult> UpdateLeavePolicyAssignment(
            int id,
            LeavePolicyAssignment model)
        {
            try
            {
                LeavePolicyAssignment local =
                    _leavePolicyAssignmentService.GetById(id);

                if (local == null)
                    throw new Exception("Leave Policy Assignment not found.");

                if (local.DocStatus != 0)
                    throw new Exception(
                        "Cannot edit a submitted or cancelled Leave Policy Assignment."
                    );

                if (string.IsNullOrWhiteSpace(local.ErpNextId))
                    throw new Exception("ERPNext reference is missing.");

                model.Id = local.Id;
                model.ErpNextId = local.ErpNextId;
                model.DocStatus = local.DocStatus;

                await PrepareLeavePolicyAssignmentForErpAsync(model);

                await _erpNextService.PutAsync(
                    "/api/resource/Leave%20Policy%20Assignment/" +
                    Uri.EscapeDataString(local.ErpNextId),
                    BuildLeavePolicyAssignmentPayload(model)
                );

                LeavePolicyAssignment refreshed =
                    await RefreshLeavePolicyAssignmentFromErpNextAsync(
                        local.ErpNextId
                    );

                _leavePolicyAssignmentService.InsertOrUpdate(refreshed);

                TempData["Success"] =
                    "Leave Policy Assignment saved successfully.";

                return RedirectToAction(
                    "LeavePolicyAssignmentDetails",
                    new { id = id }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanLeavePolicyAssignmentErpError(ex.Message);

                model.Id = id;
                await PopulatePolicyAssignmentDropdownsAsync();

                return View(
                    "~/Views/HR/LeavePolicyAssignmentDetails.cshtml",
                    model
                );
            }
        }


        [HttpPost]
        [Route("HR/SubmitLeavePolicyAssignment")]
        public async Task<ActionResult>
    SubmitLeavePolicyAssignment(
        int id)
        {
            try
            {
                var local =
                    _leavePolicyAssignmentService
                        .GetById(id);


                if (local == null)
                    throw new Exception(
                        "Leave Policy Assignment not found."
                    );


                if (string.IsNullOrWhiteSpace(
                    local.ErpNextId))
                {
                    throw new Exception(
                        "ERPNext reference is missing."
                    );
                }


                if (local.DocStatus != 0)
                {
                    throw new Exception(
                        "Only Draft Leave Policy Assignments can be submitted."
                    );
                }


                LeavePolicyAssignment refreshedDraft =
                    await RefreshLeavePolicyAssignmentFromErpNextAsync(
                        local.ErpNextId
                    );

                if (refreshedDraft == null)
                    throw new Exception(
                        "Leave Policy Assignment was not found in ERPNext."
                    );

                string detailJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Leave%20Policy%20Assignment/" +
                        Uri.EscapeDataString(local.ErpNextId)
                    );

                JObject detail = JObject.Parse(detailJson);

                await _erpNextService.PostMethodAsync(
                    "/api/method/frappe.client.submit",
                    new
                    {
                        doc = detail["data"]
                    }
                );


                // Reload ERP because submission creates allocations
                // and updates leaves_allocated.
                LeavePolicyAssignment refreshed =
                    await RefreshLeavePolicyAssignmentFromErpNextAsync(
                        local.ErpNextId
                    );


                _leavePolicyAssignmentService
                    .InsertOrUpdate(
                        refreshed
                    );


                TempData["Success"] =
                    "Leave Policy Assignment submitted successfully. Leave Allocations were processed by ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanLeavePolicyAssignmentErpError(
                        ex.Message
                    );
            }


            return RedirectToAction(
                "LeavePolicyAssignmentDetails",
                new { id = id }
            );
        }

        [HttpPost]
        [Route("HR/CancelLeavePolicyAssignment")]
        public async Task<ActionResult> CancelLeavePolicyAssignment(int id)
        {
            try
            {
                LeavePolicyAssignment local =
                    _leavePolicyAssignmentService.GetById(id);

                if (local == null)
                    throw new Exception("Leave Policy Assignment not found.");

                if (string.IsNullOrWhiteSpace(local.ErpNextId))
                    throw new Exception("ERPNext reference is missing.");

                if (local.DocStatus != 1)
                    throw new Exception(
                        "Only submitted Leave Policy Assignments can be cancelled."
                    );

                int cancelledAllocations =
                    await CancelLinkedLeaveAllocationsForPolicyAssignmentAsync(local);

                await _erpNextService.PostMethodAsync(
                    "/api/method/frappe.client.cancel",
                    new
                    {
                        doctype = "Leave Policy Assignment",
                        name = local.ErpNextId
                    }
                );

                LeavePolicyAssignment refreshed =
                    await RefreshLeavePolicyAssignmentFromErpNextAsync(
                        local.ErpNextId
                    );

                _leavePolicyAssignmentService.InsertOrUpdate(refreshed);

                TempData["Success"] =
                    "Leave Policy Assignment cancelled successfully. "
                    + cancelledAllocations
                    + " linked Leave Allocation(s) were cancelled in ERPNext and HRMS.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanLeavePolicyAssignmentErpError(ex.Message);
            }

            return RedirectToAction(
                "LeavePolicyAssignmentDetails",
                new { id = id }
            );
        }

        private async Task<int>
            CancelLinkedLeaveAllocationsForPolicyAssignmentAsync(
                LeavePolicyAssignment assignment)
        {
            string filters = JsonConvert.SerializeObject(new object[]
            {
                new object[] { "Leave Allocation", "employee", "=", assignment.Employee }
            });

            string listJson = await _erpNextService.GetAsync(
                "/api/resource/Leave%20Allocation?fields=[\"name\"]&limit_page_length=5000&filters="
                + Uri.EscapeDataString(filters));
            var rows = JObject.Parse(listJson)["data"] as JArray;
            int cancelled = 0;

            if (rows == null)
                return cancelled;

            foreach (var row in rows)
            {
                string allocationId = row["name"]?.ToString();
                if (string.IsNullOrWhiteSpace(allocationId))
                    continue;

                string detailJson = await _erpNextService.GetAsync(
                    "/api/resource/Leave%20Allocation/"
                    + Uri.EscapeDataString(allocationId));
                JToken allocation = JObject.Parse(detailJson)["data"];
                if (allocation == null)
                    continue;

                if (!IsLinkedLeaveAllocation(allocation, assignment))
                    continue;

                int docStatus = allocation["docstatus"]?.ToObject<int>() ?? 0;
                if (docStatus == 1)
                {
                    await _erpNextService.PostMethodAsync(
                        "/api/method/frappe.client.cancel",
                        new
                        {
                            doctype = "Leave Allocation",
                            name = allocationId
                        });

                    detailJson = await _erpNextService.GetAsync(
                        "/api/resource/Leave%20Allocation/"
                        + Uri.EscapeDataString(allocationId));
                    allocation = JObject.Parse(detailJson)["data"];
                    cancelled++;
                }

                if (allocation != null)
                    _leaveAllocationService.InsertOrUpdate(
                        MapErpLeaveAllocation(allocation));
            }

            return cancelled;
        }

        private static bool IsLinkedLeaveAllocation(
            JToken allocation,
            LeavePolicyAssignment assignment)
        {
            string linkedAssignment = allocation["leave_policy_assignment"]?.ToString()
                ?? allocation["from_leave_policy_assignment"]?.ToString()
                ?? allocation["leave_policy_assignment_name"]?.ToString();

            if (string.Equals(
                linkedAssignment,
                assignment.ErpNextId,
                StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }

            // Older ERPNext schemas can omit the explicit link. In that case,
            // use the policy and the assignment's effective period as the safe
            // fallback, while still limiting the search to the same employee.
            if (!string.IsNullOrWhiteSpace(linkedAssignment)
                || !string.Equals(
                    allocation["leave_policy"]?.ToString(),
                    assignment.LeavePolicy,
                    StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            DateTime.TryParse(allocation["from_date"]?.ToString(), out DateTime fromDate);
            DateTime.TryParse(allocation["to_date"]?.ToString(), out DateTime toDate);
            return fromDate >= assignment.EffectiveFrom.Date
                && toDate <= assignment.EffectiveTo.Date;
        }




        private string CleanLeavePolicyAssignmentErpError(
    string rawError)
        {
            if (string.IsNullOrWhiteSpace(rawError))
                return "ERPNext validation failed.";


            try
            {
                int start =
                    rawError.IndexOf('{');


                if (start >= 0)
                {
                    JObject json =
                        JObject.Parse(
                            rawError.Substring(start)
                        );


                    string messages =
                        json["_server_messages"]
                            ?.ToString();


                    if (!string.IsNullOrWhiteSpace(messages))
                    {
                        JArray arr =
                            JArray.Parse(messages);


                        if (arr.Count > 0)
                        {
                            JObject first =
                                JObject.Parse(
                                    arr[0].ToString()
                                );


                            string msg =
                                first["message"]
                                    ?.ToString();


                            if (!string.IsNullOrWhiteSpace(msg))
                            {
                                msg =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        msg,
                                        "<[^>]*>",
                                        ""
                                    );


                                return System.Net.WebUtility
                                    .HtmlDecode(msg)
                                    .Trim();
                            }
                        }
                    }
                }
            }
            catch
            {
            }


            return rawError.Length > 250
                ? rawError.Substring(0, 250) + "..."
                : rawError;
        }








        private async Task PopulatePolicyAssignmentDropdownsAsync()
        {
            try
            {
                // ============================================================
                // ACTIVE EMPLOYEES
                // Need company + date_of_joining because ERP derives fields.
                // ============================================================

                string employeeJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee" +
                        "?fields=[" +
                            "\"name\"," +
                            "\"employee_name\"," +
                            "\"company\"," +
                            "\"date_of_joining\"" +
                        "]" +
                        "&filters=[[\"status\",\"=\",\"Active\"]]" +
                        "&limit_page_length=5000"
                    );


                dynamic employeeParsed =
                    JsonConvert.DeserializeObject(
                        employeeJson
                    );


                ViewBag.EmployeesList =
                    employeeParsed?.data;


                // ============================================================
                // LEAVE POLICIES
                // ============================================================

                string policyJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Leave%20Policy" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=5000"
                    );


                dynamic policyParsed =
                    JsonConvert.DeserializeObject(
                        policyJson
                    );


                ViewBag.LeavePolicies =
                    policyParsed?.data;


                // ============================================================
                // LEAVE PERIODS
                //
                // Keep fields minimal to avoid Frappe "field not permitted"
                // issue like you faced earlier.
                // ============================================================

                string periodJson =
                    await _erpNextService.GetAsync(
                        "/api/resource/Leave%20Period" +
                        "?fields=[\"name\"]" +
                        "&limit_page_length=5000"
                    );


                dynamic periodParsed =
                    JsonConvert.DeserializeObject(
                        periodJson
                    );


                ViewBag.LeavePeriods =
                    periodParsed?.data;
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanLeavePolicyAssignmentErpError(
                        ex.Message
                    );

                ViewBag.EmployeesList =
                    new List<object>();

                ViewBag.LeavePolicies =
                    new List<object>();

                ViewBag.LeavePeriods =
                    new List<object>();
            }
        }



        [HttpGet]
        [Route("HR/SyncLeaveEncashmentsFromErpNext")]
        public async Task<ActionResult> SyncLeaveEncashmentsFromErpNext()
        {
            try
            {
                var listResponse = await _erpNextService.GetAsync("/api/resource/Leave%20Encashment?limit_page_length=500");
                dynamic listParsed = JsonConvert.DeserializeObject(listResponse);

                var service = new LeaveEncashmentService(_connectionString);
                int count = 0;

                if (listParsed?.data != null)
                {
                    foreach (var listItem in listParsed.data)
                    {
                        string docName = listItem.name?.ToString();
                        if (string.IsNullOrEmpty(docName)) continue;

                        try
                        {
                            var detailResponse = await _erpNextService.GetAsync($"/api/resource/Leave%20Encashment/{Uri.EscapeDataString(docName)}");
                            dynamic detailParsed = JsonConvert.DeserializeObject(detailResponse);
                            var item = detailParsed?.data;

                            if (item != null)
                            {
                                string emp = item.employee?.ToString();
                                string lPeriod = item.leave_period?.ToString();
                                string lType = item.leave_type?.ToString();

                                // Fetch existing items for this employee without using a lambda on dynamic types
                                var existingList = service.GetAll(null, item.employee_name?.ToString());
                                bool alreadyExists = false;

                                foreach (var existingItem in existingList)
                                {
                                    if (existingItem.Employee == emp && existingItem.LeavePeriod == lPeriod && existingItem.LeaveType == lType)
                                    {
                                        alreadyExists = true;
                                        break;
                                    }
                                }

                                if (!alreadyExists)
                                {
                                    var newEncashment = new LeaveEncashment
                                    {
                                        Employee = emp,
                                        EmployeeName = item.employee_name?.ToString(),
                                        LeavePeriod = lPeriod,
                                        EncashmentDays = item.encashment_days != null ? Convert.ToDecimal(item.encashment_days) : (decimal?)null,
                                        Company = item.company?.ToString() ?? "AITS",
                                        LeaveType = lType,
                                        PayViaPaymentEntry = item.pay_via_payment_entry != null && Convert.ToBoolean(item.pay_via_payment_entry),
                                        EncashmentDate = item.encashment_date != null ? Convert.ToDateTime(item.encashment_date) : DateTime.Now,
                                        Status = item.status?.ToString() ?? "Draft"
                                    };
                                    service.Insert(newEncashment);
                                    count++;
                                }
                            }
                        }
                        catch (Exception innerEx)
                        {
                            System.Diagnostics.Debug.WriteLine("Encashment sync item error: " + innerEx.Message);
                        }
                    }
                }
                TempData["Success"] = $"Successfully synced {count} Leave Encashments from ERPNext!";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Sync failed: " + ExtractErpNextErrorMessage(ex.Message);
            }

            return RedirectToAction("LeaveEncashment", "HR");
        }





