        private string ExtractErpNextErrorMessage(string rawMessage)
        {
            try
            {
                var jsonStart = rawMessage.IndexOf('{');
                if (jsonStart >= 0)
                {
                    var jsonString = rawMessage.Substring(jsonStart);
                    dynamic errObj = JsonConvert.DeserializeObject(jsonString);
                    if (errObj?._server_messages != null)
                    {
                        var serverMsgs = JsonConvert.DeserializeObject<List<object>>(errObj._server_messages.ToString());
                        if (serverMsgs != null && serverMsgs.Count > 0)
                        {
                            dynamic firstMsg = JsonConvert.DeserializeObject(serverMsgs[0].ToString());
                            if (firstMsg?.message != null)
                            {
                                return firstMsg.message.ToString();
                            }
                        }
                    }
                }
            }
            catch { }
            return rawMessage;
        }

