        // Helper method to guarantee holiday list exists and contains the requested work dates
        private async Task EnsureEmployeeHolidayListAsync(string employeeCode, DateTime workFrom, DateTime workEnd)
        {
            if (string.IsNullOrWhiteSpace(employeeCode)) return;

            try
            {
                string empResp = await _erpNextService.GetAsync($"/api/resource/Employee/{Uri.EscapeDataString(employeeCode)}");
                dynamic empParsed = JsonConvert.DeserializeObject(empResp);
                string holidayList = empParsed?.data?.holiday_list?.ToString();

                if (string.IsNullOrWhiteSpace(holidayList))
                {
                    string hlResp = await _erpNextService.GetAsync("/api/resource/Holiday List?limit_page_length=1");
                    dynamic hlParsed = JsonConvert.DeserializeObject(hlResp);
                    holidayList = hlParsed?.data?[0]?.name?.ToString();

                    if (!string.IsNullOrEmpty(holidayList))
                    {
                        await _erpNextService.PutAsync($"/api/resource/Employee/{Uri.EscapeDataString(employeeCode)}", new Dictionary<string, object> { { "holiday_list", holidayList } });
                    }
                }

                if (!string.IsNullOrWhiteSpace(holidayList))
                {
                    string hlDetailsResp = await _erpNextService.GetAsync($"/api/resource/Holiday List/{Uri.EscapeDataString(holidayList)}");
                    dynamic hlDetails = JsonConvert.DeserializeObject(hlDetailsResp);

                    var existingHolidays = new List<string>();
                    if (hlDetails?.data?.holidays != null)
                    {
                        foreach (var h in hlDetails.data.holidays)
                        {
                            existingHolidays.Add(Convert.ToDateTime(h.holiday_date).ToString("yyyy-MM-dd"));
                        }
                    }

                    bool updated = false;
                    var holidayRows = hlDetails?.data?.holidays != null ? JsonConvert.DeserializeObject<List<Dictionary<string, object>>>(hlDetails.data.holidays.ToString()) : new List<Dictionary<string, object>>();

                    for (DateTime date = workFrom; date <= workEnd; date = date.AddDays(1))
                    {
                        string dateStr = date.ToString("yyyy-MM-dd");
                        if (!existingHolidays.Contains(dateStr))
                        {
                            holidayRows.Add(new Dictionary<string, object>
                    {
                        { "holiday_date", dateStr },
                        { "description", "Auto-added for Compensatory Leave" }
                    });
                            updated = true;
                        }
                    }

                    if (updated)
                    {
                        var updateHolidayListPayload = new Dictionary<string, object>
                {
                    { "holidays", holidayRows }
                };
                        await _erpNextService.PutAsync($"/api/resource/Holiday List/{Uri.EscapeDataString(holidayList)}", updateHolidayListPayload);
                    }
                }
            }
            catch { }
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateHolidayList/{id:int}")]
        public async Task<ActionResult> UpdateHolidayList(int id, HolidayList model)
        {
            try
            {
                model.Id = id;
                model.TotalHolidays = model.Holidays?.Count ?? 0;

                var holidaysPayload = new List<object>();
                if (model.Holidays != null)
                {
                    foreach (var h in model.Holidays)
                    {
                        holidaysPayload.Add(new
                        {
                            holiday_date = h.HolidayDate.ToString("yyyy-MM-dd"),
                            description = h.Description ?? ""
                        });
                    }
                }

                var payload = new
                {
                    holiday_list_name = model.HolidayListName,
                    from_date = model.FromDate.ToString("yyyy-MM-dd"),
                    to_date = model.ToDate.ToString("yyyy-MM-dd"),
                    total_holidays = model.TotalHolidays,
                    color = model.Color,
                    country = model.Country,
                    subdivision = model.Subdivision,
                    holidays = holidaysPayload
                };

                await _erpNextService.PutAsync(
                    "/api/resource/Holiday%20List/" + Uri.EscapeDataString(model.HolidayListName),
                    payload
                );

                _holidayListService.Update(model);

                TempData["Success"] = "Holiday List updated in HRMS and ERPNext.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Holiday List update failed: " + ShortErpNextError(ex.Message);
            }

            return RedirectToAction("HolidayListDetails", new { id });
        }

        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteHolidayList/{id:int}")]
        public async Task<ActionResult> DeleteHolidayList(int id)
        {
            var model = _holidayListService.GetById(id);
            if (model == null) return NotFound();

            try
            {
                await _erpNextService.DeleteAsync(
                    "/api/resource/Holiday%20List/" + Uri.EscapeDataString(model.HolidayListName)
                );
            }
            catch (Exception ex)
            {
                if (!IsErpNextMissing(ex))
                {
                    TempData["ErpNextError"] = "Holiday List delete failed: " + ShortErpNextError(ex.Message);
                    return RedirectToAction("HolidayListDetails", new { id });
                }
            }

            _holidayListService.MarkDeletedById(id);

            TempData["Success"] = "Holiday List deleted from HRMS and ERPNext.";
            return RedirectToAction("HolidayList");
        }














        // POST: HR/CreateLeaveApplication
        [HttpPost]
        [Route("HR/CreateLeaveApplication")]
        public async Task<ActionResult> CreateLeaveApplication(LeaveApplication model)
        {
            try
            {
                string targetCompany = string.IsNullOrWhiteSpace(model.Company) ? "AITS" : model.Company.Trim();
                await EnsureDocExistsAsync("Company", targetCompany);

                string leaveType = string.IsNullOrWhiteSpace(model.LeaveType) ? "Casual Leave" : model.LeaveType.Trim();
                await EnsureDocExistsAsync("Leave Type", leaveType);

                DateTime fromDate = model.FromDate ?? DateTime.Today;
                DateTime toDate = model.ToDate ?? fromDate;
                if (toDate < fromDate) toDate = fromDate;

                var payloadDictionary = new Dictionary<string, object>
        {
            { "employee", model.Employee },
            { "company", targetCompany },
            { "leave_type", leaveType },
            { "from_date", fromDate.ToString("yyyy-MM-dd") },
            { "to_date", toDate.ToString("yyyy-MM-dd") },
            { "half_day", model.HalfDay ? 1 : 0 },
            { "reason", model.Reason ?? "Leave Application" }
        };

                try
                {
                    var responseJson = await _erpNextService.PostAsync("/api/resource/Leave%20Application", payloadDictionary);
                    dynamic responseParsed = JsonConvert.DeserializeObject(responseJson);
                    string erpNextId = responseParsed?.data?.name;

                    model.LeaveApplicationCode = erpNextId;
                    model.ErpNextId = erpNextId;
                    model.FromDate = fromDate;
                    model.ToDate = toDate;

                    _leaveApplicationService.InsertLeave(model);
                    TempData["Success"] = $"Leave Application created & synced to ERPNext successfully! (Ref: {erpNextId})";
                }
                catch (Exception syncEx) when (syncEx.Message.Contains("OverlapError") || syncEx.Message.Contains("already applied"))
                {
                    // Gracefully catch duplicate/overlapping leave requests from ERPNext
                    model.LeaveApplicationCode = _leaveApplicationService.GetNextLeaveCode();
                    model.ErpNextId = null;
                    model.FromDate = fromDate;
                    model.ToDate = toDate;

                    _leaveApplicationService.InsertLeave(model);
                    TempData["ErpNextError"] = "Saved locally, but ERPNext sync skipped: This employee has already applied for leave during these dates.";
                }
                catch (Exception syncEx)
                {
                    // Catch-all for any other allocation or sync errors
                    model.LeaveApplicationCode = _leaveApplicationService.GetNextLeaveCode();
                    model.ErpNextId = null;
                    model.FromDate = fromDate;
                    model.ToDate = toDate;

                    _leaveApplicationService.InsertLeave(model);
                    TempData["ErpNextError"] = "Saved locally, but ERPNext sync failed: " + syncEx.Message;
                }
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Failed to save leave application: " + ex.Message;
            }

            return RedirectToAction("LeaveApplication");
        }
        // Helper to forcefully post and submit a wide active leave allocation without conditional checks
        private async Task ForceCreateLeaveAllocationAsync(string employee, string leaveType, string company)
        {
            if (string.IsNullOrWhiteSpace(employee)) return;

            try
            {
                // 1. Create and Submit the Leave Allocation directly with docstatus = 1
                var allocationPayload = new Dictionary<string, object>
        {
            { "docstatus", 1 }, // Submit immediately upon creation
            { "employee", employee },
            { "leave_type", leaveType },
            { "company", company },
            { "from_date", DateTime.Today.AddYears(-5).ToString("yyyy-MM-dd") },
            { "to_date", DateTime.Today.AddYears(5).ToString("yyyy-MM-dd") },
            { "new_leaves_allocated", 120 }
        };

                string createResp = await _erpNextService.PostAsync("/api/resource/Leave%20Allocation", allocationPayload);
                dynamic createdParsed = JsonConvert.DeserializeObject(createResp);
                string allocName = createdParsed?.data?.name;

                // 2. Fallback explicit submit if the API ignored docstatus = 1 on insert
                if (!string.IsNullOrEmpty(allocName))
                {
                    var submitPayload = new Dictionary<string, object>
            {
                { "cmd", "submit" },
                { "docstatus", 1 }
            };
                    try
                    {
                        await _erpNextService.PostAsync($"/api/resource/Leave%20Allocation/{Uri.EscapeDataString(allocName)}", submitPayload);
                    }
                    catch { }
                }
            }
            catch
            {
                // If an allocation already exists for this timeframe, ignore the error and let the leave application proceed
            }
        }



        private async Task EnsureMassiveLeaveAllocationExistsAsync(string employee, string leaveType, string company, DateTime fromDate, DateTime toDate)
        {
            if (string.IsNullOrWhiteSpace(employee)) return;

            try
            {
                string filters = Uri.EscapeDataString($"[[\"employee\",\"=\",\"{employee}\"],[\"leave_type\",\"=\",\"{leaveType}\"],[\"docstatus\",\"=\",1]]");
                string fields = Uri.EscapeDataString("[\"name\",\"from_date\",\"to_date\"]");
                string queryUrl = $"/api/resource/Leave%20Allocation?fields={fields}&filters={filters}&limit_page_length=1000";
                string checkResp = await _erpNextService.GetAsync(queryUrl);
                dynamic parsed = JsonConvert.DeserializeObject(checkResp);

                bool covered = false;
                if (parsed?.data != null)
                {
                    foreach (var alloc in parsed.data)
                    {
                        // Initialize variables with default values to satisfy definite assignment
                        DateTime aFrom = default;
                        DateTime aTo = default;

                        bool parsedFrom = DateTime.TryParse(alloc.from_date?.ToString(), out aFrom);
                        bool parsedTo = DateTime.TryParse(alloc.to_date?.ToString(), out aTo);

                        if (parsedFrom && parsedTo)
                        {
                            if (fromDate >= aFrom && toDate <= aTo)
                            {
                                covered = true;
                                break;
                            }
                        }
                    }
                }

                if (!covered)
                {
                    var allocationPayload = new Dictionary<string, object>
            {
                { "employee", employee },
                { "leave_type", leaveType },
                { "company", company },
                { "from_date", DateTime.Today.AddYears(-5).ToString("yyyy-MM-dd") },
                { "to_date", DateTime.Today.AddYears(5).ToString("yyyy-MM-dd") },
                { "new_leaves_allocated", 100 }
            };

                    string createResp = await _erpNextService.PostAsync("/api/resource/Leave%20Allocation", allocationPayload);
                    dynamic createdParsed = JsonConvert.DeserializeObject(createResp);
                    string allocName = createdParsed?.data?.name;

                    if (!string.IsNullOrEmpty(allocName))
                    {
                        var submitPayload = new Dictionary<string, object> { { "docstatus", 1 } };
                        try
                        {
                            await _erpNextService.PutAsync($"/api/resource/Leave%20Allocation/{Uri.EscapeDataString(allocName)}", submitPayload);
                        }
                        catch { }
                    }
                }
            }
            catch { }
        }



        // Helper method to auto-create a Leave Allocation if it doesn't exist covering the requested dates
        private async Task EnsureActiveLeaveAllocationExistsAsync(string employee, string leaveType, string company, DateTime fromDate, DateTime toDate)
        {
            if (string.IsNullOrWhiteSpace(employee)) return;

            try
            {
                // Check if an allocation already exists for this employee and leave type
                string queryUrl = $"/api/resource/Leave Allocation?filters=[[\"employee\",\"=\",\"{employee}\"],[\"leave_type\",\"=\",\"{leaveType}\"],[\"docstatus\",\"=\",1]]";
                string checkResp = await _erpNextService.GetAsync(queryUrl);
                dynamic parsed = JsonConvert.DeserializeObject(checkResp);

                bool hasValidAllocation = false;
                if (parsed?.data != null)
                {
                    foreach (var allocation in parsed.data)
                    {
                        string allocFrom = allocation.from_date;
                        string allocTo = allocation.to_date;
                        if (DateTime.TryParse(allocFrom, out DateTime aFrom) && DateTime.TryParse(allocTo, out DateTime aTo))
                        {
                            if (fromDate >= aFrom && toDate <= aTo)
                            {
                                hasValidAllocation = true;
                                break;
                            }
                        }
                    }
                }

                // If no active allocation covers these dates, create one dynamically on ERPNext!
                if (!hasValidAllocation)
                {
                    var allocationPayload = new Dictionary<string, object>
            {
                { "employee", employee },
                { "leave_type", leaveType },
                { "company", company },
                { "from_date", fromDate.AddDays(-30).ToString("yyyy-MM-dd") },
                { "to_date", toDate.AddYears(1).ToString("yyyy-MM-dd") },
                { "new_leaves_allocated", 30 }
            };

                    var createResp = await _erpNextService.PostAsync("/api/resource/Leave%20Allocation", allocationPayload);

                    // Optionally submit the allocation so it becomes active immediately
                    dynamic createdParsed = JsonConvert.DeserializeObject(createResp);
                    string allocName = createdParsed?.data?.name;
                    if (!string.IsNullOrEmpty(allocName))
                    {
                        var submitPayload = new Dictionary<string, object>
                {
                    { "docstatus", 1 }
                };
                        try
                        {
                            await _erpNextService.PutAsync($"/api/resource/Leave%20Allocation/{Uri.EscapeDataString(allocName)}", submitPayload);
                        }
                        catch { }
                    }
                }
            }
            catch { }
        }
        // POST: HR/CreateEmployeeGroup
        // POST: HR/CreateEmployeeGroup




        [HttpPost]
        [Route("HR/CreateEmployeeGroup")]
        public async Task<ActionResult>
            CreateEmployeeGroup(EmployeeGroup model)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(
                    model.GroupName))
                {
                    TempData["ErpNextError"] =
                        "Employee Group Name is required.";

                    return RedirectToAction(
                        "CreateEmployeeGroup"
                    );
                }


                // ============================================================
                // BUILD MEMBER CHILD TABLE
                // ============================================================

                var memberRows =
                    new List<object>();


                if (model.Members != null)
                {
                    foreach (var member in model.Members)
                    {
                        if (string.IsNullOrWhiteSpace(
                            member.Employee))
                        {
                            continue;
                        }


                        memberRows.Add(new
                        {
                            employee =
                                member.Employee,

                            employee_name =
                                member.EmployeeName,

                            user_id =
                                member.ERPNextUserId
                        });
                    }
                }


                // ============================================================
                // ERP PAYLOAD
                // ============================================================

                var payload = new
                {
                    employee_group_name =
                        model.GroupName,

                    employee_list =
                        memberRows
                };


                // ============================================================
                // ERP FIRST
                // ============================================================

                var response =
                    await _erpNextService.PostAsync(
                        "/api/resource/Employee%20Group",
                        payload
                    );


                dynamic parsed =
                    JsonConvert.DeserializeObject(
                        response
                    );


                string erpId =
                    parsed?.data?.name?.ToString();


                if (string.IsNullOrWhiteSpace(
                    erpId))
                {
                    throw new Exception(
                        "ERPNext did not return Employee Group ID."
                    );
                }


                // ============================================================
                // READ FULL ERP DOCUMENT BACK
                // ============================================================

                var fullResponse =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Group/" +
                        Uri.EscapeDataString(erpId)
                    );


                dynamic fullParsed =
                    JsonConvert.DeserializeObject(
                        fullResponse
                    );


                var doc =
                    fullParsed?.data;


                if (doc == null)
                {
                    throw new Exception(
                        "Unable to reload Employee Group from ERPNext."
                    );
                }


                // ============================================================
                // MAP ERP DOCUMENT
                // ============================================================

                var localGroup =
                    MapErpEmployeeGroup(doc);


                int localId =
                    _employeeGroupService
                        .InsertOrUpdate(localGroup);


                TempData["Success"] =
                    "Employee Group created successfully.";


                return RedirectToAction(
                    "EmployeeGroupDetails",
                    new
                    {
                        id = localId
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    CleanErpNextError(ex.Message);

                return RedirectToAction(
                    "CreateEmployeeGroup"
                );
            }
        }

        private EmployeeGroup MapErpEmployeeGroup(
    dynamic doc)
        {
            var group =
                new EmployeeGroup
                {
                    ErpNextId =
                        doc?.name?.ToString()
                        ?? "",

                    GroupCode =
                        doc?.name?.ToString()
                        ?? "",

                    GroupName =
                        doc?.employee_group_name?.ToString()
                        ?? doc?.name?.ToString()
                        ?? "",

                    Members =
                        new List<EmployeeGroupMember>()
                };


            if (doc?.employee_list != null)
            {
                foreach (var row in doc.employee_list)
                {
                    group.Members.Add(
                        new EmployeeGroupMember
                        {
                            Employee =
                                row.employee?.ToString()
                                ?? "",

                            EmployeeName =
                                row.employee_name?.ToString()
                                ?? "",

                            ERPNextUserId =
                                row.user_id?.ToString()
                                ?? ""
                        }
                    );
                }
            }


            return group;
        }


        private string CleanErpNextError(string rawError)
        {
            if (string.IsNullOrWhiteSpace(rawError))
                return "ERPNext operation failed.";

            try
            {
                int jsonStart =
                    rawError.IndexOf('{');

                if (jsonStart >= 0)
                {
                    string jsonPart =
                        rawError.Substring(jsonStart);

                    var errorJson =
                        JObject.Parse(jsonPart);

                    var serverMessages =
                        errorJson["_server_messages"];

                    if (serverMessages != null)
                    {
                        var array =
                            JArray.Parse(
                                serverMessages.ToString()
                            );

                        if (array.Count > 0)
                        {
                            var msgObj =
                                JObject.Parse(
                                    array[0].ToString()
                                );

                            string message =
                                msgObj["message"]
                                    ?.ToString();

                            if (!string.IsNullOrWhiteSpace(
                                message))
                            {
                                message =
                                    System.Text.RegularExpressions.Regex.Replace(
                                        message,
                                        "<.*?>",
                                        ""
                                    );

                                return
                                    System.Net.WebUtility
                                        .HtmlDecode(message);
                            }
                        }
                    }
                }
            }
            catch
            {
            }

            return rawError;
        }











