        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> CreateBranch(
    string BranchName)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(BranchName))
                    throw new Exception(
                        "Branch Name is required."
                    );

                string branchName =
                    BranchName.Trim();

                var payload =
                    new Dictionary<string, object>
                    {
                { "branch", branchName },
                { "branch_name", branchName }
                    };

                // ERP FIRST
                string response =
                    await _erpNextService.PostAsync(
                        "/api/resource/Branch",
                        payload
                    );

                JObject json =
                    JObject.Parse(response);

                string erpName =
                    json["data"]?["name"]
                        ?.ToString();

                if (string.IsNullOrWhiteSpace(erpName))
                    throw new Exception(
                        "ERPNext did not return Branch document name."
                    );

                int localId =
                    _branchService
                        .InsertOrUpdateFromErpNext(
                            erpName,
                            branchName
                        );

                TempData["Success"] =
                    "Branch created in ERPNext and HRMS.";

                return RedirectToAction(
                    "BranchDetails",
                    new { id = localId }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Branch create failed: " +
                    ex.Message;

                return RedirectToAction("Branches");
            }
        }







