        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateBranch/{id:int}")]
        public async Task<ActionResult> UpdateBranch(
            int id,
            Branch model)
        {
            try
            {
                Branch existing =
                    _branchService.GetById(id);

                if (existing == null)
                    return NotFound();

                if (model == null ||
                    string.IsNullOrWhiteSpace(model.BranchName))
                {
                    throw new Exception(
                        "Branch Name is required."
                    );
                }

                if (string.IsNullOrWhiteSpace(existing.ErpName))
                {
                    throw new Exception(
                        "Branch is not linked with ERPNext."
                    );
                }

                string oldErpName =
                    existing.ErpName.Trim();

                string newBranchName =
                    model.BranchName.Trim();

                string finalErpName =
                    oldErpName;


                // =====================================================
                // RENAME SAME ERPNext BRANCH
                // DO NOT CREATE NEW BRANCH
                // DO NOT DELETE OLD BRANCH
                // =====================================================

                if (!string.Equals(
                    oldErpName,
                    newBranchName,
                    StringComparison.Ordinal))
                {
                    var renamePayload = new
                    {
                        doctype = "Branch",
                        old_name = oldErpName,
                        new_name = newBranchName,
                        merge = false
                    };

                    string renameResponse =
                        await _erpNextService.PostMethodAsync(
                            "/api/method/frappe.client.rename_doc",
                            renamePayload
                        );

                    JObject renameJson =
                        JObject.Parse(renameResponse);

                    string renamedName =
                        renameJson["message"]?.ToString();

                    finalErpName =
                        string.IsNullOrWhiteSpace(renamedName)
                            ? newBranchName
                            : renamedName.Trim();
                }


                // =====================================================
                // RELOAD RENAMED ERP DOCUMENT
                // =====================================================

                string response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Branch/" +
                        Uri.EscapeDataString(finalErpName)
                    );

                JObject json =
                    JObject.Parse(response);

                JToken doc =
                    json["data"];

                if (doc == null)
                {
                    throw new Exception(
                        "Updated Branch could not be reloaded from ERPNext."
                    );
                }

                string savedErpName =
                    doc["name"]?.ToString()
                    ?? finalErpName;

                // Branch document name itself is our local BranchName.
                string savedBranchName =
                    savedErpName;


                // =====================================================
                // UPDATE SAME HRMS ROW ONLY AFTER ERP SUCCESS
                // =====================================================

                _branchService.UpdateLocal(
                    id,
                    savedBranchName,
                    savedErpName
                );

                TempData["Success"] =
                    "Branch updated successfully in ERPNext and HRMS.";

                return RedirectToAction(
                    "BranchDetails",
                    new { id }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Branch update failed: " +
                    ex.Message;

                return RedirectToAction(
                    "BranchDetails",
                    new { id }
                );
            }
        }


        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteBranch/{id:int}")]
        public async Task<ActionResult> DeleteBranch(int id)
        {
            try
            {
                Branch existing =
                    _branchService.GetById(id);

                if (existing == null)
                    return NotFound();

                if (!string.IsNullOrWhiteSpace(
                    existing.ErpName))
                {
                    // ERP FIRST
                    await _erpNextService.DeleteAsync(
                        "/api/resource/Branch/" +
                        Uri.EscapeDataString(
                            existing.ErpName
                        )
                    );
                }

                // HRMS after ERP success
                _branchService.MarkDeletedById(id);

                TempData["Success"] =
                    "Branch deleted from ERPNext and HRMS.";

                return RedirectToAction("Branches");
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Branch deletion failed: " +
                    ex.Message;

                return RedirectToAction(
                    "BranchDetails",
                    new { id }
                );
            }
        }







