        // POST: HR/CreateExpenseClaim
        // POST: HR/CreateExpenseClaim
        // POST: HR/CreateExpenseClaim
        // POST: HR/CreateExpenseClaim
        // POST: HR/CreateExpenseClaim
        [HttpPost]
        [Route("HR/CreateExpenseClaim")]
        public async Task<ActionResult> CreateExpenseClaim(ExpenseClaim model)
        {
            try
            {
                string targetCompany = string.IsNullOrWhiteSpace(model.Company) ? "Vinod Cookware India Private Limited" : model.Company.Trim();

                // 1. Auto-create Employee in ERPNext if missing
                if (!string.IsNullOrWhiteSpace(model.Employee))
                {
                    await EnsureDocExistsAsync("Employee", model.Employee);
                }

                // 2. Auto-create Approver (User) in ERPNext if missing
                if (!string.IsNullOrWhiteSpace(model.ExpenseApprover))
                {
                    await EnsureDocExistsAsync("User", model.ExpenseApprover);
                }

                // 3. Ensure Company exists in ERPNext
                await EnsureDocExistsAsync("Company", targetCompany);

                // 4. Resolve a Default Expense Account for the Company
                string defaultExpenseAccount = null;
                try
                {
                    // Find an active Expense account for this company
                    var accJson = await _erpNextService.GetAsync($"/api/resource/Account?filters=[[\"company\",\"=\",\"{targetCompany}\"],[\"root_type\",\"=\",\"Expense\"],[\"is_group\",\"=\",0]]&fields=[\"name\"]&limit_page_length=1");
                    dynamic accParsed = JsonConvert.DeserializeObject(accJson);
                    if (accParsed?.data != null && accParsed.data.Count > 0)
                    {
                        defaultExpenseAccount = accParsed.data[0].name;
                    }
                    else
                    {
                        // Fallback to company default expense account
                        var compJson = await _erpNextService.GetAsync($"/api/resource/Company/{Uri.EscapeDataString(targetCompany)}");
                        dynamic compParsed = JsonConvert.DeserializeObject(compJson);
                        defaultExpenseAccount = compParsed?.data?.default_expense_account;
                    }
                }
                catch { }

                // 5. Auto-Fix / Auto-Create Department for Target Company
                string targetDepartment = null;
                if (!string.IsNullOrWhiteSpace(model.Department))
                {
                    try
                    {
                        var deptCheck = await _erpNextService.GetAsync($"/api/resource/Department/{Uri.EscapeDataString(model.Department)}");
                        dynamic checkParsed = JsonConvert.DeserializeObject(deptCheck);
                        string deptCompany = checkParsed?.data?.company;

                        if (string.Equals(deptCompany, targetCompany, StringComparison.OrdinalIgnoreCase) || string.IsNullOrEmpty(deptCompany))
                        {
                            targetDepartment = checkParsed?.data?.name ?? model.Department;
                        }
                        else
                        {
                            string baseDeptName = model.Department.Contains("-") ? model.Department.Split('-')[0].Trim() : model.Department.Trim();
                            try
                            {
                                var createDeptPayload = new { department_name = baseDeptName, company = targetCompany };
                                var createDeptResp = await _erpNextService.PostAsync("/api/resource/Department", createDeptPayload);
                                dynamic createDeptParsed = JsonConvert.DeserializeObject(createDeptResp);
                                targetDepartment = createDeptParsed?.data?.name;
                            }
                            catch
                            {
                                var searchDept = await _erpNextService.GetAsync($"/api/resource/Department?filters=[[\"company\",\"=\",\"{targetCompany}\"],[\"department_name\",\"=\",\"{baseDeptName}\"]]&limit_page_length=1");
                                dynamic searchParsed = JsonConvert.DeserializeObject(searchDept);
                                targetDepartment = (searchParsed?.data != null && searchParsed.data.Count > 0) ? searchParsed.data[0].name : null;
                            }
                        }
                    }
                    catch
                    {
                        try
                        {
                            var createDeptPayload = new { department_name = model.Department, company = targetCompany };
                            var createDeptResp = await _erpNextService.PostAsync("/api/resource/Department", createDeptPayload);
                            dynamic createDeptParsed = JsonConvert.DeserializeObject(createDeptResp);
                            targetDepartment = createDeptParsed?.data?.name;
                        }
                        catch { targetDepartment = null; }
                    }
                }

                // 6. Auto-create / Validate Cost Center in ERPNext
                string targetCostCenter = null;
                if (!string.IsNullOrWhiteSpace(model.CostCenter))
                {
                    try
                    {
                        var ccCheck = await _erpNextService.GetAsync($"/api/resource/Cost%20Center/{Uri.EscapeDataString(model.CostCenter)}");
                        dynamic checkParsed = JsonConvert.DeserializeObject(ccCheck);
                        if (checkParsed?.data != null) targetCostCenter = checkParsed.data.name;
                    }
                    catch
                    {
                        try
                        {
                            var createCostCenterPayload = new { cost_center_name = model.CostCenter, company = targetCompany, is_group = 0 };
                            var ccResp = await _erpNextService.PostAsync("/api/resource/Cost%20Center", createCostCenterPayload);
                            dynamic ccParsed = JsonConvert.DeserializeObject(ccResp);
                            targetCostCenter = ccParsed?.data?.name ?? model.CostCenter;
                        }
                        catch
                        {
                            try
                            {
                                var compJson = await _erpNextService.GetAsync($"/api/resource/Company/{Uri.EscapeDataString(targetCompany)}");
                                dynamic compParsed = JsonConvert.DeserializeObject(compJson);
                                targetCostCenter = compParsed?.data?.cost_center;
                            }
                            catch { targetCostCenter = null; }
                        }
                    }
                }

                // 7. Auto-create Project in ERPNext if missing
                string targetProject = null;
                if (!string.IsNullOrWhiteSpace(model.Project))
                {
                    try
                    {
                        var projCheck = await _erpNextService.GetAsync($"/api/resource/Project/{Uri.EscapeDataString(model.Project)}");
                        dynamic checkParsed = JsonConvert.DeserializeObject(projCheck);
                        targetProject = checkParsed?.data?.name;
                    }
                    catch
                    {
                        try
                        {
                            var projPayload = new { project_name = model.Project, company = targetCompany };
                            var projResp = await _erpNextService.PostAsync("/api/resource/Project", projPayload);
                            dynamic projParsed = JsonConvert.DeserializeObject(projResp);
                            targetProject = projParsed?.data?.name ?? model.Project;
                        }
                        catch { targetProject = null; }
                    }
                }

                // 8. Auto-create and Link Default Account to Expense Claim Types (Fixes: "Set the default account for Expense Claim Type")
                var expensesList = new List<object>();
                if (model.Expenses != null)
                {
                    foreach (var e in model.Expenses)
                    {
                        if (string.IsNullOrWhiteSpace(e.ExpenseClaimType)) continue;

                        string typeName = e.ExpenseClaimType.Trim();

                        // Ensure Expense Claim Type has account set for targetCompany
                        try
                        {
                            var typeJson = await _erpNextService.GetAsync($"/api/resource/Expense%20Claim%20Type/{Uri.EscapeDataString(typeName)}");
                            dynamic typeParsed = JsonConvert.DeserializeObject(typeJson);
                            var accounts = typeParsed?.data?.accounts;
                            bool hasCompanyAccount = false;

                            if (accounts != null)
                            {
                                foreach (var acc in accounts)
                                {
                                    if (string.Equals(acc.company?.ToString(), targetCompany, StringComparison.OrdinalIgnoreCase))
                                    {
                                        hasCompanyAccount = true;
                                        break;
                                    }
                                }
                            }

                            if (!hasCompanyAccount && !string.IsNullOrEmpty(defaultExpenseAccount))
                            {
                                // Add account mapping to existing Expense Claim Type
                                var updatePayload = new
                                {
                                    accounts = new List<object>
                            {
                                new { company = targetCompany, default_account = defaultExpenseAccount }
                            }
                                };
                                await _erpNextService.PutAsync($"/api/resource/Expense%20Claim%20Type/{Uri.EscapeDataString(typeName)}", updatePayload);
                            }
                        }
                        catch
                        {
                            // Expense Claim Type does not exist; create it with default account
                            try
                            {
                                var createTypePayload = new
                                {
                                    expense_type = typeName,
                                    accounts = string.IsNullOrEmpty(defaultExpenseAccount) ? new List<object>() : new List<object>
                            {
                                new { company = targetCompany, default_account = defaultExpenseAccount }
                            }
                                };
                                await _erpNextService.PostAsync("/api/resource/Expense%20Claim%20Type", createTypePayload);
                            }
                            catch { }
                        }

                        expensesList.Add(new
                        {
                            expense_date = e.ExpenseDate?.ToString("yyyy-MM-dd") ?? DateTime.Now.ToString("yyyy-MM-dd"),
                            expense_type = typeName,
                            default_account = defaultExpenseAccount, // Explicitly pass resolved account
                            description = string.IsNullOrWhiteSpace(e.Description) ? typeName : e.Description,
                            amount = e.Amount,
                            sanctioned_amount = e.SanctionedAmount > 0 ? e.SanctionedAmount : e.Amount
                        });
                    }
                }

                // 9. Auto-create Child Taxes
                var taxesList = new List<object>();
                if (model.Taxes != null)
                {
                    foreach (var t in model.Taxes)
                    {
                        if (string.IsNullOrWhiteSpace(t.AccountHead)) continue;

                        taxesList.Add(new
                        {
                            account_head = t.AccountHead,
                            description = t.AccountHead,
                            rate = t.Rate,
                            tax_amount = t.Amount,
                            total = t.Total
                        });
                    }
                }

                // 10. Auto-create / Validate Child Advances
                var advancesList = new List<object>();
                if (model.Advances != null)
                {
                    foreach (var a in model.Advances)
                    {
                        if (string.IsNullOrWhiteSpace(a.EmployeeAdvance)) continue;

                        string validAdvanceId = a.EmployeeAdvance;
                        bool advanceMatchesEmployee = false;

                        try
                        {
                            var advCheck = await _erpNextService.GetAsync($"/api/resource/Employee%20Advance/{Uri.EscapeDataString(validAdvanceId)}");
                            dynamic advParsed = JsonConvert.DeserializeObject(advCheck);
                            string advEmp = advParsed?.data?.employee;

                            if (string.Equals(advEmp, model.Employee, StringComparison.OrdinalIgnoreCase))
                            {
                                advanceMatchesEmployee = true;
                            }
                        }
                        catch { advanceMatchesEmployee = false; }

                        if (!advanceMatchesEmployee)
                        {
                            try
                            {
                                var createAdvPayload = new
                                {
                                    employee = model.Employee,
                                    company = targetCompany,
                                    posting_date = a.PostingDate?.ToString("yyyy-MM-dd") ?? DateTime.Now.ToString("yyyy-MM-dd"),
                                    advance_amount = a.AdvancePaid > 0 ? a.AdvancePaid : (a.AllocatedAmount > 0 ? a.AllocatedAmount : 100)
                                };
                                var createAdvResp = await _erpNextService.PostAsync("/api/resource/Employee%20Advance", createAdvPayload);
                                dynamic createAdvParsed = JsonConvert.DeserializeObject(createAdvResp);
                                validAdvanceId = createAdvParsed?.data?.name;
                            }
                            catch
                            {
                                validAdvanceId = null;
                            }
                        }

                        if (!string.IsNullOrEmpty(validAdvanceId))
                        {
                            advancesList.Add(new
                            {
                                employee_advance = validAdvanceId,
                                posting_date = a.PostingDate?.ToString("yyyy-MM-dd") ?? DateTime.Now.ToString("yyyy-MM-dd"),
                                advance_paid = a.AdvancePaid,
                                unclaimed_amount = a.UnclaimedAmount,
                                allocated_amount = a.AllocatedAmount
                            });
                        }
                    }
                }

                // 11. Construct ERPNext Payload
                var payload = new
                {
                    employee = model.Employee,
                    employee_name = model.EmployeeName,
                    expense_approver = model.ExpenseApprover,
                    approval_status = string.IsNullOrWhiteSpace(model.ApprovalStatus) ? "Draft" : model.ApprovalStatus,
                    department = targetDepartment,
                    company = targetCompany,
                    posting_date = model.PostingDate?.ToString("yyyy-MM-dd") ?? DateTime.Now.ToString("yyyy-MM-dd"),
                    clearance_date = model.ClearanceDate?.ToString("yyyy-MM-dd"),
                    is_paid = model.IsPaid ? 1 : 0,
                    remark = model.Remark,
                    payable_account = string.IsNullOrWhiteSpace(model.PayableAccount) ? null : model.PayableAccount,
                    project = targetProject,
                    cost_center = targetCostCenter,
                    status = string.IsNullOrWhiteSpace(model.Status) ? "Draft" : model.Status,
                    task = string.IsNullOrWhiteSpace(model.Task) ? null : model.Task,
                    expenses = expensesList,
                    taxes = taxesList,
                    advances = advancesList
                };

                // 12. Post to ERPNext
                var responseJson = await _erpNextService.PostAsync("/api/resource/Expense%20Claim", payload);
                dynamic responseParsed = JsonConvert.DeserializeObject(responseJson);
                string erpNextId = responseParsed?.data?.name;

                // 13. Save locally
                model.ErpNextId = erpNextId;
                model.ExpenseClaimCode = erpNextId;
                model.Department = targetDepartment;
                model.CostCenter = targetCostCenter;
                model.Project = targetProject;
                model.Company = targetCompany;
                int localId;

                if (!string.IsNullOrWhiteSpace(erpNextId))
                {
                    ExpenseClaim refreshed =
                        await RefreshExpenseClaimFromErpNextAsync(erpNextId);
                    localId =
                        _expenseClaimService.InsertOrUpdateExpenseClaim(refreshed);
                }
                else
                {
                    localId =
                        _expenseClaimService.InsertOrUpdateExpenseClaim(model);
                }

                TempData["Success"] = $"Expense Claim created locally & synced to ERPNext (Ref: {erpNextId})!";
                return RedirectToAction("ExpenseClaimDetails", new { id = localId });
            }
            catch (Exception ex)
            {
                try
                {
                    int localId = _expenseClaimService.InsertOrUpdateExpenseClaim(model);
                    TempData["ErpNextError"] = "Saved locally, but ERPNext sync failed: " + ex.Message;
                    return RedirectToAction("ExpenseClaimDetails", new { id = localId });
                }
                catch (Exception dbEx)
                {
                    TempData["ErpNextError"] = "Failed to save locally and ERPNext sync failed: " + dbEx.Message;
                }
            }

            return RedirectToAction("ExpenseClaimList");
        }











