        private async Task PopulateAllocationDropdownsAsync()
        {
            try
            {
                // Fetch Leave Types from ERPNext
                var leaveTypeResponse = await _erpNextService.GetAsync("/api/resource/Leave Type?fields=[\"name\"]&limit_page_length=100");
                dynamic ltParsed = JsonConvert.DeserializeObject(leaveTypeResponse);
                var leaveTypes = new List<string>();
                if (ltParsed?.data != null)
                {
                    foreach (var lt in ltParsed.data) leaveTypes.Add(lt.name.ToString());
                }
                ViewBag.LeaveTypes = leaveTypes;

                // Fetch Employees for the employee dropdown from ERPNext Employee resource
                var empResponse = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=100");
                dynamic empParsed = JsonConvert.DeserializeObject(empResponse);
                var employeesList = new List<object>();
                if (empParsed?.data != null)
                {
                    foreach (var e in empParsed.data)
                    {
                        employeesList.Add(new
                        {
                            EmployeeId = e.name?.ToString(),
                            EmployeeName = e.employee_name?.ToString() ?? e.name?.ToString()
                        });
                    }
                }
                ViewBag.EmployeesList = employeesList;

                var periodResponse = await _erpNextService.GetAsync("/api/resource/Leave Period?fields=[\"name\"]&limit_page_length=100");
                dynamic periodParsed = JsonConvert.DeserializeObject(periodResponse);
                var leavePeriods = new List<string>();
                if (periodParsed?.data != null)
                {
                    foreach (var p in periodParsed.data) leavePeriods.Add(p.name.ToString());
                }
                ViewBag.LeavePeriods = leavePeriods;

                var policyResponse = await _erpNextService.GetAsync("/api/resource/Leave Policy?fields=[\"name\"]&limit_page_length=100");
                dynamic policyParsed = JsonConvert.DeserializeObject(policyResponse);
                var leavePolicies = new List<string>();
                if (policyParsed?.data != null)
                {
                    foreach (var p in policyParsed.data) leavePolicies.Add(p.name.ToString());
                }
                ViewBag.LeavePolicies = leavePolicies;
            }
            catch
            {
                ViewBag.LeaveTypes = new List<string> { "Casual Leave", "Sick Leave", "Earned Leave" };
                ViewBag.EmployeesList = new List<object> {
                    new { EmployeeId = "EMP-00001", EmployeeName = "Test Employee" }
                };
                ViewBag.LeavePeriods = new List<string>();
                ViewBag.LeavePolicies = new List<string>();
            }
        }


        [HttpPost]
        [Route("HR/CreateShiftRequest")]
        public async Task<ActionResult> CreateShiftRequest(ShiftRequest model)
        {
            try
            {
                var service = new ShiftRequestService(_connectionString);

                if (string.IsNullOrEmpty(model.ShiftRequestCode))
                {
                    model.ShiftRequestCode = service.GetNextCode();
                }

                int newId = service.Insert(model);

                try
                {
                    // Exact field names mapping to ERPNext Shift Request DocType
                    var erpPayload = new
                    {
                        doctype = "Shift Request",
                        employee = model.Employee,
                        company = model.Company,
                        shift_type = model.ShiftType,
                        from_date = model.FromDate?.ToString("yyyy-MM-dd"),
                        to_date = model.ToDate?.ToString("yyyy-MM-dd"),
                        docstatus = 0
                    };

                    await _erpNextService.PostAsync("/api/resource/Shift%20Request", erpPayload);
                    TempData["Success"] = "Shift Request saved locally and pushed to ERPNext successfully!";
                }
                catch (Exception syncEx)
                {
                    string friendlyMessage = ExtractErpNextErrorMessage(syncEx.Message);
                    TempData["ErpNextError"] = "Saved locally, but ERPNext push failed: " + friendlyMessage;
                    return RedirectToAction("ShiftRequestList", "HR");
                }

                return RedirectToAction("ShiftRequestList", "HR");
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Failed to save locally: " + ex.Message;
                return RedirectToAction("ShiftRequestList", "HR");
            }
        }




















