        [HttpGet]
        [Route("HR/CreateLeave")]
        public async Task<ActionResult> CreateLeave()
        {
            var service = new LeaveApplicationService(_connectionString);
            var model = new LeaveApplication
            {
                LeaveApplicationCode = service.GetNextLeaveCode(),
                PostingDate = DateTime.Now,
                Status = "Open"
            };

            try
            {
                // Fetch Employees from ERPNext
                var empResponse = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=500");
                dynamic empParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(empResponse);
                ViewBag.Employees = empParsed?.data;

                // Fetch Leave Types from ERPNext
                //var ltResponse = await _erpNextService.GetAsync("/api/resource/Leave%20Type?fields=[\"name\"]&limit_page_length=500");
                // Fetch Leave Types from ERPNext
                // Fetch Leave Types from ERPNext
                var leaveTypeFields = Uri.EscapeDataString("[\"name\"]");
                var ltResponse = await _erpNextService.GetAsync($"/api/resource/{Uri.EscapeDataString("Leave Type")}?fields={leaveTypeFields}&limit_page_length=0");

                var ltJson = Newtonsoft.Json.Linq.JObject.Parse(ltResponse);
                ViewBag.LeaveTypes = ltJson["data"]?
                    .Select(x => x["name"]?.ToString())
                    .Where(x => !string.IsNullOrWhiteSpace(x))
                    .Distinct()
                    .OrderBy(x => x)
                    .ToList() ?? new List<string>();
                // Fetch Leave Approvers / Users from ERPNext
                var userResponse = await _erpNextService.GetAsync("/api/resource/User?fields=[\"name\",\"email\"]&limit_page_length=500");
                dynamic userParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(userResponse);
                ViewBag.LeaveApprovers = userParsed?.data;

                // Fetch Companies from ERPNext
                var compResponse = await _erpNextService.GetAsync("/api/resource/Company?fields=[\"name\"]&limit_page_length=500");
                dynamic compParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(compResponse);

                ViewBag.Companies = compParsed?.data;
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext fetch failed: " + ex.Message;

                ViewBag.Employees = new List<object>();
                ViewBag.LeaveTypes = new List<object>();
                ViewBag.LeaveApprovers = new List<object>();
                ViewBag.Companies = new List<object>();
            }

            return View("CreateLeave", model);
        }


        [HttpGet]
        [Route("HR/GetAllowedLeaveTypes")]
        public async Task<JsonResult> GetAllowedLeaveTypes(string employee, DateTime? date)
        {
            var leaveTypes = new List<string>();

            try
            {
                if (string.IsNullOrWhiteSpace(employee))
                    return Json(leaveTypes);

                var useDate = (date ?? DateTime.Today).ToString("yyyy-MM-dd");

                var url = "/api/method/hrms.hr.doctype.leave_application.leave_application.get_leave_details"
                    + $"?employee={Uri.EscapeDataString(employee)}&date={Uri.EscapeDataString(useDate)}";

                var response = await _erpNextService.GetAsync(url);
                var parsed = Newtonsoft.Json.Linq.JObject.Parse(response);

                var allocation = parsed["message"]?["leave_allocation"] as Newtonsoft.Json.Linq.JObject;
                if (allocation != null)
                {
                    foreach (var item in allocation.Properties())
                        leaveTypes.Add(item.Name);
                }

                var lwps = parsed["message"]?["lwps"] as Newtonsoft.Json.Linq.JArray;
                if (lwps != null)
                {
                    foreach (var item in lwps)
                        leaveTypes.Add(item.ToString());
                }
            }
            catch { }

            return Json(leaveTypes.Distinct().ToList());
        }

