        // 2. POST Action: Receives form submission when you click Save
        [HttpPost]
        [Route("HR/CreateLeave")]
        public async Task<ActionResult> CreateLeave(LeaveApplication model)
        {
            try
            {
                var service = new LeaveApplicationService(_connectionString);

                if (model.FromDate.HasValue && model.ToDate.HasValue)
                {
                    await EnsureActiveLeaveAllocationExistsAsync(
                        model.Employee,
                        model.LeaveType,
                        model.Company,
                        model.FromDate.Value.Date,
                        model.ToDate.Value.Date);
                }

                var payload = new
                {
                    employee = model.Employee,
                    employee_name = model.EmployeeName,
                    leave_type = model.LeaveType,
                    company = model.Company,
                    from_date = model.FromDate?.ToString("yyyy-MM-dd"),
                    to_date = model.ToDate?.ToString("yyyy-MM-dd"),
                    half_day = model.HalfDay ? 1 : 0,
                    description = model.Reason,
                    leave_approver = model.LeaveApprover,
                    posting_date = model.PostingDate?.ToString("yyyy-MM-dd"),
                    status = model.Status ?? "Open"
                };

                var response = await _erpNextService.PostAsync("/api/resource/Leave%20Application", payload);
                dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);
                string remoteId = parsed?.data?.name?.ToString();

                //model.ErpNextId = remoteId;
                //model.LeaveApplicationCode = remoteId ?? service.GetNextLeaveCode();

                //service.InsertLeave(model);
                model.ErpNextId = remoteId;
                model.LeaveApplicationCode = remoteId ?? model.LeaveApplicationCode ?? service.GetNextLeaveCode();

                int localId;
                if (!string.IsNullOrWhiteSpace(remoteId) && service.ExistsByErpNextId(remoteId))
                {
                    service.UpdateByErpNextId(model);
                    localId = service.GetByErpNextId(remoteId)?.Id ?? service.InsertLeave(model);
                }
                else
                {
                    localId = service.InsertLeave(model);
                }
                service.SoftDeleteDuplicateSamePeriod(localId, model);
                TempData["Success"] = "Leave Application created successfully!";
                return RedirectToAction("LeaveApplicationDetails", "HR", new { id = localId });
            }
            //catch (Exception ex)
            //{
            //    // Extract clean 1-line error message from ERPNext response
            //    string errorMessage = ex.Message;
            //    if (errorMessage.Contains("ValidationError:"))
            //    {
            //        var parts = errorMessage.Split(new[] { "ValidationError:" }, StringSplitOptions.None);
            //        if (parts.Length > 1)
            //        {
            //            errorMessage = parts[1].Split('\\')[0].Trim().Replace("\"", "");
            //        }
            //    }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = CleanErpNextError(ex);
                return RedirectToAction("LeaveApplications", "HR");
            }

            // Show error on the Leave Applications list page


        }



        private static string CleanErpNextError(Exception ex)
        {
            var message = ex.Message ?? "ERPNext validation failed.";

            try
            {
                int jsonStart = message.IndexOf('{');
                if (jsonStart >= 0)
                {
                    var json = Newtonsoft.Json.Linq.JObject.Parse(message.Substring(jsonStart));

                    var serverMessagesText = json["_server_messages"]?.ToString();
                    if (!string.IsNullOrWhiteSpace(serverMessagesText))
                    {
                        var serverMessages = Newtonsoft.Json.Linq.JArray.Parse(serverMessagesText);
                        var first = serverMessages.FirstOrDefault()?.ToString();

                        if (!string.IsNullOrWhiteSpace(first))
                        {
                            var firstJson = Newtonsoft.Json.Linq.JObject.Parse(first);
                            message = firstJson["message"]?.ToString() ?? message;
                        }
                    }
                    else
                    {
                        message = json["exception"]?.ToString() ?? message;
                    }
                }
            }
            catch { }

            message = System.Text.RegularExpressions.Regex.Replace(message, "<.*?>", "");
            message = System.Net.WebUtility.HtmlDecode(message);

            if (message.Contains(":"))
                message = message.Substring(message.LastIndexOf(":") + 1).Trim();

            return message;
        }



        [HttpGet]
        [Route("HR/LeaveApplicationDetails/{id}")]
        public async Task<ActionResult> LeaveApplicationDetails(int id, bool edit = false)
        {
            var service = new LeaveApplicationService(_connectionString);
            var leave = service.GetAllLeaves().FirstOrDefault(l => l.Id == id);
            if (leave == null) return NotFound();

            bool isSubmitted = string.Equals(leave.Status, "Submitted", StringComparison.OrdinalIgnoreCase);
            bool isCancelled = string.Equals(leave.Status, "Cancelled", StringComparison.OrdinalIgnoreCase);
            if (edit && (isSubmitted || isCancelled))
            {
                TempData["ErpNextError"] = isSubmitted
                    ? "You can't edit submitted document."
                    : "Cancelled Leave Application cannot be edited.";
                edit = false;
            }

            try
            {
                // Fetch Employees
                var empResponse = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=500");
                ViewBag.Employees = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(empResponse)?.data;

                // Fetch Leave Types
                var ltResponse = await _erpNextService.GetAsync("/api/resource/Leave%20Type?fields=[\"name\"]&limit_page_length=500");
                ViewBag.LeaveTypes = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(ltResponse)?.data;

                // Fetch Users / Approvers
                var userResponse = await _erpNextService.GetAsync("/api/resource/User?fields=[\"name\",\"email\"]&limit_page_length=500");
                ViewBag.LeaveApprovers = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(userResponse)?.data;
            }
            catch
            {
                ViewBag.Employees = new List<object>();
                ViewBag.LeaveTypes = new List<object>();
                ViewBag.LeaveApprovers = new List<object>();
            }

            ViewBag.IsEdit = edit;
            return View("LeaveApplicationDetails", leave);
        }









        [HttpPost]
        [Route("HR/UpdateLeaveApplication/{id}")]
        public async Task<ActionResult> UpdateLeaveApplication(int id, LeaveApplication model, string actionCommand)
        {
            var service = new LeaveApplicationService(_connectionString);
            var existing = service.GetAllLeaves().FirstOrDefault(l => l.Id == id);

            if (existing == null) return NotFound();

            model.Id = id;
            model.LeaveApplicationCode = existing.LeaveApplicationCode;
            model.ErpNextId = !string.IsNullOrEmpty(existing.ErpNextId) ? existing.ErpNextId : existing.LeaveApplicationCode;
            actionCommand = string.IsNullOrWhiteSpace(actionCommand) ? "Save" : actionCommand;

            // Helper to keep dropdown lists populated if validation fails
            async Task ReloadDropdownsAsync()
            {
                try
                {
                    var empRes = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=500");
                    ViewBag.Employees = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(empRes)?.data;

                    var ltRes = await _erpNextService.GetAsync("/api/resource/Leave%20Type?fields=[\"name\"]&limit_page_length=500");
                    ViewBag.LeaveTypes = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(ltRes)?.data;

                    var userRes = await _erpNextService.GetAsync("/api/resource/User?fields=[\"name\",\"email\"]&limit_page_length=500");
                    ViewBag.LeaveApprovers = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(userRes)?.data;
                }
                catch
                {
                    ViewBag.Employees = new List<object>();
                    ViewBag.LeaveTypes = new List<object>();
                    ViewBag.LeaveApprovers = new List<object>();
                }
            }

            try
            {
                string encodedErpId = Uri.EscapeDataString(model.ErpNextId);

                if (string.Equals(actionCommand, "Cancel", StringComparison.OrdinalIgnoreCase))
                {
                    if (!string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase))
                    {
                        TempData["ErpNextError"] = "Only submitted Leave Application can be cancelled.";
                        return RedirectToAction("LeaveApplicationDetails", new { id });
                    }

                    await CancelSubmittedAttendanceForLeaveAsync(existing);

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                    {
                        doctype = "Leave Application",
                        name = model.ErpNextId
                    });

                    existing.Status = "Cancelled";
                    service.UpdateFromErpNext(existing);
                    await PullAttendanceFromErpNext();
                    TempData["Success"] = "Leave Application cancelled in ERPNext and HRMS.";
                    return RedirectToAction("LeaveApplicationDetails", new { id });
                }

                if (string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(existing.Status, "Cancelled", StringComparison.OrdinalIgnoreCase))
                {
                    TempData["ErpNextError"] = string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase)
                        ? "You can't edit submitted document."
                        : "Cancelled Leave Application cannot be edited.";
                    return RedirectToAction("LeaveApplicationDetails", new { id });
                }

                if (string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase))
                {
                    var latestDocResponse = await _erpNextService.GetAsync($"/api/resource/Leave%20Application/{encodedErpId}");
                    var latestDocJson = Newtonsoft.Json.Linq.JObject.Parse(latestDocResponse);
                    var latestDoc = latestDocJson["data"];

                    if (latestDoc == null)
                        throw new Exception("Submit failed: ERPNext Leave Application document not found.");

                    await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new
                    {
                        doc = latestDoc
                    });

                    existing.Status = "Submitted";
                    service.UpdateFromErpNext(existing);
                    TempData["Success"] = "Leave Application submitted in ERPNext and HRMS.";
                    return RedirectToAction("LeaveApplicationDetails", new { id });
                }

                // Explicitly map updated fields: Approver, Dates, and Reason (description)
                var payload = new
                {
                    employee = model.Employee,
                    employee_name = model.EmployeeName,
                    leave_type = model.LeaveType,
                    company = model.Company,
                    from_date = model.FromDate?.ToString("yyyy-MM-dd"),
                    to_date = model.ToDate?.ToString("yyyy-MM-dd"),
                    half_day = model.HalfDay ? 1 : 0,
                    description = model.Reason,        // Reason maps to ERPNext description field
                    leave_approver = model.LeaveApprover, // Approver maps to ERPNext leave_approver field
                    status = model.Status
                };

                // Send update to ERPNext
                await _erpNextService.PutAsync($"/api/resource/Leave%20Application/{encodedErpId}", payload);

                // Save locally to SQL Server
                model.Status = string.IsNullOrWhiteSpace(model.Status) ? "Open" : model.Status;
                service.UpdateFromErpNext(model);
                TempData["Success"] = "Leave Application saved successfully. You can still edit it until it is submitted.";
                return RedirectToAction("LeaveApplicationDetails", new { id = id });
            }
            catch (Exception ex)
            {
                string msg = ex.Message;
                if (msg.Contains("Application period cannot be outside leave allocation"))
                    msg = "Update failed: The From/To dates must fall within this employee's active Leave Allocation period in ERPNext.";
                else if (msg.Contains("LinkValidationError"))
                    msg = "Update failed: The selected Leave Approver is invalid or unrecognized by ERPNext.";
                else if (msg.Contains("UpdateAfterSubmitError") || msg.Contains("not allowed to change"))
                    msg = "Cannot modify fields after submission. Cancel the document in ERPNext first.";

                TempData["ErpNextError"] = msg;

                // Reload dropdowns and return view so data stays visible
                await ReloadDropdownsAsync();
                return View("LeaveApplicationDetails", model);
            }
        }

        [HttpPost]
        [Route("HR/DeleteLeaveApplication/{id:int}")]
        public async Task<ActionResult> DeleteLeaveApplication(int id)
        {
            var service = new LeaveApplicationService(_connectionString);
            var existing = service.GetAllLeaves().FirstOrDefault(l => l.Id == id);
            if (existing == null) return RedirectToAction("LeaveApplications");

            try
            {
                string erpId = !string.IsNullOrWhiteSpace(existing.ErpNextId)
                    ? existing.ErpNextId
                    : existing.LeaveApplicationCode;

                if (!string.IsNullOrWhiteSpace(erpId))
                {
                    await _erpNextService.DeleteAsync($"/api/resource/Leave%20Application/{Uri.EscapeDataString(erpId)}");
                }

                service.MarkDeletedById(id);
                TempData["Success"] = "Leave Application deleted from ERPNext and HRMS.";
                return RedirectToAction("LeaveApplications");
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Leave Application delete failed: " + ExtractErpNextErrorMessage(ex.Message);
                return RedirectToAction("LeaveApplicationDetails", new { id });
            }
        }



