        [HttpGet]
        [Route("HR/SyncAppraisalsFromErpNext")]
        public async Task<ActionResult> SyncAppraisalsFromErpNext()
        {
            try
            {
                var service = new AppraisalService(_connectionString);
                var response = await _erpNextService.GetAsync("/api/resource/Appraisal?fields=[\"name\",\"employee\",\"employee_name\",\"appraisal_cycle\",\"appraisal_template\"]&limit_page_length=500");
                dynamic parsed = JsonConvert.DeserializeObject(response);

                int newSyncCount = 0;

                if (parsed?.data != null && parsed.data.Count > 0)
                {
                    foreach (var item in parsed.data)
                    {
                        string erpId = item.name?.ToString();
                        string employee = item.employee?.ToString();
                        string employeeName = item.employee_name?.ToString();
                        string appraisalCycle = item.appraisal_cycle?.ToString();
                        string appraisalTemplate = item.appraisal_template?.ToString();

                        if (!string.IsNullOrEmpty(erpId))
                        {
                            service.SyncRecordFromErpNext(erpId, employee, employeeName, appraisalCycle, appraisalTemplate);
                            newSyncCount++;
                        }
                    }

                    TempData["SuccessMessage"] = "Successfully synced records from ERPNext!";
                }
                else
                {
                    TempData["ErrorMessage"] = "No Appraisal records found in ERPNext to sync.";
                }
            }
            catch (Exception ex)
            {
                TempData["ErrorMessage"] = "Failed to sync from ERPNext: " + ex.Message;
            }

            return RedirectToAction("Appraisal");
        }








        [HttpGet]
        [Route("HR/CreateCompensatoryLeaveRequest")]
        public async Task<ActionResult> CreateCompensatoryLeaveRequest()
        {
            var model = new CompensatoryLeaveRequest();

            try
            {
                // Fetch Employees from ERPNext
                var empFields = Uri.EscapeDataString("[\"name\",\"employee_name\"]");

                var empRes = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Employee")}?fields={empFields}&limit_page_length=500"
                );

                dynamic empParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(empRes);
                ViewBag.Employees = empParsed?.data ?? new List<object>();

                // Fetch only Compensatory Leave Types from ERPNext
                var leaveTypeFields = Uri.EscapeDataString("[\"name\"]");
                var leaveTypeFilters = Uri.EscapeDataString("[[\"Leave Type\",\"is_compensatory\",\"=\",1]]");

                var leaveTypeRes = await _erpNextService.GetAsync(
                    $"/api/resource/{Uri.EscapeDataString("Leave Type")}?fields={leaveTypeFields}&filters={leaveTypeFilters}&limit_page_length=0"
                );

                var leaveTypeJson = Newtonsoft.Json.Linq.JObject.Parse(leaveTypeRes);

                ViewBag.LeaveTypes = leaveTypeJson["data"]?
                    .Select(x => x["name"]?.ToString())
                    .Where(x => !string.IsNullOrWhiteSpace(x))
                    .Distinct()
                    .OrderBy(x => x)
                    .ToList() ?? new List<string>();
            }
            catch
            {
                ViewBag.Employees = new List<object>();
                ViewBag.LeaveTypes = new List<string>();
            }

            return View(model);
        }
        [HttpPost]
        [Route("HR/CreateCompensatoryLeaveRequest")]
        public async Task<ActionResult> CreateCompensatoryLeaveRequest(CompensatoryLeaveRequest model)
        {
            var service = new CompensatoryLeaveRequestService(_connectionString);

            try
            {
                var payload = new
                {
                    employee = model.Employee,
                    leave_type = model.LeaveType,
                    work_from_date = model.WorkFromDate?.ToString("yyyy-MM-dd"),
                    work_end_date = model.WorkEndDate?.ToString("yyyy-MM-dd"),
                    half_day = model.HalfDay ? 1 : 0,
                    reason = model.Reason
                };

                var response = await _erpNextService.PostAsync("/api/resource/Compensatory%20Leave%20Request", payload);
                var parsed = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(response);
                string erpNextId = parsed?.data?.name;

                model.ErpNextId = erpNextId;
                model.Status = "Draft";
                if (!string.IsNullOrWhiteSpace(erpNextId) && service.ExistsByErpNextId(erpNextId))
                {
                    service.UpdateFromErpNext(model);
                }
                else
                {
                    model.Id = service.InsertRequest(model);
                }

                TempData["Success"] = "Compensatory Leave Request created successfully!";
                return RedirectToAction("CompensatoryLeaveRequestDetails", "HR", new { id = string.IsNullOrWhiteSpace(erpNextId) ? model.Id.ToString() : erpNextId });
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Creation failed: " + CleanErpNextError(ex);

                try
                {
                    var empFields = Uri.EscapeDataString("[\"name\",\"employee_name\"]");

                    var empRes = await _erpNextService.GetAsync(
                        $"/api/resource/{Uri.EscapeDataString("Employee")}?fields={empFields}&limit_page_length=500"
                    );

                    dynamic empParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(empRes);
                    ViewBag.Employees = empParsed?.data ?? new List<object>();

                    var leaveTypeFields = Uri.EscapeDataString("[\"name\"]");
                    var leaveTypeFilters = Uri.EscapeDataString("[[\"Leave Type\",\"is_compensatory\",\"=\",1]]");

                    var leaveTypeRes = await _erpNextService.GetAsync(
                        $"/api/resource/{Uri.EscapeDataString("Leave Type")}?fields={leaveTypeFields}&filters={leaveTypeFilters}&limit_page_length=0"
                    );

                    var leaveTypeJson = Newtonsoft.Json.Linq.JObject.Parse(leaveTypeRes);

                    ViewBag.LeaveTypes = leaveTypeJson["data"]?
                        .Select(x => x["name"]?.ToString())
                        .Where(x => !string.IsNullOrWhiteSpace(x))
                        .Distinct()
                        .OrderBy(x => x)
                        .ToList() ?? new List<string>();
                }
                catch
                {
                    ViewBag.Employees = new List<object>();
                    ViewBag.LeaveTypes = new List<string>();
                }

                return View(model);
            }
        }




