        [HttpGet]
        [Route("HR/CompensatoryLeaveRequestDetails")]
        public async Task<ActionResult> CompensatoryLeaveRequestDetails(string id)
        {
            if (string.IsNullOrEmpty(id)) return RedirectToAction("CompensatoryLeaveRequest");

            var service = new CompensatoryLeaveRequestService(_connectionString);
            var allRequests = service.GetAllRequests();

            var request = allRequests.FirstOrDefault(x => x.ErpNextId == id || x.Id.ToString() == id);

            if (request == null) return NotFound();

            string erpId = request.ErpNextId;

            try
            {
                if (!string.IsNullOrEmpty(erpId))
                {
                    var liveResponse = await _erpNextService.GetAsync($"/api/resource/Compensatory%20Leave%20Request/{Uri.EscapeDataString(erpId)}");
                    var liveParsed = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(liveResponse);
                    var doc = liveParsed?.data;

                    if (doc != null)
                    {
                        request.Employee = doc.employee ?? request.Employee;
                        request.LeaveType = doc.leave_type ?? request.LeaveType;
                        request.Reason = doc.reason ?? request.Reason;
                        request.HalfDay = (doc.half_day ?? 0) == 1;
                        int docStatus = doc.docstatus != null ? Convert.ToInt32(doc.docstatus) : 0;
                        request.Status = docStatus == 1 ? "Submitted" : docStatus == 2 ? "Cancelled" : "Draft";

                        if (DateTime.TryParse((string)doc.work_from_date, out var fDate)) request.WorkFromDate = fDate;
                        if (DateTime.TryParse((string)doc.work_end_date, out var tDate)) request.WorkEndDate = tDate;
                        service.UpdateFromErpNext(request);
                    }
                }

                var empRes = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=500");
                ViewBag.Employees = Newtonsoft.Json.JsonConvert.DeserializeObject<dynamic>(empRes)?.data;
            }
            catch
            {
                ViewBag.Employees = new List<object>();
            }

            bool isEdit = string.Equals(Request.Query["edit"], "true", StringComparison.OrdinalIgnoreCase);
            if (isEdit && (string.Equals(request.Status, "Submitted", StringComparison.OrdinalIgnoreCase) || string.Equals(request.Status, "Cancelled", StringComparison.OrdinalIgnoreCase)))
            {
                TempData["ErpNextError"] = string.Equals(request.Status, "Submitted", StringComparison.OrdinalIgnoreCase)
                    ? "You can't edit submitted document."
                    : "Cancelled Compensatory Leave Request cannot be edited.";
                isEdit = false;
            }

            ViewBag.IsEdit = isEdit;
            return View("CompensatoryLeaveRequestDetails", request);
        }


        [HttpPost]
        [Route("HR/DeleteCompensatoryLeaveRequest/{id:int}")]
        public async Task<ActionResult> DeleteCompensatoryLeaveRequest(int id)
        {
            var service = new CompensatoryLeaveRequestService(_connectionString);
            var existing = service.GetById(id);

            if (existing == null)
            {
                TempData["ErpNextError"] = "Delete failed: record not found.";
                return RedirectToAction("CompensatoryLeaveRequestList");
            }

            try
            {
                if (!string.IsNullOrWhiteSpace(existing.ErpNextId))
                {
                    string erpId = Uri.EscapeDataString(existing.ErpNextId);

                    try
                    {
                        await _erpNextService.DeleteAsync($"/api/resource/Compensatory%20Leave%20Request/{erpId}");
                    }
                    catch
                    {
                        await _erpNextService.PostAsync("/api/method/frappe.client.cancel", new
                        {
                            doctype = "Compensatory Leave Request",
                            name = existing.ErpNextId
                        });

                        await _erpNextService.DeleteAsync($"/api/resource/Compensatory%20Leave%20Request/{erpId}");
                    }
                }

                service.SoftDeleteById(id);
                TempData["Success"] = "Compensatory Leave Request deleted successfully.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Delete failed: " + CleanErpNextError(ex);
            }

            return RedirectToAction("CompensatoryLeaveRequestList");
        }


















