        [HttpPost]
        [Route("HR/UpdateCompensatoryLeaveRequest")]
        public async Task<ActionResult> UpdateCompensatoryLeaveRequest(CompensatoryLeaveRequest model, string actionCommand)
        {
            
            {
                var service = new CompensatoryLeaveRequestService(_connectionString);
                int id = model.Id;

                var existing = service.GetById(id);

                if (existing == null)
                {
                    TempData["ErpNextError"] = "Update failed: record not found.";
                    return RedirectToAction("CompensatoryLeaveRequestList");
                }

                string erpId = !string.IsNullOrEmpty(existing.ErpNextId) ? existing.ErpNextId : string.Empty;

                if (string.IsNullOrEmpty(erpId))
                {
                    TempData["ErpNextError"] = "Update failed: Missing ERPNext identification link.";
                    return RedirectToAction("CompensatoryLeaveRequestDetails", new { id = id });
                }

                try
                {
                    string encodedErpId = Uri.EscapeDataString(erpId);
                    actionCommand = string.IsNullOrWhiteSpace(actionCommand) ? "Save" : actionCommand;

                    if (string.Equals(actionCommand, "Cancel", StringComparison.OrdinalIgnoreCase))
                    {
                        if (!string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase))
                        {
                            TempData["ErpNextError"] = "Only submitted Compensatory Leave Request can be cancelled.";
                            return RedirectToAction("CompensatoryLeaveRequestDetails", new { id = id });
                        }

                        await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                        {
                            doctype = "Compensatory Leave Request",
                            name = erpId
                        });

                        existing.Status = "Cancelled";
                        service.UpdateFromErpNext(existing);
                        TempData["Success"] = "Compensatory Leave Request cancelled in ERPNext and HRMS.";
                        return RedirectToAction("CompensatoryLeaveRequestDetails", new { id = id });
                    }

                    if (string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase) ||
                        string.Equals(existing.Status, "Cancelled", StringComparison.OrdinalIgnoreCase))
                    {
                        TempData["ErpNextError"] = string.Equals(existing.Status, "Submitted", StringComparison.OrdinalIgnoreCase)
                            ? "You can't edit submitted document."
                            : "Cancelled Compensatory Leave Request cannot be edited.";
                        return RedirectToAction("CompensatoryLeaveRequestDetails", new { id = id });
                    }

                    if (string.Equals(actionCommand, "Submit", StringComparison.OrdinalIgnoreCase))
                    {
                        var latestDocResponse = await _erpNextService.GetAsync($"/api/resource/Compensatory%20Leave%20Request/{encodedErpId}");
                        var latestDocJson = Newtonsoft.Json.Linq.JObject.Parse(latestDocResponse);
                        var latestDoc = latestDocJson["data"];

                        if (latestDoc == null)
                            throw new Exception("Submit failed: ERPNext Compensatory Leave Request document not found.");

                        await _erpNextService.PostMethodAsync("/api/method/frappe.client.submit", new
                        {
                            doc = latestDoc
                        });

                        existing.Status = "Submitted";
                        service.UpdateFromErpNext(existing);
                        TempData["Success"] = "Compensatory Leave Request submitted in ERPNext and HRMS.";
                        return RedirectToAction("CompensatoryLeaveRequestDetails", new { id = id });
                    }

                    var payload = new
                    {
                        employee = model.Employee,
                        leave_type = model.LeaveType,
                        work_from_date = model.WorkFromDate?.ToString("yyyy-MM-dd"),
                        work_end_date = model.WorkEndDate?.ToString("yyyy-MM-dd"),
                        half_day = model.HalfDay ? 1 : 0,
                        reason = model.Reason
                    };

                    await _erpNextService.PutAsync($"/api/resource/Compensatory%20Leave%20Request/{encodedErpId}", payload);

                    model.ErpNextId = erpId;
                    model.Status = "Draft";
                    service.UpdateFromErpNext(model);

                    TempData["Success"] = "Compensatory Leave Request saved successfully. You can still edit it until it is submitted.";
                }
                catch (Exception ex)
                {
                    TempData["ErpNextError"] = "Update failed: " + CleanErpNextError(ex);
                }

                return RedirectToAction("CompensatoryLeaveRequestDetails", new { id = id });
            }














        }






