        [HttpGet]
        [Route("HR/CreateLeaveEncashment")]
        public async Task<ActionResult> CreateLeaveEncashment()
        {
            var model = new LeaveEncashment
            {
                EncashmentDate = DateTime.Now,
                Status = "Draft"
            };

            try
            {
                // 1. Fetch Employees (name and employee_name)
                var empResp = await _erpNextService.GetAsync("/api/resource/Employee?fields=[\"name\",\"employee_name\"]&limit_page_length=100");
                dynamic empParsed = JsonConvert.DeserializeObject(empResp);
                var employeesList = new List<object>();
                if (empParsed?.data != null)
                {
                    foreach (var e in empParsed.data)
                    {
                        employeesList.Add(new
                        {
                            EmployeeId = e.name?.ToString(),
                            EmployeeName = e.employee_name?.ToString() ?? e.name?.ToString()
                        });
                    }
                }
                ViewBag.EmployeesList = employeesList;

                // 2. Fetch Companies
                var compResp = await _erpNextService.GetAsync("/api/resource/Company?fields=[\"name\"]&limit_page_length=100");
                ViewBag.Companies = ExtractNamesList(compResp);

                // 3. Fetch Leave Periods
                var lpResp = await _erpNextService.GetAsync("/api/resource/Leave%20Period?fields=[\"name\"]&limit_page_length=100");
                ViewBag.LeavePeriods = ExtractNamesList(lpResp);

                // 4. Fetch Leave Types
                var ltResp = await _erpNextService.GetAsync("/api/resource/Leave%20Type?fields=[\"name\"]&limit_page_length=100");
                ViewBag.LeaveTypes = ExtractNamesList(ltResp);
            }
            catch
            {
                // Fallbacks if offline
                ViewBag.EmployeesList = new List<object>();
                ViewBag.Companies = new List<string>();
                ViewBag.LeavePeriods = new List<string>();
                ViewBag.LeaveTypes = new List<string>();
            }

            return View("~/Views/HR/CreateLeaveEncashment.cshtml", model);
        }




        [HttpGet]
        [Route("HR/CreateGrievance")]
        public async Task<ActionResult> CreateGrievance()
        {
            EmployeeGrievance modelToRestore = null;
            var grievanceTypesList = new List<string> { "General", "Harassment", "Workplace", "+ Create New Grievance Type" };

            try
            {
                // Restore form state if returning from creating a new Grievance Type
                if (TempData["RestoredGrievanceForm"] != null)
                {
                    modelToRestore = JsonConvert.DeserializeObject<EmployeeGrievance>(TempData["RestoredGrievanceForm"].ToString());
                }

                // Fetch Grievance Types dynamically from ERPNext
                try
                {
                    var gJson = await _erpNextService.GetAsync("/api/resource/Grievance Type?fields=[\"name\"]&limit_page_length=500");
                    dynamic gParsed = JsonConvert.DeserializeObject(gJson);
                    if (gParsed?.data != null)
                    {
                        grievanceTypesList.Clear();
                        foreach (var g in gParsed.data)
                        {
                            grievanceTypesList.Add(g.name.ToString());
