        [HttpGet]
        [Route("HR/EmployeeGradeDetails/{id}")]
        public async Task<ActionResult> EmployeeGradeDetails(int id)
        {


            try
            {
                await RefreshEmployeeGradesFromErpNextAsync();
            }
            catch (Exception ex)
            {
                ViewBag.SyncWarning =
                    "ERPNext refresh failed: " + ex.Message;
