            }

            return View(grade);
        }







        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/UpdateEmployeeGrade/{id:int}")]
        public async Task<ActionResult> UpdateEmployeeGrade(
            int id,
            EmployeeGrade model)
        {
            try
            {
                var service =
                    new EmployeeGradeService(_connectionString);

                // =====================================================
                // 1. GET CURRENT HRMS RECORD
                // =====================================================

                var existing =
                    service.GetById(id);

                if (existing == null)
                {
                    return NotFound();
                }

                if (model == null ||
                    string.IsNullOrWhiteSpace(model.GradeName))
                {
                    throw new Exception(
                        "Grade Name is required."
                    );
                }

                if (string.IsNullOrWhiteSpace(
                    existing.ErpNextId))
                {
                    throw new Exception(
                        "Employee Grade is not linked with ERPNext."
                    );
                }

                string oldErpName =
                    existing.ErpNextId.Trim();

                string requestedGradeName =
                    model.GradeName.Trim();

                string finalErpName =
                    oldErpName;


                // =====================================================
                // 2. VALIDATE SALARY STRUCTURE
                // =====================================================

                if (!string.IsNullOrWhiteSpace(
                    model.DefaultSalaryStructure))
                {
                    model.DefaultSalaryStructure =
                        model.DefaultSalaryStructure.Trim();

                    await _erpNextService.EnsureLinkExistsAsync(
                        "Salary Structure",
                        model.DefaultSalaryStructure,
                        "name"
                    );
                }


                // =====================================================
                // 3. IF GRADE NAME CHANGED -> RENAME SAME ERP DOCUMENT
                // =====================================================

                if (!string.Equals(
                    oldErpName,
                    requestedGradeName,
                    StringComparison.Ordinal))
                {
                    var renamePayload = new
                    {
                        doctype = "Employee Grade",
                        old_name = oldErpName,
                        new_name = requestedGradeName,
                        merge = 0
                    };

                    string renameResponse =
                        await _erpNextService.PostMethodAsync(
                            "/api/method/frappe.client.rename_doc",
                            renamePayload
                        );

                    JObject renameJson =
                        JObject.Parse(renameResponse);

                    JToken renameMessage =
                        renameJson["message"];

                    if (renameMessage != null)
                    {
                        // Usually frappe.client.rename_doc returns
                        // renamed document name in message.
                        if (renameMessage.Type ==
                            JTokenType.String)
                        {
                            string returnedName =
                                renameMessage.ToString();

                            if (!string.IsNullOrWhiteSpace(
                                returnedName))
                            {
                                finalErpName =
                                    returnedName.Trim();
                            }
                            else
                            {
                                finalErpName =
                                    requestedGradeName;
                            }
                        }
                        else
                        {
                            finalErpName =
                                renameMessage["name"]
                                    ?.ToString()
                                ?? requestedGradeName;
                        }
                    }
                    else
                    {
                        finalErpName =
                            requestedGradeName;
                    }
                }


                // =====================================================
                // 4. UPDATE MUTABLE ERP FIELDS
                //
                // IMPORTANT:
                // Do NOT send employee_grade_name here.
                // =====================================================

                var payload = new
                {
                    default_salary_structure =
                        string.IsNullOrWhiteSpace(
                            model.DefaultSalaryStructure)
                            ? null
                            : model.DefaultSalaryStructure,

                    default_base_pay =
                        model.DefaultBasePay
                };


                await _erpNextService.PutAsync(
                    "/api/resource/Employee%20Grade/" +
                    Uri.EscapeDataString(
                        finalErpName
                    ),
                    payload
                );


                // =====================================================
                // 5. RELOAD ACTUAL ERP DATA
                // =====================================================

                string response =
                    await _erpNextService.GetAsync(
                        "/api/resource/Employee%20Grade/" +
                        Uri.EscapeDataString(
                            finalErpName
                        )
                    );


                JObject json =
                    JObject.Parse(response);

                JToken doc =
                    json["data"];


                if (doc == null)
                {
                    throw new Exception(
                        "Updated Employee Grade could not be reloaded from ERPNext."
                    );
                }


                // =====================================================
                // 6. ERP -> HRMS
                // =====================================================

                var saved =
                    new EmployeeGrade
                    {
                        Id = id,

                        ErpNextId =
                            doc["name"]?.ToString()
                            ?? finalErpName,

                        GradeName =
                            doc["name"]?.ToString()
                            ?? requestedGradeName,

                        DefaultSalaryStructure =
                            doc["default_salary_structure"]
                                ?.ToString()
                            ?? "",

                        DefaultBasePay =
                            doc["default_base_pay"] == null ||
                            doc["default_base_pay"].Type ==
                                JTokenType.Null
                                ? (decimal?)null
                                : doc["default_base_pay"]
                                    .ToObject<decimal?>()
                    };


                // =====================================================
                // 7. UPDATE SAME LOCAL HRMS ROW
                // =====================================================

                service.Update(saved);


                TempData["Success"] =
                    "Employee Grade updated successfully in ERPNext and HRMS.";


                return RedirectToAction(
                    "EmployeeGradeDetails",
                    new
                    {
                        id = id
                    }
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Employee Grade update failed: " +
                    ex.Message;

                return RedirectToAction(
                    "EmployeeGradeDetails",
                    new
                    {
                        id = id
                    }
                );
            }
        }



        [HttpPost]
        [ValidateAntiForgeryToken]
        [Route("HR/DeleteEmployeeGrade/{id:int}")]
        public async Task<ActionResult> DeleteEmployeeGrade(int id)
        {
            try
            {
                var service =
                    new EmployeeGradeService(
                        _connectionString
                    );

                var grade =
                    service.GetById(id);

                if (grade == null)
                {
                    return NotFound();
                }

                // ERP FIRST
                if (!string.IsNullOrWhiteSpace(
                    grade.ErpNextId))
                {
                    await _erpNextService.DeleteAsync(
                        "/api/resource/Employee%20Grade/" +
                        Uri.EscapeDataString(
                            grade.ErpNextId
                        )
                    );
                }

                // HRMS AFTER ERP SUCCESS
                service.MarkDeletedById(id);

                TempData["Success"] =
                    "Employee Grade deleted from ERPNext and HRMS.";

                return RedirectToAction(
                    "EmployeeGrades"
                );
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] =
                    "Employee Grade deletion failed: " +
                    ex.Message;

                return RedirectToAction(
                    "EmployeeGradeDetails",
                    new { id = id }
                );
            }
        }















        [HttpGet]
        [Route("HR/SyncShiftTypesFromErpNext")]
        public async Task<ActionResult> SyncShiftTypesFromErpNext()
        {
            try
            {
                var listResponse = await _erpNextService.GetAsync("/api/resource/Shift%20Type?fields=[\"name\",\"start_time\",\"end_time\",\"holiday_list\",\"color\",\"enable_auto_attendance\"]&limit_page_length=1000");
                dynamic listParsed = JsonConvert.DeserializeObject(listResponse);

                var service = new ShiftTypeService(_connectionString);
                var erpNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                var shifts = new List<ShiftType>();

                if (listParsed?.data != null)
                {
                    foreach (var listItem in listParsed.data)
                    {
                        string docName = listItem.name?.ToString();
                        if (string.IsNullOrEmpty(docName)) continue;
                        erpNames.Add(docName);

                        shifts.Add(new ShiftType
                        {
                            ShiftTypeCode = docName,
                            Name = docName,
                            StartTime = listItem.start_time?.ToString() ?? "",
                            EndTime = listItem.end_time?.ToString() ?? "",
                            HolidayList = listItem.holiday_list?.ToString() ?? "",
                            RosterColor = listItem.color?.ToString() ?? "Blue",
                            EnableAutoAttendance =
                                listItem.enable_auto_attendance != null &&
                                (listItem.enable_auto_attendance.ToString() == "1" ||
                                 listItem.enable_auto_attendance.ToString().Equals("true", StringComparison.OrdinalIgnoreCase))
                        });
                    }
                }

                var count = service.UpsertFromErpNextBatch(shifts, erpNames);
                TempData["Success"] = $"Successfully synced {count} Shift Types from ERPNext!";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Sync failed: " + ExtractErpNextErrorMessage(ex.Message);
            }

            return RedirectToAction("ShiftType", "HR");
        }


        [HttpPost]
        [Route("HR/CreateShiftType")]
        public async Task<ActionResult> CreateShiftType(ShiftType model)
        {
            ViewBag.HolidayLists = await LoadHolidayListNamesAsync();

            var errors = new List<string>();

            if (string.IsNullOrWhiteSpace(model.Name))
                errors.Add("Shift Type Name is required.");

            if (string.IsNullOrWhiteSpace(model.HolidayList))
                errors.Add("Holiday List is required.");

            if (string.IsNullOrWhiteSpace(model.StartTime))
                errors.Add("Start Time is required.");

            if (string.IsNullOrWhiteSpace(model.EndTime))
                errors.Add("End Time is required.");

            if (!string.IsNullOrWhiteSpace(model.StartTime) &&
                !string.IsNullOrWhiteSpace(model.EndTime) &&
                model.StartTime == model.EndTime)
            {
                errors.Add("Start time and end time cannot be same.");
            }

            if (errors.Any())
            {
                TempData["ErpNextError"] = string.Join(" ", errors);
                return View("~/Views/HR/CreateShiftType.cshtml", model);
            }

            try
            {
                var service = new ShiftTypeService(_connectionString);

                model.ShiftTypeCode = model.Name;
                model.RosterColor = string.IsNullOrWhiteSpace(model.RosterColor) ? "Blue" : model.RosterColor;

                var erpPayload = new
                {
                    name = model.Name,
                    start_time = model.StartTime,
                    end_time = model.EndTime,
                    holiday_list = model.HolidayList,
                    color = model.RosterColor,
                    enable_auto_attendance = model.EnableAutoAttendance ? 1 : 0
                };

                await _erpNextService.PostAsync("/api/resource/Shift%20Type", erpPayload);

                service.Insert(model);

                TempData["Success"] = "Shift Type saved successfully in HRMS and ERPNext.";
                return RedirectToAction("ShiftType", "HR");
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "ERPNext validation failed: " + ExtractErpNextErrorMessage(ex.Message);
                return View("~/Views/HR/CreateShiftType.cshtml", model);
            }
        }

        [HttpGet]
        [Route("HR/SyncShiftAssignmentsFromErpNext")]
        public async Task<ActionResult> SyncShiftAssignmentsFromErpNext()
        {
            try
            {
                var listResponse = await _erpNextService.GetAsync("/api/resource/Shift%20Assignment?limit_page_length=500");
                dynamic listParsed = JsonConvert.DeserializeObject(listResponse);

                var service = new HRShiftAssignmentService(_connectionString);
                var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                int inserted = 0;
                int updated = 0;

                if (listParsed?.data != null)
                {
                    foreach (var listItem in listParsed.data)
                    {
                        string docName = listItem.name?.ToString();
                        if (string.IsNullOrEmpty(docName)) continue;
                        erpIds.Add(docName);

                        try
                        {
                            var detailResponse = await _erpNextService.GetAsync($"/api/resource/Shift%20Assignment/{Uri.EscapeDataString(docName)}");
                            dynamic detailParsed = JsonConvert.DeserializeObject(detailResponse);
                            var item = detailParsed?.data;

                            if (item != null)
                            {
                                bool exists = service.GetByErpNextId(docName) != null;
                                var assignment = new HRShiftAssignment
                                {
                                    ErpNextId = docName,
                                    Employee = item.employee?.ToString(),
                                    EmployeeName = item.employee_name?.ToString() ?? string.Empty,
                                    Company = item.company?.ToString() ?? "AITS",
                                    ShiftType = item.shift_type?.ToString(),
                                    ShiftLocation = item.shift_location?.ToString() ?? string.Empty,
                                    StartDate = item.start_date != null ? Convert.ToDateTime(item.start_date) : DateTime.Now,
                                    EndDate = item.end_date != null ? Convert.ToDateTime(item.end_date) : (DateTime?)null,
                                    Status = item.docstatus != null && Convert.ToInt32(item.docstatus) == 1
                                        ? "Submitted"
                                        : item.docstatus != null && Convert.ToInt32(item.docstatus) == 2
                                            ? "Cancelled"
                                            : item.status?.ToString() ?? "Active"
                                };

                                service.InsertOrUpdate(assignment);
                                if (exists) updated++; else inserted++;
                            }
                        }
                        catch (Exception innerEx)
                        {
                            System.Diagnostics.Debug.WriteLine("Shift Assignment sync error: " + innerEx.Message);
                        }
                    }
                }
                SoftDeleteMissingErpDocuments("HRShiftAssignments", "ErpNextId", erpIds);
                TempData["Success"] = $"Shift Assignments synced from ERPNext. New: {inserted}, Updated: {updated}.";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Sync failed: " + ExtractErpNextErrorMessage(ex.Message);
            }

            return RedirectToAction("ShiftAssignment", "HR");
        }



