        private async Task<(int inserted, int updated)> PullTimesheetsFromErpNext()
        {
            var response = await _erpNextService.GetAsync("/api/resource/Timesheet?fields=[\"name\"]&limit_page_length=1000");
            dynamic parsed = Newtonsoft.Json.JsonConvert.DeserializeObject(response);
            var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var service = new TimeSheetService(_connectionString);
            int inserted = 0;
            int updated = 0;

            if (parsed?.data != null)
            {
                foreach (var item in parsed.data)
                {
                    string erpId = item.name?.ToString();
                    if (string.IsNullOrWhiteSpace(erpId)) continue;
                    erpIds.Add(erpId);

                    var detailResponse = await _erpNextService.GetAsync($"/api/resource/Timesheet/{Uri.EscapeDataString(erpId)}");
                    dynamic detailParsed = Newtonsoft.Json.JsonConvert.DeserializeObject(detailResponse);
                    var data = detailParsed?.data;
                    if (data == null) continue;

                    bool exists = service.GetByErpNextId(erpId) != null || service.GetBySeries(erpId) != null;
                    string docStatus = GetDocStatusLabel(data.docstatus);
                    string erpStatus = data.status?.ToString();

                    var sheet = new TimeSheet
                    {
                        ErpNextId = erpId,
                        Series = erpId,
                        Status = docStatus == "Draft" && !string.IsNullOrWhiteSpace(erpStatus) ? erpStatus : docStatus,
                        Company = data.company?.ToString(),
                        Project = data.parent_project?.ToString(),
                        Customer = data.customer?.ToString(),
                        Currency = data.currency?.ToString() ?? "INR",
                        ExchangeRate = data.exchange_rate != null ? Convert.ToDecimal(data.exchange_rate) : 1.000m,
                        Employee = data.employee?.ToString(),
                        TotalWorkingHours = data.total_hours != null ? Convert.ToDecimal(data.total_hours) : 0,
                        TotalBillableHours = data.total_billable_hours != null ? Convert.ToDecimal(data.total_billable_hours) : 0,
                        TotalBillableAmount = data.total_billable_amount != null ? Convert.ToDecimal(data.total_billable_amount) : 0,
                        TotalCostingAmount = data.total_costing_amount != null ? Convert.ToDecimal(data.total_costing_amount) : 0,
                        Note = data.note?.ToString()
                    };

                    if (data.time_logs != null)
                    {
                        foreach (var log in data.time_logs)
                        {
                            sheet.TimeLogs.Add(new TimeSheetDetail
                            {
                                ActivityType = log.activity_type?.ToString(),
                                FromTime = log.from_time != null ? Convert.ToDateTime(log.from_time) : (DateTime?)null,
                                ToTime = log.to_time != null ? Convert.ToDateTime(log.to_time) : (DateTime?)null,
                                Hrs = log.hours != null ? Convert.ToDecimal(log.hours) : 0,
                                Project = log.project?.ToString(),
                                Task = log.task?.ToString(),
                                IsBillable = log.is_billable != null && Convert.ToBoolean(log.is_billable)
                            });
                        }
                    }

                    service.InsertOrUpdate(sheet);
                    if (exists) updated++; else inserted++;
                }
            }

            SoftDeleteMissingErpDocuments("TimeSheets", "Series", erpIds);
            return (inserted, updated);
        }


















