        private List<string> ExtractNamesList(string jsonResponse)
        {
            var list = new List<string>();
            try
            {
                dynamic parsed = JsonConvert.DeserializeObject(jsonResponse);
                if (parsed?.data != null)
                {
                    foreach (var item in parsed.data)
                    {
                        string name = item.name?.ToString();
                        if (!string.IsNullOrEmpty(name))
                        {
                            list.Add(name);
                        }
                    }
                }
            }
            catch { }
            return list;
        }

        private bool ShouldRefreshFromErpNext()
        {
            string cacheControl =
                Request.Headers["Cache-Control"].ToString();

            string pragma =
                Request.Headers["Pragma"].ToString();

            return cacheControl.Contains(
                       "no-cache",
                       StringComparison.OrdinalIgnoreCase)
                   || cacheControl.Contains(
                       "max-age=0",
                       StringComparison.OrdinalIgnoreCase)
                   || pragma.Contains(
                       "no-cache",
                       StringComparison.OrdinalIgnoreCase);
        }

        private List<object> ExtractEmployeesList(string jsonResponse)
        {
            var result = new List<object>();
            try
            {
                dynamic parsed = JsonConvert.DeserializeObject(jsonResponse);
                if (parsed?.data != null)
                {
                    foreach (var item in parsed.data)
                    {
                        string id = item.name?.ToString();
                        string name = item.employee_name?.ToString() ?? id;
                        if (!string.IsNullOrEmpty(id))
                        {
                            result.Add(new { EmployeeId = id, EmployeeName = name });
                        }
                    }
                }
            }
            catch { }
            return result;
        }

