        private static string GetDocStatusLabel(object docstatus)
        {
            if (docstatus == null) return "Draft";
            if (!int.TryParse(docstatus.ToString(), out var status)) return "Draft";
            return status == 1 ? "Submitted" : status == 2 ? "Cancelled" : "Draft";
        }

