        private void SoftDeleteMissingErpDocuments(string tableName, string erpColumnName, HashSet<string> erpIds)
        {
            var allowed = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase)
            {
                ["LeaveApplications"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId", "LeaveApplicationCode" },
                ["CompensatoryLeaveRequests"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" },
                ["ShiftRequests"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ShiftRequestCode" },
                ["HRShiftAssignments"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" },
                ["HRShiftSchedules"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "Name" },
                ["HRShiftScheduleAssignments"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" },
                ["TimeSheets"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "Series", "ErpNextId" },
                ["LeaveTypes"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" },
                ["LeavePeriods"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" },
                ["LeavePolicies"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" },
                ["LeaveAllocations"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" },
                ["LeaveBlockLists"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" },
                ["LeavePolicyAssignments"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" },
                ["EmployeeAdvances"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "EmployeeAdvanceCode" },
                ["ExpenseClaimTypes"] = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "ErpNextId" }
            };

            if (!allowed.TryGetValue(tableName, out var columns) || !columns.Contains(erpColumnName))
            {
                throw new InvalidOperationException("Unsupported sync table or column.");
            }

            using (var conn = new SqlConnection(_connectionString))
            {
                conn.Open();

                if (erpIds == null || erpIds.Count == 0)
                {
                    using (var cmd = new SqlCommand(
                        $"UPDATE {tableName} SET IsDeleted = 1 WHERE IsDeleted = 0 AND {erpColumnName} IS NOT NULL AND {erpColumnName} <> ''",
                        conn))
                    {
                        cmd.ExecuteNonQuery();
                    }
                    return;
                }

                var parameterNames = erpIds.Select((_, index) => "@p" + index).ToList();
                string sql = $@"
                    UPDATE {tableName}
                    SET IsDeleted = 1
                    WHERE IsDeleted = 0
                      AND {erpColumnName} IS NOT NULL
                      AND {erpColumnName} <> ''
                      AND {erpColumnName} NOT IN ({string.Join(",", parameterNames)})";

                using (var cmd = new SqlCommand(sql, conn))
                {
                    int i = 0;
                    foreach (var id in erpIds)
                    {
                        cmd.Parameters.AddWithValue("@p" + i, id);
                        i++;
                    }

                    cmd.ExecuteNonQuery();
                }
            }
        }



        private async Task CancelSubmittedAttendanceForLeaveAsync(LeaveApplication leave)
        {
            if (leave == null || string.IsNullOrWhiteSpace(leave.Employee) || !leave.FromDate.HasValue || !leave.ToDate.HasValue)
                return;

            var filters = Uri.EscapeDataString(
                "[[\"Attendance\",\"employee\",\"=\",\"" + leave.Employee + "\"]," +
                "[\"Attendance\",\"attendance_date\",\">=\",\"" + leave.FromDate.Value.ToString("yyyy-MM-dd") + "\"]," +
                "[\"Attendance\",\"attendance_date\",\"<=\",\"" + leave.ToDate.Value.ToString("yyyy-MM-dd") + "\"]," +
                "[\"Attendance\",\"docstatus\",\"=\",1]]");
            var fields = Uri.EscapeDataString("[\"name\"]");
            var json = await _erpNextService.GetAsync($"/api/resource/Attendance?fields={fields}&filters={filters}&limit_page_length=500");
            var parsed = Newtonsoft.Json.Linq.JObject.Parse(json);
            var rows = parsed["data"] as Newtonsoft.Json.Linq.JArray;

            if (rows == null)
                return;

            foreach (var row in rows)
            {
                string attendanceName = row["name"]?.ToString();
                if (string.IsNullOrWhiteSpace(attendanceName))
                    continue;

                await _erpNextService.PostMethodAsync("/api/method/frappe.client.cancel", new
                {
                    doctype = "Attendance",
                    name = attendanceName
                });
            }
        }





















        public async Task<ActionResult> SyncLeaveApplicationsFromErpNext()
        {
            try
            {
                // 1. Fetch fields explicitly including docstatus for draft detection
                string fields = Uri.EscapeDataString("[\"name\",\"employee\",\"employee_name\",\"leave_type\",\"company\",\"from_date\",\"to_date\",\"half_day\",\"description\",\"leave_approver\",\"status\",\"docstatus\"]");
                string listJson = await _erpNextService.GetAsync(
    $"/api/resource/{Uri.EscapeDataString("Leave Application")}?fields={fields}&limit_start=0&limit_page_length=1000&order_by=creation%20desc");
                dynamic listParsed = JsonConvert.DeserializeObject(listJson);

                int importedCount = 0;
                int updatedCount = 0;
                var erpIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

                if (listParsed.data != null)
                {
                    foreach (var row in listParsed.data)
                    {
                        string erpNextId = row.name;
                        if (!string.IsNullOrWhiteSpace(erpNextId))
                        {
                            erpIds.Add(erpNextId);
                        }

                        int docStatus = row.docstatus != null ? (int)row.docstatus : 0;
                        string currentStatus = (string)row.status;

                        if (docStatus == 1)
                        {
                            currentStatus = "Submitted";
                        }
                        else if (docStatus == 2)
                        {
                            currentStatus = "Cancelled";
                        }
                        else if (docStatus == 0 && (string.IsNullOrWhiteSpace(currentStatus) || currentStatus == "Open"))
                        {
                            currentStatus = "Draft";
                        }

                        var leave = new LeaveApplication
                        {
                            LeaveApplicationCode = erpNextId,
                            Employee = (string)row.employee,
                            EmployeeName = (string)row.employee_name,
                            LeaveType = (string)row.leave_type,
                            Company = (string)row.company,
                            FromDate = row.from_date != null ? (DateTime?)DateTime.Parse((string)row.from_date) : null,
                            ToDate = row.to_date != null ? (DateTime?)DateTime.Parse((string)row.to_date) : null,
                            HalfDay = row.half_day != null && (int)row.half_day == 1,
                            Reason = (string)row.description,
                            LeaveApprover = (string)row.leave_approver,
                            Status = currentStatus ?? "Open",
                            ErpNextId = erpNextId
                        };

                        // 2. Instead of skipping with 'continue', update existing records or insert new ones
                        if (_leaveService.ExistsByErpNextId(erpNextId))
                        {
                            _leaveService.UpdateByErpNextId(leave);
                    var existing = _leaveService.GetByErpNextId(erpNextId);
                    if (existing != null)
                    {
                        _leaveService.SoftDeleteDuplicateSamePeriod(existing.Id, leave);
                    }
                            updatedCount++;
                        }
                        else
                        {
                            _leaveService.InsertFromErpNext(leave);
                    var inserted = _leaveService.GetByErpNextId(erpNextId);
                    if (inserted != null)
                    {
                        _leaveService.SoftDeleteDuplicateSamePeriod(inserted.Id, leave);
                    }
                            importedCount++;
                        }
                    }
                }

                SoftDeleteMissingErpDocuments("LeaveApplications", "ErpNextId", erpIds);
                TempData["Success"] = $"Synced from ERPNext: {importedCount} new imported, {updatedCount} updated (including Drafts).";
            }
            catch (Exception ex)
            {
                TempData["ErpNextError"] = "Sync from ERPNext failed: " + ex.Message;
            }

            return RedirectToAction("LeaveApplications");
        }
    }
}







